```jac
"""Hunger Heroes donation graph: walkers traverse donation relationships,
perform a BFS-style recommendation crawl with a visited set for donor
deduplication, and cascade-invalidate a donor's nearby donations."""

node Donation {
    has title: str = "";
    has category: str = "";
    has zip_code: str = "";
    has days_to_expiry: int = 0;
    has available: bool = True;
}

node Donor {
    has name: str = "";
    has home_zip: str = "";
}

edge DonatedBy {
    has since: str = "";
}

edge NearbyTo {
    has distance_miles: int = 0;
}

walker BFSRecommendation {
    has visited: set[str] = set();
    has donor_name: str = "";
    has donor_zip: str = "";

    can start with Root entry {
        here ++> Donation(title="Sourdough Bread", category="bakery",
                          zip_code="10001", days_to_expiry=2);
        here ++> Donation(title="Brown Rice 5kg", category="grains",
                          zip_code="10001", days_to_expiry=10);
        visit [-->];
    }

    can crawl with Donor entry {
        key = f"{here.name}|{here.home_zip}";
        if key not in self.visited {
            self.visited.add(key);
            self.donor_name = here.name;
            self.donor_zip = here.home_zip;
        }
        visit [-->];
    }

    can recommend with Donation entry {
        if here.available {
            zip_bonus = "+30 zip" if here.zip_code == self.donor_zip else "";
            urgency_bonus = "";
            if here.days_to_expiry <= 1 {
                urgency_bonus = "+40 urgent";
            } elif here.days_to_expiry <= 3 {
                urgency_bonus = "+20 soon";
            }
            line = (
                f"[RECOMMEND] donor={self.donor_name} ({self.donor_zip}) "
                f"-> {here.title} cat={here.category} exp={here.days_to_expiry}d"
            );
            if zip_bonus != "" {
                line = f"{line} {zip_bonus}";
            }
            if urgency_bonus != "" {
                line = f"{line} {urgency_bonus}";
            }
            print(line);
        }
        visit [-->];
    }
}

walker CascadeInvalidate {
    has target_name: str = "";
    has invalidated: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can scan with Donor entry {
        visit [-->];
        if self.target_name == "" or here.name == self.target_name {
            for d in [->:NearbyTo:->] {
                if d.available {
                    d.available = False;
                    self.invalidated += 1;
                    print(f"[INVALIDATE] {d.title} (cat={d.category})");
                }
            }
        }
    }
}

with entry {
    donor_alice = Donor(name="Alice", home_zip="94110");
    donor_bob = Donor(name="Bob", home_zip="10001");
    donor_carol = Donor(name="Carol", home_zip="94110");

    bread = Donation(title="Sourdough Bread", category="bakery",
                     zip_code="94110", days_to_expiry=2);
    rice = Donation(title="Brown Rice 5kg", category="grains",
                    zip_code="94110", days_to_expiry=10);
    apples = Donation(title="Organic Apples", category="produce",
                      zip_code="10001", days_to_expiry=1);
    soup = Donation(title="Tomato Soup", category="canned",
                    zip_code="94110", days_to_expiry=30, available=False);

    root +>:DonatedBy(since="2024-01-15"):+> donor_alice;
    root +>:DonatedBy(since="2024-02-20"):+> donor_bob;
    root +>:DonatedBy(since="2024-03-05"):+> donor_carol;

    donor_alice +>:NearbyTo(distance_miles=2):+> bread;
    donor_alice +>:NearbyTo(distance_miles=3):+> rice;
    donor_alice +>:NearbyTo(distance_miles=5):+> soup;
    donor_bob +>:NearbyTo(distance_miles=1):+> apples;
    donor_carol +>:NearbyTo(distance_miles=4):+> bread;
    donor_alice +>:NearbyTo(distance_miles=6):+> donor_carol;

    print("=== BFS Recommendation Crawl ===");
    root spawn BFSRecommendation();

    print("\n=== DFS Cascade Invalidation (Alice's donations) ===");
    root spawn CascadeInvalidate(target_name="Alice");
}
```

```jac
"""Outage SLA status derivation demo: the dead denormalized sla_status
column is gone; the Exporter walker joins each SLAResult back to its
Outage over typed ComputedFor edges and reports the latest status live."""

node Outage {
    has title: str = "";
    has resolved: bool = False;
}

node SLAResult {
    has status: str = "";
    has is_latest: bool = False;
}

edge ComputedFor {
    has computed_at: str = "";
}

walker Exporter {
    can start with Root entry {
        visit [-->];
    }

    can export with Outage entry {
        visit [-->];
    }

    can note with SLAResult entry {
        owners = [<-:ComputedFor:<-];
        owner = owners[0].title if owners else "unknown outage";
        if here.is_latest {
            print(f"export: {owner}: {here.status}");
        } else {
            print(f"skipping stale result for {owner}: {here.status}");
        }
        visit [-->];
    }
}

walker Resolver {
    can start with Root entry {
        visit [-->];
    }

    can resolve with Outage entry {
        here.resolved = True;
        print(f"resolved {here.title}");
        visit [-->];
    }

    can compute with SLAResult entry {
        tag = "latest" if here.is_latest else "stale";
        print(f"computed SLA ({tag}): {here.status}");
        visit [-->];
    }
}

with entry {
    o1 = Outage(title="API outage", resolved=False);
    o2 = Outage(title="DB timeout", resolved=False);
    root ++> o1;
    root ++> o2;
    o1 +>:ComputedFor(computed_at="2024-05-01T10:00"):+> SLAResult(status="met", is_latest=True);
    o1 +>:ComputedFor(computed_at="2024-04-01T09:00"):+> SLAResult(status="breached", is_latest=False);
    o2 +>:ComputedFor(computed_at="2024-05-02T08:00"):+> SLAResult(status="met", is_latest=True);

    root spawn Resolver();
    root spawn Exporter();
}
