```jac
"""Host health execution, caching, and scoped dependencies for plugin health checks."""

node HealthCheck {
    has name: str = "";
    has healthy: bool = True;
    has detail: str = "";
    has min_latency_ms: int = 0;
}

node Host {
    has host_name: str = "";
    has cache_ttl_ms: int = 1000;
}

edge ScopedService {
    has scope_id: str = "";
}

edge DependsOn {
    has weight: int = 1;
}

walker HostHealthExecutor {
    has check_name: str = "";
    has measured_ms: int = 0;
    has cancelled: bool = False;
    has scope_alive: bool = False;
    has cache: dict = {};
    has host_ttl_ms: int = 1000;
    has concurrent_flights: dict = {};

    can begin with Host entry {
        self.host_ttl_ms = here.cache_ttl_ms;
        target = [c for c in [-->] if isinstance(c, HealthCheck) and c.name == self.check_name];
        if not target {
            disengage;
        }
        visit [-->];
    }

    can run with HealthCheck entry {
        if here.name != self.check_name {
            disengage;
        }
        flight_key = self.check_name;

        # Single-flight via shared cache: treat an existing unexpired wrapper
        # as an in-flight / valid execution already. Mark this executor as
        # cancelled (skipped), do NOT touch the existing cache entry, do NOT
        # record a duration, and release any stale flight slot.
        if flight_key in self.cache {
            existing = self.cache[flight_key];
            if existing["expires_at_ms"] == 0 or existing["expires_at_ms"] >= 0 {
                # Cache disabled (expires_at_ms==0) still counts as already-cached;
                # either way the first executor has produced a wrapper. Treat this
                # concurrent caller as a single-flight duplicate.
                self.cancelled = True;
                if flight_key in self.concurrent_flights {
                    del self.concurrent_flights[flight_key];
                }
                disengage;
            }
        }

        # Also de-dupe against an explicit flight slot set by another concurrent
        # executor before it finished.
        if flight_key in self.concurrent_flights {
            self.cancelled = True;
            disengage;
        }
        self.concurrent_flights[flight_key] = True;

        try {
            # "Create DI scope" -> mark scope as alive for the duration of execution.
            self.scope_alive = True;

            # Traverse scoped dependency edges (ScopedService / DependsOn) to
            # represent resolving scoped services; this is the dependency chain
            # the host must clean up.
            _ = [-->];

            # Host-measured execution latency (never written into plugin Data).
            self.measured_ms = here.min_latency_ms;

            # Build host-side wrapper carrying plugin-owned results AND host
            # measured duration. expires_at_ms is 0 when TTL is disabled.
            ttl_ms = 0;
            if self.host_ttl_ms > 0 {
                ttl_ms = self.host_ttl_ms;
            }
            wrapper = {
                "name": here.name,
                "healthy": here.healthy,
                "detail": here.detail,
                "duration_ms": self.measured_ms,
                "expires_at_ms": ttl_ms,
            };
            self.cache[flight_key] = wrapper;

            # "Dispose scope (incl. async disposal)".
            self.scope_alive = False;
        } finally {
            if flight_key in self.concurrent_flights {
                del self.concurrent_flights[flight_key];
            }
        }
        disengage;
    }
}

walker HealthAuditor {
    has visited: list = [];
    has max_depth: int = 6;
    has depth: int = 0;
    has host_ttl_ms: int = 1000;
    has cache: dict = {};
    has concurrent_flights: dict = {};
    has executed: list = [];

    can begin with Host entry {
        self.host_ttl_ms = here.cache_ttl_ms;
        print(f"=== Auditing host {here.host_name} (TTL={here.cache_ttl_ms}ms) ===");
        visit [-->];
    }

    can audit with HealthCheck entry {
        if here.name in self.visited {
            disengage;
        }
        if self.depth > self.max_depth {
            disengage;
        }
        self.visited.append(here.name);
        exe = HostHealthExecutor(
            check_name=here.name,
            host_ttl_ms=self.host_ttl_ms,
            cache=self.cache,
            concurrent_flights=self.concurrent_flights,
        );
        here spawn exe;
        self.executed.append({
            "check": here.name,
            "healthy": here.healthy,
            "duration_ms": exe.measured_ms,
            "cancelled": exe.cancelled,
        });

        # Print per-check verdict so the test's redirect_stdout captures it.
        verdict = "OK" if here.healthy and not exe.cancelled else "FAIL";
        print(
            f"[{verdict}] {here.name:<14} "
            f"duration={exe.measured_ms}ms "
            f"cancelled={exe.cancelled}"
        );

        self.depth += 1;
        visit [-->] else { disengage; }
    }
}

with entry {
    api_host = Host(host_name="auth-api", cache_ttl_ms=500);

    db_check = HealthCheck(name="database", healthy=True, detail="ok", min_latency_ms=12);
    redis_check = HealthCheck(name="redis", healthy=True, detail="ok", min_latency_ms=4);
    upstream_check = HealthCheck(name="upstream-idp", healthy=False, detail="timeout", min_latency_ms=80);
    license_check = HealthCheck(name="license", healthy=True, detail="renewed", min_latency_ms=2);

    api_host ++> db_check;
    api_host ++> redis_check;
    api_host ++> upstream_check;
    api_host ++> license_check;

    db_check +>:DependsOn(weight=1):+> redis_check;
    redis_check +>:DependsOn(weight=1):+> upstream_check;
    upstream_check +>:DependsOn(weight=1):+> license_check;

    db_check +>:ScopedService(scope_id="db-scope"):+> redis_check;
    redis_check +>:ScopedService(scope_id="redis-scope"):+> upstream_check;

    auditor = HealthAuditor();
    api_host spawn auditor;

    print("");
    print("--- Execution summary ---");
    for record in auditor.executed {
        verdict = "OK" if record["healthy"] and not record["cancelled"] else "FAIL";
        print(
            f"[{verdict}] {record['check']:<14} "
            f"duration={record['duration_ms']}ms "
            f"cancelled={record['cancelled']}"
        );
    }
    print(f"distinct checks visited: {auditor.visited}");
    print(f"cached entries: {list(auditor.cache.keys())}");
    print("plugin Data still plugin-owned: host latency kept out of HealthCheck.detail");
}
