```jac
"""PeakATail Stage 1d: IP-filter window, strand asymmetry, and per-site bookkeeping.

Models the essential scenario from issue #95: cleavage sites on plus/minus strands,
internal-priming windows that are strand-asymmetric, a pas catalog that drops zero-count
gene-assigned sites, and a unified-bed column-5 bug where the first merged member's count
is emitted instead of cohort-level support. A walker audits a small dataset and reports
each defect class.
"""

node CleavageSite {
    has chrom: str = "";
    has pos: int = 0;
    has strand: str = "";
    has a_run_len: int = 0;
    has is_novel: bool = False;
    has clip_umis: int = 0;
}

node PASRecord {
    has pas_id: str = "";
    has gene: str = "";
    has clip_umis: int = 0;
    has in_annotatedpas: bool = True;
}

node UnifiedPAS {
    has unified_id: str = "";
    has first_member_umis: int = 0;
    has cohort_clip_umis_sum: int = 0;
    has any_tier1: bool = False;
}

edge OnStrand {
    has label: str = "";
}

edge MergedInto {
    has order: int = 0;
}

walker IPAuditor {
    has wrong_window_count: int = 0;
    has zero_count_dropped: int = 0;
    has wrong_col5_count: int = 0;
    has audited: list[str] = [];

    can start with Root entry {
        print("Stage 1d audit: strand-asymmetric IP window, zero-count drops, unified col5");
        visit [-->] else { disengage; }
    }

    can audit_site with CleavageSite entry {
        window_ok = (here.strand == "+" and here.a_run_len <= 30)
            or (here.strand == "-" and here.a_run_len <= 10);
        if not window_ok {
            self.wrong_window_count += 1;
            note = f"[IP-WINDOW] {here.chrom}:{here.pos}{here.strand} a_run={here.a_run_len} tested wrong side";
            self.audited.append(note);
            print(note);
        }
        if here.is_novel and here.a_run_len >= 6 {
            note2 = f"[KINNEX-DECOY?] {here.chrom}:{here.pos}{here.strand} novel + a_run={here.a_run_len}";
            self.audited.append(note2);
            print(note2);
        }
        visit [-->] else { disengage; }
    }

    can audit_pas with PASRecord entry {
        if here.in_annotatedpas and here.clip_umis == 0 {
            self.zero_count_dropped += 1;
            note = f"[ZERO-DROP] {here.pas_id} gene={here.gene} dropped from pasbed";
            self.audited.append(note);
            print(note);
        }
        visit [-->] else { disengage; }
    }

    can audit_unified with UnifiedPAS entry {
        if here.first_member_umis != here.cohort_clip_umis_sum {
            self.wrong_col5_count += 1;
            note = f"[COL5-BUG] {here.unified_id} first={here.first_member_umis} cohort_sum={here.cohort_clip_umis_sum} any_tier1={here.any_tier1}";
            self.audited.append(note);
            print(note);
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    plus_known = CleavageSite(
        chrom="chr1", pos=1000, strand="+",
        a_run_len=4, is_novel=False, clip_umis=120
    );
    plus_novel = CleavageSite(
        chrom="chr1", pos=2500, strand="+",
        a_run_len=8, is_novel=True, clip_umis=42
    );
    minus_suspicious = CleavageSite(
        chrom="chr2", pos=750, strand="-",
        a_run_len=25, is_novel=True, clip_umis=17
    );
    dropped_zero = PASRecord(
        pas_id="pas:chr1:3000:+", gene="GENE_X",
        clip_umis=0, in_annotatedpas=True
    );
    kept_nonzero = PASRecord(
        pas_id="pas:chr1:3050:+", gene="GENE_X",
        clip_umis=9, in_annotatedpas=True
    );
    unified_bad = UnifiedPAS(
        unified_id="u:chr3:4000:+",
        first_member_umis=5,
        cohort_clip_umis_sum=137,
        any_tier1=True
    );

    root +>:OnStrand(label="catalog"):+> plus_known
        +>:OnStrand:+> plus_novel
        +>:OnStrand:+> minus_suspicious;
    root +>:OnStrand(label="pasbed"):+> dropped_zero
        +>:OnStrand:+> kept_nonzero;
    root +>:MergedInto(order=0):+> unified_bad;

    auditor = IPAuditor();
    root spawn auditor;

    print(f"\n--- Stage 1d audit summary ---");
    print(f"wrong-window sites flagged: {auditor.wrong_window_count}");
    print(f"zero-count PAS dropped:     {auditor.zero_count_dropped}");
    print(f"unified-bed col5 wrong:     {auditor.wrong_col5_count}");
    print(f"total findings:             {len(auditor.audited)}");
    for note in auditor.audited {
        print(f"  {note}");
    }
}
