```jac
"""Devbox cleanup preflight: model the safe-to-purge decision natively.

Models the core entities (Devbox workspaces, Git ancestry, PR delivery,
dependencies) as node archetypes and lets walkers cascade the purge
safety decision through dependencies in both directions.
"""

node Devbox {
    has name: str = "";
    has clean: bool = True;
    has inspection_failed: bool = False;
    has ahead_count: int = 0;
    has delivered: bool = False;
    has content_represented: bool = True;
    has has_open_pr: bool = False;
}

node PullRequest {
    has pr_id: str = "";
    has merged: bool = False;
}

edge DependsOn { has mode: str = "rw"; }
edge ReferencedBy { }
edge DeliveredBy { }

def node_is_unsafe(d: Devbox) -> bool {
    return (
        d.inspection_failed
        or not d.clean
        or (d.ahead_count > 0 and not d.delivered)
        or (d.delivered and not d.content_represented)
    );
}

walker SafetyAuditor {
    has findings: list = [];
    has visited: list = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can audit with Devbox entry {
        if here.name not in self.visited {
            self.visited.append(here.name);

            reason = "";
            if here.inspection_failed {
                reason = "inspection-failed: cannot prove safe";
            } elif not here.clean {
                reason = "dirty working tree";
            } elif here.has_open_pr {
                reason = "open PR in flight";
            } elif here.ahead_count > 0 and not here.delivered {
                reason = f"{here.ahead_count} unpushed commits, not delivered";
            } elif here.delivered and not here.content_represented {
                reason = "ahead of upstream but content not represented in target";
            }

            decision = "review-required" if reason else "safe-to-purge";

            record = {
                "name": here.name,
                "ahead": here.ahead_count,
                "delivered": here.delivered,
                "represented": here.content_represented,
                "decision": decision,
                "reason": reason,
            };
            self.findings.append(record);
            print(f"[{decision}] {here.name}: ahead={here.ahead_count} delivered={here.delivered} represented={here.content_represented} :: {reason}");

            visit [-->];
        }
    }
}

walker PurgeCascade {
    has blocked: list = [];
    has cleared: list = [];
    has visited: list = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can probe with Devbox entry {
        if here.name not in self.visited {
            self.visited.append(here.name);

            reason = "";
            if here.inspection_failed {
                reason = "inspection failed";
            } elif not here.clean {
                reason = "dirty tree";
            } elif here.ahead_count > 0 and not here.delivered {
                reason = "unpushed and not delivered";
            } elif here.delivered and not here.content_represented {
                reason = "content not represented after merge";
            } else {
                for dep in [->:DependsOn:->] {
                    if dep.name in self.blocked or node_is_unsafe(dep) {
                        reason = "depends on blocked workspace";
                    }
                }
                if not reason {
                    for ref in [->:ReferencedBy:->] {
                        if ref.name in self.blocked or node_is_unsafe(ref) {
                            reason = "referenced by blocked workspace";
                        }
                    }
                }
            }

            if reason {
                self.blocked.append(here.name);
                print(f"BLOCKED {here.name}: {reason}");
            } else {
                self.cleared.append(here.name);
                print(f"SAFE {here.name}: ok to purge");
            }

            visit [-->];
        }
    }
}

with entry {
    devbox37 = Devbox(
        name="devbox--37",
        clean=True,
        inspection_failed=False,
        ahead_count=2,
        delivered=True,
        content_represented=True,
        has_open_pr=False,
    );
    ui103 = Devbox(
        name="ui--103",
        clean=True,
        inspection_failed=True,
        ahead_count=0,
        delivered=False,
        content_represented=False,
        has_open_pr=False,
    );
    ui94 = Devbox(
        name="ui--94",
        clean=True,
        inspection_failed=False,
        ahead_count=0,
        delivered=True,
        content_represented=True,
        has_open_pr=False,
    );
    pr54 = PullRequest(pr_id="#54", merged=True);

    root ++> devbox37 ++> ui103 ++> ui94;
    devbox37 +>:DeliveredBy:+> pr54;
