"""DreamCo Master Upgrade backlog tracker.

Models the canonical owner-approved backlog as a graph: each goal is a
``Goal`` node, goals roll up into ``Milestone`` nodes via ``PartOf`` edges,
and a walker named ``UpgradeAuditor`` walks the backlog top-down to flag
already-complete foundations, identify unmet active gaps, and detect
dependency cycles that would block the rebuild.
"""

node Goal {
    has title: str = "";
    has done: bool = False;
    has category: str = "";
}

node Milestone {
    has title: str = "";
    has weight: int = 1;
}

edge PartOf {
    has rank: int = 0;
}

edge DependsOn {
}

walker UpgradeAuditor {
    has complete_count: int = 0;
    has open_count: int = 0;
    has cycle_hits: list[str] = [];
    has visited: list = [];
    has mode: str = "tree";
    has max_steps: int = 50;
    has steps: int = 0;

    can start with Root entry {
        print("DreamCo Master Upgrade — canonical audit walk");
        visit [-->];
    }

    can tally_milestones with Milestone entry {
        if self.steps >= self.max_steps {
            disengage;
        }
        self.steps += 1;
        bucket = "DONE" if here.weight == 0 else "OPEN";
        print(f"[{bucket}] milestone: {here.title} (weight={here.weight})");
        if here.weight == 0 {
            self.complete_count += 1;
        } else {
            self.open_count += 1;
        }
        if self.mode == "tree" {
            visit [->:PartOf:->];
        } else {
            disengage;
        }
    }

    can tally_goals with Goal entry {
        if self.steps >= self.max_steps {
            disengage;
        }
        self.steps += 1;
        marker = f"{here.category}::{here.title}";
        if marker in self.visited {
            self.cycle_hits.append(marker);
            print(f"  ! cycle reached goal: {marker}");
            disengage;
        }
        self.visited.append(marker);
        status = "DONE" if here.done else "OPEN";
        print(f"  - [{status}] {here.category} :: {here.title}");
        if here.done {
            self.complete_count += 1;
        } else {
            self.open_count += 1;
        }
        visit [->:DependsOn:->];
    }
}

with entry {
    # Foundations already laid during the rebuild (owner-cleared).
    foundations = Milestone(title="Foundations", weight=0);
    root ++> foundations;

    foundations +>:PartOf(rank=1):+> Goal(
        title="Universal Verification contract + runner",
        done=True,
        category="foundations",
    );
    foundations +>:PartOf(rank=2):+> Goal(
        title="Repository Test Matrix wired to UVE",
        done=True,
        category="foundations",
    );
    foundations +>:PartOf(rank=3):+> Goal(
        title="Canonical bot/system deduplication contract",
        done=True,
        category="foundations",
    );

    # Active gap: shared intelligence layer (not yet complete).
    intelligence = Milestone(title="Shared intelligence and learning", weight=1);
    root ++> intelligence;

    shared_layer = Goal(
        title="Shared intelligence layer for specialists + Buddy",
        done=False,
        category="intelligence",
    );
    intelligence +>:PartOf(rank=1):+> shared_layer;

    memory_scopes = Goal(
        title="Role/project memory scopes so learning does not leak",
        done=False,
        category="intelligence",
    );
    intelligence +>:PartOf(rank=2):+> memory_scopes;

    # Dependency: memory_scopes depends on shared_layer being started.
    shared_layer +>:DependsOn:+> memory_scopes;

    # Cycle: a stale note accidentally points back, demonstrating the
    # dependency cycle that blocks the rebuild.
    memory_scopes +>:DependsOn:+> shared_layer;

    # Active gap: builder-team daily loop.
    builder = Milestone(title="Builder team daily loop", weight=1);
    root ++> builder;

    daily_loop = Goal(
        title="read repo -> compare issue -> design -> code -> test -> PR",
        done=False,
        category="builder",
    );
    builder +>:PartOf(rank=1):+> daily_loop;

    reconcile = Goal(
        title="Issue Reconciler attaches repo evidence per criterion",
        done=False,
        category="builder",
    );
    builder +>:PartOf(rank=2):+> reconcile;

    daily_loop +>:DependsOn:+> reconcile;

    # First pass: top-down tally over PartOf edges.
    auditor = UpgradeAuditor(mode="tree", max_steps=20);
    auditor spawn foundations;

    # Second pass: explicit cycle walk over DependsOn to flag loops the
    # first pass stepped into while descending the tree.
    print("\n--- dependency cycle scan ---");
    cycle_walker = UpgradeAuditor(mode="cycle", max_steps=20);
    cycle_walker spawn shared_layer;

    print(
        f"\nsummary: complete={auditor.complete_count} "
        f"open={auditor.open_count} "
        f"cycle_goals={len(cycle_walker.cycle_hits)}"
    );
}
```

A maintainer on the project EffortlessMetrics/perl-lsp-swarm (unknown) filed this issue about hand-rolled graph machinery causing pain:

Issue #7790: feat(moose): emit static attribute, constructor, provided-member, hook, constraint, and boundary facts

Parent: #7648
Depends on Moose detection: #7788
Framework FactSink: #6820 / #6821 / #6822 / #6874
Semantic truth/corrections: #2373 / #8935 / #8940 / #1649
Canonical project facts: #4746
Differential generated-member proof: #4766
Constraint/type follow-on: #7793 / #7280
Role/inheritance follow-on: #7794
Acceptance manifest: #7430

## Objective

Implement the bounded static `has` extraction slice for current exact `Moose` / `Moose::Role` activation and emit canonical attribute, constructor-input, **provided generated-member**, referenced-hook, declared-constraint-metadata, and dynamic-boundary facts through `FactSink`.

This is one fact-production PR. It consumes independently reviewed #2373 semantics and the shared correction seams. It does not compose inheritance/roles, classify constraint spellings into return types, or change live provider output.

## Governing distinctions

Keep separate:

```text
AttributeFact
ProvidedGeneratedMemberFact
ReferencedHookFact
ConstructorInputFact
DeclaredConstraintFact
DynamicBoundaryFact
```

A builder or trigger target name is a hook unless current source/framework evidence separately proves a method implementation is provided. Declared constraint spelling is metadata until #7793 classifies it.

## Supported first slice — core Moose

For a statically named attribute and statically reviewable option list under the reviewed plain-Moose profile, model:

- declaring package/role and exact `has` generator/name/option anchors;
- adapter/framework/version/source generation identity;
- `is => ro`, `rw`, and `bare` according to #2373/#8935;
- omitted `is` as an attribute with **no default accessor**, not a combined accessor;
- explicit static `reader`, `writer`, and `accessor` names;
- explicit static predicate and clearer names;
- explicit static builder/trigger **hook** names;
- `lazy => 1` as a separate state from access mode;
- reviewed `lazy_build => 1` shortcut behavior, preserving which generated names are provided and which builder name is a hook;
- `init_arg` same/renamed/disabled;
- `required`, lazy, default-present, and builder/default constructor disposition as separate metadata;
- a bounded independently reviewed static `handles` subset only where generated delegate names are exact;
- raw/static `isa` declared-constraint identity and source anchor as metadata only;
- explicit-source-over-generated precedence/conflict evidence;
- provenance, confidence, completeness, limitations, and invalidation dependencies.

## Extension boundary

Plain Moose does not silently inherit Moo or MooseX::AttributeShortcuts semantics.

For forms such as:

- `is => rwp`;
- `is => lazy`;
- numeric/default shorthand values for builder/predicate/clearer;
- other MooseX::AttributeShortcuts behavior;

require exact current extension activation/profile evidence before emitting the extension-specific fact. If extension detection is not admitted in this PR, emit a stable extension-required/unsupported boundary and no false exact member.

Do not infer extension activation from the option shape alone.

## Provided-member rules

The admitted provided-member inventory contains only methods Moose actually installs for the reviewed active profile, such as the relevant:

- reader;
- writer/accessor;
- predicate;
- clearer;
- admitted static delegate.

A named builder hook is not a provided method merely because the name is static (#1649). A role `requires` relation is likewise not a provided method.

Every source-backed generated member points to the real `has` generator anchor and never a fabricated method-body range.

## Constructor-input rules

Keep constructor participation independent from callable inventory:

- default/static custom/disabled `init_arg`;
- `required`;
- `lazy`;
- default versus builder-hook disposition;
- exact source anchors needed for later constructor-key/refactor consumers.

Do not infer arbitrary matching hash keys as constructor occurrences.

## Constraint boundary

Record the declared `isa` ex

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Moose attribute fact extraction: model a package's `has` declarations as nodes
and walk the chain of declared facts (attribute, generated member, hook,
constraint, boundary) with a fact-emitter walker.

Each `has` in a Moose package produces several distinct fact records.
A maintainer walking the attribute must emit each fact type only when the
source actually supports it, otherwise emit a stable boundary fact.
"""

# ---- Entity archetypes ----------------------------------------------------

node Package {
    has pkg_name: str = "";
    has framework: str = "Moose";
    has version: str = "2.0";
}

# An attribute node owns one `has` declaration's option set as typed fields.
node Attribute {
    has attr_name: str = "";
    has access_mode: str = "rw";      # ro | rw | bare | (none -> no default accessor)
    has has_reader: bool = False;
    has has_writer: bool = False;
    has has_predicate: bool = False;
    has has_clearer: bool = False;
    has has_builder: bool = False;     # a *hook* name, NOT a provided method
    has builder_name: str = "";
    has is_lazy: bool = False;
    has is_required: bool = False;
    has init_arg: str = "";           # "" means "same as attr name"
    has isa_constraint: str = "";     # metadata only, no classification
    has explicit_source: bool = False;
}

# A constructed accessor / predicate / clearer / admitted delegate member.
node ProvidedMember {
    has member_name: str = "";
    has kind: str = "";               # reader | writer | predicate | clearer | delegate
}

# A builder or trigger target name. NOT a provided method unless separately proved.
node Hook {
    has hook_name: str = "";
    has role: str = "";               # builder | trigger
}

# The boundary marker when current evidence is insufficient.
node Boundary {
    has boundary_kind: str = "";      # unsupported | extension_required | not_admitted
    has reason: str = "";
}

# ---- Typed edges ----------------------------------------------------------

edge DeclaredIn { }    # Package -> Attribute
edge Provides { }      # Attribute -> ProvidedMember
edge HooksTo { }       # Attribute -> Hook
edge Constrains { }    # Attribute -> Boundary (extension/unsupported)

# ---- Walkers --------------------------------------------------------------

# Walks every Attribute under a Package and emits the fact records the
# reviewer admits. Distinct fact kinds stay as distinct nodes — never
# collapsed into a single combined record.
walker FactExtractor {
    has package_name: str = "";
    has stats: dict = {};

    can start with Root entry {
        visit [-->];
    }

    # At the Package, walk every declared attribute via the typed edge.
    can visit_pkg with Package entry {
        self.package_name = here.pkg_name;
        print(f"== Package: {here.pkg_name} ({here.framework} {here.version}) ==");
        visit [->:DeclaredIn:->];
    }

    # The core: one union ability that decides which fact nodes to attach
    # and walks all of them out via typed edges. A builder hook is NOT a
    # provided member — it gets its own Hook node, separate from ProvidedMember.
    can emit_facts with Attribute entry {
        # 1. Provided members: only the ones Moose actually installs.
        if here.has_reader {
            self.stats["provided"] = self.stats.get("provided", 0) + 1;
        }
        if here.has_writer {
            self.stats["provided"] = self.stats.get("provided", 0) + 1;
        }
        if here.has_predicate {
            self.stats["provided"] = self.stats.get("provided", 0) + 1;
        }
        if here.has_clearer {
            self.stats["provided"] = self.stats.get("provided", 0) + 1;
        }

        # 2. Builder / trigger hooks — separate from provided members.
        if here.has_builder {
            self.stats["hooks"] = self.stats.get("hooks", 0) + 1;
        }

        # 3. Declared constraint is metadata, not a classified return type.
        if here.isa_constraint != "" {
            self.stats["constraints"] = self.stats.get("constraints", 0) + 1;
        }

        # 4. Explicit source over generated precedence evidence.
        if here.explicit_source {
            self.stats["explicit_sources"] = self.stats.get("explicit_sources", 0) + 1;
        }

        # 5. Boundary: if the option shape suggests an extension but the
        #    reviewer has NOT admitted it in this PR, emit a stable
        #    boundary fact instead of fabricating a member.
        suspicious = (here.access_mode == "rwp") or (here.access_mode == "lazy");
        if suspicious {
            self.stats["boundaries"] = self.stats.get("boundaries", 0) + 1;
            b = Boundary(
                boundary_kind="extension_required",
                reason=f"access mode '{here.access_mode}' needs extension evidence"
            );
            here +>:Constrains:+> b;
        }

        # Walk to all queued typed-edge targets (provided, hooks, boundaries).
        # We issue separate visits so each typed relationship gets traversed.
        if [->:Provides:->] {
            visit [->:Provides:->];
        }
        if [->:HooksTo:->] {
            visit [->:HooksTo:->];
        }
        if [->:Constrains:->] {
            visit [->:Constrains:->];
        }
    }

    # Report provided member names.
    can report_member with ProvidedMember entry {
        print(f"  [provided {here.kind}] {here.member_name}");
    }

    # Report builder / trigger hook names separately.
    can report_hook with Hook entry {
        print(f"  [hook {here.role}] {here.hook_name}");
    }

    # Report the extension boundary explicitly.
    can report_boundary with Boundary entry {
        print(f"  [BOUNDARY {here.boundary_kind}] {here.reason}");
    }
}

# ---- Demo wiring ----------------------------------------------------------

with entry {
    # Package with mixed admitted + boundary cases.
    pkg = Package(pkg_name="MyApp::Thing", framework="Moose", version="2.2200");

    # Attribute #1: a plain rw attribute with reader, predicate, builder hook,
    # an init_arg rename, and a declared isa constraint.
    a1 = Attribute(
        attr_name="name",
        access_mode="rw",
        has_reader=True,
        has_predicate=True,
        has_builder=True,
        builder_name="_build_name",
        is_required=True,
        init_arg="full_name",
        isa_constraint="Str"
    );

    # Attribute #2: ro + writer, lazy, default-present, no builder.
    a2 = Attribute(
        attr_name="count",
        access_mode="ro",
        has_writer=True,
        is_lazy=True,
        isa_constraint="Int"
    );

    # Attribute #3: bare (no default accessor at all), with predicate and clearer.
    a3 = Attribute(
        attr_name="internal",
        access_mode="bare",
        has_predicate=True,
        has_clearer=True
    );

    # Attribute #4: rwp — extension territory; should emit a boundary, NOT
    # fabricate a writer accessor as a plain provided member.
    a4 = Attribute(
        attr_name="settable",
        access_mode="rwp",
        has_writer=True,
        explicit_source=True
    );

    # Wire the graph with typed edges carrying meaning.
    pkg +>:DeclaredIn:+> a1;
    pkg +>:DeclaredIn:+> a2;
    pkg +>:DeclaredIn:+> a3;
    pkg +>:DeclaredIn:+> a4;

    # Provided members (only what Moose actually installs for the profile).
    a1 +>:Provides:+> ProvidedMember(member_name="name", kind="reader");
    a1 +>:Provides:+> ProvidedMember(member_name="has_name", kind="predicate");
    a2 +>:Provides:+> ProvidedMember(member_name="count", kind="reader");
    a2 +>:Provides:+> ProvidedMember(member_name="_set_count", kind="writer");
    a3 +>:Provides:+> ProvidedMember(member_name="has_internal", kind="predicate");
    a3 +>:Provides:+> ProvidedMember(member_name="clear_internal", kind="clearer");

    # Hooks — these are NOT provided methods; they are builder/trigger targets.
    a1 +>:HooksTo:+> Hook(hook_name="_build_name", role="builder");

    root ++> pkg;

    # Run the extractor.
    fe = FactExtractor();
    pkg spawn fe;

    print(f"stats: {fe.stats}");
}
```

```jac
"""Test-grip summary projection: a bounded selector-scoped walker that
reuses canonical analyzer facts and batches N selectors into M summaries.

Models the core entities (Test selectors, Seam records, analyzer facts,
and the batch envelope) as node archetypes, wires their relationships
with typed edges, and drives the projection with a single walker. The
walker follows typed edges in the order encoded on each edge so the
traversal is deterministic and respects the Selects ordering set up by
the test/demo.
"""

node Selector {
    has name: str = "";
    has body_id: str = "";
    has marker_id: str = "";
    has helper_id: str = "";
    has fixture_id: str = "";
    has snapshot_id: str = "";
    has cfg_features: str = "";
}

node Seam {
    has seam_id: str = "";
    has owner: str = "";
    has kind: str = "";
    has source: str = "";
    has span: str = "";
    has expression: str = "";
    has expected_sink: str = "";
    has required_discriminator: str = "";
    has seam_body_id: str = "";
}

node GripFacts {
    has relation_reason: str = "";
    has confidence: float = 0.0;
    has reach: bool = False;
    has activate: bool = False;
    has propagate: bool = False;
    has observe: bool = False;
    has discriminate: bool = False;
    has grip_class: str = "";
    has actionability: str = "";
    has headline: str = "";
    has oracle_kind: str = "";
    has oracle_strength: str = "";
    has observed_values: str = "";
    has missing_discriminators: str = "";
    has limitations: str = "";
    has disposition: str = "";
}

node AnalyzerContext {
    has generation: str = "";
    has schema_generation: str = "";
    has repo_tree_id: str = "";
    has mode: str = "";
}

# Typed edges: the projection's relationship backbone.
edge Selects { has order: int = 0; }
edge MapsTo {
    has confidence: float = 0.0;
    has reason: str = "";
}
edge AnchoredIn { }

walker Projector {
    has batch_cap: int = 10;
    has inspected_selectors: int = 0;
    has inspected_seams: int = 0;
    has omitted: int = 0;
    has fingerprint: str = "";
    has duration_ms: int = 0;
    has current: str = "";

    can start with AnalyzerContext entry {
        visit [->:Selects:->];
    }

    can project with Selector entry {
        self.current = here.name;
        self.inspected_selectors += 1;
        # Fold the selector's own identity into the fingerprint so any
        # change to the selected test body / marker / helper / fixture /
        # snapshot moves the summary identity.
        self.fingerprint = self.fingerprint + "|" + here.name;
        self.fingerprint = self.fingerprint + "|" + here.body_id;
        if here.marker_id != "" {
            self.fingerprint = self.fingerprint + "|m=" + here.marker_id;
        }
        if here.helper_id != "" {
            self.fingerprint = self.fingerprint + "|h=" + here.helper_id;
        }
        if here.fixture_id != "" {
            self.fingerprint = self.fingerprint + "|f=" + here.fixture_id;
        }
        if here.snapshot_id != "" {
            self.fingerprint = self.fingerprint + "|s=" + here.snapshot_id;
        }
        if here.cfg_features != "" {
            self.fingerprint = self.fingerprint + "|cfg=" + here.cfg_features;
        }
        visit [->:MapsTo:->];
    }

    can record with Seam entry {
        self.inspected_seams += 1;
        self.fingerprint = self.fingerprint + "|seam=" + here.seam_id;
        self.fingerprint = self.fingerprint + "|owner=" + here.owner;
        self.fingerprint = self.fingerprint + "|kind=" + here.kind;
        self.fingerprint = self.fingerprint + "|expr=" + here.expression;
        if here.expected_sink != "" {
            self.fingerprint = self.fingerprint + "|sink=" + here.expected_sink;
        }
        if here.required_discriminator != "" {
            self.fingerprint = self.fingerprint + "|req=" + here.required_discriminator;
        }
        visit [->:AnchoredIn:->];
    }

    can fold with GripFacts entry {
        self.fingerprint = self.fingerprint + "|class=" + here.grip_class;
        self.fingerprint = self.fingerprint + "|disp=" + here.disposition;
        self.fingerprint = self.fingerprint + "|oracle=" + here.oracle_kind;
        self.fingerprint = self.fingerprint + "|ostr=" + here.oracle_strength;
        self.fingerprint = self.fingerprint + "|reach=" + str(here.reach);
        self.fingerprint = self.fingerprint + "|act=" + str(here.activate);
        self.fingerprint = self.fingerprint + "|prop=" + str(here.propagate);
        self.fingerprint = self.fingerprint + "|obs=" + str(here.observe);
        self.fingerprint = self.fingerprint + "|disc=" + str(here.discriminate);
        if here.missing_discriminators != "" {
            self.fingerprint = self.fingerprint + "|miss=" + here.missing_discriminators;
        }
        if here.limitations != "" {
            self.fingerprint = self.fingerprint + "|lim=" + here.limitations;
        }
        visit [-->];
    }
}

walker SummarizeBatch {
    has cap: int = 10;
    has omitted: int = 0;
    has total: int = 0;

    can start with AnalyzerContext entry {
        visit [->:Selects:->];
    }

    can tally with Selector entry {
        self.total += 1;
        if self.total > self.cap {
            self.omitted += 1;
            visit [-->];
        }
        visit [-->];
    }
}

with entry {
    ctx = AnalyzerContext(
        generation="analyzer-7",
        schema_generation="v1",
        repo_tree_id="tree-abc",
        mode="offline"
    );
    root ++> ctx;

    s_reach = Selector(name="test_reach_handshake", body_id="b1", cfg_features="std");
    s_activate = Selector(name="test_activate_flow", body_id="b2");
    s_obs = Selector(name="test_observe_only", body_id="b3");
    s_unrelated = Selector(name="test_sanity_check", body_id="b4");

    se_seam1 = Seam(
        seam_id="S1", owner="net", kind="net::connect",
        source="src/net/mod.rs", span="10-20",
        expression="connect()", expected_sink="tcp_sink",
        required_discriminator="addr_family"
    );
    se_seam2 = Seam(
        seam_id="S2", owner="io", kind="io::write",
        source="src/io/writer.rs", span="40-55",
        expression="write_all()", expected_sink="file_handle",
        required_discriminator="path"
    );

    g1 = GripFacts(
        relation_reason="matched_expression", confidence=0.9,
        reach=True, activate=True, propagate=False, observe=True,
        discriminate=True, grip_class="Strong",
        actionability="actionable", headline="covers net seam",
        oracle_kind="equality", oracle_strength="strong",
        observed_values="3 runs", missing_discriminators="none",
        limitations="none", disposition="Covered"
    );
    g2 = GripFacts(
        relation_reason="path_proximity", confidence=0.4,
        reach=False, activate=False, propagate=False, observe=True,
        discriminate=False, grip_class="Partial",
        actionability="informational", headline="observes only",
        oracle_kind="none", oracle_strength="weak",
        observed_values="0", missing_discriminators="addr_family",
        limitations="known FN #1431", disposition="Partial"
    );

    # Typed-edge wiring: ordered selection, then selector->seam mapping
    # with the relation reason+confidence as payload, and a final
    # analyzer-context anchor for staleness/fingerprinting.
    ctx +>:Selects(order=1):+> s_reach;
    ctx +>:Selects(order=2):+> s_activate;
    ctx +>:Selects(order=3):+> s_obs;
    ctx +>:Selects(order=4):+> s_unrelated;

    s_reach +>:MapsTo(confidence=0.9, reason="matched_expression"):+> se_seam1;
    s_activate +>:MapsTo(confidence=0.7, reason="matched_expression"):+> se_seam2;
    s_obs +>:MapsTo(confidence=0.4, reason="path_proximity"):+> se_seam1;

    se_seam1 +>:AnchoredIn:+> g1;
    se_seam2 +>:AnchoredIn:+> g2;

    p = Projector(batch_cap=10);
    ctx spawn p;

    b = SummarizeBatch(cap=3);
    ctx spawn b;

    print(
        f"inspected selectors={p.inspected_selectors}, "
        f"seams={p.inspected_seams}, "
        f"omitted={p.omitted}, "
        f"fingerprint_seed={p.fingerprint}, "
        f"duration_ms={p.duration_ms}"
    );
    print(
        f"batch total seen={b.total}, omitted by cap={b.omitted}"
    );
}
