"""Wiki + raw capture lint: detect capture files under raw/ that no page references.

Models the maintain-wiki lint gap: walk a small wiki graph (pages connected to
raw captures via Source edges) and report any capture node that no page
reaches. Mirrors the existing orphaned-pages check, but in the other
direction — and surfaces byte counts so the keep/drop decision is informed.
"""

node Capture {
    has path: str = "";
    has size_bytes: int = 0;
    has hit: bool = False;
}

node Page {
    has title: str = "";
    has depth: int = 0;
    has sources: list[str] = [];
}

edge Source {
    has note: str = "";
}

walker OrphanHunter {
    has seen_pages: list = [];
    has found: list = [];
    has total_bytes: int = 0;

    can start with Root entry {
        print("Unreferenced captures under raw/:");
        visit [-->];
    }

    can scan_page with Page entry {
        self.seen_pages.append(here);
        targets = [->:Source:->];
        for t in targets {
            t.hit = True;
        }
        visit [-->];
    }

    can tally with Capture entry {
        if not here.hit {
            self.found.append({"path": here.path, "bytes": here.size_bytes});
            self.total_bytes += here.size_bytes;
            print(f"  - {here.path} ({here.size_bytes} bytes)");
        }
        visit [-->] else {
            print(f"Total orphan bytes: {self.total_bytes}");
        }
    }
}

with entry {
    p_index = Page(title="index.md", depth=1, sources=["captures/intro.md"]);
    p_deep = Page(title="deep/note.md", depth=3, sources=["../../captures/intro.md"]);
    p_plan = Page(title="plan.md", depth=1, sources=["captures/plan.md"]);

    c_kept = Capture(path="captures/intro.md", size_bytes=1200);
    c_orphan = Capture(path="captures/orphan.md", size_bytes=4464);
    c_small = Capture(path="captures/plan.md", size_bytes=300);

    root ++> p_index ++> p_deep ++> p_plan;

    p_index +>:Source(note="intro ref"):+> c_kept;
    p_deep +>:Source(note="deep ref"):+> c_kept;
    p_plan +>:Source(note="plan ref"):+> c_small;

    root +>:Source(note="unreferenced"):+> c_orphan;

    root spawn OrphanHunter();
}
