"""Wiki lint demo: detect capture files under raw/ that no page cites."""

edge Contains { }
edge Cites {
    has resource: str = "";
}

node Page {
    has title: str = "";
    has sources: list[str] = [];
}

node Capture {
    has path: str = "";
    has bytes: int = 0;
}

walker LintOrphanCaptures {
    has referenced: dict[str, str] = {};
    has orphans: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can scan_pages with Page entry {
        for res in here.sources {
            norm = res;
            while len(norm) >= 3 and norm[0:3] == "../" {
                norm = norm[3:];
            }
            if norm not in self.referenced {
                self.referenced[norm] = here.title;
            }
        }
        visit [-->];
    }

    can check_captures with Capture entry {
        if len(self.referenced) > 0 and here.path not in self.referenced and here.bytes > 0 {
            self.orphans += [f"{here.path} ({here.bytes} bytes)"];
        }
        visit [-->] else {
            if len(self.orphans) == 0 {
                print("lint: no unreferenced captures under raw/");
            } else {
                for o in self.orphans {
                    print(f"[orphan capture] {o} referenced by nothing");
                }
            }
            disengage;
        }
    }
}

with entry {
    wiki = Page(title="wiki");
    root +>:Contains:+> wiki;

    overview = Page(title="overview.md", sources=["../../raw/plan/schedule.md", "../../raw/notes.md"]);
    guide = Page(title="guide.md", sources=["../../../raw/notes.md"]);
    wiki +>:Contains:+> overview +>:Contains:+> guide;

    raw_dir = Capture(path="raw", bytes=0);
