    sched = Capture(path="raw/plan/schedule.md", bytes=344_320);
    notes = Capture(path="raw/notes.md", bytes=1_204);
    legacy = Capture(path="raw/legacy/export-004.md", bytes=4_464);
    raw_dir +>:Contains:+> sched +>:Contains:+> notes +>:Contains:+> legacy;

    overview +>:Cites(resource="raw/notes.md"):+> notes;

    root spawn LintOrphanCaptures();
}
