```jac
"""Hierarchical Manager delegation and reconciliation demo.

Models the core scenario from Issue #20: a tree of Manager streams rooted at
an Owner, where Manager A spawns independently orchestrated child Managers
B and C, each of which in turn delegates bounded work to an Executor and a
Reviewer. A reconciliation walker walks the delegation graph depth-first,
detects cycles, enforces an authority-containment invariant, and reports the
stream lineage.
"""

node WorkItem {
    has title: str = "";
    has work_id: str = "";
}

node Owner {
    has name: str = "";
}

node Manager {
    has name: str = "";
    has authority: str = "investigate";
    has child_count: int = 0;
}

node Executor {
    has name: str = "";
    has bound_task: str = "";
}

node Reviewer {
    has name: str = "";
}

edge Delegates {
    has handoff: str = "";
}

edge BoundedTask {
    has scope: str = "";
}

edge Reviews {
    has stage: str = "";
}

edge Parents {
    has lineage_ref: str = "";
}

walker LineageAuditor {
    has path: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 8;
    has seen_ids: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Owner entry {
        print(f"OWNER root: {here.name}");
        self.path = self.path + [here.name];
        visit [-->];
    }

    can descend with Manager entry {
        cur_depth = self.depth;
        if cur_depth > self.max_depth {
            print(f"DEPTH CAP at {here.name} (depth={cur_depth})");
            disengage;
        }
        marker = f"{here.name}@{here.authority}";
        if marker in self.seen_ids {
            print(f"CYCLE detected revisiting {here.name}");
            disengage;
        }
        self.seen_ids = self.seen_ids + [marker];
        self.path = self.path + [here.name];
        self.depth = self.depth + 1;
        print(f"  Manager {here.name} [{here.authority}] children={here.child_count}");
        visit [-->];
    }

    can record_exec with Executor entry {
        print(f"    Executor {here.name} bound to: {here.bound_task}");
    }

    can record_review with Reviewer entry {
        print(f"    Reviewer {here.name} standing by");
    }
}

walker CascadeInvalidator {
    has revoked: list[str] = [];
    has invalidating: bool = True;

    can start with Root entry {
        visit [-->];
    }

    can revoke_owner with Owner entry {
        if self.invalidating {
            print(f"OWNER {here.name} revokes delegation chain");
        }
        visit [-->];
    }

    can revoke_manager with Manager entry {
        if self.invalidating {
            self.revoked = self.revoked + [here.name];
            print(f"  Manager {here.name} authority '{here.authority}' invalidated");
            here.authority = "revoked";
        }
        visit [-->];
    }

    can revoke_exec with Executor entry {
        if self.invalidating {
            print(f"    Executor {here.name} bound task '{here.bound_task}' cancelled");
            here.bound_task = "cancelled";
        }
    }

    can revoke_review with Reviewer entry {
        if self.invalidating {
            print(f"    Reviewer {here.name} stand-down");
        }
    }
}

with entry {
    owner = Owner(name="alice");

    a = Manager(name="A", authority="investigate-and-prepare", child_count=2);
    b = Manager(name="B", authority="investigate", child_count=1);
    c = Manager(name="C", authority="investigate", child_count=1);

    exec_b = Executor(name="ExecB", bound_task="scan-candidate");
    rev_b = Reviewer(name="RevB");
    exec_c = Executor(name="ExecC", bound_task="draft-proposal");
    rev_c = Reviewer(name="RevC");

    owner +>:Parents(lineage_ref="root"):+> a;
    a +>:Delegates(handoff="[MANAGER->MANAGER]"):+> b;
    a +>:Delegates(handoff="[MANAGER->MANAGER]"):+> c;
    b +>:BoundedTask(scope="scan"):+> exec_b;
    b +>:Reviews(stage="initial"):+> rev_b;
    c +>:BoundedTask(scope="draft"):+> exec_c;
    c +>:Reviews(stage="final"):+> rev_c;

    root ++> owner;

    print("=== Lineage Audit ===");
    LineageAuditor(max_depth=8) spawn root;

    print("\n=== Cascade Invalidation ===");
    CascadeInvalidator() spawn root;

    print(f"\nFinal revoked set: cycle terminated cleanly on detached graph");
}
```

```jac
"""Qualification slice gate: models the real-device/accessibility/responsive
qualification outcome chain for a release slice. Walks an immutable
evidence chain to verify that every release gate (real-device, accessibility,
responsive, performance) has been satisfied before the slice can ship.

Entities (nodes): Slice, Gate, Evidence, SignOff.
Relationships (typed edges): DependsOn (gates require gates), Proves
(evidence proves a gate), SignedBy (sign-off references evidence).
Walkers:
  - QualifyGate performs depth-bounded gate resolution with cycle
    protection (the manual recursion over a hand-rolled adjacency map).
  - CascadeInvalidate walks the graph and flags every unsatisfied gate.
"""

node Slice {
    has title: str = "";
    has version: str = "";
}

node Gate {
    has title: str = "";
    has category: str = "";
    has threshold: str = "";
    has satisfied: bool = False;
}

node Evidence {
    has label: str = "";
    has kind: str = "";
    has passed: bool = False;
}

node SignOff {
    has reviewer: str = "";
    has reviewer_role: str = "qa";
    has verdict: str = "pending";
}

edge DependsOn { has weight: int = 1; }
edge Proves { has strength: int = 1; }
edge SignedBy { has role: str = "qa"; }

walker QualifyGate {
    has seen: list[str] = [];
    has max_depth: int = 8;
    has failures: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can arrive with Slice entry {
        print(f"[slice] {here.title} v{here.version} -- starting gate qualification");
        visit [-->] else { disengage; }
    }

    can resolve with Gate entry {
        next_label = here.title + ":" + str(len(self.seen));
        if next_label in self.seen {
            self.failures.append(f"cycle at {here.title}");
            disengage;
        }
        self.seen.append(next_label);

        if len(self.seen) > self.max_depth {
            self.failures.append(f"depth-cap hit at {here.title}");
            disengage;
        }

        verdict = "PASS" if here.satisfied else "FAIL";
        print(f"  [gate] {here.category:>11} :: {here.title:<35} threshold={here.threshold:<10} -> {verdict}");

        if not here.satisfied {
            self.failures.append(here.title);
            visit [-->] else { disengage; };
            next_seen = [s for s in self.seen if s != next_label];
            self.seen = next_seen;
            report {"gate": here.title, "status": verdict};
            disengage;
        }

        visit [-->];
        next_seen = [s for s in self.seen if s != next_label];
        self.seen = next_seen;
        report {"gate": here.title, "status": verdict};
    }

    can collect_evidence with Evidence entry {
        verdict = "PASS" if here.passed else "FAIL";
        print(f"    [evidence] {here.kind:<14} {here.label:<30} -> {verdict}");
        if not here.passed {
            self.failures.append(f"evidence:{here.label}");
        }
        visit [-->];
    }

    can record with SignOff entry {
        print(f"      [signoff] reviewer={here.reviewer} role={here.reviewer_role} verdict={here.verdict}");
        if here.verdict != "approved" {
            self.failures.append(f"signoff:{here.reviewer}");
        }
        visit [-->];
    }
}

walker CascadeInvalidate {
    has stale_keys: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can pass_through with Slice entry {
        visit [-->];
    }

    can invalidate with Gate entry {
        if not here.satisfied {
            self.stale_keys.append(here.title);
            print(f"[invalidate] {here.title}");
        }
        visit [-->];
    }
}

with entry {
    # Build the release slice graph
    slice = Slice(title="Qualification slice", version="1.0.0");

    # Gates (the things that must pass before the release can ship)
    g_real = Gate(title="real_device_android", category="real-device", threshold=">=95% journeys", satisfied=True);
    g_real_ios = Gate(title="real_device_ios", category="real-device", threshold=">=95% journeys", satisfied=True);
    g_a11y = Gate(title="wcag_22_aa", category="accessibility", threshold="0 P1 violations", satisfied=True);
    g_resp = Gate(title="responsive_layout", category="responsive", threshold="<=1 layout break", satisfied=True);
    g_perf = Gate(title="latency_budget", category="performance", threshold="p95<=400ms", satisfied=True);

    # Evidence that proves each gate
    e_android = Evidence(label="android-physical-pixel7", kind="device-run", passed=True);
    e_ios = Evidence(label="ios-physical-iphone15", kind="device-run", passed=True);
    e_a11y = Evidence(label="axe-scan-checkout", kind="a11y-audit", passed=True);
    e_resp = Evidence(label="viewport-320-screenshot", kind="responsive", passed=True);
    e_perf = Evidence(label="k6-spike-200rps", kind="perf-trace", passed=True);

    # Sign-offs
    s_qa = SignOff(reviewer="alice", reviewer_role="qa", verdict="approved");
    s_eng = SignOff(reviewer="bob", reviewer_role="eng-lead", verdict="approved");

    # Wire the graph: root -> slice -> gates -> evidence -> sign-offs
    root ++> slice;

    slice +>:DependsOn:+> g_real;
    slice +>:DependsOn:+> g_real_ios;
    slice +>:DependsOn:+> g_a11y;
    slice +>:DependsOn:+> g_resp;
    slice +>:DependsOn:+> g_perf;

    g_real +>:Proves(strength=3):+> e_android;
    g_real_ios +>:Proves(strength=3):+> e_ios;
    g_a11y +>:Proves(strength=2):+> e_a11y;
    g_resp +>:Proves(strength=2):+> e_resp;
    g_perf +>:Proves(strength=2):+> e_perf;

    e_android +>:SignedBy(role="qa"):+> s_qa;
    e_ios +>:SignedBy(role="qa"):+> s_qa;
    e_a11y +>:SignedBy(role="qa"):+> s_qa;
    e_resp +>:SignedBy(role="eng"):+> s_eng;
    e_perf +>:SignedBy(role="eng"):+> s_eng;

    print("=== Running gate qualification walker ===");
    root spawn QualifyGate(max_depth=8);

    print("\n=== Running invalidation cascade (after dropping perf evidence) ===");
    e_perf.passed = False;
    g_perf.satisfied = False;
    root spawn CascadeInvalidate();

    print("\n=== Re-running gate qualification after regression ===");
    root spawn QualifyGate(max_depth=8);
}
