```jac
"""Plan Files blast-radius audit: pre-dispatch check that a plan's declared
Files block matches the symbols its steps actually touch.

Models the FootageOrganizer3 Wave 3 scenario where a plan's declared file
list undercounted the change's true blast radius (files outside the block
that share scope with declared ones via same-class or caller-of-symbol
relationships). The audit walker scans a plan's declared Files, gathers
the symbols the steps reference, and flags any related file that is
missing from the declared block — the missing-before-dispatch check the
issue asks for.
"""

# ── Archetypes ───────────────────────────────────────────────────────────

node Symbol {
    has name: str = "";
    has kind: str = "function";
}

node File {
    has path: str = "";
    has module_name: str = "";
    has declared: bool = False;
}

node Plan {
    has title: str = "";
    has declared_files: list[str] = [];
    has flagged: list[str] = [];
}

# ── Typed edges (the relationship carries meaning) ───────────────────────

edge Declares {
    has role: str = "primary";
}

edge Defines {
}

edge Calls {
}

edge SharesScope {
    has reason: str = "";
}

# ── Walker: the pre-dispatch blast-radius audit ──────────────────────────

walker BlastRadiusAuditor {
    has `report: list[str] = [];

    can start with Root entry {
        visit [-->] else { disengage; }
        plans = [-->][?:Plan];
        if not plans {
            print("No plan to audit.");
            disengage;
        }
        plan_node = plans[0];
        print(f"Auditing plan: '{plan_node.title}'");
        print(f"  declared Files ({len(plan_node.declared_files)}): "
              f"{plan_node.declared_files}");
    }

    can audit_plan with Plan entry {
        visit [-->];
    }

    can audit_file with File entry {
        if not here.declared {
            visit [-->];
            disengage;
        }

        touched: list[str] = [];
        for sym_node in [-->][?:Symbol] {
            touched.append(sym_node.name);
        }
        print(f"  declared file '{here.path}' touches symbols: {touched}");

        for related in [-->][?:File] {
            if not related.declared and related.path not in self.`report {
                self.`report.append(related.path);
                print(f"    [MISSING] shares scope with '{here.path}': "
                      f"'{related.path}'");
            }
        }
        visit [-->];
    }

    can audit_symbol with Symbol entry {
        for home_file in [-->][?:File] {
            if not home_file.declared and home_file.path not in self.`report {
                self.`report.append(home_file.path);
                print(f"    [MISSING] symbol '{here.name}' resolves to "
                      f"undeclared file '{home_file.path}'");
            }
        }
        visit [-->];
    }
}

# ── Demo wiring ──────────────────────────────────────────────────────────

with entry {
    plan = Plan(
        title="Wave 3 player-transport cycle",
        declared_files=["src/transport.py", "src/player.py"]
    );

    transport_py = File(path="src/transport.py", module_name="transport", declared=True);
    player_py    = File(path="src/player.py",    module_name="player",    declared=True);
    audio_py     = File(path="src/audio.py",     module_name="audio",     declared=False);

    sym_transport_load   = Symbol(name="load_player",   kind="function");
    sym_transport_unload = Symbol(name="unload_player", kind="function");
    sym_player_tick      = Symbol(name="Player.tick",   kind="method");
    sym_audio_play       = Symbol(name="play",          kind="function");

    plan +>:Declares(role="primary"):+> transport_py;
    plan +>:Declares(role="primary"):+> player_py;

    transport_py +>:Defines:+> sym_transport_load;
    transport_py +>:Defines:+> sym_transport_unload;
    player_py    +>:Defines:+> sym_player_tick;

    sym_player_tick +>:Calls:+> sym_audio_play;
    sym_audio_play  +>:Defines:+> audio_py;

    player_py +>:SharesScope(reason="player-runtime"):+> audio_py;

    root ++> plan;
    auditor = BlastRadiusAuditor();
    root spawn auditor;

    plan.flagged = auditor.`report;
    print("");
    print("=== PRE-DISPATCH BLAST-RADIUS REPORT ===");
    print(f"Plan: {plan.title}");
    print(f"Declared files: {plan.declared_files}");
    print(f"Missing from Files block: {plan.flagged}");
    if len(plan.flagged) > 0 {
        print("BLOCK DISPATCH: blast radius exceeds declared scope.");
    } else {
        print("DISPATCH OK: declared block covers the change.");
    }
}
