```jac
"""LMCache Session hash-reuse control-path demo.

Models the request-scoped Session that owns rolling token-hash state used by
lookup and store/retrieve. The Session keeps the full token sequence plus one
rolling hash per complete chunk, so store/retrieve over an unchanged prefix
needs zero extra hash operations, an extension only hashes newly completed
chunks, and a changed or shortened prefix invalidates incompatible state.
"""

# ---- Nodes ---------------------------------------------------------------

node TokenHasher {
    has chunk_size: int = 4;
    has ops: int = 0;

    def compute_chunk_hashes(token_ids: list, start: int, end: int) -> list {
        out: list = [];
        i = start;
        while i < end {
            self.ops += 1;
            out.append((i, token_ids[i]));
            i += self.chunk_size;
        }
        return out;
    }
}

node Session {
    has request_id: str = "";
    has tokens: list = [];
    has rolling_hashes: list = [];
    has hasher: TokenHasher | None = None;

    def set_tokens_and_get_hashes(full_token_ids: list) -> list {
        if self.hasher is None {
            self.tokens = list(full_token_ids);
            self.rolling_hashes = [];
            return [];
        }
        chunk = self.hasher.chunk_size;
        limit = len(self.tokens);
        if len(full_token_ids) < limit {
            limit = len(full_token_ids);
        }
        common = 0;
        while common < limit and self.tokens[common] == full_token_ids[common] {
            common += 1;
        }
        keep = common // chunk;
        if keep > len(self.rolling_hashes) {
            keep = len(self.rolling_hashes);
        }
        self.rolling_hashes = self.rolling_hashes[:keep];
        self.tokens = list(full_token_ids);
        end = (len(self.tokens) // chunk) * chunk;
        start = keep * chunk;
        if start < end {
            self.rolling_hashes += self.hasher.compute_chunk_hashes(
                self.tokens, start, end
            );
        }
        return list(self.rolling_hashes);
    }

    def get_hashes(start: int, end: int) -> list {
        if self.hasher is None {
            return [];
        }
        chunk = self.hasher.chunk_size;
        complete = (len(self.tokens) // chunk) * chunk;
        need = end;
        if need > complete {
            need = complete;
        }
        pos = len(self.rolling_hashes) * chunk;
        if pos < need {
            self.rolling_hashes += self.hasher.compute_chunk_hashes(
                self.tokens, pos, need
            );
        }
        return list(self.rolling_hashes[start // chunk : end // chunk]);
    }
}

node Request {
    has rid: str = "";
    has session: Session | None = None;
    has hasher: TokenHasher | None = None;
}

# ---- Edges ---------------------------------------------------------------

edge OwnedBy { }
edge Reuses { }

# ---- Walker --------------------------------------------------------------

walker HashReuseAuditor {
    has scenario: str = "lookup_then_store";
    has lookup_tokens: list = [];
    has store_tokens: list = [];
    has `report: dict = {};

    can start with Root entry {
        self.report = {};
        visit [-->];
    }

    can audit with Request entry {
        if (here.hasher is not None) and (here.session is not None) {
            here.session.hasher = here.hasher;
            chunk = here.hasher.chunk_size;

            if self.scenario == "lookup_then_store" {
                hashes = here.session.set_tokens_and_get_hashes(self.lookup_tokens);
                before = here.hasher.ops;
                stored = here.session.get_hashes(0, len(hashes) * chunk);
                self.report["scenario"] = "lookup_then_store";
                self.report["lookup_hashes"] = len(hashes);
                self.report["hash_ops"] = here.hasher.ops;
                self.report["store_extra_ops"] = here.hasher.ops - before;
            } elif self.scenario == "extension" {
                here.session.set_tokens_and_get_hashes(self.lookup_tokens);
                before = here.hasher.ops;
                here.session.set_tokens_and_get_hashes(self.store_tokens);
                self.report["scenario"] = "extension";
                self.report["new_chunks"] = (
                    len(self.store_tokens) - len(self.lookup_tokens)
                ) // chunk;
                self.report["hash_ops"] = here.hasher.ops;
                self.report["delta_ops"] = here.hasher.ops - before;
            } elif self.scenario == "changed_prefix" {
                here.session.set_tokens_and_get_hashes(self.lookup_tokens);
                before = here.hasher.ops;
                here.session.set_tokens_and_get_hashes(self.store_tokens);
                self.report["scenario"] = "changed_prefix";
                self.report["hash_ops"] = here.hasher.ops;
                self.report["delta_ops"] = here.hasher.ops - before;
            }
        }
        visit [-->] else { disengage; }
    }
}

# ---- Demo -----------------------------------------------------------------

with entry {
    hasher = TokenHasher(chunk_size=4);
    session = Session(request_id="req-1");
    req = Request(rid="req-1", session=session, hasher=hasher);
    req +>:OwnedBy:+> hasher;
    session +>:Reuses:+> hasher;
    root ++> req;

    base = [1, 2, 3, 4, 5, 6, 7, 8];
    extended = base + [9, 10, 11, 12, 13, 14, 15, 16];
    changed = [0, 0, 0, 0, 5, 6, 7, 8];

    a = root spawn HashReuseAuditor(
        scenario="lookup_then_store", lookup_tokens=base, store_tokens=base
    );
    print("lookup_then_store", a.report);

    b = root spawn HashReuseAuditor(
        scenario="extension", lookup_tokens=base, store_tokens=extended
    );
    print("extension", b.report);

    c = root spawn HashReuseAuditor(
        scenario="changed_prefix", lookup_tokens=base, store_tokens=changed
    );
    print("changed_prefix", c.report);
}
