"""Branch hygiene model: branches as nodes, audit a graph of merge/PR state with walkers.

Models the branch-hygiene report: each branch is a node, edges encode
merge-PR relationships, and a walker traverses the dependency graph to
classify branches into safe-to-delete / keep / review buckets.
"""

node Branch {
    has name: str = "";
    has last_commit: str = "";
    has ahead_of_main: int = 0;
    has verdict: str = "unreviewed";
}

node PullRequest {
    has pr_id: int = 0;
    has status: str = "draft";
    has category: str = "";
}

edge MergedInto {
    has merged_on: str = "";
    has via_pr: int = 0;
}

edge TrackedBy {
    has pr_id: int = 0;
}

edge SupersededBy {
    has reason: str = "";
}

walker BranchAuditor {
    has safe_to_delete: list[str] = [];
    has keep_branches: list[str] = [];
    has review_branches: list[str] = [];

    can start with Root entry {
        print("=== Branch Hygiene Audit ===");
        visit [-->] else { disengage; }
    }

    can audit with Branch entry {
        bucket = "review";
        if here.verdict == "merged" {
            bucket = "safe";
            self.safe_to_delete.append(here.name);
        } elif here.verdict == "tracked" {
            bucket = "keep";
            self.keep_branches.append(here.name);
        } else {
            self.review_branches.append(here.name);
        }
        print(f"[{bucket.upper()}] {here.name} (last commit {here.last_commit})");
    }
}

with entry {
    # Merged branches - safe to delete
    b1 = Branch(name="automated/firebase-optimization", last_commit="2026-05-03", verdict="merged");
    b2 = Branch(name="feature/beta-testing-workflow", last_commit="2026-02-10", verdict="merged");
    b3 = Branch(name="fix/blank-screen-missing-env-vars", last_commit="2026-03-11", verdict="merged");

    # Tracked branches - keep (have open PRs)
    b4 = Branch(name="claude/issue-15-20260610-1900", last_commit="2026-06-10", verdict="tracked");
    b5 = Branch(name="copilot/branch-hygiene-report-2026-06-08", last_commit="2026-06-08", verdict="tracked");

    # Orphaned - review needed
    b6 = Branch(name="fix/audit-criticals", last_commit="2026-05-09", ahead_of_main=1, verdict="orphaned");
    b7 = Branch(name="feature/certification-system", last_commit="2026-05-09", ahead_of_main=1, verdict="orphaned");
    b8 = Branch(name="claude/session-start-hook-3Pk8d", last_commit="2026-07-01", ahead_of_main=1, verdict="orphaned");

    # Pull requests tracking optimizer branches
    pr1 = PullRequest(pr_id=26, status="draft", category="dead-code");
    pr2 = PullRequest(pr_id=31, status="draft", category="performance");
    pr3 = PullRequest(pr_id=42, status="draft", category="security");

    # Build the graph: root -> branches
    root ++> b1;
    root ++> b2;
    root ++> b3;
    root ++> b4;
    root ++> b5;
    root ++> b6;
    root ++> b7;
    root ++> b8;

    # Merged branches connect to root (representing main) via MergedInto edge
    b1 +>:MergedInto(merged_on="2026-05-09", via_pr=8):+> root;
    b2 +>:MergedInto(merged_on="2026-02-15", via_pr=0):+> root;
    b3 +>:MergedInto(merged_on="2026-03-20", via_pr=0):+> root;

    # Tracked branches connect to their PRs
    b4 +>:TrackedBy(pr_id=26):+> pr1;
    b5 +>:TrackedBy(pr_id=16):+> pr2;

    # Superseded relationship
    b6 +>:SupersededBy(reason="salvaged into PR #26"):+> pr1;

    # Run the audit
    root spawn BranchAuditor();
}
