```jac
"""Normative hierarchy: an ancestor rule governs every descendant.

Models the load-bearing scenario from issue #447 — retrieval over a tree
where a rule placed at a parent node constrains every node beneath it,
regardless of whether the descendant mentions the rule. A walker descends
the hierarchy, collects every inherited constraint, and detects cycles
that would otherwise let an ancestor reach itself through descendants.
"""

node Policy {
    has title: str = "";
    has rule: str = "";
}

node Category {
    has title: str = "";
}

node Document {
    has title: str = "";
    has summary: str = "";
}

edge Governs {
    has since: str = "";
}

edge BelongsTo {
}

edge Contains {
}

walker InheritanceAuditor {
    has visited: list[str] = [];
    has inherited_rules: list[tuple[str, str]] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        print("Inheritance audit over normative hierarchy");
        visit [-->];
    }

    can descend with Category entry {
        if here.title in self.visited {
            self.cycle_found = True;
            print(f"  cycle detected: re-entering {here.title}");
            disengage;
        }
        self.visited.append(here.title);
        visit [->:Governs:->];
    }

    can descend_doc with Document entry {
        if here.title in self.visited {
            self.cycle_found = True;
            print(f"  cycle detected: re-entering {here.title}");
            disengage;
        }
        self.visited.append(here.title);
        visit [->:Governs:->];
    }

    can collect with Policy entry {
        pair = (here.title, here.rule);
        self.inherited_rules.append(pair);
        print(f"  inherited rule [{here.title}]: {here.rule}");
    }
}

walker ReachabilityProbe {
    has target: str = "";
    has found: bool = False;

    can start with Root entry {
        print(f"Reachability probe: can {self.target} be reached from root?");
        visit [-->];
    }

    can descend with Category entry {
        if here.title == self.target {
            self.found = True;
            print(f"  reached target node: {self.target}");
            disengage;
        }
        visit [-->];
    }

    can descend_doc with Document entry {
        if here.title == self.target {
            self.found = True;
            print(f"  reached target node: {self.target}");
            disengage;
        }
        visit [-->];
    }
}

with entry {
    root ++> Category(title="regulated-products");

    excluded = Policy(title="exclusion-note",
                      rule="No health claims may appear in any descendant document");
    root +>:Governs(since="2023-01"):+> excluded;

    electronics = Category(title="electronics");
    software = Category(title="software");
    root ++> electronics ++> software;

    excluded +>:Governs(since="2023-01"):+> electronics;
    excluded +>:Governs(since="2023-01"):+> software;

    user_manual = Document(title="user-manual",
                           summary="How to pair the device over Bluetooth");
    datasheet = Document(title="datasheet",
                         summary="Voltage ratings and pinouts");
    app_guide = Document(title="app-guide",
                         summary="Configuring the companion mobile app");

    electronics +>:Contains:+> user_manual;
    electronics +>:Contains:+> datasheet;
    software +>:Contains:+> app_guide;

    excluded +>:Governs(since="2023-01"):+> user_manual;
    excluded +>:Governs(since="2023-01"):+> datasheet;
    excluded +>:Governs(since="2023-01"):+> app_guide;

    orphan_doc = Document(title="marketing-brochure",
                          summary="Marketing copy with no normative parent");
    root +>:BelongsTo:+> orphan_doc;

    auditor = InheritanceAuditor();
    root spawn auditor;
    print(f"audit collected {len(auditor.inherited_rules)} inherited rules");
    print(f"audit cycle detected: {auditor.cycle_found}");

    probe = ReachabilityProbe(target="app-guide");
    root spawn probe;
    print(f"probe found {probe.target}: {probe.found}");

    orphan_probe = ReachabilityProbe(target="nonexistent-doc");
    root spawn orphan_probe;
    print(f"probe found {orphan_probe.target}: {orphan_probe.found}");
}
