```jac
"""Kanban task tree with persisted parent runtime anchor.

Models the essential scenario from SL4: nested tasks form a parent/child
tree via typed ``ParentOf`` edges. The first keep-alive on a nested child
sets the parent's ``runtime_started_at`` once and bumps its generation;
later nested activity must not re-anchor. Completion, reassignment, or
deletion of the parent clears the anchor. A walker audits the tree and
reports which parents are anchored and on which generation they sit,
traversing each task exactly once via typed ``ParentOf`` edges only.
"""

# --- Entity archetypes -----------------------------------------------------

node Task {
    has title: str = "";
    has assignee: str = "";
    has state: str = "open";        # open | in_progress | done | blocked
    has depth: int = 0;
    # Parent runtime anchor fields (inert on non-nested tasks).
    has runtime_started_at: str = "";   # ISO-ish stamp; "" means unanchored
    has generation: int = 0;

    def clear_anchor() -> str {
        cleared = self.runtime_started_at != "";
        self.runtime_started_at = "";
        self.generation = 0;
        label = "cleared" if cleared else "already empty";
        return f"[CLEAR] {self.title}: {label}";
    }

    def first_anchor(child_title: str) -> str {
        if self.runtime_started_at == "" {
            self.runtime_started_at = "2025-01-01T00:00:00Z";
            self.generation = self.generation + 1;
            return (f"[ANCHORED] parent={self.title} gen={self.generation} "
                    f"by child={child_title}");
        }
        return (f"[kept] parent={self.title} gen={self.generation} "
                f"child={child_title} did NOT re-anchor");
    }
}

# --- Typed edges -----------------------------------------------------------

edge ParentOf {
    # Slot in the parent's child list (preserves declaration order).
    has slot: int = 0;
}

# --- Audit walker ----------------------------------------------------------

walker ParentAnchorAuditor {
    has report_lines: list[str] = [];

    can start with Root entry {
        self.report_lines = [];
        visit [-->];
    }

    can audit with Task entry {
        # Audit this task exactly once, then descend only via typed
        # ParentOf edges so we never re-visit or cross-tree-walk.
        label = here.first_anchor(here.title);
        self.report_lines.append(label);
        visit [->:ParentOf:->] else { self.report_lines; };
    }
}

# --- Cascade-clear walker --------------------------------------------------

walker CascadeClear {
    has cleared_lines: list[str] = [];

    can start with Root entry {
        self.cleared_lines = [];
        visit [-->];
    }

    can cascade with Task entry {
        # Reassignment / archive / delete on a parent clears its anchor;
        # cascade only along typed ParentOf edges.
        self.cleared_lines.append(here.clear_anchor());
        visit [->:ParentOf:->] else { self.cleared_lines; };
    }
}

# --- Demo wiring -----------------------------------------------------------

with entry {
    # Build a small tree:
    #   root -> Epic -> [StoryA, StoryB] -> [TaskA1, TaskA2, TaskB1]
    epic = Task(title="Epic", assignee="alice", depth=1);
    story_a = Task(title="StoryA", assignee="bob", depth=2);
    story_b = Task(title="StoryB", assignee="carol", depth=2);
    task_a1 = Task(title="TaskA1", assignee="dan", depth=3);
    task_a2 = Task(title="TaskA2", assignee="dan", depth=3);
    task_b1 = Task(title="TaskB1", assignee="erin", depth=3);

    root ++> epic;
    epic +>:ParentOf(slot=0):+> story_a;
    epic +>:ParentOf(slot=1):+> story_b;
    story_a +>:ParentOf(slot=0):+> task_a1;
    story_a +>:ParentOf(slot=1):+> task_a2;
    story_b +>:ParentOf(slot=0):+> task_b1;

    # 1. First nested keep-alive anchors each parent once; the auditor
    #    visits every task exactly once via ParentOf edges only.
    auditor = ParentAnchorAuditor();
    root spawn auditor;
    for line in auditor.report_lines {
        print(line);
    }

    # 2. Reassignment / archive of the Epic clears its anchor; nested
    #    max-runtime readers will see "no anchor" again.
    epic.assignee = "frank";          # explicit assignee change
    clearer = CascadeClear();
    root spawn clearer;
    for line in clearer.cleared_lines {
        print(line);
    }

    # 3. Ordinary (non-nested) tasks remain attempt-scoped: their anchor
    #    fields stay empty and generation stays 0.
    print(f"[non-nested] {epic.title} runtime_started_at="
          f"'{epic.runtime_started_at}' gen={epic.generation}");
}
