```jac
"""OpenMS ownership-policy audit walker.

Models the essential scenario from OpenMS issue #9792: pyOpenMS bindings
have no coherent copy-vs-alias semantics. Each element accessor must be
classified as OwnedCopy, AliasView, or CachedSingleton, and the rules
(``get_*`` => owned, ``*_view`` => alias under keep-alive, singletons
detached from the registry) must be enforced by walking the binding
graph and flagging violations.
"""

node Binding {
    has name: str = "";
    has category: str = "";      # OwnedCopy | AliasView | CachedSingleton
    has returns_alias: bool = False;
    has keep_alive: bool = False;
    has follows_rule: bool = True;
}

node Param {
    has name: str = "";
    has is_singleton: bool = False;
    has detached: bool = False;
}

edge Returns { }
edge Holds { }
edge ReturnsView {
    has keep_alive: bool = True;
}

walker OwnershipAuditor {
    has violations: list = [];
    has audited: int = 0;

    can begin with Root entry {
        print(f"=== Ownership audit starting ===");
        visit [-->];
    }

    can audit_param with Param entry {
        # Singletons must be detached from any global registry, otherwise
        # callers receive an aliased reference whose lifetime they do
        # not own -- the exact use-after-free class #9794 fixed.
        if here.is_singleton and not here.detached {
            self.violations = self.violations + [
                f"[V-9] singleton '{here.name}' is still attached to the registry"
            ];
        }
        visit [-->];
    }

    can audit_binding with Binding entry {
        self.audited = self.audited + 1;
        name = here.name;
        # Rule R-1: get_* accessors must return owned copies, never aliases.
        if name.startswith("get_") and here.returns_alias {
            self.violations = self.violations + [
                f"[R-1] '{name}' is a get_* that returns an alias"
            ];
            here.follows_rule = False;
        }
        # Rule R-3: aliases must be opt-in; bare getters must not alias.
        # Only fires when R-1 did not already cover this binding (R-1 is
        # more specific for get_* accessors and supersedes R-3).
        elif here.returns_alias and not here.keep_alive and not name.endswith("_view") {
            self.violations = self.violations + [
                f"[R-3] '{name}' returns an alias without an opt-in name"
            ];
            here.follows_rule = False;
        }
        # Rule R-2: *_view accessors may alias only if paired with keep-alive.
        if name.endswith("_view") and here.returns_alias and not here.keep_alive {
            self.violations = self.violations + [
                f"[R-2] '{name}' aliases without keep-alive contract"
            ];
            here.follows_rule = False;
        }
        status = "OK" if here.follows_rule else "FAIL";
        print(f"  [{status}] {here.name} -> {here.category}");
        visit [-->];
    }

    can summarize with Root exit {
        print(f"=== Audit complete: {self.audited} bindings, "
              f"{len(self.violations)} violations ===");
        for v in self.violations {
            print(f"  {v}");
        }
    }
}

with entry {
    # --- a clean Param registry -----------------------------------------
    detached_cv = Param(name="CVTerm", is_singleton=True, detached=True);
    attached_cv = Param(name="LegacyCV", is_singleton=True, detached=False);
    root ++> detached_cv;
    root ++> attached_cv;

    # --- the binding surface (#9947 reference shape) --------------------
    good_getter = Binding(name="get_intensity", category="OwnedCopy");
    good_view = Binding(
        name="spectrum_view", category="AliasView",
        returns_alias=True, keep_alive=True
    );
    bad_getter = Binding(
        name="get_peaks_ref", category="AliasView",
        returns_alias=True, keep_alive=False
    );
    bad_unnamed_alias = Binding(
        name="fetch_meta", category="AliasView",
        returns_alias=True, keep_alive=False
    );
    bare_view_no_keepalive = Binding(
        name="mz_view", category="AliasView",
        returns_alias=True, keep_alive=False
    );

    # Param -> Binding relationship: a param "holds" its accessors.
    detached_cv +>:Holds:+> good_getter;
    detached_cv +>:Holds:+> good_view;
    attached_cv +>:Holds:+> bad_getter;
    attached_cv +>:Holds:+> bad_unnamed_alias;
    attached_cv +>:Holds:+> bare_view_no_keepalive;

    # --- spawn the auditor on the root graph ----------------------------
    root spawn OwnershipAuditor();
}
```

```jac
"""Recursive indexing of a package folder: walk a folder tree, inventory files,
detect stale derived artifacts, and report unsupported content."""

# ------------------------------------------------------------------
# Entity archetypes
# ------------------------------------------------------------------

node Folder {
    has name: str = "";
}

node File {
    has rel_path: str = "";
    has media_type: str = "";
    has size: int = 0;
    has sha256: str = "";
    has source_sha256: str = "";
}

# ------------------------------------------------------------------
# Edge archetypes
# ------------------------------------------------------------------

edge Contains { }      # Folder -> child Folder or File (tree membership)
edge DerivedFrom { }   # DerivedFile -> source File (provenance)

# ------------------------------------------------------------------
# Walker: indexes the folder tree starting from a chosen root folder.
# ------------------------------------------------------------------

walker Indexer {
    has visited: list[str] = [];
    has unsupported: list[str] = [];
    has stale: list[str] = [];

    can start with Root entry {
        print("Indexing package from root...");
        visit [-->];
    }

    # Descend into any folder node the walker reaches.
    can descend with Folder entry {
        guard_key = f"F:{here.name}";
        if guard_key in self.visited {
            disengage;
        }
        self.visited.append(guard_key);
        print(f"  enter folder: {here.name}");
        visit [->:Contains:->];
    }

    # Leaf File nodes (both raw sources and derived artifacts share the
    # File archetype — the only differing field is source_sha256).
    can inspect with File entry {
        key = f"X:{here.rel_path}";
        if key in self.visited {
            disengage;
        }
        self.visited.append(key);

        if here.media_type == "unsupported" {
            self.unsupported.append(here.rel_path);
            print(f"  [UNSUPPORTED] {here.rel_path}");
        } elif here.source_sha256 != "" {
            # Derived artifact — compare recorded source SHA against the
            # current source SHA reachable through the DerivedFrom edge.
            current_source: str | None = None;
            for src in [->:DerivedFrom:->] {
                current_source = src.sha256;
                break;
            }
            if current_source is not None and current_source != here.source_sha256 {
                self.stale.append(here.rel_path);
                stale_label = "STALE";
                print(f"  [{stale_label}] {here.rel_path} (recorded={here.source_sha256}, current={current_source})");
            } else {
                fresh_label = "DERIVED";
                print(f"  [{fresh_label}] {here.rel_path}");
            }
        } else {
            source_label = "SOURCE";
            print(f"  [{source_label}] {here.rel_path} ({here.media_type}, {here.size}B, sha={here.sha256})");
        }

        visit [->:DerivedFrom:->];
    }
}

# ------------------------------------------------------------------
# Demonstration graph
# ------------------------------------------------------------------

with entry {
    # Build a small package tree:
    #   package/
    #     docs/                       (folder)
    #       ruling.pdf                (source, application/pdf)
    #       ruling.pdf.casegraph.yaml(sidecar declaring extraction policy)
    #       ruling.md                 (derived from ruling.pdf)
    #       ruling.md.casegraph.yaml  (derived sidecar — stale: wrong sha)
    #     notes.txt                   (text/plain — supported)
    #     blob.bin                    (unsupported media type)

    root_folder = Folder(name="package");
    docs = Folder(name="docs");

    ruling_pdf = File(
        rel_path="docs/ruling.pdf",
        media_type="application/pdf",
        size=2048,
        sha256="pdf-sha-abc"
    );
    ruling_pdf_yaml = File(
        rel_path="docs/ruling.pdf.casegraph.yaml",
        media_type="application/x-yaml",
        size=128,
        sha256="pdf-yaml-sha-xyz"
    );
    ruling_md = File(
        rel_path="docs/ruling.md",
        media_type="text/markdown",
        size=512,
        sha256="md-sha-111",
        source_sha256="pdf-sha-abc"
    );
    ruling_md_yaml = File(
        rel_path="docs/ruling.md.casegraph.yaml",
        media_type="application/x-yaml",
        size=96,
        sha256="md-yaml-sha-222",
        source_sha256="pdf-sha-OLD"
    );
    notes = File(
        rel_path="notes.txt",
        media_type="text/plain",
        size=42,
        sha256="notes-sha-333"
    );
    blob = File(
        rel_path="blob.bin",
        media_type="unsupported",
        size=9000,
        sha256="blob-sha-444"
    );

    # Tree structure via typed Contains edges.
    root_folder +>:Contains:+> docs;
    docs +>:Contains:+> ruling_pdf;
    docs +>:Contains:+> ruling_pdf_yaml;
    docs +>:Contains:+> ruling_md;
    docs +>:Contains:+> ruling_md_yaml;
    root_folder +>:Contains:+> notes;
    root_folder +>:Contains:+> blob;

    # Provenance: derived artifacts point back to their source PDF.
    ruling_md +>:DerivedFrom:+> ruling_pdf;
    ruling_md_yaml +>:DerivedFrom:+> ruling_pdf;

    # Anchor the demo on a local root so the shared `root` stays clean
    # for the regression harness.
    demo_root = root;
    demo_root ++> root_folder;
    idx = Indexer();
    demo_root spawn idx;

    print("\n--- Indexer summary ---");
    print(f"visited nodes : {len(idx.visited)}");
    print(f"unsupported   : {idx.unsupported}");
    print(f"stale derivs  : {idx.stale}");
}
