```jac
"""Role hierarchy demo: model tenant-scoped roles as a tree, validate moves
(detect cycles, prevent self-moves), and walk the hierarchy to compute
permission scope for a given role.

Entities:
- Tenant: an organization that owns roles.
- Role: a role node inside one tenant; linked into the tree by ReportsTo
  edges that also carry the sibling sort_order.

Walkers:
- HierarchyDump: prints the tree rooted at the Organization role for a
  tenant, computing descendant reachability via the ReportsTo edges.
- ScopeInspector: spawned on a Role, collects every descendant role the
  role's branch contains, demonstrating branch-scoped permission
  reasoning without any hand-rolled adjacency plumbing.
- DescendantProbe: collects the descendant Role nodes under a role so
  move validation can detect cycles.
- MoveValidator: walks the tenant's role tree looking for a target role,
  then applies the move-validation rules the issue calls out (no
  self-move, no cycles, the Organization role cannot be reparented) and
  reports a verdict.
"""

node Tenant {
    has name: str = "";
}

node Role {
    has title: str = "";
    has tenant_name: str = "";
    has archived: bool = False;
}

edge Contains { }
edge ReportsTo {
    has sort_order: int = 0;
}

walker HierarchyDump {
    has indent: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can show_tenant with Tenant entry {
        print(f"Tenant: {here.name}");
        visit [-->];
    }

    can show_role with Role entry {
        prefix = "  " * self.indent;
        org_marker = " [ORG-ROOT]" if here.title == "Organization" else "";
        print(f"{prefix}- {here.title}{org_marker}");
        self.indent += 1;
        visit [->:ReportsTo:->];
        self.indent -= 1;
    }
}

walker ScopeInspector {
    has branch: list[str] = [];

    can gather with Role entry {
        self.branch.append(here.title);
        visit [->:ReportsTo:->];
    }
}

walker DescendantProbe {
    has found: list[Role] = [];

    can collect with Role entry {
        self.found.append(here);
        visit [->:ReportsTo:->];
    }
}

walker MoveValidator {
    has target_title: str = "";
    has new_parent_title: str = "";
    has verdict: str = "";
    has detail: str = "";

    can start with Root entry {
        visit [-->];
    }

    can descend with Tenant entry {
        visit [-->];
    }

    can validate with Role entry {
        visit [-->];
        if here.title == self.target_title {
            reason = "";
            if here.title == self.new_parent_title {
                reason = "cannot move a role beneath itself";
            } elif here.title == "Organization" {
                reason = "the Organization role must stay at the root";
            } else {
                probe = DescendantProbe();
                here spawn probe;
                for d in probe.found {
                    if d.title == self.new_parent_title {
                        reason = "move would create a cycle";
                        break;
                    }
                }
            }
            if reason == "" {
                self.verdict = "ALLOWED";
                self.detail = f"move '{here.title}' under '{self.new_parent_title}' keeps the tree a DAG";
            } else {
                self.verdict = "REJECTED";
                self.detail = reason;
            }
            print(f"[MoveValidator] {self.verdict}: {self.detail}");
            disengage;
        }
    }
}

with entry {
    acme = Tenant(name="AcmeCRM");
    org = Role(title="Organization", tenant_name="AcmeCRM");
    admin_exec = Role(title="ADMIN/EXEC", tenant_name="AcmeCRM");
    exec_role = Role(title="Exec", tenant_name="AcmeCRM");
    sales_ops = Role(title="Sales Ops", tenant_name="AcmeCRM");
    ops_total = Role(title="Operations Total", tenant_name="AcmeCRM");
    partner_admin = Role(title="Partner Admin TEMPLATE", tenant_name="AcmeCRM");
    mobile_sage = Role(title="MobileSage", tenant_name="AcmeCRM");
    exagrow = Role(title="Exagrow", tenant_name="AcmeCRM");

    root ++> acme;
    acme +>:Contains:+> org;
    org +>:ReportsTo(sort_order=0):+> admin_exec;
    org +>:ReportsTo(sort_order=1):+> exec_role;
    exec_role +>:ReportsTo(sort_order=0):+> sales_ops;
    exec_role +>:ReportsTo(sort_order=1):+> ops_total;
    ops_total +>:ReportsTo(sort_order=0):+> partner_admin;
    ops_total +>:ReportsTo(sort_order=1):+> mobile_sage;
    ops_total +>:ReportsTo(sort_order=2):+> exagrow;

    print("=== Hierarchy dump for AcmeCRM ===");
    root spawn HierarchyDump();

    print("");
    print("=== ScopeInspector on 'Exec' ===");
    inspector = ScopeInspector();
    exec_role spawn inspector;
    print(f"branch reach: {inspector.branch}");

    print("");
    print("=== MoveValidator probes ===");
    root spawn MoveValidator(target_title="Sales Ops", new_parent_title="Operations Total");
    root spawn MoveValidator(target_title="Sales Ops", new_parent_title="Sales Ops");
    root spawn MoveValidator(target_title="Organization", new_parent_title="Exec");
    root spawn MoveValidator(target_title="MobileSage", new_parent_title="Operations Total");
    root spawn MoveValidator(target_title="Operations Total", new_parent_title="Partner Admin TEMPLATE");
}
