```jac
"""CI workflow build-graph composition: one heavy executor, one workspace.

Models the issue's build-state-reuse contract: product tasks that share
build state are connected to a single executor/workspace via typed edges,
and an auditor walker traverses the task graph, reusing workspace state
instead of rebuilding, and detecting revisits explicitly (jac walkers do
not dedupe visits on their own).
"""

node Task {
    has name: str = "";
    has heavy: bool = False;
}

node Workspace {
    has path: str = "";
}

node Executor {
    has label: str = "";
    has hosted: bool = True;
}

edge RunsOn {}
edge UsesState {}
edge DependsOn {}

walker BackendAuditor {
    has built: dict = {};
    has rebuilds_avoided: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit_executor with Executor entry {
        backend = "github-hosted" if here.hosted else "organization";
        print(f"executor [{here.label}] backend={backend}");
        visit [-->];
    }

    can run_task with Task entry {
        if here.name in self.built {
            print(f"skip {here.name}: already built (shared state reuse)");
        } else {
            self.built[here.name] = True;
            print(f"building {here.name}");
            self.rebuilds_avoided += 1;
            visit [-->];
        }
    }

    can touch_workspace with Workspace entry {
        print(f"reusing workspace {here.path} (no artifact round-trip)");
        visit [-->];
    }
}

with entry {
    gh = Executor(label="ubuntu-central", hosted=True);
    ws = Workspace(path="/workspace/src");
    lint = Task(name="lint", heavy=False);
    test = Task(name="test", heavy=True);
