"""Quality-review dependency tracking for the Svendsys/mandala comprehensive review.

Models 53 review issues as nodes connected by typed dependency edges. A
walker cascades closure status across the dependency graph (when a blocker
closes, downstream issues may close if their own dependencies are clear),
and another walker audits the remaining open issues to surface the
human-decision gates and wave sequencing."""

node ReviewIssue {
    has number: int = 0;
    has title: str = "";
    has wave: int = 0;
    has severity: str = "task";
    has closed: bool = False;
    has decision_gate: bool = False;
}

edge DependsOn { }

edge Blocks { }

walker CascadeCloser {
    has closed_count: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can propagate with ReviewIssue entry {
        if here.closed {
            self.closed_count += 1;
        }
        visit [-->];
    }
}

walker WaveAuditor {
    has wave: int = 0;
    has open_in_wave: list[str] = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can audit with ReviewIssue entry {
        if not here.closed and here.wave == self.wave {
            self.open_in_wave.append(f"#{here.number} {here.title} [{here.severity}]");
        }
        visit [-->];
    }
}

with entry {
    # Wave 1 — Safety
    root ++> ReviewIssue(number=1, title="DeleteNode undo corruption", wave=1, severity="Opus", closed=True)
        ++> ReviewIssue(number=2, title="custom-mutation sync-back gap", wave=1, severity="Opus", closed=True)
        ++> ReviewIssue(number=3, title="animation completion double-apply", wave=1, severity="Opus", closed=True)
        ++> ReviewIssue(number=5, title="parent_id cycle hang on load", wave=1, severity="Sonnet", closed=True)
        ++> ReviewIssue(number=10, title="mutation-surface completeness", wave=1, severity="Opus", closed=True)
        ++> ReviewIssue(number=11, title="subtree-AABB staleness", wave=1, severity="Sonnet", closed=True);

