    root ++> ReviewIssue(number=15, title="palette system: wire or re-document", wave=4, severity="Opus", closed=True, decision_gate=True)
        ++> ReviewIssue(number=32, title="keybind config SSOT", wave=4, severity="Opus", closed=True)
        ++> ReviewIssue(number=37, title="interaction rebuild tiers", wave=4, severity="Sonnet", closed=True);

    # Wave 5 — Documentation sweep (the remaining open work)
    root ++> ReviewIssue(number=50, title="API reference finalization", wave=5, severity="Sonnet", closed=False)
        ++> ReviewIssue(number=51, title="CHANGELOG reconciliation", wave=5, severity="Sonnet", closed=False)
        ++> ReviewIssue(number=52, title="Migration guide", wave=5, severity="Sonnet", closed=False)
