```jac
"""Build graph timing audit: model crates as nodes, dependencies as typed
DependsOn edges, and walk the graph to rank the slowest compilation units,
flag duplicate TLS/crypto backends, and cascade "late" markings from a
critical-path crate down through its transitive dependents."""

node Crate {
    has name: str = "";
    has version: str = "";
    has duration: float = 0.0;
    has start: float = 0.0;
    has kind: str = "rust";
    has dep_count: int = 0;
    has late_flag: bool = False;
}

edge DependsOn {
    has critical_path: bool = False;
    has test_only: bool = False;
}

walker BuildAuditor {
    has top_n: int = 5;
    has seen: list[str] = [];
    has slow: list[Crate] = [];
    has duplicates: list[str] = [];
    has seen_kinds: dict[str, int] = {};

    can start with Root entry {
        print(f"Auditing build graph (top {self.top_n} slowest)");
        visit [-->];
    }

    can audit with Crate entry {
        if here.name in self.seen {
            return;
        }
        self.seen.append(here.name);

        key = here.kind;
        if key in self.seen_kinds {
            self.seen_kinds[key] = self.seen_kinds[key] + 1;
            if self.seen_kinds[key] == 2 {
                self.duplicates.append(here.name);
            }
        } else {
            self.seen_kinds[key] = 1;
        }

        # The first crate visited hangs directly off the workspace root — it
        # is the package being built, not a compilation unit, so it is seen
        # but never ranked among the slowest units.
        if len(self.seen) > 1 {
            inserted = False;
            for i in range(len(self.slow)) {
                if here.duration > self.slow[i].duration {
                    self.slow.insert(i, here);
                    inserted = True;
                    break;
                }
            }
            if not inserted and len(self.slow) < self.top_n {
                self.slow.append(here);
            }
            if len(self.slow) > self.top_n {
                self.slow.pop();
            }
        }

        children = [here->:DependsOn:->];
        if len(children) > 0 {
            visit children;
        } else {
            disengage;
        }
    }
}

walker CriticalPathCascader {
    has late_set: list[str] = [];
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can cascade with Crate entry {
        if here.name in self.seen {
            return;
        }
        self.seen.append(here.name);

        if here.start >= 100.0 or here.late_flag {
            self.late_set.append(here.name);
            here.late_flag = True;
        }

        children = [here->:DependsOn:->];
        if here.late_flag {
            for c in children {
                c.late_flag = True;
            }
        }
        if len(children) > 0 {
            visit children;
        } else {
            disengage;
        }
    }
}

with entry {
    jsonschema = Crate(name="jsonschema", version="0.46", kind="rust", dep_count=22);
    reqwest = Crate(name="reqwest", version="0.12", kind="rust", dep_count=18);
    aws_lc_rs = Crate(name="aws-lc-rs", version="1.13", kind="aws-lc", dep_count=4);
    aws_lc_sys = Crate(name="aws-lc-sys", version="0.40", duration=93.86, start=16.06, kind="c-build", dep_count=2);
    ring = Crate(name="ring", version="0.17", duration=23.28, start=85.93, kind="tls-ring", dep_count=3);
    rustls = Crate(name="rustls", version="0.23", duration=22.00, start=171.09, kind="tls-ring", dep_count=6);
    git2 = Crate(name="git2", version="0.19", kind="rust", dep_count=4);
    libgit2_sys = Crate(name="libgit2-sys", version="0.17", duration=71.69, start=120.00, kind="c-build", dep_count=2);
    syn = Crate(name="syn", version="2.0", duration=27.02, start=4.27, kind="rust", dep_count=8);

    root ++> jsonschema;
    root ++> git2;
    jsonschema +>:DependsOn(critical_path=True):+> reqwest;
    reqwest +>:DependsOn:+> aws_lc_rs;
    aws_lc_rs +>:DependsOn(critical_path=True):+> aws_lc_sys;
    reqwest +>:DependsOn:+> aws_lc_sys;
    reqwest +>:DependsOn:+> ring;
    reqwest +>:DependsOn:+> rustls;
    git2 +>:DependsOn(critical_path=True):+> libgit2_sys;
    git2 +>:DependsOn:+> syn;

    root spawn BuildAuditor(top_n=5);
    root spawn CriticalPathCascader();
}
