```jac
"""TinyChain Class-aware ORM traversal: members, mutations, and dependency ordering.

Models a small graph of Class definitions, their members (some writable, some
read-only, some derived), the backing Collections each member resolves through,
and pending mutation plans that must be ordered by dependency before dispatch.

A walker walks the Class graph from root, classifies each member it encounters,
records the mutations required, and emits an ordered dispatch plan respecting
dependency edges (foreign keys, derived-from, through-collection) without ever
materializing a Collection in full.
"""

# ---------- Node archetypes ----------

node ClassDef {
    has name: str = "";
    has base_class: str = "";
}

node Member {
    has name: str = "";
    has kind: str = "stored";
    has writable: bool = False;
}

node Collection {
    has name: str = "";
    has path: str = "";
}

node MutationPlan {
    has target: str = "";
    has op: str = "update";
    has depends_on: str = "";
}

# ---------- Typed edges ----------

edge SubclassOf { }
edge HasMember { }
edge BackedBy { }
edge PendingMutation { }
edge DependsOn { }

# ---------- Walker: classify members ----------

walker Or {
    has order: list[str] = [];
    has seen_members: list[str] = [];
    can start with Root entry {
        visit [-->];
    }
    can classify with ClassDef entry {
        print(f"Class {here.name}" + (f" extends {here.base_class}" if here.base_class else ""));
        visit [-->];
    }
    can record_member with Member entry {
        tag = "W" if here.writable else "R";
        label = f"{here.kind}/{tag}/{here.name}";
        short = f"{tag}/{here.name}";
        self.seen_members.append(short);
        print(f"  member [{label}]");
        visit [-->];
    }
    can record_collection with Collection entry {
        print(f"  backing collection: {here.name} @ {here.path}");
        visit [-->];
    }
    can order_plan with MutationPlan entry {
        self.order.append(here.target);
        visit [-->];
    }
}

walker Cascade {
    has invalidated: list[str] = [];
    can start with Root entry {
        visit [-->];
    }
    can invalidate with ClassDef entry {
        self.invalidated.append(here.name);
        print(f"invalidating class {here.name}");
        visit [-->];
    }
    can drop_member with Member entry {
        if not here.writable {
            print(f"  cannot drop read-only member {here.name}");
        } else {
            print(f"  dropping member {here.name}");
        }
        visit [-->];
    }
    can sweep_collection with Collection entry {
        if here.name == "" {
            print("  collection has no path; nothing to release");
        } else {
            print(f"  releasing view on {here.path} (bounded, no full materialize)");
        }
        visit [-->];
    }
}

# ---------- Demo wiring ----------

with entry {
    user_cls = ClassDef(name="User", base_class="");
    audit_cls = ClassDef(name="AuditLog", base_class="User");
    root ++> user_cls ++> audit_cls;

    email = Member(name="email", kind="stored", writable=True);
    created = Member(name="created_at", kind="stored", writable=False);
    full_name = Member(name="full_name", kind="derived", writable=False);
    activate = Member(name="activate", kind="method", writable=False);
    user_cls +>:HasMember:+> email;
    user_cls +>:HasMember:+> created;
    user_cls +>:HasMember:+> full_name;
    user_cls +>:HasMember:+> activate;

    actor_ref = Member(name="actor", kind="reference", writable=True);
    audit_cls +>:HasMember:+> actor_ref;

    users_table = Collection(name="users", path="/tx/table/users");
    audit_table = Collection(name="audit", path="/tx/table/audit");
    email +>:BackedBy:+> users_table;
    created +>:BackedBy:+> users_table;
    actor_ref +>:BackedBy:+> audit_table;

    create_user = MutationPlan(target="User.email", op="create", depends_on="");
    update_actor = MutationPlan(target="AuditLog.actor", op="update", depends_on="User.email");
    user_cls +>:PendingMutation:+> create_user;
    audit_cls +>:PendingMutation:+> update_actor;
    create_user +>:DependsOn:+> update_actor;

    print("=== classification pass ===");
    root spawn Or();

    print("\n=== cascade invalidation ===");
    root spawn Cascade();
}
