```jac
"""Type checker cycle detection.

Models the recursive type-resolution problem from issue #199: type
definitions may reference themselves (directly or mutually), so a naive
walker that follows type references would loop forever. The TypeResolver
walker keeps an in-progress set per resolver and reports the cycle path
when it re-enters a type that is already being resolved.
"""

node TypeDef {
    has name: str = "";
    # Human-readable kind label ("alias", "object", "primitive").
    has kind: str = "alias";
}

# A type references another type through its body. The payload is the
# referenced type's name so the resolver can follow it.
edge RefersTo {
    has target: str = "";
}

walker TypeResolver {
    # The type we are currently trying to resolve.
    has target: str = "";
    # Types currently on the active resolution stack for this walker.
    has stack: list[str] = [];
    # The cycle path captured when a re-entry is detected.
    has cycle_path: list[str] = [];
    # Whether the most recent resolution attempt hit a cycle.
    has found_cycle: bool = False;

    can begin with Root entry {
        # Look at every TypeDef child of root, but only enter the one
        # whose name matches `self.target`.
        for child in [-->] {
            if isinstance(child, TypeDef) and child.name == self.target {
                visit child;
                return;
            }
        }
        # Target not found -- nothing to resolve, exit cleanly.
        disengage;
    }

    can resolve with TypeDef entry {
        # Skip primitives: they never refer to user-defined types.
        if here.kind == "primitive" {
            return;
        }

        # Re-entry on an in-progress type -> cycle detected.
        if here.name in self.stack {
            self.found_cycle = True;
            idx = self.stack.index(here.name);
            self.cycle_path = self.stack[idx:] + [here.name];
            disengage;
        }

        # Record this type as in-progress, then walk its references.
        self.stack = self.stack + [here.name];
        visit [->:RefersTo:->];
    }
}

# Helper: run a resolver and return its cycle path (empty if none).
def check(graph_root: object, type_name: str) -> list[str] {
    resolver = TypeResolver(target=type_name);
    graph_root spawn resolver;
    return resolver.cycle_path;
}

with entry {
    # --- Build the small demo type graph ----------------------------------
    # Primitive leaf types.
    int_t = TypeDef(name="int", kind="primitive");
    str_t = TypeDef(name="str", kind="primitive");

    # `type A = A[]`  ->  A refers to itself.
    a = TypeDef(name="A", kind="alias");
    a +>:RefersTo(target="A"):+> a;

    # `type B = { x: C }` and `type C = { y: B }`  ->  mutual recursion.
    b = TypeDef(name="B", kind="object");
    c = TypeDef(name="C", kind="object");
    b +>:RefersTo(target="C"):+> c;
    c +>:RefersTo(target="B"):+> b;

    # `type D = { x: int }`  ->  fine, resolves through a primitive.
    d = TypeDef(name="D", kind="object");
    d +>:RefersTo(target="int"):+> int_t;

    # Wire everything under a single root so a single spawn reaches all.
    typegraph = root;
    typegraph ++> int_t ++> str_t;
    typegraph ++> a;
    typegraph ++> b ++> c;
    typegraph ++> d;

    # --- Demo: each pathological case should report a clean cycle ---------
    path_a = check(typegraph, "A");
    print(f"check A -> cycle: {path_a}");

    path_bc = check(typegraph, "B");
    print(f"check B -> cycle: {path_bc}");

    path_d = check(typegraph, "D");
    print(f"check D -> cycle: {path_d}  (empty == no cycle)");

    # Confirm shape of the diagnostic string the issue calls for.
    label_a = "infinite type: " + " -> ".join(path_a);
    print(f"diagnostic: {label_a}");
}
```

```jac
"""Asset graph: trace relationships, update attributes, suggest next workflow step.

Models the atlassian-assets scenario where objects live in a graph of
schema types connected by typed relationships (composition, dependency,
reference). A walker traverses the graph, traces relationships, performs
attribute updates, and emits a context-specific workflow suggestion.
"""

# ---- Edge archetypes -------------------------------------------------------

edge Composition {
    has quantity: int = 1;
}

edge Dependency {
    has required: bool = True;
}

# ---- Node archetypes -------------------------------------------------------

node AssetObject {
    has name: str = "";
    has object_type: str = "";
    has attributes: dict = {};
    has available: bool = True;
}

node SchemaType {
    has type_name: str = "";
}

node WorkflowContext {
    has step: str = "";
}

# ---- Walker: traverse relationships, update, suggest ------------------------

walker AssetMaintainer {
    has pending_update: dict = {};
    has visited: list = [];
    has ver_log: list = [];

    can start with Root entry {
        print("AssetMaintainer: scanning object graph from root");
        visit [-->];
    }

    can plan with WorkflowContext entry {
        print(f"Workflow step loaded: {here.step}");
        visit [-->];
    }

    can index with SchemaType entry {
        print(f"SchemaType seen: {here.type_name}");
        visit [-->];
    }

    can inspect with AssetObject entry {
        first_visit = here.name not in self.visited;
        if first_visit {
            self.visited.append(here.name);
        }
        log_line = f"visited {here.object_type} '{here.name}'";
        if first_visit {
            self.ver_log.append(log_line);
        }
        print(log_line);

        # Apply pending attribute update if one was queued.
        if self.pending_update and here.available {
            for (k, v) in self.pending_update.items() {
                here.attributes[k] = v;
            }
            print(f"  updated attributes -> {here.attributes}");

            # Invalidate downstream dependents (even if previously visited,
            # we still want to log the invalidation line per dependent edge).
            for dep in [->:Dependency:->] {
                dep_name = dep.name;
                dep_log = f"  -> dep {dep.object_type} '{dep_name}'";
                self.ver_log.append(dep_log);
                print(dep_log);
            }
            return;
        }

        # Compose-children first (cascade), then dependencies.
        for child in [->:Composition:->] {
            visit [->:Composition:->];
            break;
        }
        for child in [->:Dependency:->] {
            visit [->:Dependency:->];
            break;
        }
    }

    can record_dependency with AssetObject entry {
        first_visit = here.name not in self.visited;
        if first_visit {
            self.visited.append(here.name);
            log_line = f"  -> dep {here.object_type} '{here.name}'";
            self.ver_log.append(log_line);
            print(log_line);
        }
        visit [->:Dependency:->];
    }

    can finalize with Root exit {
        # Context-specific suggestion derived from trace.
        total = len(self.ver_log);
        updated_label = "updated" if self.pending_update else "read-only";
        suggestion = (
            "schedule dependency impact review"
            if self.pending_update
            else "open relationship explorer"
        );
        print(
            f"Trace complete: {total} nodes ({updated_label}). "
            f"Suggested next step: {suggestion}"
        );
    }
}

# ---- Demo graph ------------------------------------------------------------

with entry {
    # Schemas.
    server_schema = SchemaType(type_name="Server");
    app_schema = SchemaType(type_name="Application");
    root ++> server_schema ++> app_schema;

    # Server composed of hardware, depending on a license.
    web_server = AssetObject(
        name="web-01",
        object_type="Server",
        attributes={"hostname": "web-01", "rack": "R3"},
        available=True,
    );
    nic = AssetObject(
        name="nic-eth0",
        object_type="NIC",
        attributes={"mac": "aa:bb:cc:dd:ee:ff"},
        available=True,
    );
    license = AssetObject(
        name="license-acme",
        object_type="License",
        attributes={"key": "ACME-2026"},
        available=True,
    );

    root ++> web_server;
    web_server +>:Composition(quantity=1):+> nic;
    web_server +>:Dependency(required=True):+> license;

    # A second server shares the same license -> cross-reference.
    db_server = AssetObject(
        name="db-01",
        object_type="Server",
        attributes={"hostname": "db-01", "rack": "R3"},
        available=True,
    );
    root ++> db_server;
    db_server +>:Composition(quantity=1):+> AssetObject(
        name="disk-0",
        object_type="Disk",
        attributes={"size_gb": 500},
        available=True,
    );
    db_server +>:Dependency(required=True):+> license;

    # Workflow context node feeding the walker.
    wf = WorkflowContext(step="trace-and-update");
    root ++> wf;

    # Spawn a read-only trace first.
    reader = AssetMaintainer();
    root spawn reader;

    # Then an update pass that mutates web_server's hostname.
    updater = AssetMaintainer(
        pending_update={"hostname": "web-01-prod"},
    );
    root spawn updater;
}
