```jac
"""CDN security PILOT-03: inventory NestJS-scale projects, run cold/warm analysis, and cascade cache invalidation over dependency stages."""

edge DependsOn {
    has stage_order: int = 0;
}

node Project {
    has name: str = "";
    has file_count: int = 0;
}

node Controller {
    has name: str = "";
    has route_prefix: str = "";
}

node Operation {
    has http_method: str = "";
    has route: str = "";
}

node AnalysisArtifact {
    has label: str = "";
    has cached: bool = False;
}

node OpenAPISpec(AnalysisArtifact) {
    has operation_count: int = 0;
}

node PolicyBundle(AnalysisArtifact) {
    has rule_count: int = 0;
}

node SourceModule(AnalysisArtifact) {
    has ts_file_count: int = 0;
}

node Finding {
    has severity: str = "Warning";
    has category: str = "";
    has instance_id: str = "";
    has reviewed: bool = False;
}

walker ScaleInventory {
    has controller_total: int = 0;
    has operation_total: int = 0;
    has error_total: int = 0;
    has warning_total: int = 0;
    has partial_total: int = 0;

    can start with Root entry {
        print("=== PILOT-03 Pre-run Inventory ===");
        visit [-->];
    }

    can inventory with Project entry {
        print(f"Project '{here.name}': {here.file_count} source files");
        visit [-->];
    }

    can tally_controller with Controller entry {
        self.controller_total += 1;
        print(f"  Controller {here.name} @ {here.route_prefix}");
        visit [-->];
    }

    can tally_operation with Operation entry {
        self.operation_total += 1;
        print(f"    Operation {here.http_method} {here.route}");
        visit [-->];
    }

    can review_finding with Finding entry {
        if here.severity == "Error" {
            self.error_total += 1;
            here.reviewed = True;
            print(f"      [ERROR]   {here.category} ({here.instance_id}) - reviewed");
        } elif here.severity == "Warning" {
            self.warning_total += 1;
            print(f"      [WARNING] {here.category} ({here.instance_id})");
        } elif here.severity == "Partial" {
            self.partial_total += 1;
            print(f"      [PARTIAL] {here.category} ({here.instance_id})");
        } else {
            self.partial_total += 1;
            print(f"      [OTHER]   {here.category} ({here.instance_id})");
        }
        visit [-->];
    }
}

walker AnalysisRunner {
    has mode: str = "cold";
    has stages_run: int = 0;
    has cache_hits: int = 0;

    can start with Root entry {
        mode_label = self.mode.upper();
        print(f"=== {mode_label} Source-aware Analysis ===");
        visit [-->];
    }

    can execute with OpenAPISpec | PolicyBundle | SourceModule entry {
        if here.cached and self.mode == "warm" {
            self.cache_hits += 1;
            print(f"  [CACHE HIT] {here.label}");
        } else {
            self.stages_run += 1;
            here.cached = True;
            print(f"  [ANALYZE] {here.label}");
        }
        visit [->:DependsOn:->] else { disengage; };
    }
}

walker CacheInvalidator {
    has visited_labels: list[str] = [];
    has invalidated_count: int = 0;

    can invalidate with OpenAPISpec | PolicyBundle | SourceModule entry {
        label = here.label;
        if label in self.visited_labels {
            print(f"  [CYCLE GUARD] stopping at {label}");
            disengage;
        }
        self.visited_labels.append(label);
        here.cached = False;
        self.invalidated_count += 1;
        print(f"  Invalidated: {here.label}");
        visit [->:DependsOn:->] else { disengage; };
    }
}

with entry {
    nest = Project(name="nestjs-oss-pilot", file_count=1842);

    auth_ctrl = Controller(name="AuthController", route_prefix="/auth");
    users_ctrl = Controller(name="UsersController", route_prefix="/users");
    items_ctrl = Controller(name="ItemsController", route_prefix="/items");

    login_op = Operation(http_method="POST", route="/auth/login");
    profile_op = Operation(http_method="GET", route="/users/profile");
    list_op = Operation(http_method="GET", route="/items");

    openapi = OpenAPISpec(label="openapi-v3", operation_count=3);
    policy = PolicyBundle(label="cdn-policy", rule_count=42);
    source = SourceModule(label="source-slice", ts_file_count=180);

    err_finding = Finding(
        severity="Error",
        category="path-mismatch",
        instance_id="E-001"
    );
    warn_finding = Finding(
        severity="Warning",
        category="deprecated-header",
        instance_id="W-014"
    );
    part_finding = Finding(
        severity="Partial",
        category="alias-unresolved",
        instance_id="P-003"
    );

    root ++> nest;
    root ++> openapi;
    nest ++> auth_ctrl ++> login_op ++> err_finding;
    nest ++> users_ctrl ++> profile_op ++> warn_finding;
    nest ++> items_ctrl ++> list_op ++> part_finding;
    openapi +>:DependsOn(stage_order=1):+> policy;
    policy +>:DependsOn(stage_order=2):+> source;

    inventory = ScaleInventory();
    root spawn inventory;

    cold_run = AnalysisRunner(mode="cold");
    root spawn cold_run;

    warm_run = AnalysisRunner(mode="warm");
    root spawn warm_run;

    invalidator = CacheInvalidator();
    openapi spawn invalidator;

    rerun = AnalysisRunner(mode="cold");
    root spawn rerun;

    ctrl_ok = inventory.controller_total >= 3;
    decision = "LARGE_PROJECT_SUPPORTED" if ctrl_ok else "NEEDS_BLOCKING_SCALE_FIXES";
    print(
