A maintainer on the project algoscope-hq/AlgoScope (JavaScript) filed this issue about hand-rolled graph machinery causing pain:

Issue #838: [Feature]: Add Topological Sort Visualizer (Kahn's Algorithm + DFS-Based) with Dependency Graph Use-Case Demo

## Summary

AlgoScope's graph section (`src/components/searchAlgo/`) covers BFS, DFS, and shortest-path algorithms. However, **Topological Sort** — one of the most practically important graph algorithms — is entirely absent. Topological sort appears in build systems, course scheduling, package dependency resolution, and task scheduling. Visualizing it on a Directed Acyclic Graph (DAG) with a real-world dependency context (e.g., "compile this code" or "take this course before that one") makes the algorithm immediately relatable and memorable. I would like to implement both Kahn's (BFS-based) and DFS-based approaches for side-by-side comparison in AlgoScope's Comparison Mode.

## Proposed Implementation

**Step generator (`src/algorithms/searching/topoSortEngine.js`):**

```js
export function kahnTopologicalSort(adjList, numNodes) {
  const steps = [];
  const inDegree = new Array(numNodes).fill(0);

  // Compute in-degrees
  for (const [u, neighbors] of Object.entries(adjList)) {
    for (const v of neighbors) {
      inDegree[v]++;
    }
  }

  steps.push({ type: 'INIT_INDEGREES', inDegree: [...inDegree] });

  const queue = [];
  for (let i = 0; i < numNodes; i++) {
    if (inDegree[i] === 0) {
      queue.push(i);
      steps.push({ type: 'ENQUEUE_ZERO_INDEGREE', node: i });
    }
  }

  const result = [];

  while (queue.length > 0) {
    const node = queue.shift();
    result.push(node);
    steps.push({ type: 'PROCESS', node, currentOrder: [...result] });

    for (const neighbor of (adjList[node] || [])) {
      inDegree[neighbor]--;
      steps.push({
        type: 'DECREMENT_INDEGREE',
        from: node,
        to: neighbor,
        newInDegree: inDegree[neighbor]
      });

      if (inDegree[neighbor] === 0) {
        queue.push(neighbor);
        steps.push({ type: 'ENQUEUE', node: neighbor });
      }
    }
  }

  const hasCycle = result.length !== numNodes;
  steps.push({ type: hasCycle ? 'CYCLE_DETECTED' : 'COMPLETE', order: result });

  return { order: result, hasCycle, steps };
}

export function dfsTopologicalSort(adjList, numNodes) {
  const steps = [];
  const visited = new Set();
  const stack = [];

  function dfs(node) {
    visited.add(node);
    steps.push({ type: 'VISIT', node });
    for (const neighbor of (adjList[node] || [])) {
      if (!visited.has(neighbor)) {
        steps.push({ type: 'RECURSE', from: node, to: neighbor });
        dfs(neighbor);
      }
    }
    stack.push(node);
    steps.push({ type: 'PUSH_STACK', node, stack: [...stack] });
  }

  for (let i = 0; i < numNodes; i++) {
    if (!visited.has(i)) dfs(i);
  }

  const order = stack.reverse();
  steps.push({ type: 'COMPLETE', order });
  return { order, steps };
}
```

