Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Topological sort on a build dependency DAG using Kahn's algorithm.

Models compile/link/exe tasks as nodes connected by ``DependsOn`` edges
(``compile.c -> compile.o`` means "``compile.c`` must build before
``compile.o``"). A ``Builder`` walker performs Kahn's algorithm natively:
its ``Root`` ability seeds in-degrees from the actual ``DependsOn`` edges
(Kahn's INIT_INDEGREES step), then repeatedly emits ready (in-degree 0)
tasks, pruning their outgoing edges -- which decrements each neighbor's
in-degree -- until no progress can be made. Nodes still unvisited after
the walk are part of (or downstream of) a cycle, exactly like Kahn's
``result.length !== numNodes`` check. The walker's traversal over the
tasks reports anything left stuck.
"""

node Task {
    has name: str = "";
    has in_degree: int = 0;
    has visited: bool = False;
}

edge DependsOn { }

walker Builder {
    has order: list[str] = [];

    can start with Root entry {
        tasks = [-->];

        # Seed in-degrees authoritatively from the actual DependsOn
        # edges so the walk is correct regardless of how the tasks'
        # fields were initialized.
        for t in tasks {
            t.in_degree = 0;
        }
        for t in tasks {
            for nbr in [t->:DependsOn:->] {
                nbr.in_degree += 1;
            }
        }

        print("Builder begins: Kahn's algorithm over the dependency DAG");

        # Kahn's main loop: emit ready tasks, pruning each emitted task's
        # outgoing DependsOn edges -- that pruning IS the
        # ``inDegree[neighbor]--`` decrement step. Stop when a full pass
        # emits nothing (either done or wedged on a cycle).
        progress = True;
        while progress {
            progress = False;
            for t in tasks {
                if not t.visited and t.in_degree == 0 {
                    t.visited = True;
                    self.order.append(t.name);
                    print(f"  build -> {t.name}");
                    for nbr in [t->:DependsOn:->] {
                        nbr.in_degree -= 1;
                        print(f"     decrement in-degree of {nbr.name} -> {nbr.in_degree}");
                        t del ->:DependsOn:-> nbr;
                    }
                    progress = True;
                }
            }
        }

        visit [-->];
    }

    can schedule with Task entry {
        if not here.visited {
            if here.in_degree == 0 {
                # A ready task that the Root pass did not reach -- emit
                # it and keep walking its remaining outgoing edges.
                here.visited = True;
                self.order.append(here.name);
                print(f"  build -> {here.name}");
                for nbr in [here->:DependsOn:->] {
                    nbr.in_degree -= 1;
                    print(f"     decrement in-degree of {nbr.name} -> {nbr.in_degree}");
                    here del ->:DependsOn:-> nbr;
                }
                visit [-->];
            } else {
                # Unscheduled AND still has unmet prerequisites: it is on
                # (or downstream of) a dependency cycle. Report it and do
                # NOT follow its DependsOn edges -- that would loop
                # forever around the cycle.
                print(f"  stuck on {here.name} (in_degree={here.in_degree}) -- part of a cycle");
            }
        }
    }
}

with entry {
    # Build dependency DAG:
    #
    #   compile.c ---> compile.o ---> link.o ----> build.exe
    #                             \--> link.lib -/
    #
    #   compile.exe (no deps) ------------------> build.exe

    c    = Task(name="compile.c");
    o    = Task(name="compile.o");
    lib  = Task(name="link.lib");
    link = Task(name="link.o");
    exe  = Task(name="build.exe");
    c2   = Task(name="compile.exe");

    c    +>:DependsOn:+> o;
    o    +>:DependsOn:+> link;
    o    +>:DependsOn:+> lib;
    lib  +>:DependsOn:+> link;
    link +>:DependsOn:+> exe;
    c2   +>:DependsOn:+> exe;

    # A cycled pair to exercise the cycle-detection path.
    x = Task(name="cycle.a");
    y = Task(name="cycle.b");
    x +>:DependsOn:+> y;
    y +>:DependsOn:+> x;

    root ++> c;
    root ++> o;
    root ++> lib;
    root ++> link;
    root ++> exe;
    root ++> c2;
    root ++> x;
    root ++> y;

    builder = Builder();
    root spawn builder;

    print("");
    print(f"Final build order: {builder.order}");

    all_tasks = [c, o, lib, link, exe, c2, x, y];
    unvisited = [t.name for t in all_tasks if not t.visited];
    if len(unvisited) > 0 {
        print(f"CYCLE DETECTED -- topological order not possible; stuck on: {unvisited}");
    } else {
        print("No cycle: every task was scheduled.");
    }
}
