```jac
"""Maven transitive dependency resolution — model the repository-pollution scenario.

In Maven, a project's pom.xml can pull in a transitive dependency whose own
parent-pom (or BOM) declares additional repositories. When the resolver walks
the dependency tree it inherits those remote repositories and tries to fetch
artifacts from URLs the user never approved. This demo lifts that hand-rolled
machinery into native Jac: project/dependency/repository nodes connected by
typed edges (DependsOn, Inherits, DeclaredIn), and a walker that traverses
the tree and reports which repositories end up "in scope" at every node.

Cycle policy is preserved: a parent-pom can point back to an ancestor
(boot-dependencies -> spring-boot-parent -> boot-dependencies). Without an
explicit guard the walker would loop forever, exactly as the issue describes
the build falling into remote repos it never asked for.
"""

# --- Entity archetypes -------------------------------------------------------

node Project {
    has name: str = "";
    has version: str = "";
}

node Dependency {
    has group: str = "";
    has artifact: str = "";
    has version: str = "";
    has classifier: str = "";
}

node Repository {
    has id: str = "";
    has url: str = "";
    has releases_enabled: bool = True;
    has snapshots_enabled: bool = True;
}

# --- Relationship archetypes -------------------------------------------------

edge DependsOn {
    has scope: str = "compile";
}

edge Inherits { }

edge DeclaredIn { }

# --- The walker --------------------------------------------------------------

walker RepoResolver {
    has visited_ids: list[str] = [];
    has scoped_repos: list[str] = [];
    has verbose: bool = True;

    can start with Root entry {
        if self.verbose {
            print("Resolving repositories across the dependency tree...");
        }
        visit [-->] else {
            disengage;
        }
    }

    can resolve with Project entry {
        proj_key = here.name + ":" + here.version;
        if proj_key in self.visited_ids {
            if self.verbose {
                print(f"[cycle-guard] skip {proj_key} (already visited)");
            }
            disengage;
        }
        self.visited_ids.append(proj_key);

        # Collect repositories declared DIRECTLY on this project.
        for repo in [here->:DeclaredIn:->] {
            label = f"{repo.id} ({repo.url})";
            if label not in self.scoped_repos {
                self.scoped_repos.append(label);
                if self.verbose {
                    print(f"  + repo [self] {label} on {proj_key}");
                }
            }
        }

        # Inherit repositories from the parent-pom (if any).
        for parent in [here->:Inherits:->] {
            for repo in [parent->:DeclaredIn:->] {
                label = f"{repo.id} ({repo.url})";
                if label not in self.scoped_repos {
                    self.scoped_repos.append(label);
                    if self.verbose {
                        print(f"  + repo [inherited] {label} on {proj_key} (via {parent.name}:{parent.version})");
                    }
                }
            }
        }

        # Walk transitive dependencies AND parent-pom inheritance.
        visit [->:DependsOn:->];
        visit [->:Inherits:->];
    }

    can resolve_dep with Dependency entry {
        # A dependency's pom declares its own parent-pom via Inherits.
        # We need to walk those to surface repositories inherited from
        # ancestor poms (e.g. spring-boot-dependencies BOM).
        visit [->:Inherits:->];
    }
}

walker RepoAuditor {
    has user_approved: list[str] = [];

    can start with Root entry {
        print("Auditing resolved repos against user-approved set...");
        visit [-->] else {
            disengage;
        }
    }

    can audit with Project entry {
        # Directly declared repos on this project.
        for repo in [here->:DeclaredIn:->] {
            label = f"{repo.id} ({repo.url})";
            if label not in self.user_approved {
                print(f"  [POLLUTED] {here.name}:{here.version} dragged in unapproved repo {label}");
            }
        }
        # Inherited repos via parent-poms.
        for parent in [here->:Inherits:->] {
            for repo in [parent->:DeclaredIn:->] {
                label = f"{repo.id} ({repo.url})";
                if label not in self.user_approved {
                    print(f"  [POLLUTED] {here.name}:{here.version} dragged in unapproved repo {label} (via {parent.name}:{parent.version})");
                }
            }
        }
        visit [->:DependsOn:->];
    }

    can audit_dep with Dependency entry {
        # Hop to the dependency's parent-pom so its repos get audited too.
        visit [->:Inherits:->];
    }
}

# --- Demonstration graph -----------------------------------------------------

with entry {
    app = Project(name="demo-backend", version="1.0.0-SNAPSHOT");
    user_repo = Repository(
        id="central",
        url="https://artifacts.example.com/repository/maven/",
        releases_enabled=True,
        snapshots_enabled=True,
    );

    starter = Dependency(group="org.springframework.boot",
                        artifact="spring-boot-starter-web",
                        version="2.0.0.RELEASE",
                        classifier="compile");

    parent_pom = Project(name="org.springframework.boot:spring-boot-parent",
                         version="2.0.0.RELEASE");

    bom = Project(name="org.springframework.boot:spring-boot-dependencies",
                  version="2.0.0.RELEASE");

    spring_milestone = Repository(id="spring-milestone",
                                  url="https://repo.spring.io/milestone",
                                  releases_enabled=True,
                                  snapshots_enabled=True);
    bintray_milestones = Repository(id="rabbitmq-maven-milestones",
                                    url="https://dl.bintray.com/rabbitmq/maven-milestones",
                                    releases_enabled=True,
                                    snapshots_enabled=True);

    root ++> app;

    app +>:DependsOn(scope="compile"):+> starter;
    starter +>:Inherits:+> parent_pom;
    parent_pom +>:Inherits:+> bom;

    bom +>:DeclaredIn:+> spring_milestone;
    bom +>:DeclaredIn:+> bintray_milestones;

    app +>:DeclaredIn:+> user_repo;

    resolver = RepoResolver();
    app spawn resolver;

    print("\nFinal repository scope seen by the resolver:");
    for r in resolver.scoped_repos {
        print(f"  - {r}");
    }

    print("\nRunning RepoAuditor with user_approved = [central only]...");
    approved_label = f"{user_repo.id} ({user_repo.url})";
    auditor = RepoAuditor(user_approved=[approved_label]);
    app spawn auditor;
}
