"""Delivery DAG: tasks with typed dependencies and topological execution order.

Models a small build/test/release pipeline as a directed acyclic graph of
Task nodes connected by typed DependsOn edges. A Delivery walker performs
a topological traversal, marking each task ready once all of its
prerequisites are satisfied and reporting the execution order. An
Invalidator walker cascades over the reachable graph clearing satisfied
flags. Because Jac 0.36.1 walkers have no built-in once-per-node
visitation, callers re-spawn Delivery until every task is satisfied —
the dependency-respecting eligibility check is the policy.
"""

node Task {
    has title: str = "";
    has duration_min: int = 0;
    has satisfied: bool = False;
}

edge DependsOn {
    has weight: int = 1;
}

walker Delivery {
    has ready_order: list[str] = [];

    can start with Root entry {
        print("Delivery DAG: topologically scheduling tasks");
        visit [-->];
    }

    can schedule with Task entry {
        all_done = True;
        for prereq in [->:DependsOn:->] {
            if not prereq.satisfied {
                all_done = False;
                break;
            }
        }
        if all_done {
            if not here.satisfied {
                here.satisfied = True;
                self.ready_order.append(here.title);
                print(f"  ready -> {here.title} ({here.duration_min} min)");
            }
        } else {
            print(f"  waiting -> {here.title} (deps not met)");
        }
        visit [-->];
    }
}

walker Invalidator {
    can start with Root entry {
        print("Invalidator: cascade from root");
        visit [-->];
    }

    can cascade with Task entry {
        print(f"  invalidating downstream of {here.title}");
        here.satisfied = False;
        visit [-->];
    }
}

with entry {
    lint = Task(title="lint", duration_min=3);
    security = Task(title="security-scan", duration_min=5);
    test = Task(title="test", duration_min=10);
    package = Task(title="package", duration_min=4);

    test +>:DependsOn:+> lint;
    test +>:DependsOn:+> security;
    package +>:DependsOn:+> test;

    root ++> lint;
    root ++> security;
    root ++> test;
    root ++> package;

    for pass_num in [1, 2, 3] {
        print(f"--- Delivery pass {pass_num} ---");
        root spawn Delivery();
    }

    root spawn Invalidator();
}
