"""Canvas lane control room: model lanes, claims, blockers, and handoffs as
a graph and walk it to surface stale claims, cross-lane blockers, and
ready-but-unstarted work — replacing the hand-rolled comment scan with
typed edges and walker traversal.
"""

node Lane {
    has name: str = "";
}

node Claim {
    has task_id: str = "";
    has title: str = "";
    has state: str = "";        # CLAIMED | IN_PROGRESS | BLOCKED | HANDED_OFF | READY | LIVE | UNSTARTED
    has board_says: str = "";   # what the durable board claims
    has reality: str = "";      # what production / git / alias actually shows
    has stale: bool = False;
}

node Handoff {
    has task_id: str = "";
    has pr_ref: str = "";
    has ci_dark: bool = False;
    has local_check: str = "";
}

node Blocker {
    has task_id: str = "";
    has summary: str = "";
    has resolved: bool = False;
}

# Lane --owns--> Claim  (a claim lives in a single lane)
edge Owns { }

# Claim --crosses--> Blocker  (a claim waiting on another lane's work)
edge Blocks { }

# Claim --resolves_to--> Handoff  (a claim that produced a mergeable handoff)
edge ResolvesTo { }

walker Auditor {
    has stale_count: int = 0;
    has ready_count: int = 0;
    has open_blocker_count: int = 0;
    has printed: bool = False;

    can start with Root entry {
        # Defer summary until traversal fully completes.
        visit [-->];
    }

    can sweep_lane with Lane entry {
        print(f"--- lane: {here.name} ---");
        visit [-->];
    }

    can audit_claim with Claim entry {
        verdict = "CONFIRMED";
        if here.stale {
            verdict = "STALE";
            self.stale_count += 1;
        } elif here.state == "READY" {
            verdict = "READY";
            self.ready_count += 1;
        }
        print(
            f"[{verdict}] {here.task_id}: "
            f"board='{here.board_says}' reality='{here.reality}'"
        );
        visit [-->];
    }

    can audit_blocker with Blocker entry {
        tag = "OPEN" if not here.resolved else "CLEAR";
        if not here.resolved {
            self.open_blocker_count += 1;
        }
        print(
            f"[{tag}] blocker {here.task_id}: {here.summary}"
        );
        visit [-->];
    }

    can audit_handoff with Handoff entry {
        ci = "ci=dark" if here.ci_dark else "ci=live";
        print(
            f"[HANDOFF] {here.task_id} -> {here.pr_ref} [{ci}] "
            f"local: {here.local_check}"
        );
        visit [-->];
    }

    # Fires when the walker finishes traversing and disengages from Root,
    # after every lane / claim / blocker / handoff ability has executed and
    # the counters are final.
    can end with Root exit {
        if not self.printed {
            self.printed = True;
            print(
                f"summary: stale={self.stale_count} ready={self.ready_count} "
                f"open_blockers={self.open_blocker_count}"
            );
        }
    }
}

with entry {
    runtime = Lane(name="Runtime");
    parser = Lane(name="Parser");
    brain = Lane(name="Brain");
    integration = Lane(name="Integration");

    parser_002 = Claim(
        task_id="PARSER-002",
        title="Parser stage hardened",
        state="IN_PROGRESS",
        board_says="IN PROGRESS",
        reality="MERGED (#500 bee67e41), NOT DEPLOYED",
        stale=True,
    );
    parser_001 = Claim(
        task_id="PARSER-001",
        title="Parser stage open PR",
        state="CLAIMED",
        board_says="CLAIMED",
        reality="OPEN PR #504, mergeable, CI dark from infra",
        stale=True,
    );
    runtime_001 = Claim(
        task_id="RUNTIME-001",
        title="Compositional runtime live",
        state="LIVE",
        board_says="LIVE",
        reality="TRUE, verified via production alias 60b1365e",
        stale=False,
    );
    brain_003 = Claim(
        task_id="BRAIN-003",
        title="Brain unblock on substrate",
        state="READY",
        board_says="BLOCKED on #496/#497",
        reality="Both merged; substrate shipped",
        stale=False,
    );
    integration_001 = Claim(
        task_id="INTEGRATION-001",
        title="Integration pass unstarted",
        state="UNSTARTED",
        board_says="IN PROGRESS / BLOCKED (self-contradictory)",
        reality="Unblocked and unstarted",
        stale=True,
    );

    parser ++> parser_002;
    parser ++> parser_001;
    runtime ++> runtime_001;
    brain ++> brain_003;
    integration ++> integration_001;

    parser_002 +>:Blocks:+> Blocker(
        task_id="PARSER-002-DEPLOY",
        summary="Vercel rate-limited; production verification blocked",
        resolved=False,
    );
    brain_003 +>:Blocks:+> Blocker(
