```jac
"""Bounded filesystem walk vs bare read_dir recursion — models banso walk-safety gate blind spots."""

node FsEntry {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has name: str = "";
}

node Directory(FsEntry) { }

node File(FsEntry) {
    has bytes: int = 0;
}

node Crate {
    has name: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node WalkCallSite {
    has label: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has uses_walkdir: bool = False;
    has uses_read_dir_recursion: bool = False;
    has has_entry_cap: bool = False;
    has has_depth_cap: bool = False;
}

edge Contains { }

edge Junction { }

edge Hosts { }

walker BoundedFsWalker {
    has max_depth: int = 32;
    has max_entries: int = 100;
    has depth: int = 0;
    has count: int = 0;
    has seen: list[str] = [];
    has log: list[str] = [];
    has fail_reason: str = "";

    can start with Root entry {
        print(f"walk_files_bounded(max_depth={self.max_depth}, max_entries={self.max_entries})");
        visit [-->] else { disengage; }
    }

    can descend with Directory entry {
        if self.count >= self.max_entries {
            self.fail_reason = "entry_cap";
            disengage;
        }
        if not (here.name in self.seen) {
            self.seen.append(here.name);
            self.count += 1;
            self.log.append(f"dir/{here.name}");
            self.depth += 1;
            if self.depth >= self.max_depth {
                self.fail_reason = "depth_cap";
            } else {
                visit [->:Contains:->];
                visit [->:Junction:->] else { }
            }
            self.depth -= 1;
        }
    }

    can scan with File entry {
        if self.count >= self.max_entries {
            self.fail_reason = "entry_cap";
            disengage;
        }
        self.count += 1;
        self.log.append(f"file/{here.name}");
    }
}

walker BareReadDirWalker {
    has count: int = 0;
    has log: list[str] = [];

    can start with Root entry {
        print("bare read_dir recursion (no entry cap; junctions not followed)");
        visit [-->] else { disengage; }
    }

    can recurse with Directory entry {
        self.count += 1;
        self.log.append(f"dir/{here.name}");
        visit [->:Contains:->] else { disengage; }
    }

    can pick_up with File entry {
        self.count += 1;
        self.log.append(f"file/{here.name}");
    }
}

walker WalkSafetyAuditor {
    has gate_flagged: list[str] = [];
    has gate_blind: list[str] = [];
    has truly_unsafe: list[str] = [];

    can start with Root entry {
        print("audit walk-safety gate (WalkDir needle only, no entry-cap check)");
        visit [-->] else { disengage; }
    }

    can inspect with Crate entry {
        visit [->:Hosts:->];
        visit [-->];
    }

    can audit with WalkCallSite entry {
        if here.uses_walkdir and (not here.has_depth_cap) {
            self.gate_flagged.append(here.label);
        }
        if here.uses_walkdir and (not here.has_entry_cap) {
            self.gate_blind.append(f"{here.label}:entry_cap_unchecked");
        }
        if here.uses_read_dir_recursion {
            self.gate_blind.append(f"{here.label}:read_dir_recursion_invisible");
        }
        needs_cap = (not here.has_entry_cap) or (not here.has_depth_cap);
        is_unsafe = False;
        if here.uses_read_dir_recursion and needs_cap {
            is_unsafe = True;
        }
        if here.uses_walkdir and needs_cap {
            is_unsafe = True;
        }
        if is_unsafe {
            self.truly_unsafe.append(here.label);
        }
    }
}

with entry {
    src = Directory(name="src");
    lib = Directory(name="lib");
    utils = Directory(name="utils");
    deep = Directory(name="deep");
    root ++> src;
    src +>:Contains:+> lib;
    src +>:Contains:+> File(name="main.rs", bytes=420);
    src +>:Contains:+> File(name="extra_a.rs", bytes=10);
    src +>:Contains:+> File(name="extra_b.rs", bytes=10);
    src +>:Contains:+> File(name="extra_c.rs", bytes=10);
    lib +>:Contains:+> File(name="mod.rs", bytes=88);
    lib +>:Contains:+> utils;
    utils +>:Contains:+> File(name="helper.rs", bytes=55);
    utils +>:Contains:+> deep;
    deep +>:Contains:+> File(name="bottom.rs", bytes=12);
    lib +>:Junction:+> src;

    core = Crate(name="banso-core");
    cli = Crate(name="banso-cli");
    graph = Crate(name="banso-graph");
    root ++> core ++> cli ++> graph;
    core +>:Hosts:+> WalkCallSite(
        label="core::walk_files_bounded",
        uses_walkdir=True,
        has_depth_cap=True,
        has_entry_cap=True
    );
    cli +>:Hosts:+> WalkCallSite(
        label="cli::inventory (WalkDir::new)",
        uses_walkdir=True,
        has_depth_cap=True,
        has_entry_cap=False
    );
    cli +>:Hosts:+> WalkCallSite(
        label="cli::scan_docs (read_dir recurse)",
        uses_read_dir_recursion=True,
        has_depth_cap=False,
        has_entry_cap=False
    );
    graph +>:Hosts:+> WalkCallSite(
        label="graph::collect_nodes (read_dir recurse)",
        uses_read_dir_recursion=True,
        has_depth_cap=True,
        has_entry_cap=False
    );

    bounded = BoundedFsWalker(max_depth=3, max_entries=6);
    root spawn bounded;
    print(f"bounded stopped at {bounded.count} entries: {bounded.fail_reason}");
    for entry in bounded.log {
        print(f"  {entry}");
    }

    bare = BareReadDirWalker();
    root spawn bare;
    print(f"bare read_dir collected {bare.count} entries (no cap)");

    auditor = WalkSafetyAuditor();
    root spawn auditor;
    print(f"gate flagged: {auditor.gate_flagged}");
    print(f"gate blind spots: {auditor.gate_blind}");
    print(f"actually unsafe (gate under-reports): {auditor.truly_unsafe}");
}
