```jac
"""Qt tree source: pre/post insert and delete notifications.

Models the essential scenario from beeware/toga issue #4202: when a Qt tree
source mutates, we need pre-change events so the view can rebind QModelIndex
references before they go stale. We model the tree, a source that tracks it,
and walkers that traverse the tree reporting invalidation points in the
correct order (pre-delete before removal, post-delete after).
"""

# --- Node archetypes ---------------------------------------------------------

node HasRow {
    has row: int = 0;
    has label: str = "";
    has deleted: bool = False;
}

node TreeSource(HasRow) {
    has name: str = "";
}

node TreeNode(HasRow) {
    has title: str = "";
}

# --- Typed edges -------------------------------------------------------------

edge Parent {
    has row: int = 0;
}

# --- The walker --------------------------------------------------------------

walker SourceAuditor {
    has source_name: str = "";
    has visited: list[str] = [];
    has pre_delete_emitted: int = 0;
    has post_delete_emitted: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can audit_source with TreeSource entry {
        print("[source] beginning structural audit");
        self.source_name = here.name;
        # Seed visited with the source's own label so it is not revisited.
        if here.label not in self.visited {
            self.visited.append(here.label);
        }
        visit [->:Parent:->];
    }

    # A union ability handles both kinds of nodes the walker may encounter.
    # The body only touches fields declared on the shared HasRow base
    # (row, label, deleted).
    can audit_node with TreeNode | TreeSource entry {
        key = here.label;
        if key in self.visited {
            visit [->:Parent:->];
            return;
        }
        self.visited.append(key);

        if here.deleted {
            self.pre_delete_emitted += 1;
            print(f"  [pre-delete] {key}#{here.row} (source={self.source_name})");
            self.post_delete_emitted += 1;
            print(f"  [post-delete] {key}#{here.row}");
        } else {
            print(f"  [audit] {key}#{here.row}");
        }
        visit [->:Parent:->];
    }
}

# --- Cascade invalidator -----------------------------------------------------

walker CascadeInvalidator {
    has target_label: str = "";
    has marked: list[str] = [];
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can find_source with TreeSource entry {
        print(f"[cascade] source {here.name} looking for {self.target_label}");
        visit [->:Parent:->];
    }

    can mark_phase with TreeNode | TreeSource entry {
        key = here.label;
        if key in self.visited {
            visit [->:Parent:->];
            return;
        }
        self.visited.append(key);

        if key != self.target_label and not here.deleted {
            self.marked.append(key);
            here.deleted = True;
            print(f"  [mark] {key}#{here.row} -> pending invalidation");
        }
        visit [->:Parent:->];
    }
}

# --- Demo wiring -------------------------------------------------------------

with entry {
    source = TreeSource(name="DocsTree", label="DocsTree", row=0);
    root ++> source;

    docs = TreeNode(title="docs", label="docs", row=0);
    src = TreeNode(title="src", label="src", row=1);
    source +>:Parent(row=0):+> docs;
    source +>:Parent(row=1):+> src;

    overview = TreeNode(title="overview.txt", label="overview.txt", row=0);
    changelog = TreeNode(title="changelog.txt", label="changelog.txt", row=1);
    docs +>:Parent(row=0):+> overview;
    docs +>:Parent(row=1):+> changelog;

    main_py = TreeNode(title="main.py", label="main.py", row=0);
    util_py = TreeNode(title="util.py", label="util.py", row=1);
    src +>:Parent(row=0):+> main_py;
    src +>:Parent(row=1):+> util_py;

    print("=== audit pass: nothing pending ===");
    auditor = SourceAuditor();
    source spawn auditor;
    print(f"audit summary: pre_delete={auditor.pre_delete_emitted} "
          f"post_delete={auditor.post_delete_emitted}");

    print("\n=== cascade invalidate: src ===");
    invalidator = CascadeInvalidator(target_label="src");
    src spawn invalidator;
    print(f"cascade marked: {invalidator.marked}");

    print("\n=== audit pass: src subtree flagged ===");
    auditor2 = SourceAuditor();
    source spawn auditor2;
    print(f"audit summary: pre_delete={auditor2.pre_delete_emitted} "
          f"post_delete={auditor2.post_delete_emitted}");
}
