```jac
"""Task dependency workflow: tasks blocked by other tasks, with auto-unblock cascade."""

node Task {
    has title: str = "";
    has status: str = "pending";
    has completed: bool = False;
}

edge Blocks {
    has weight: int = 1;
}

walker UnblockCascade {
    has unlocked_count: int = 0;
    has visited_titles: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can process_task with Task entry {
        if here.title in self.visited_titles {
            disengage;
        }
        self.visited_titles.append(here.title);

        if here.completed {
            visit [->:Blocks:->];
        } else {
            blockers: list = [<-:Blocks:<-];
            blocker_tasks: list = [];
            for n in blockers {
                if isinstance(n, Task) {
                    blocker_tasks.append(n);
                }
            }
            if len(blocker_tasks) > 0 {
                all_clear = True;
                for blocker in blocker_tasks {
                    if not blocker.completed {
                        all_clear = False;
                        break;
                    }
                }
                if all_clear {
                    here.status = "ready";
                    self.unlocked_count = self.unlocked_count + 1;
                    print(f"  -> '{here.title}' is now Ready to Work");
                } else {
                    print(f"  - '{here.title}' still blocked");
                }
            } else {
                print(f"  - '{here.title}' still blocked");
            }
        }
        visit [-->];
    }
}

walker CycleDetector {
    has cycles_found: list[list[str]] = [];

    can start with Root entry {
        print("=== Cycle Detection ===");
        visit [-->];
    }

    can scan with Task entry {
        path: list[str] = [];

        def walk(current: Task, trail: list) {
            if current.title in trail {
                cycle_start = trail.index(current.title);
                cycle_trail = trail[cycle_start:] + [current.title];
                self.cycles_found.append(cycle_trail);
                return;
            }
            new_trail = trail + [current.title];
            children: list = [current -->];
            for child in children {
                if isinstance(child, Task) {
                    walk(child, new_trail);
                }
            }
        }

        walk(here, path);
        if len(self.cycles_found) > 0 {
            print(f"  Cycle detected involving '{here.title}':");
            for c in self.cycles_found {
                joined = " -> ".join(c);
                print(f"    {joined}");
            }
        } else {
            print(f"  No cycles downstream of '{here.title}'");
        }
    }
}

