```jac
"""Articulation points and bridges: DFS low-link connectivity analysis for undirected graphs."""

node Vertex {
    has label: str = "";
    has disc: int = -1;
    has low: int = -1;
    has visited: bool = False;
}

edge Adjacent { }

walker ConnectivityAnalyzer {
    has clock: int = 0;
    has articulation_pts: list[str] = [];
    has bridge_edges: list[str] = [];

    can start with Root entry {
        visit [-->] else {
            print(f"articulation points: {self.articulation_pts}");
            print(f"bridges: {self.bridge_edges}");
            disengage;
        }
    }

    can analyze with Vertex entry {
        if not here.visited {
            dfs(here, None, self);
        }
        print(f"articulation points: {self.articulation_pts}");
        print(f"bridges: {self.bridge_edges}");
    }
}

def add_cut(w: ConnectivityAnalyzer, label: str) {
    for name in w.articulation_pts {
        if name == label {
            return;
        }
    }
    w.articulation_pts.append(label);
}

def add_bridge(w: ConnectivityAnalyzer, a: str, b: str) {
    lo = a if a < b else b;
    hi = b if a < b else a;
    key = f"{lo}-{hi}";
    for name in w.bridge_edges {
        if name == key {
            return;
        }
    }
    w.bridge_edges.append(key);
}

def dfs(u: Vertex, par: Vertex | None, w: ConnectivityAnalyzer) {
    u.visited = True;
    u.disc = w.clock;
    u.low = w.clock;
    w.clock += 1;
    kids = 0;
    for v in [u->:Adjacent:->] {
        if not v.visited {
            kids += 1;
            dfs(v, u, w);
            if v.low < u.low {
                u.low = v.low;
            }
            if par is not None and v.low >= u.disc {
                add_cut(w, u.label);
            }
            if v.low > u.disc {
                add_bridge(w, u.label, v.label);
            }
        } else {
            if par is None or v is not par {
                if v.disc < u.low {
                    u.low = v.disc;
                }
            }
        }
    }
    if par is None and kids >= 2 {
        add_cut(w, u.label);
    }
}

with entry {
    # Main component: triangle A-B-E with pendant bridges B-C and B-D (cut vertex B).
    a = Vertex(label="A");
    b = Vertex(label="B");
    c = Vertex(label="C");
    d = Vertex(label="D");
    e = Vertex(label="E");
    a +>:Adjacent:+> b;
    b +>:Adjacent:+> a;
    a +>:Adjacent:+> e;
    e +>:Adjacent:+> a;
    b +>:Adjacent:+> e;
    e +>:Adjacent:+> b;
    b +>:Adjacent:+> c;
    c +>:Adjacent:+> b;
    b +>:Adjacent:+> d;
    d +>:Adjacent:+> b;
    # Second component: 3-cycle F-G-H (no articulation points, no bridges).
    f = Vertex(label="F");
    g = Vertex(label="G");
    h = Vertex(label="H");
    f +>:Adjacent:+> g;
    g +>:Adjacent:+> f;
    g +>:Adjacent:+> h;
    h +>:Adjacent:+> g;
    h +>:Adjacent:+> f;
    f +>:Adjacent:+> h;
    root ++> a;
    root ++> f;
    root spawn ConnectivityAnalyzer();
}
