```jac
"""Revocable API-key lifecycle and security audit trail.

Models the core scenario from issue #42: API keys belong to projects, carry
scopes, can be rotated with a bounded overlap, and can be revoked. A walker
audits every key, walks the revocation graph via typed edges, and reports
which keys are active, which are in their rotation overlap window, and which
are revoked. Secrets (fingerprints) are never printed.
"""

node Project {
    has name: str = "";
    has description: str = "";
}

node APIKey {
    has key_id: str = "";
    has scope: str = "read";          # least-privilege scope label
    has fingerprint: str = "";        # non-recoverable verifier only — never printed
    has created_at: int = 0;
    has expires_at: int = 0;
    has revoked: bool = False;
    has overlap_until: int = 0;       # rotation overlap window end
}

node AuditEvent {
    has event_id: str = "";
    has event_type: str = "";         # created | rotated | revoked | used
    has key_id: str = "";             # safe identifier only (never the secret)
    has note: str = "";
}

# Typed edges: a Project OWNS its APIKeys; APIKeys EMIT AuditEvents.
edge Owns { }
edge Emits { }

walker KeyAuditor {
    has active_count: int = 0;
    has overlap_count: int = 0;
    has revoked_count: int = 0;

    # --- forward sweep from root ---
    can start with Root entry {
        visit [-->];
    }

    can enter_project with Project entry {
        print(f"[project] {here.name} — {here.description}");
        visit [-->];
    }

    can inspect_key with APIKey entry {
        # Classification precedence: REVOKED > OVERLAP > ACTIVE.
        label = "REVOKED" if here.revoked else (
            "OVERLAP" if here.overlap_until > here.expires_at else "ACTIVE"
        );
        if label == "REVOKED" {
            self.revoked_count += 1;
        } elif label == "OVERLAP" {
            self.overlap_count += 1;
        } else {
            self.active_count += 1;
        }
        # Never print the fingerprint — only the safe key_id and scope.
        print(f"  [key {label}] id={here.key_id} scope={here.scope} "
              f"expires_at={here.expires_at} overlap_until={here.overlap_until}");
        # Walk to the audit events emitted by this key via the typed edge.
        visit [->:Emits:->];
    }

    # Union trigger: same audit-event handling regardless of how we
    # arrived (key path OR project-scoped audit history).
    can record_event with AuditEvent entry {
        print(f"    [audit] {here.event_type} key={here.key_id} — {here.note}");
    }
}

with entry {
    # --- demo graph: two projects, several keys, audit events ---
    proj_alpha = Project(name="alpha", description="production billing API");
    proj_beta = Project(name="beta", description="internal metrics API");

    # Alpha project keys
    k_alpha_old = APIKey(
        key_id="k-alpha-001",
        scope="read",
        fingerprint="fp:9f3c:1a2b",
        created_at=1000,
        expires_at=2000,
        overlap_until=2500    # overlap window open (rotation in progress)
    );
    k_alpha_new = APIKey(
        key_id="k-alpha-002",
        scope="write",
        fingerprint="fp:7e44:9d12",
        created_at=1500,
        expires_at=3000,
        overlap_until=0
    );
    k_alpha_dead = APIKey(
        key_id="k-alpha-003",
        scope="admin",
        fingerprint="fp:0000:dead",
        created_at=500,
        expires_at=1500,
        revoked=True
    );

    # Beta project keys
    k_beta_one = APIKey(
        key_id="k-beta-100",
        scope="read",
        fingerprint="fp:abcd:1111",
        created_at=1800,
        expires_at=4000,
        overlap_until=0
    );

    # Audit events keyed by safe identifier (never the secret itself)
    ev1 = AuditEvent(event_id="e1", event_type="created", key_id="k-alpha-001", note="issued");
    ev2 = AuditEvent(event_id="e2", event_type="rotated", key_id="k-alpha-002", note="overlap open");
    ev3 = AuditEvent(event_id="e3", event_type="revoked", key_id="k-alpha-003", note="manual revoke");
    ev4 = AuditEvent(event_id="e4", event_type="created", key_id="k-beta-100", note="issued");

    # --- wire the graph with typed edges ---
    root ++> proj_alpha ++> proj_beta;

    proj_alpha +>:Owns:+> k_alpha_old;
    proj_alpha +>:Owns:+> k_alpha_new;
    proj_alpha +>:Owns:+> k_alpha_dead;
    proj_beta +>:Owns:+> k_beta_one;

    k_alpha_old +>:Emits:+> ev1;
    k_alpha_new +>:Emits:+> ev2;
    k_alpha_dead +>:Emits:+> ev3;
    k_beta_one +>:Emits:+> ev4;

    # --- run the auditor walker from the root ---
    auditor = KeyAuditor();
    root spawn auditor;

    print("--- audit summary ---");
    print(f"active={auditor.active_count} "
          f"overlap={auditor.overlap_count} "
          f"revoked={auditor.revoked_count}");
}
