```jac
"""Critic blast-radius walk: a chunk's fixes cascade into defects because
each fix alters something with dependents it does not visit.

Models the scenario from issue #731:
  - a `Chunk` carries a series of `Fix` nodes that mutate a shared surface
  - each Fix has dependents (`Caller`, `Contract`, `Guard`) that must be
    re-validated after the edit; the original NEXT-ACTION only worried about
    *when* to commit, never about *what the commit broke*
  - the `Critic` walker traverses every chunk and emits the cascade defects
    that fall out of each fix's diff: stale callers, violated contracts, and
    guards that used to be reachable and aren't anymore
"""

node Caller {
    has name: str = "";
    has handles_new_shape: bool = True;
}

node Contract {
    has name: str = "";
    has still_honored: bool = True;
}

node Guard {
    has name: str = "";
    has previously_reachable: bool = True;
}

node Fix {
    has title: str = "";
    # What this fix changed: one of "sig", "out", "guard"
    has kind: str = "sig";
    # Did the builder run the blast-radius check before committing?
    has blast_radius_checked: bool = False;

    has callers: list[Caller] = [];
    has contracts: list[Contract] = [];
    has guards: list[Guard] = [];

    def cascade_defects -> list[str] {
        defects: list[str] = [];
        if not self.blast_radius_checked {
            defects.append(f"FIX '{self.title}' committed without blast-radius check");
        }
        if self.kind == "sig" {
            for c in self.callers {
                if not c.handles_new_shape {
                    defects.append(
                        f"  stale caller: {c.name} does not handle new signature"
                    );
                }
            }
        }
        if self.kind == "out" {
            for k in self.contracts {
                if not k.still_honored {
                    defects.append(f"  contract violated: {k.name}");
                }
            }
        }
        if self.kind == "guard" {
            for g in self.guards {
                if not g.previously_reachable {
                    defects.append(
                        f"  guard {g.name} used to be reachable, no longer is"
                    );
                }
            }
        }
        return defects;
    }
}

node Chunk {
    has label: str = "";
    has fixes: list[Fix] = [];
}

edge Holds {}

walker Critic {
    has log: list[str] = [];
    has rounds: int = 1;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can audit with Chunk entry {
        visit [-->];
        cascade_count = 0;
        header = f"=== round {self.rounds}: chunk '{here.label}' ===";
        self.log.append(header);
        print(header);
        for f in here.fixes {
            line = f"fix: {f.title}  kind={f.kind}  "
                f"blast_radius_checked={f.blast_radius_checked}";
            self.log.append(line);
            print(line);
            for d in f.cascade_defects() {
                self.log.append(d);
                print(d);
                if d.startswith("  ") {
                    cascade_count += 1;
                }
            }
        }
        # Cascade defects from this chunk's fixes open the next review round.
        if cascade_count > 0 {
            self.rounds += 1;
            nxt = f"-> {cascade_count} cascade defect(s) feed round {self.rounds}";
            self.log.append(nxt);
            print(nxt);
        }
    }
}

with entry {
    # Chunk arithmetic passed clean in round 1; the cascade was entirely
    # in fix commits, exactly as the issue describes.
    c = Chunk(label="core-arithmetic-chunk");

    f1 = Fix(
        title="reorder refusal-collapsing branches",
        kind="guard",
        blast_radius_checked=False,
        guards=[Guard(name="empty-input-rejection", previously_reachable=False)]
    );

    f2 = Fix(
        title="return named tuple instead of (a, b)",
        kind="sig",
        blast_radius_checked=False,
        callers=[Caller(name="cli/main.py:format_row", handles_new_shape=False)]
    );

    f3 = Fix(
        title="add `severity` field to Finding",
        kind="out",
        blast_radius_checked=False,
        contracts=[
            Contract(name="boundary-patterns.md#Finding", still_honored=False)
        ]
    );

    c.fixes = [f1, f2, f3];
    root +>:Holds:+> c;

    critic = Critic();
    root spawn critic;

    print("");
    print(f"total rounds the chunk dragged through: {critic.rounds}");
    print(
        "with a pre-commit blast-radius prompt, round-2/3 cascade "
        "defects would have been caught in round 1"
    );
}
