```jac
"""Transitive skill dependencies: recursively resolve nested ai.json skills into a flat lock, deduplicated by (git, commit, path), with cycle and version-conflict guards."""

node Manifest {
    has title: str = "";
}

node Skill {
    has name: str = "";
    has git: str = "";
    has commit: str = "";
    has path: str = "";

    def pin_key() -> str {
        return f"{self.git}@{self.commit}:{self.path}";
    }

    def repo_path_key() -> str {
        return f"{self.git}:{self.path}";
    }
}

edge ListedIn { }

edge DependsOn {
    has spec: str = "";
}

walker DependencyResolver {
    has resolving: list[str] = [];
    has resolved: list[str] = [];
    has lock: list[str] = [];
    has cycles: list[str] = [];
    has conflicts: list[str] = [];
    has pin_keys: list[str] = [];
    has pin_commits: list[str] = [];
    has cycle_header: bool = False;
    has conflict_header: bool = False;

    def in_list(needle: str, haystack: list[str]) -> bool {
        for item in haystack {
            if item == needle {
                return True;
            }
        }
        return False;
    }

    def pop_resolving(key: str) -> None {
        kept = [];
        for k in self.resolving {
            if k != key {
                kept.append(k);
            }
        }
        self.resolving = kept;
    }

    def record_pin(skill: Skill) -> None {
        ck = skill.repo_path_key();
        for (i, pk) in enumerate(self.pin_keys) {
            if pk == ck {
                if self.pin_commits[i] != skill.commit {
                    msg = f"{ck}: locked {self.pin_commits[i]} vs wants {skill.commit}";
                    self.conflicts.append(msg);
                    if not self.conflict_header {
                        print("version conflicts (error-on-conflict):");
                        self.conflict_header = True;
                    }
                    print(f"  ! {msg}");
                }
                return;
            }
        }
        self.pin_keys.append(ck);
        self.pin_commits.append(skill.commit);
    }

    def explore(skill: Skill) -> None {
        key = skill.pin_key();

        if self.in_list(key, self.resolved) {
            return;
        }
        if self.in_list(key, self.resolving) {
            msg = f"cycle at {skill.name} ({key})";
            self.cycles.append(msg);
            if not self.cycle_header {
                print("cycle guards tripped:");
                self.cycle_header = True;
            }
            print(f"  ! {msg}");
            return;
        }

        self.resolving.append(key);

        for dep in [skill ->:DependsOn:->] {
            self.explore(dep);
        }

        self.record_pin(skill);
        line = f"  {skill.name}: {key}";
        self.lock.append(line);
        print(line);
        self.resolved.append(key);
        self.pop_resolving(key);
    }

    can start with Root entry {
        print("spm resolve: walking manifest and transitive ai.json skills");
        print("--- ai.lock (flat, deduped by git@commit:path) ---");
        visit [-->];
    }

    can open with Manifest entry {
        print(f"manifest: {here.title}");
        visit [-->] else { disengage; }
    }

    can resolve with Skill entry {
        if self.in_list(here.pin_key(), self.resolved) {
            disengage;
        }
        self.explore(here);
        visit [->:DependsOn:->] else { disengage; }
    }
}

with entry {
    utils = Skill(
        name="common-utils",
        git="https://git.example/common-utils",
        commit="ddd111",
        path="/"
    );
    lint = Skill(
        name="linting",
        git="https://git.example/linting",
        commit="bbb222",
        path="/skills/lint"
    );
    test = Skill(
        name="testing",
        git="https://git.example/testing",
        commit="ccc333",
        path="/skills/test"
    );
    codegen = Skill(
        name="codegen",
        git="https://git.example/codegen",
        commit="aaa000",
        path="/skills/codegen"
    );
    docs = Skill(
        name="docs-helper",
        git="https://git.example/docs",
        commit="eee444",
        path="/skills/docs"
    );

    lint +>:DependsOn(spec="main"):+> utils;
    test +>:DependsOn(spec="^1.0"):+> utils;
    codegen +>:DependsOn(spec="latest"):+> lint;
    codegen +>:DependsOn:+> test;
    docs +>:DependsOn(spec="main"):+> utils;

    manifest = Manifest(title="project ai.json");
    root ++> manifest;
    manifest +>:ListedIn:+> codegen;
    manifest +>:ListedIn:+> docs;

    root spawn DependencyResolver();
}
