```jac
"""UI component reconciliation: model retained vs retired UI surfaces and
walk the render graph to surface orphans and unreachable demo routes.

The original project hand-rolled a parent-id registry and BFS to decide
which components had reachable mock-mode routes. We lift that machinery
into typed edges and a walker, keeping the reachability semantics (cycle
guard, retirement verdict, surface evidence) explicit.
"""

# ---------- node archetypes ----------

node Component {
    has name: str = "";
    has status: str = "candidate";   # retained | retired | candidate
    has mock_route: str = "";        # documented mock-mode route, if any
    has evidence: str = "";          # browser/console evidence note
}

node Header {
    has name: str = "Header";
    has status: str = "candidate";
    has mock_route: str = "/mock/header";
    has evidence: str = "rendered under order-summary surface";
}

node Circles {
    has name: str = "Circles";
    has status: str = "candidate";   # orphaned in source -> decision below
    has mock_route: str = "";
    has evidence: str = "no live parent usage discovered";
}

node ProductCard {
    has name: str = "ProductCard";
    has status: str = "candidate";   # order-summary variant, orphaned
    has mock_route: str = "";
    has evidence: str = "no live parent usage discovered";
}

node ProgressBar {
    has name: str = "ProgressBar";
    has status: str = "candidate";
    has mock_route: str = "/mock/settings#progress";
    has evidence: str = "settings route reachable";
}

node SVGUpload {
    has name: str = "SVGUpload";
    has status: str = "candidate";
    has mock_route: str = "/mock/settings#upload";
    has evidence: str = "settings route reachable";
}

node SettingsPage {
    has name: str = "SettingsPage";
    has status: str = "retained";
    has mock_route: str = "/mock/settings";
    has evidence: str = "route /mock/settings resolves in dev";
}

node OrderSummaryPage {
    has name: str = "OrderSummaryPage";
    has status: str = "retained";
    has mock_route: str = "";
    has evidence: str = "surface page — hosts components, no dedicated mock route";
}

# ---------- typed edges ----------
# RenderedUnder: a page surface that hosts/uses the component.
# SameSurface: two components sharing a parent surface (evidence of co-render).

edge RenderedUnder {
    has note: str = "";
}

edge SameSurface {
    has note: str = "";
}

# ---------- walker: reconcile UI components ----------

walker Reconciler {
    has visited: list[str] = [];   # explicit cycle guard (walker has no built-in dedup)
    has expected: int = 0;         # populated at Root: how many nodes the walk covers
    has orphans: list[str] = [];
    has reachable: list[str] = [];
    has retired: list[str] = [];

    # Domain logic preserved: orphan = candidate component with no RenderedUnder
    # parent and no documented mock route. The guard set is carried explicitly
    # because walkers on cyclic graphs otherwise loop forever.

    can start with Root entry {
        print("=== UI component reconciliation ===");
        self.expected = len([-->]);
        visit [-->] else { disengage; }
    }

    can audit with Header | Circles | ProductCard | ProgressBar | SVGUpload | SettingsPage | OrderSummaryPage entry {
        if here.name not in self.visited {
            self.visited.append(here.name);

            # Apply the issue's decision rules:
            # 1. Components named Circles or ProductCard -> orphaned in source,
            #    explicit disposition is RETIRED (no mock route fabricated).
            if here.name == "Circles" or here.name == "ProductCard" {
                self.retired.append(here.name);
                print(f"[RETIRED] {here.name} — {here.evidence}");
            } else {
                # 2. Reachable iff some surface renders it (incoming
                #    RenderedUnder edge) OR it has a documented mock route.
                under = [<-:RenderedUnder:<-];
                if len(under) > 0 or here.mock_route != "" {
                    self.reachable.append(here.name);
                    print(f"[RETAINED] {here.name} -> {here.mock_route}  ({here.evidence})");
                } else {
                    # 3. Candidate components with no parent and no route are
                    #    orphans; retained surfaces are reported but not counted.
                    if here.status == "candidate" {
                        self.orphans.append(here.name);
                        print(f"[ORPHAN ] {here.name} — {here.evidence}");
                    } else {
                        print(f"[SURFACE ] {here.name} — {here.evidence}");
                    }
                }
            }

            # Once every queued node has been audited, emit the matrix + report.
            if len(self.visited) == self.expected {
                print("--- component-to-surface matrix ---");
                for n in self.reachable {
                    print(f"  reachable : {n}");
                }
                for n in self.retired {
                    print(f"  retired   : {n}");
                }
                for n in self.orphans {
                    print(f"  orphan    : {n}");
                }
                report {
                    "reachable": self.reachable,
                    "orphans": self.orphans,
                    "retired": self.retired,
                };
            }

            # Continue traversal along the render-relationship edges.
            visit [->:RenderedUnder:->];
            visit [->:SameSurface:->];
        }
        visit [-->];
    }
}

# ---------- demo wiring ----------

with entry {
    settings = SettingsPage();
    order = OrderSummaryPage();
    progress = ProgressBar();
    upload = SVGUpload();
    header = Header();
    circles = Circles();
    card = ProductCard();

    # Reachable: settings hosts ProgressBar and SVGUpload.
    settings +>:RenderedUnder(note="settings hosts ProgressBar"):+> progress;
    settings +>:RenderedUnder(note="settings hosts SVGUpload"):+> upload;

    # Reachable: order summary renders the header component.
    order +>:RenderedUnder(note="order summary renders header"):+> header;

    # SameSurface co-render evidence between ProgressBar and SVGUpload.
    progress +>:SameSurface(note="co-render on settings"):+> upload;

    # Orphans-in-source: Circles and ProductCard get no parent edge and no
    # fabricated mock route -> the walker retires them explicitly.

    root ++> settings;
    root ++> order;
    root ++> progress;
    root ++> upload;
    root ++> header;
    root ++> circles;
    root ++> card;

    root spawn Reconciler();
}
