```jac
"""Role registry: model roles as nodes with inherits edges and walk the
inheritance graph to compute effective permissions.

The DrizzleRoleRegistry issue is that `getRolePermissions` returns only
direct permissions and never follows `inherits`. The reference
RoleRegistry recursively unions inherited permissions and detects
cycles with a `visited` set. This program models that recursion as a
walker over typed `Inherits` edges with an explicit visited guard so
that cyclic inheritance terminates safely instead of looping forever.
"""

node Role {
    has name: str = "";
    has permissions: list[str] = [];
}

edge Inherits {
    has label: str = "inherits";
}

walker PermissionCollector {
    has effective: list[str] = [];
    has visited: list[str] = [];

    can start with Role entry {
        if here.name in self.visited {
            disengage;
        }
        self.visited.append(here.name);
        for perm in here.permissions {
            if perm not in self.effective {
                self.effective.append(perm);
            }
        }
        visit [->:Inherits:->];
    }
}

walker RoleInspector {
    has role_name: str = "";
    has effective: list[str] = [];

    can start with Root entry {
        visit [-->] else {
            report self.effective;
            disengage;
        }
    }

    can inspect with Role entry {
        if here.name == self.role_name {
            collector = PermissionCollector();
            collector spawn here;
            self.effective = collector.effective;
            report self.effective;
            disengage;
        }
        visit [-->] else {
            report self.effective;
            disengage;
        }
    }
}

with entry {
    editor = Role(name="editor", permissions=["read", "write"]);
    author = Role(name="author", permissions=["write"]);
    admin = Role(name="admin", permissions=["manage"]);
    viewer = Role(name="viewer", permissions=["read"]);

    root ++> editor ++> author ++> admin ++> viewer;

    editor +>:Inherits:+> author;
    author +>:Inherits:+> editor;
    admin +>:Inherits:+> editor;

    inspector = RoleInspector(role_name="admin");
    root spawn inspector;
    print(f"admin effective permissions: {inspector.effective}");

    inspector2 = RoleInspector(role_name="editor");
    root spawn inspector2;
    print(f"editor effective permissions: {inspector2.effective}");

    inspector3 = RoleInspector(role_name="viewer");
    root spawn inspector3;
    print(f"viewer effective permissions: {inspector3.effective}");

    inspector4 = RoleInspector(role_name="admin");
    root spawn inspector4;
    print(f"admin again (cycle-safe re-run): {inspector4.effective}");
}
