```jac
"""Recursive planner subgraph: validated topological order vs raw edge order.

Models frankenbeast issue #4184 where PlanGraph.fromTasks validation is
discarded and createWithRawEdges returns tasks in arbitrary insertion order.
"""

node PlanTask {
    has title: str = "";
    has task_id: int = 0;
    has insert_order: int = 0;
}

node SubGraph {
    has reason: str = "";
}

edge DependsOn { }

walker TopoSort {
    has order: list[PlanTask] = [];
    has cyclic: bool = False;
    has done_ids: list[int] = [];
    has seen: list[int] = [];

    can start with SubGraph entry {
        tasks = [here -->];
        remaining = [];
        for t in tasks {
            remaining.append(t);
        }
        while len(remaining) > 0 {
            progressed = False;
            next_remaining = [];
            for t in remaining {
                unmet = False;
                for d in [t ->:DependsOn:->] {
                    if not (d.task_id in self.done_ids) {
                        unmet = True;
                    }
                }
                if unmet {
                    next_remaining.append(t);
                } else {
                    self.order.append(t);
                    self.done_ids.append(t.task_id);
                    progressed = True;
                }
            }
            if not progressed {
                self.cyclic = True;
                self.order = [];
                break;
            }
            remaining = next_remaining;
        }
        visit [-->] else { disengage; }
    }

    can descend with PlanTask entry {
        if here.task_id in self.seen {
            disengage;
        }
        self.seen.append(here.task_id);
        visit [->:DependsOn:->] else { disengage; }
    }
}

walker RawEdgeCollector {
    has raw_order: list[PlanTask] = [];
    has seen: list[int] = [];

    can start with SubGraph entry {
        visit [-->];
    }

    can collect with PlanTask entry {
        if here.task_id in self.seen {
            disengage;
        }
        self.seen.append(here.task_id);
        self.raw_order.append(here);
        visit [-->];
    }
}

walker RecursivePlanner {
    has discard_validated: bool = False;

    can start with SubGraph entry {
        validator = here spawn TopoSort();
        if validator.cyclic {
            print(f"CyclicDependencyError during {here.reason}");
            disengage;
        }
        if self.discard_validated {
            collector = here spawn RawEdgeCollector();
            execution_order = collector.raw_order;
            path_label = "BUG: discarded validated fromTasks, returned raw edges";
        } else {
            execution_order = validator.order;
            path_label = "FIX: returned validated fromTasks graph";
        }
        print(f"[{path_label}] {here.reason}");
        for task in execution_order {
            print(f"  -> {task.title} (insert_order={task.insert_order})");
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    sg = SubGraph(reason="recursive expansion");
    root ++> sg;

    deploy = PlanTask(title="deploy", task_id=4, insert_order=1);
    compile = PlanTask(title="compile", task_id=3, insert_order=2);
    lint = PlanTask(title="lint", task_id=1, insert_order=3);
    test = PlanTask(title="test", task_id=2, insert_order=4);

    sg ++> deploy ++> compile ++> lint ++> test;

    compile +>:DependsOn:+> lint;
    compile +>:DependsOn:+> test;
    deploy +>:DependsOn:+> compile;

    print("=== Buggy _buildSubGraph (validate then discard) ===");
    sg spawn RecursivePlanner(discard_validated=True);

    print("=== Fixed _buildSubGraph (return fromTasks) ===");
    sg spawn RecursivePlanner(discard_validated=False);

    print("=== Cycle probe ===");
    sg_cycle = SubGraph(reason="cycle probe");
    root ++> sg_cycle;
    task_a = PlanTask(title="task_a", task_id=10, insert_order=1);
    task_b = PlanTask(title="task_b", task_id=11, insert_order=2);
    sg_cycle ++> task_a ++> task_b;
    task_a +>:DependsOn:+> task_b;
    task_b +>:DependsOn:+> task_a;
    cycle_check = sg_cycle spawn TopoSort();
    if cycle_check.cyclic {
        print("CyclicDependencyError: cycle detected in task dependencies");
    }
}
