"""Parser comparison run plan: compile an immutable plan population and independently verify receipt completeness across executions, observation cells, differentials, and performance rows."""

edge PlannedIn { }

edge SpawnsCell { }

node PlannedRow {
    has stable_id: str = "";
    has role: str = "required";
    has accounted: bool = False;
}

node RunPlan {
    has schema_id: str = "parser_comparison_run_plan.v1";
