```jac
"""Parser repository split readiness: package dependency ordering, forbidden product boundaries, and split-gate traversal before physical extraction."""

edge DependsOn { }
edge BlockedBy { }

node ParserCrate {
    has name: str = "";
    has version: str = "0.1.0";
    has available: bool = True;
}

node ProductCrate {
    has name: str = "";
    has title: str = "";
    has available: bool = True;
}

node SplitGate {
    has gate_id: str = "";
    has label: str = "";
    has satisfied: bool = False;
}

walker TopoProofer {
    has visiting: list[str] = [];
    has proved: list[str] = [];
    has publish_order: list[str] = [];
    has cycle_found: bool = False;
    has stack: list = [];
    has cursor: list[int] = [];

    can start with Root entry {
        print("=== G7 topological package proof ===");
        seeds = [here -->];
        for s in seeds {
            if not (s.name in self.proved) {
                self.stack += [s];
                self.cursor += [0];
                self.visiting += [s.name];
            }
        }
        while len(self.stack) > 0 {
            top = self.stack[len(self.stack) - 1];
            kids = [top ->:DependsOn:->];
            i = self.cursor[len(self.cursor) - 1];
            pushed = False;
            while i < len(kids) {
                kid = kids[i];
                i += 1;
                if kid.name in self.visiting {
                    self.cycle_found = True;
                    print(f"[CYCLE] dependency loop at {kid.name}");
                } elif not (kid.name in self.proved) {
                    self.cursor[len(self.cursor) - 1] = i;
                    self.stack += [kid];
                    self.cursor += [0];
                    self.visiting += [kid.name];
                    pushed = True;
                    break;
                }
            }
            if not pushed {
                self.stack.pop();
                self.cursor.pop();
                if top.name in self.visiting {
                    self.visiting.remove(top.name);
                }
                if not (top.name in self.proved) {
                    self.proved += [top.name];
                    self.publish_order += [top.name];
                }
            }
        }
        if not self.cycle_found {
            visit [-->];
        } else {
            disengage;
        }
    }

    can show with ParserCrate entry {
        if here.name in self.publish_order {
            print(f"  pack-order: {here.name}");
        }
        visit [-->] else { disengage; }
    }

    can skip_product with ProductCrate entry {
        visit [-->] else { disengage; }
    }

    can skip_gate with SplitGate entry {
        visit [-->] else { disengage; }
    }
}

walker BoundaryAuditor {
    has current_pkg: str = "";
    has violations: list[str] = [];

    can start with Root entry {
        print("=== forbidden dependency boundary audit ===");
        visit [-->];
    }

    can scan with ParserCrate entry {
        self.current_pkg = here.name;
        visit [->:DependsOn:->] else {
            visit [-->];
        };
    }

    can flag with ProductCrate entry {
        msg = f"{self.current_pkg} -> {here.name} (product boundary violation)";
        self.violations += [msg];
        print(f"[VIOLATION] {msg}");
        visit [-->] else { disengage; }
    }

    can skip_gate with SplitGate entry {
        visit [-->] else { disengage; }
    }
}

walker SplitGateAuditor {
    has blocked: list[str] = [];

    can start with Root entry {
        print("=== split gate readiness (G1-G8) ===");
        visit [-->];
    }

    can check with ParserCrate entry {
        visit [->:BlockedBy:->] else {
            print(f"[READY] {here.name} — all gates clear");
            visit [-->];
        };
    }

    can at_gate with SplitGate entry {
        status_lbl = "PASS" if here.satisfied else "BLOCK";
        print(f"  [{status_lbl}] {here.gate_id}: {here.label}");
        if not here.satisfied {
            self.blocked += [f"{here.gate_id}:{here.label}"];
        }
        visit [-->];
    }

    can skip_product with ProductCrate entry {
        visit [-->] else { disengage; }
    }
}

with entry {
    pos = ParserCrate(name="perl-position-tracking", version="0.3.0");
    tok = ParserCrate(name="perl-token", version="0.5.0");
    ast = ParserCrate(name="perl-ast", version="0.8.0");
    lex = ParserCrate(name="perl-lexer", version="0.9.0");
    core = ParserCrate(name="perl-parser-core", version="1.0.0");
    parser = ParserCrate(name="perl-parser", version="1.0.0");
    analyzer = ParserCrate(name="perl-semantic-analyzer", version="0.7.0");
    workspace = ProductCrate(name="perl-workspace");

    g1 = SplitGate(
        gate_id="G1",
        label="facade authority",
        satisfied=True,
    );
    g7 = SplitGate(
        gate_id="G7",
        label="package/release isolation",
        satisfied=False,
    );

    tok +>:DependsOn:+> pos;
    lex +>:DependsOn:+> tok;
    core +>:DependsOn:+> lex;
    core +>:DependsOn:+> ast;
    parser +>:DependsOn:+> core;
    analyzer +>:DependsOn:+> core;
    analyzer +>:DependsOn:+> workspace;

    parser +>:BlockedBy:+> g1;
    parser +>:BlockedBy:+> g7;

    root ++> parser ++> core ++> lex ++> tok ++> pos;
    root ++> ast;
    root ++> analyzer;
    root ++> workspace;

    root spawn TopoProofer();
    root spawn BoundaryAuditor();
    root spawn SplitGateAuditor();
}
