"""Skill turn execution: sequential script calls, cumulative budgets, and idempotent evidence replay."""

node Question {
    has thread_id: str = "";
    has locked: bool = False;
    has executed_calls: list[str] = [];
    has executed_fps: list[str] = [];
    has rejected_calls: list[str] = [];
}

node SkillTurn {
    has max_calls: int = 4;
    has cpu_budget_ms: int = 100;
    has wall_budget_ms: int = 200;
    has calls_consumed: int = 0;
    has cpu_consumed_ms: int = 0;
    has wall_consumed_ms: int = 0;
}

node SkillCall {
    has tool_call_id: str = "";
    has fingerprint: str = "";
    has script_path: str = "";
    has cpu_cost_ms: int = 0;
    has wall_cost_ms: int = 0;
}

node SkillOutcome {
    has tool_call_id: str = "";
    has fingerprint: str = "";
    has result_kind: str = "none";
    has summary: str = "";
}

edge Hosts { }

edge ScheduledIn {
    has seq: int = 0;
}

edge EvidenceSlot {
    has tool_call_id: str = "";
    has fingerprint: str = "";
}

edge RecordedAs { }

walker SkillTurnExecutor {
    has host: Question | None = None;
    has turn: SkillTurn | None = None;
    has executed: int = 0;
    has replayed: int = 0;
    has conflicts: int = 0;
    has budget_rejects: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can attach with Question entry {
        self.host = here;
        visit [->:Hosts:->];
    }

    can traverse_turn with SkillTurn entry {
        self.turn = here;
        visit [->:ScheduledIn:->];
    }

    can dispatch with SkillCall entry {
        turn = self.turn;
        host = self.host;
        if turn is None or host is None {
            visit [-->] else { disengage; };
        }

        idx = 0;
        found_id = False;
        found_fp = False;
        while idx < len(host.executed_calls) {
            if host.executed_calls[idx] == here.tool_call_id {
                found_id = True;
                if host.executed_fps[idx] == here.fingerprint {
                    found_fp = True;
                }
                break;
            }
            idx += 1;
        }

        already_rejected = False;
        ridx = 0;
        while ridx < len(host.rejected_calls) {
            if host.rejected_calls[ridx] == here.tool_call_id {
                already_rejected = True;
                break;
            }
            ridx += 1;
        }

        if found_id and not found_fp {
            print(f"[CONFLICT] {here.tool_call_id} script_call_conflict");
            self.conflicts += 1;
            disengage;
        } elif found_id and found_fp {
            print(f"[REPLAY] {here.tool_call_id} stored outcome");
            self.replayed += 1;
            disengage;
        } elif turn.calls_consumed >= turn.max_calls {
            print(f"[REJECT] {here.tool_call_id} call cap exceeded");
            self.budget_rejects += 1;
            if not already_rejected {
                host.rejected_calls.append(here.tool_call_id);
            }
        } elif (turn.cpu_consumed_ms + here.cpu_cost_ms) > turn.cpu_budget_ms {
            print(f"[REJECT] {here.tool_call_id} cpu budget exceeded");
            self.budget_rejects += 1;
            if not already_rejected {
                host.rejected_calls.append(here.tool_call_id);
            }
        } elif (turn.wall_consumed_ms + here.wall_cost_ms) > turn.wall_budget_ms {
            print(f"[REJECT] {here.tool_call_id} wall budget exceeded");
            self.budget_rejects += 1;
            if not already_rejected {
                host.rejected_calls.append(here.tool_call_id);
            }
        } else {
            kind = "json";
            outcome = SkillOutcome(
                tool_call_id=here.tool_call_id,
                fingerprint=here.fingerprint,
                result_kind=kind,
                summary=f"ok:{here.script_path}",
            );
            host +>:EvidenceSlot(
                tool_call_id=here.tool_call_id,
                fingerprint=here.fingerprint,
            ):+> outcome;
            here +>:RecordedAs:+> outcome;
            turn.calls_consumed += 1;
            turn.cpu_consumed_ms += here.cpu_cost_ms;
            turn.wall_consumed_ms += here.wall_cost_ms;
            host.executed_calls.append(here.tool_call_id);
            host.executed_fps.append(here.fingerprint);
            print(f"[EXECUTE] {here.tool_call_id} {here.script_path}");
            self.executed += 1;
        }

        visit [-->];
    }
}

with entry {
    chat = Question(thread_id="chat-42");
    turn = SkillTurn(max_calls=4, cpu_budget_ms=100, wall_budget_ms=200);
    root ++> chat;
    chat +>:Hosts:+> turn;

    first = SkillCall(
        tool_call_id="tc-1",
        fingerprint="fp-alpha",
        script_path="summarize.py",
        cpu_cost_ms=30,
        wall_cost_ms=40,
    );
    dupe = SkillCall(
        tool_call_id="tc-1",
        fingerprint="fp-alpha",
        script_path="summarize.py",
        cpu_cost_ms=30,
        wall_cost_ms=40,
    );
    clash = SkillCall(
        tool_call_id="tc-1",
        fingerprint="fp-beta",
        script_path="summarize.py",
        cpu_cost_ms=20,
        wall_cost_ms=30,
    );
    heavy = SkillCall(
        tool_call_id="tc-2",
        fingerprint="fp-gamma",
        script_path="transform.py",
        cpu_cost_ms=80,
        wall_cost_ms=90,
    );

    turn +>:ScheduledIn(seq=1):+> first;
    turn +>:ScheduledIn(seq=2):+> dupe;
    turn +>:ScheduledIn(seq=3):+> clash;
    turn +>:ScheduledIn(seq=4):+> heavy;

    auditor = SkillTurnExecutor();
    root spawn auditor;
    print(
        f"turn evidence: executed={auditor.executed} "
        f"replayed={auditor.replayed} conflicts={auditor.conflicts} "
        f"rejects={auditor.budget_rejects} "
        f"cpu={turn.cpu_consumed_ms}/{turn.cpu_budget_ms}",
    );
}
