"""FreeFlow PATH-shadow recursion model.

A bare `fflow` hook resolved through ambient PATH can delegate back to the
same package and recurse without bound (issue #156). This program models
the incident's call chain as a typed graph and inspects it with a walker
that enforces the issue's fail-closed safeguards:

  Plugin --Spawns--> Hook --Invokes--> ResolvedBinary --DelegatesTo--> Target

Safeguards checked while descending:
  1. the plugin entry point must be plugin-local/absolute, not ambient PATH;
  2. the hook must reap its whole process group on timeout/failure;
  3. the resolved binary must not self-delegate to the same package;
  4. descent is bounded by a depth limit (process-tree cap).
"""

node Plugin {
    has name: str = "";
    has hook_command: str = "";
    has absolute_entry: str = "";
}

node Hook {
    has stage: str = "";
    has timeout_s: int = 0;
    has from_path: bool = False;
    has terminates_tree: bool = True;
}

node ResolvedBinary {
    has label: str = "";
    has self_delegates: bool = False;
    has terminates_tree: bool = True;
}

node Target {
    has package: str = "";
    has kind: str = "";
}

edge Spawns { }
edge Invokes { }
edge DelegatesTo { }

walker ChainInspector {
    has depth_limit: int = 4;
    has depth: int = 0;
    has `report: list[str] = [];
    has chain_label: str = "";

    can start with Root entry {
        visit [-->]
        else {
            hp = Plugin(
                name="@freematters/freeflow",
                hook_command="fflow _hook post-tool-use",
                absolute_entry="/opt/freeflow/dist/cli.js",
            );
            hh = Hook(
                stage="post-tool-use",
                timeout_s=10,
                from_path=False,
                terminates_tree=True,
            );
            hb = ResolvedBinary(
                label="/opt/freeflow/dist/cli.js",
                self_delegates=False,
                terminates_tree=True,
            );
            ht = Target(package="@freematters/freeflow", kind="cli-entry");
            here +>:Spawns:+> hp;
            hp +>:Invokes:+> hh;
            hh +>:Invokes:+> hb;
            hb +>:DelegatesTo:+> ht;
            visit [-->];
        }
    }

    can inspect_plugin with Plugin entry {
        visit [-->];
        entry_point = here.absolute_entry if here.absolute_entry else here.hook_command;
        deterministic = "yes" if here.absolute_entry else "NO (PATH)";
        self.`report.append(
            f"plugin={here.name} entry={entry_point} deterministic={deterministic}"
        );
        if not here.absolute_entry {
            self.`report.append("FAIL-CLOSED: hook uses ambient PATH, not plugin-local entry");
            disengage;
        }
    }

    can inspect_hook with Hook entry {
        visit [-->];
        self.depth += 1;
        if self.depth > self.depth_limit {
            self.`report.append(
                f"FAIL-CLOSED: descent exceeded depth {self.depth_limit} (process-tree cap)"
            );
            disengage;
        }
        guard = "ok" if here.timeout_s > 0 and here.terminates_tree else "weak";
        self.`report.append(
            f"hook stage={here.stage} timeout={here.timeout_s}s termination_guard={guard}"
        );
        if not here.terminates_tree {
            self.`report.append("FAIL-CLOSED: hook does not reap its process group");
            disengage;
        }
    }

    can inspect_binary with ResolvedBinary entry {
        visit [-->];
        self.`report.append(f"binary={here.label} self_delegates={here.self_delegates}");
        if here.self_delegates {
            self.`report.append(
                f"FAIL-CLOSED: resolved binary '{here.label}' self-delegates to the same package"
            );
            disengage;
        }
    }

    can inspect_target with Target entry {
        self.`report.append(f"target reached: {here.package} ({here.kind})");
        visit [-->] else { disengage; }
    }
}

with entry {
    hp = Plugin(
        name="@freematters/freeflow",
        hook_command="fflow _hook post-tool-use",
        absolute_entry="/opt/freeflow/dist/cli.js",
    );
    hh = Hook(
        stage="post-tool-use",
        timeout_s=10,
        from_path=False,
        terminates_tree=True,
    );
    hb = ResolvedBinary(
        label="/opt/freeflow/dist/cli.js",
        self_delegates=False,
        terminates_tree=True,
    );
    ht = Target(package="@freematters/freeflow", kind="cli-entry");
    root +>:Spawns:+> hp;
    hp +>:Invokes:+> hh;
    hh +>:Invokes:+> hb;
    hb +>:DelegatesTo:+> ht;

    sp = Plugin(
        name="@freematters/freeflow",
        hook_command="fflow _hook post-tool-use",
        absolute_entry="",
    );
    sh = Hook(
        stage="post-tool-use",
        timeout_s=10,
        from_path=True,
        terminates_tree=False,
    );
    sb = ResolvedBinary(
        label="local-shim/fflow",
        self_delegates=True,
        terminates_tree=False,
    );
    st = Target(package="@freematters/freeflow", kind="recursion-loop");
    sp +>:Invokes:+> sh;
    sh +>:Invokes:+> sb;
    sb +>:DelegatesTo:+> st;

    print("=== healthy chain ===");
    w1 = root spawn ChainInspector(depth_limit=4, chain_label="healthy");
    for line in w1.`report {
        print(line);
    }
    print("");

    print("=== pathological shadowed-PATH chain ===");
    w2 = sp spawn ChainInspector(depth_limit=4, chain_label="pathological");
    for line in w2.`report {
        print(line);
    }
}
