"""Extension install path-traversal defense model.

Demonstrates the core scenario from gemini-cli issue #29076: extension
names must be validated so that ``path.join(extensionsDir, name)``
cannot escape the extensions directory. The model uses a tree of
``Dir`` nodes connected by ``Contains`` edges and ``Extension`` request
nodes. A walker traverses from the root, locates the extensions ``Dir``
subtree, and for every ``Extension`` virtually walks the proposed path
through that subtree to verify the resolved location stays inside the
extensions root.
"""

node Dir {
    has name: str = "";
    has depth: int = 0;
}

node File {
    has name: str = "";
}

node Extension {
    has title: str = "";
    has proposed_name: str = "";
    has is_safe: bool = True;
    has reject_reason: str = "";
}

edge Contains { }

walker PathAuditor {
    has segments: list[str] = [];
    has safe: bool = True;
    has reason: str = "";
    has ext_root_depth: int = 0;
    has current_depth: int = 0;
    has found_ext_root: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can locate with Dir entry {
        if not self.found_ext_root {
            self.found_ext_root = True;
            self.ext_root_depth = here.depth;
            self.current_depth = here.depth;
        }
        visit [-->];
    }

    can audit with Extension entry {
        self.safe = True;
        self.reason = "";
        raw = here.proposed_name.replace("\\", "/");
        segs = raw.split("/");
        if segs == [] or segs == [""] {
            segs = [""];
        }
        # Simulate walking: start at ext_root_depth, process each segment
        depth = self.ext_root_depth;
        rejected = False;
        reject_msg = "";
        if segs[0] == "" {
            rejected = True;
            reject_msg = "absolute path rejected";
        } else {
            for seg in segs {
                if seg == ".." {
                    if depth == self.ext_root_depth {
                        rejected = True;
                        reject_msg = "traversal escapes extensions root";
                        break;
                    }
                    depth = depth - 1;
                } elif seg != "" {
                    depth = depth + 1;
                }
            }
        }
        self.safe = not rejected;
        self.reason = reject_msg;
        label = "ACCEPT" if self.safe else "REJECT";
        tail = f" ({self.reason})" if not self.safe else "";
        print(f"[{label}] '{here.title}' -> '{here.proposed_name}'" + tail);
        disengage;
    }

    can land with File entry {
        return;
    }
}

with entry {
    extensions_dir = Dir(name="extensions", depth=0);
    tools_dir = Dir(name="tools", depth=1);
    linters_dir = Dir(name="linters", depth=2);
    cache_dir = Dir(name="cache", depth=0);

    root ++> extensions_dir;
    extensions_dir +>:Contains:+> tools_dir;
    tools_dir +>:Contains:+> linters_dir;
    root ++> cache_dir;

    good_ext = Extension(title="safe-ext", proposed_name="tools/linters");
    traversal_ext = Extension(title="evil-ext", proposed_name="../../etc/passwd");
    absolute_ext = Extension(title="abs-ext", proposed_name="/usr/local/bin");
    sibling_ext = Extension(title="sibling-ext", proposed_name="../cache/payload");
    plain_ext = Extension(title="plain-ext", proposed_name="plain-name");
    nested_ext = Extension(title="nested-ext", proposed_name="tools/nested/deep");

    root ++> good_ext;
    root ++> traversal_ext;
    root ++> absolute_ext;
    root ++> sibling_ext;
    root ++> plain_ext;
    root ++> nested_ext;

    PathAuditor() spawn root;
}
