A maintainer on the project hydra-db/hydradb-mcp (TypeScript) filed this issue about hand-rolled graph machinery causing pain:

Issue #39: Performance: buildRecalledContext() O(n²) on Graph Relations causes high query latency

## Overview

`buildRecalledContext()` in `src/context.ts` (lines 1-200) has O(n²) complexity when processing graph relations. For each chunk, it scans ALL relations to find matches, causing query p99 latency to spike to 2s+; the function dominates the query hot path (verified via static analysis + code review).

## Pain

- 100 chunks × 500 relations = 50,000 iterations per query
- Worst case: 500 chunks × 2000 relations = 1,000,000 iterations
- Query p99 latency ~2s → target <500ms

## Proposed Solution

Pre-build a `chunkId → relationIds` index during response processing, then use O(1) lookup per chunk instead of a full relation scan.

```ts
// Build once during response processing
const chunkToRelationIds = new Map<string, string[]>();
for (const [gid, rel] of Object.entries(relationIndex)) {
  for (const triplet of rel.triplets ?? []) {
    const chunkId = triplet.relation?.chunk_id;
    if (chunkId) {
      if (!chunkToRelationIds.has(chunkId)) {
        chunkToRelationIds.set(chunkId, []);
      }
      chunkToRelationIds.get(chunkId)!.push(gid);
    }
  }
}

// Then in chunk loop: O(1) lookup
const linkedGids = chunkToRelationIds.get(chunk.chunk_uuid) ?? [];
for (const gid of linkedGids) {
  if (relationIndex[gid]) matchedRelations.push(relationIndex[gid]);
}
```

Complexity: O(chunks + relations) instead of O(chunks × relations) → expected 50-70% reduction in context build time.

## Alternatives Considered

1. **Memoize per-chunk relations** — similar complexity, but requires cache invalidation logic
2. **Push indexing upstream to @hydradb/sdk** — better long-term, but requires SDK release cycle
3. **Limit maxGroupOccurrences** — reduces output size but doesn't fix the scan cost

Chosen approach: in-function index build — localized change, immediate impact, no external dependencies.

## Validation

- Add timing logs to `runQuery()` in `server.ts`
- Run the same query twice, verify 50%+ latency reduction

## Related

- Issue #2: Sync SDK calls block event loop — should be addressed together

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Hydra buildRecalledContext: naive O(chunks×relations) scans vs indexed typed-edge lookup."""

node ChunkShelf {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Chunk {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has chunk_uuid: str = "";
    has snippet: str = "";
}

node Relation {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has gid: str = "";
    has predicate: str = "";
    has triplet_chunk_ids: list[str] = [];
}

edge IndexedLink { }

walker NaiveRecaller {
    has chunks: list[Chunk] = [];
    has relations: list[Relation] = [];
    has scans: int = 0;
    has matches: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can cross_shelf with ChunkShelf entry {
        visit [-->];
    }

    can gather_chunk with Chunk entry {
        if here not in self.chunks {
            self.chunks.append(here);
            for r in self.relations {
                self.scans += 1;
                if here.chunk_uuid in r.triplet_chunk_ids {
                    self.matches += 1;
                    print(f"NAIVE match {here.chunk_uuid} <- {r.gid}");
                }
            }
        }
        visit [-->];
    }

    can gather_relation with Relation entry {
        if here not in self.relations {
            self.relations.append(here);
            for c in self.chunks {
                self.scans += 1;
                if c.chunk_uuid in here.triplet_chunk_ids {
                    self.matches += 1;
                    print(f"NAIVE match {c.chunk_uuid} <- {here.gid}");
                }
            }
        }
        visit [-->];
    }
}

walker IndexBuilder {
    has chunk_by_uuid: dict[str, Chunk] = {};
    has pending: dict[str, list[Relation]] = {};
    has seen: list[Relation] = [];
    has built: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can cross_shelf with ChunkShelf entry {
        visit [-->];
    }

    def add_link(c: Chunk, r: Relation) {
        c +>:IndexedLink:+> r;
        self.built += 1;
    }

    can index_chunk with Chunk entry {
        self.chunk_by_uuid[here.chunk_uuid] = here;
        if here.chunk_uuid in self.pending {
            for r in self.pending[here.chunk_uuid] {
                self.add_link(here, r);
            }
            self.pending.pop(here.chunk_uuid);
        }
        visit [-->];
    }

    can link with Relation entry {
        if here not in self.seen {
            self.seen.append(here);
            for cid in here.triplet_chunk_ids {
                c = self.chunk_by_uuid.get(cid, None);
                if c is not None {
                    self.add_link(c, here);
                } else {
                    if cid not in self.pending {
                        self.pending[cid] = [];
                    }
                    self.pending[cid].append(here);
                }
            }
        }
        visit [-->];
    }
}

walker IndexedRecaller {
    has lookups: int = 0;
    has matched: list[Relation] = [];
    has matches: int = 0;

    can start with ChunkShelf entry {
        visit [-->];
    }

    can recall with Chunk entry {
        self.lookups += 1;
        print(f"INDEXED recall {here.chunk_uuid}");
        for r in [here ->:IndexedLink:->] {
            self.matched.append(r);
            self.matches += 1;
            print(f"INDEXED match {r.gid} ({r.predicate})");
        }
        visit [-->];
    }
}

with entry {
    shelf = ChunkShelf(title="chunk-shelf");
    root ++> shelf
        ++> Chunk(
            title="alpha",
            chunk_uuid="uuid-1",
            snippet="alpha"
        )
        ++> Chunk(
            title="beta",
            chunk_uuid="uuid-2",
            snippet="beta"
        )
        ++> Chunk(
            title="gamma",
            chunk_uuid="uuid-3",
            snippet="gamma"
        );
    root ++> Relation(
        title="mentions",
        gid="g-1",
        predicate="mentions",
        triplet_chunk_ids=["uuid-1", "uuid-2"]
    )
        ++> Relation(
            title="defines",
            gid="g-2",
            predicate="defines",
            triplet_chunk_ids=["uuid-2"]
        )
        ++> Relation(
            title="links",
            gid="g-3",
            predicate="links",
            triplet_chunk_ids=["uuid-1"]
        )
        ++> Relation(
            title="quotes",
            gid="g-4",
            predicate="quotes",
            triplet_chunk_ids=["uuid-3"]
        )
        ++> Relation(
            title="orphan",
            gid="g-5",
            predicate="orphan",
            triplet_chunk_ids=["uuid-99"]
        );

    print("=== buildRecalledContext: naive O(n^2) relation scan ===");
    naive = NaiveRecaller();
    root spawn naive;
    print(f"Naive scans={naive.scans} matches={naive.matches}");

    print("=== pre-build chunkId -> relationIds index ===");
    indexer = IndexBuilder();
    root spawn indexer;
    print(f"IndexedLink edges built={indexer.built}");

    print("=== indexed O(1) lookup per chunk ===");
    indexed = IndexedRecaller();
    shelf spawn indexed;
    print(f"Indexed lookups={indexed.lookups} matches={indexed.matches}");
}
