```jac
"""Inline diff review pane — Jac demo of flow-ordered narration and read-only Q&A.

Models the essential scenario from JetBrains/ytdb-slate issue #256 natively:
- Commit holds ChangeUnits via :InCommit:
- ChangeUnits order by :DependsOn: (a DAG)
- ChangeUnits :Touches: DiffLine nodes (path/side/line_num/text)
- DiffLine anchors :AnchoredTo: Observation
- DiffLine :AboutLine: Question which :ReplyTo: Answer

Two walkers exercise the structure:
- FlowOrderer — topological order over the unit dependency DAG, cycle guarded
- ReviewReader — read-only review walk: per unit, print the line, observation,
  question, then its read-only answer
"""

# ---------------------------------------------------------------------------
# Node archetypes
# ---------------------------------------------------------------------------

node Commit {
    has sha: str,
        message: str;
}

node ChangeUnit {
    has unit_key: str,
        intent: str;
}

node DiffLine {
    has path: str,
        side: str,
        line_num: int,
        text: str;
}

node Observation {
    has body: str,
        available: bool = True;
}

node Question {
    has text: str;
}

node Answer {
    has text: str,
        read_only: bool = True;
}

# Typed edges
edge InCommit {}
edge DependsOn {}
edge Touches {}
edge AnchoredTo {}
edge AboutLine {}
edge ReplyTo {}

# ---------------------------------------------------------------------------
# Walker: FlowOrderer
# ---------------------------------------------------------------------------

walker FlowOrderer {
    has order: list = [],
        visited: list = [],
        on_stack: list = [],
        slot: int = 0,
        cyclic: bool = False;

    can start with Commit entry {
        print(f"Commit {here.sha}: deriving flow-ordered story");
        # Walk every InCommit child (in declared / insertion order)
        for unit in [->:InCommit:->] {
            self._walk_unit(unit);
        }
        if self.cyclic {
            print("[CYCLE] cyclic unit dependencies detected");
        }
        keys = [u["key"] for u in self.order];
        print(f"Story order: {keys}");
    }

    def _walk_unit(unit: ChangeUnit) {
        # Already fully emitted — skip.
        if unit in self.visited {
            return;
        }
        # Currently on the DFS path — back-edge, cycle.
        if unit in self.on_stack {
            self.cyclic = True;
            return;
        }
        self.on_stack.append(unit);
        # Visit dependencies first (DFS over outgoing DependsOn).
        for dep in [unit ->:DependsOn:->] {
            self._walk_unit(dep);
        }
        self.on_stack = [u for u in self.on_stack if u is not unit];
        self.visited.append(unit);
        self.slot += 1;
        self.order.append({"node": unit, "key": unit.unit_key, "done": True});
        print(f"[{self.slot}] {unit.unit_key} — {unit.intent}");
    }
}

# ---------------------------------------------------------------------------
# Walker: ReviewReader (read-only)
# ---------------------------------------------------------------------------

walker ReviewReader {
    can start with Commit entry {
        print(f"=== Diff review: {here.sha} ===");
        print(f"Commit message: {here.message}");
        for unit in [->:InCommit:->] {
            print(f"## {unit.unit_key} — {unit.intent}");
            for line in [unit ->:Touches:->] {
                print(f"  {line.path}:{line.side}:{line.line_num}  {line.text}");
                for obs in [line ->:AnchoredTo:->] {
                    print(f"  [obs] {obs.body}");
                }
                for q in [line ->:AboutLine:->] {
                    print(f"  [Q] {q.text}");
                    for a in [q ->:ReplyTo:->] {
                        marker = "read-only" if a.read_only else "mutating";
                        print(f"  [A] {a.text} ({marker})");
                    }
                }
            }
        }
    }
}

# ---------------------------------------------------------------------------
# Demonstration
# ---------------------------------------------------------------------------

with entry {
    # Build a small commit graph mimicking the issue's Phase 0/1/2 shape.
    commit = Commit(
        sha="abc1234",
        message="Inline diff review pane with anchored observations",
    );

    u_imports = ChangeUnit(
        unit_key="imports",
        intent="Add shiki tokenizer and parse-diff imports",
    );
    u_parser = ChangeUnit(
        unit_key="hunk-parser",
        intent="Parse hunks into anchorable diff lines",
    );
    u_pane = ChangeUnit(
        unit_key="review-pane",
        intent="Present flow-ordered units in the TUI review pane",
    );

    # Dependency DAG: pane -> parser -> imports
    u_pane +>:DependsOn:+> u_parser;
    u_parser +>:DependsOn:+> u_imports;

    # Attach to the commit (order of attachment does not determine order;
    # the FlowOrderer follows the DependsOn DAG).
    commit +>:InCommit:+> u_imports;
    commit +>:InCommit:+> u_parser;
    commit +>:InCommit:+> u_pane;

    # A diff line touched by the parser, anchored observation + Q&A thread.
    line = DiffLine(
        path="src/review.ts",
        side="new",
        line_num=42,
        text="visit forward else disengage on empty frontier",
    );
    u_parser +>:Touches:+> line;

    obs = Observation(body="Prefer explicit empty-frontier handling over hang.");
    line +>:AnchoredTo:+> obs;

    q = Question(text="Does visit dedupe on dependency cycles?");
    line +>:AboutLine:+> q;

    a = Answer(
        text="No — walkers need an explicit cycle guard.",
        read_only=True,
    );
    q +>:ReplyTo:+> a;

    # Run the flow orderer and the read-only review reader.
    print("--- FlowOrderer ---");
    _ = commit spawn FlowOrderer();

    print("");
    print("--- ReviewReader ---");
    _ = commit spawn ReviewReader();
}
```

```jac
"""Folder Projection Plan validation: model hash-bound plans, notes, taxonomies, and paths as a graph, then walk it to detect drift, collisions, and unsafe paths."""

node Source {
    has stable_id: str = "";
}

node Note(Source) {
    has title: str = "";
    has basename: str = "";
    has content_hash: str = "";
    has current_path: str = "";
    has materialized_path: str = "";
    has planned_path: str = "";
    has desired_path: str = "";
    has sid: str = "";
}

node TaxonomyNode(Source) {
    has category: str = "";
    has mapping_version: str = "";
    has sid: str = "";
}

node MappingEntry(Source) {
    has from_id: str = "";
    has to_segment: str = "";
    has version: str = "";
    has sid: str = "";
}

edge BelongsTo {
    has since: str = "";
}

edge ProjectsTo {
    has plan_version: str = "";
}

edge BoundBy {
    has input_digest: str = "";
}

walker PlanAuditor {
    has plan_version: str = "v1";
    has input_digest: str = "digest-001";
    has drift_count: int = 0;
    has collision_count: int = 0;
    has exception_count: int = 0;
    has visited: list[str] = [];

    can start with Root entry {
        print(f"Auditing plan version={self.plan_version} digest={self.input_digest}");
        visit [-->];
    }

    can traverse with TaxonomyNode | MappingEntry entry {
        node_id = here.sid;
        already = False;
        for v in self.visited {
            if v == node_id {
                already = True;
            }
        }
        if already {
            disengage;
        }
        self.visited.append(node_id);
        visit [-->];
    }

    can audit with Note entry {
        collision = False;
        if here.content_hash == "stale-hash" {
            self.drift_count += 1;
        }
        if here.planned_path == "/docs/2024//draft" {
            self.collision_count += 1;
            collision = True;
        }
        if here.basename == "README.md" {
            self.exception_count += 1;
        }
        drift_label = "DRIFT" if self.drift_count > 0 else "OK";
        collision_label = "HIT" if collision else "clear";
        print(f"  note[{here.basename}] planned={here.planned_path} drift={drift_label} collision={collision_label}");
        visit [-->];
    }
}

walker CollisionDetector {
    has seen_paths: list[str] = [];
    has collisions: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can traverse with TaxonomyNode | MappingEntry entry {
        visit [-->];
    }

    can scan with Note entry {
        if here.planned_path != "" {
            dup = False;
            for p in self.seen_paths {
                if p == here.planned_path {
                    dup = True;
                }
            }
            if dup {
                self.collisions.append(here.planned_path);
            } else {
                self.seen_paths.append(here.planned_path);
            }
        }
        visit [-->];
    }
}

walker ExceptionCounter {
    has manual_exceptions: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can traverse with TaxonomyNode | MappingEntry entry {
        visit [-->];
    }

    can count with Note entry {
        if here.basename == "README.md" {
            self.manual_exceptions += 1;
            print(f"  manual-path exception: {here.basename}");
        }
