```jac
"""Bounded RFC 5280 certificate path construction and validation demo.

Models peer-supplied intermediates plus explicit trust anchors, walks issuer
chains with cycle/depth/budget guards, and validates policy at an injected UTC
instant. V1 reports revocation-not-checked and performs no network fetch.
"""

node Certificate {
    has subject: str = "";
    has issuer: str = "";
    has not_before: int = 0;
    has not_after: int = 0;
    has is_ca: bool = False;
    has path_len: int = 0;
    has unlimited_path_len: bool = True;
    has server_auth: bool = False;
    has sig_valid: bool = True;
}

node TrustAnchor {
    has subject: str = "";
    has label: str = "";
}

node ValidationPolicy {
    has validation_time: int = 0;
    has max_depth: int = 8;
    has search_budget: int = 32;
    has clock_available: bool = True;
}

edge Issues { }
edge IssuedBy { }
edge Anchors { }

walker PathConstructor {
    has budget: int = 16;
    has target_subject: str = "";
    has seen: list[str] = [];
    has path: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can build with Certificate entry {
        if here.subject in self.seen {
            print("FAIL: cycle or duplicate certificate in path");
            disengage;
        }
        self.seen.append(here.subject);
        self.path.append(here.subject);
        if here.subject == self.target_subject {
            print(f"built candidate path: {self.path}");
            disengage;
        }
        self.budget -= 1;
        if self.budget <= 0 {
            print("FAIL: construction budget exhausted");
            disengage;
        }
        visit [->:Issues:->] else { disengage; }
    }
}

walker CertPathValidator {
    has validation_time: int = 0;
    has max_depth: int = 8;
    has budget: int = 32;
    has trust_subjects: list[str] = [];
    has seen: list[str] = [];
    has depth: int = 0;
    has valid: bool = False;
    has status: str = "";

    def check_time(cert: Certificate) -> bool {
        return (
            self.validation_time >= cert.not_before
            and self.validation_time <= cert.not_after
        );
    }

    def finish_chain(top: Certificate) {
        if top.issuer in self.trust_subjects {
            self.valid = True;
            self.status = "valid";
            print(
                f"PASS: chain anchors at trusted '{top.issuer}' "
                f"(revocation-not-checked)"
            );
        } else {
            self.status = "untrusted-root";
            print(f"FAIL: untrusted issuer '{top.issuer}'");
        }
    }

    def process_cert(cert: Certificate, is_leaf: bool) -> bool {
        if self.budget <= 0 {
            self.status = "budget-exhausted";
            print("FAIL: validation search budget exhausted");
            return False;
        }
        self.budget -= 1;

        if cert.subject in self.seen {
            self.status = "cycle-or-duplicate";
            print(f"FAIL: duplicate certificate '{cert.subject}'");
            return False;
        }
        self.seen.append(cert.subject);
        self.depth += 1;

        if self.depth > self.max_depth {
            self.status = "excessive-depth";
            print("FAIL: excessive path depth");
            return False;
        }

        if not self.check_time(cert) {
            self.status = "validity";
            print(
                f"FAIL: '{cert.subject}' outside validity at "
                f"t={self.validation_time}"
            );
            return False;
        }

        if not cert.sig_valid {
            self.status = "signature";
            print(f"FAIL: bad signature on '{cert.subject}'");
            return False;
        }

        if is_leaf {
            if not cert.server_auth {
                self.status = "policy";
                print("FAIL: leaf missing TLS serverAuth EKU");
                return False;
            }
            if cert.is_ca {
                self.status = "policy";
                print("FAIL: TLS leaf must not be a CA");
                return False;
            }
        } else {
            if not cert.is_ca {
                self.status = "policy";
                print(f"FAIL: '{cert.subject}' is not a CA");
                return False;
            }
            remaining = self.depth - 1;
            if not cert.unlimited_path_len and cert.path_len < remaining {
                self.status = "policy";
                print(f"FAIL: pathLen violated on '{cert.subject}'");
                return False;
            }
        }
        return True;
    }

    can validate with Certificate entry {
        is_leaf = self.depth == 0;
        if not self.process_cert(here, is_leaf=is_leaf) {
            disengage;
        }
        visit [->:IssuedBy:->] else {
            self.finish_chain(here);
            disengage;
        }
    }
}

with entry {
    policy = ValidationPolicy(
        validation_time=2000,
        max_depth=8,
        search_budget=32,
        clock_available=True
    );
    ta = TrustAnchor(subject="Root CA", label="corp-root");
    root_cert = Certificate(
        subject="Root CA",
        issuer="Root CA",
        is_ca=True,
        not_before=1000,
        not_after=3000,
        sig_valid=True
    );
    inter = Certificate(
        subject="Intermediate CA",
        issuer="Root CA",
        is_ca=True,
        not_before=1000,
        not_after=3000,
        sig_valid=True
    );
    leaf = Certificate(
        subject="server.example",
        issuer="Intermediate CA",
        server_auth=True,
        is_ca=False,
        not_before=1000,
        not_after=3000,
        sig_valid=True
    );

    inter +>:Issues:+> leaf;
    leaf +>:IssuedBy:+> inter;
    inter +>:IssuedBy:+> root_cert;
    ta +>:Anchors:+> root_cert;

    root ++> policy ++> ta;
    root ++> inter;
    root ++> leaf;
    root ++> root_cert;

    if not policy.clock_available {
        print("FAIL: wall clock unavailable - fail closed");
    } else {
        print("--- bounded path construction ---");
        inter spawn PathConstructor(
            budget=16,
            target_subject="server.example"
        );

        print("--- RFC 5280 path validation ---");
        leaf spawn CertPathValidator(
            validation_time=policy.validation_time,
            max_depth=policy.max_depth,
            budget=policy.search_budget,
            trust_subjects=["Root CA"]
        );
    }
}
```

A maintainer on the project joshyorko/actions (Python) filed this issue about hand-rolled graph machinery causing pain:

Issue #86: Make capability artifacts and large-result handles replica-safe

## Overview

Replace the assumption that Run artifacts, logs, screenshots, reports, Robot Framework outputs, generated bundles, files, and large results live only on the local Runtime/worker filesystem with an explicit replica-safe storage and metadata contract.

An artifact produced by Worker C through RCC, uv, Python, Robot Framework, or another adapter must be discoverable/authorized through Runtime B without routing to the producer process/node. A stale Attempt cannot finalize authoritative output after fence loss.

Parent: #82. Depends on: #83, #84, #129. Related: #85, #87, #90, #131, #132, #137, #143.

## Use Cases

- Independent Runtime replicas can serve/authorize artifacts produced on other workers/nodes.
- Provisional→final two-phase publication so stale fenced Attempts cannot finalize output.
- Adapter-native output collection (RCC, Robot Framework, uv/Python) with safe publication rules.

## Artifact planes remain separate

Do not conflate:

- Package Revision source artifacts (#136);
- adapter runtime artifacts/providers: RCC Environment Artifacts/provider content (#133); uv/other immutable runtime content where supported;
- Run output artifacts/results owned here;
- data/knowledge result handles (#131).

They may reuse storage/CAS infrastructure but have different identity, auth, retention, publication, and GC semantics. `rcc cache serve` distributes RCC runtime content, not Run screenshots/reports/logs unless a separately typed output provider explicitly implements both contracts.

## Artifact metadata

Durable metadata through #84 includes:

- Workspace; Deployment Revision; Package Revision/capability/schema;
- selected Runtime Plan/`runtime_kind`/plan digest;
- Run/Attempt/owner/epoch;
- Worker Profile/placement and bounded execution receipt reference;
- optional Workflow/Node/Work Item/parent-child lineage;
- artifact ID/content digest; logical name/media type/size/schema/type/purpose;
- storage provider/opaque object reference;
- provisional/final/aborted/expired state; creation/finalization/expiry;
- retention/legal hold/encryption/access policy;
- producer capability/adapter and related result/Task handles;
- redaction/truncation/validation provenance.

Adapter-local paths, RCC/venv/interpreter paths, container IDs, provider URLs, and credentials are **not** portable artifact identity.

## Blob/object provider contract

Support at least:

- local filesystem for collapsed development;
- one shared/object implementation for independent replicas;
- bounded streaming upload/download;
- atomic/two-phase provisional→final publish;
- abort/cleanup of incomplete uploads;
- range reads;
- optional short-lived provider-native signed access under policy;
- checksum/digest verification;
- safe content-addressed reuse;
- metadata/list/head/delete;
- typed health/failure behavior;
- immutable finalized bytes unless separate versioned mutable-resource contract exists.

Database stores metadata/opaque references, not large blobs except explicit local/small-object policy. Do not expose arbitrary host paths, bucket keys, raw provider credentials, or unmanaged signed URLs as durable client contract.

## Publication lifecycle

A producer Attempt:

1. creates provisional metadata tied to Run/Attempt/current epoch and selected Runtime Plan;
2. streams bytes to authorized output provider;
3. enforces per-artifact/Run limits and content policy;
4. verifies size/digest and closes upload;
5. conditionally finalizes under current fence;
6. transactionally attaches final reference to Run/Workflow/Work Item result;
7. leaves failed/stale uploads abortable/GC-able;
8. releases adapter/process resources only after required publication completes.

If owner loses fence before finalization, bytes may remain temporarily but cannot become authoritative output. Cleanup must preserve content referenced by another finalized artifact safely.

## Adapter-native output collection

#143 adapters declare output behavior.

- **RCC**: collect declared `artifactsDir`, Robot/Action outputs, screenshots, reports, stdout/stderr, and structured receipt through supported RCC/runtime execution lifecycle. RCC Environment Artifact content remains a separate runtime-artifact plane.
- **Robot Framework**: collect output XML, log/report HTML, screenshots, listener outputs, and declared files safely.
- **uv/Python**: collect declared output roots/files and structured results without scanning arbitrary host filesystem.

Common rules: package declares allowed output roots/patterns/limits; adapter/worker does not publish arbitrary host files; symlink/path escape/special files rejected; secrets redacted where known before durable publication; binary/sensitive output treated under explicit policy; adapter unavailable/failure never synthesizes artifact/result success.

## Logs/events/results

Define relationship among: best-effort live events/log streaming; durable ordered log chunks/streams; final log artifacts; compact Task/protocol progress; structured inline result versus large-result handle. Durable state/result never depends on the original WebSocket/SSE/MCP request/worker process.

Logs define ordering/cursors, truncation/rate limits, binary handling, multiline/log-injection protection, redaction, retention, and stale-owner publication rejection.

## Identity and naming

- Artifact IDs globally unambiguous or explicitly Workspace-scoped.
- Logical names are presentation metadata, never storage paths.
- Content digest identifies bytes, not authorization.
- Same bytes may back multiple artifact metadata records with separate lineage/policy.
- User uploads, Package build outputs, Runtime Adapter content, Run outputs, logs, screenshots, datasets, and reports are typed distinctly.

## Current implementation / Pain

No shared replica-safe artifact storage exists; outputs are assumed local to the producing Runtime/worker filesystem.

Related residual from #86 (safe shared-static-serving admission): review verdict **NOT READY / no candidate** at exact base `4be069f3940bf2127a37f76925e102c4664ce1e4`. Four independent Luna/max reviews converged: Starlette 0.50.0 `FileResponse` reopens pathnames and exposes no opened-handle seam; prevalidate-then-serve, validated `Path`, ordinary `open()`, and plain `StreamingResponse` were rejected — they either retain the symlink-swap TOCTOU or fail native HTTP semantics. A safe solution requires handle-bound authorization/open/stat/stream/close, POSIX/Windows no-reparse and lock parity, descriptor cleanup/resource limits, plus GET/HEAD/ETag/Last-Modified/single/suffix/multi/invalid Range behavior — a platform architecture expansion beyond the bounded residual lane. No source/docs/commit/push/PR mutation occurred; PR #116 remains the accept record.

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Replica-safe artifact publication: provisional→final lifecycle with fence checks.

Models the core entities from issue #86 — Run, Attempt, Artifact, Worker — and
demonstrates the two-phase publication lifecycle: a producer Attempt streams
provisional metadata + bytes under the current fence, verifies digest, and only
then transactionally attaches the final reference to the Run. A stale Attempt
whose fence has been lost cannot finalize; orphaned provisional blobs remain
GC-able without poisoning authoritative output.
"""

node Run {
    has run_id: str = "";
    has owner_epoch: int = 0;
}

node Attempt {
    has attempt_id: str = "";
    has fence_epoch: int = 0;
    has is_stale: bool = False;
    has uploaded_bytes: int = 0;
    has declared_digest: str = "";
    has verified_digest: str = "";
    has state: str = "provisional";
}

node Artifact {
    has artifact_id: str = "";
    has logical_name: str = "";
    has content_digest: str = "";
    has size: int = 0;
    has publication_state: str = "provisional";
}

node Worker {
    has worker_id: str = "";
    has reachable: bool = True;
}

edge ProducedAttempt {
    has plan_digest: str = "";
}

edge FinalizedBy {
    has finalized_at_epoch: int = 0;
}

edge ServedBy {
    has provider_kind: str = "local";
}

edge Orphaned {
    has reason: str = "";
}

walker Auditor {
    has report_lines: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can inspect_run with Run entry {
        self.report_lines.append(f"Run {here.run_id} (owner_epoch={here.owner_epoch})");
        visit [-->];
    }

    can inspect_attempt with Attempt entry {
        verdict = "FINALIZED";
        if here.is_stale {
            verdict = "STALE_NO_FINALIZE";
        } elif here.state == "provisional" {
            verdict = "PROVISIONAL_PENDING";
        } elif here.verified_digest != here.declared_digest {
            verdict = "DIGEST_MISMATCH";
        }
        self.report_lines.append(
            f"  Attempt {here.attempt_id} fence={here.fence_epoch} "
            f"state={here.state} -> {verdict}"
        );
        visit [-->];
    }

    can inspect_artifact with Artifact entry {
        self.report_lines.append(
            f"    Artifact {here.artifact_id} name={here.logical_name} "
            f"digest={here.content_digest} state={here.publication_state}"
        );
        visit [-->];
    }

    can inspect_worker with Worker entry {
        self.report_lines.append(f"      Worker {here.worker_id} reachable={here.reachable}");
        visit [-->];
    }
}

walker FenceEnforcer {
    has current_epoch: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can enforce with Run entry {
        self.current_epoch = here.owner_epoch;
        visit [-->];
    }

    can invalidate_stale with Attempt entry {
        visit [-->];
        if here.fence_epoch != self.current_epoch {
            here.is_stale = True;
            here.state = "aborted";
        }
    }
}

walker Publisher {
    can start with Root entry {
        visit [-->];
    }

    can pass_run with Run entry {
        visit [-->];
    }

    can publish_attempt with Attempt entry {
        visit [-->];
        if here.is_stale {
            here.state = "aborted";
        } elif here.verified_digest != here.declared_digest {
            here.state = "rejected";
        } else {
            here.state = "finalized";
        }
    }
}

walker CascadeGC {
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can pass_run with Run entry {
        visit [-->];
    }

    can sweep with Attempt entry {
        visit [-->];
        if here.state == "aborted" or here.state == "provisional" {
            self.visited.append(here.attempt_id);
        }
    }

    can reap_orphans with Artifact entry {
        visit [-->];
        if here.publication_state == "provisional" {
            self.visited.append(f"orphan:{here.artifact_id}");
        }
    }
}

walker ReachabilityProbe {
    has reachable_workers: list[str] = [];

    can probe with Root entry {
        visit [-->];
    }

    can pass_run with Run entry {
        visit [-->];
    }

    can pass_attempt with Attempt entry {
        visit [-->];
    }

    can pass_artifact with Artifact entry {
        visit [-->];
    }

    can check_worker with Worker entry {
        visit [-->];
        if here.reachable {
            self.reachable_workers.append(here.worker_id);
        }
    }
}

with entry {
    # --- Build the demo graph -------------------------------------------------
    run = Run(run_id="R-1001", owner_epoch=7);

    # Live attempt under current fence — can finalize.
    live_attempt = Attempt(
        attempt_id="A-1",
        fence_epoch=7,
        uploaded_bytes=4096,
        declared_digest="sha256:abc",
        verified_digest="sha256:abc"
    );

    # Stale attempt — fence lost; bytes streamed but never finalize.
    stale_attempt = Attempt(
        attempt_id="A-2",
        fence_epoch=5,
        uploaded_bytes=2048,
        declared_digest="sha256:def",
        verified_digest="sha256:def",
        state="provisional"
    );

    # Digest-mismatch attempt — adapter corrupted mid-stream.
    bad_attempt = Attempt(
        attempt_id="A-3",
        fence_epoch=7,
        uploaded_bytes=1024,
        declared_digest="sha256:000",
        verified_digest="sha256:fff",
        state="provisional"
    );

    artifact_final = Artifact(
        artifact_id="art-1",
        logical_name="report.html",
        content_digest="sha256:abc",
        size=4096,
        publication_state="provisional"
    );

    artifact_orphan = Artifact(
        artifact_id="art-2",
        logical_name="partial.zip",
        content_digest="sha256:def",
        size=2048,
        publication_state="provisional"
    );

    local_worker = Worker(worker_id="W-local", reachable=True);
    remote_worker = Worker(worker_id="W-remote", reachable=True);

    root ++> run;
    run +>:ProducedAttempt(plan_digest="plan:v3"):+> live_attempt;
    run +>:ProducedAttempt(plan_digest="plan:v3"):+> stale_attempt;
    run +>:ProducedAttempt(plan_digest="plan:v3"):+> bad_attempt;
    live_attempt +>:FinalizedBy:+> artifact_final;
    stale_attempt +>:Orphaned(reason="fence-lost"):+> artifact_orphan;
    artifact_final +>:ServedBy(provider_kind="local"):+> local_worker;
    artifact_final +>:ServedBy(provider_kind="s3"):+> remote_worker;

    # --- Run 1: audit the graph (read-only) -----------------------------------
    auditor = Auditor();
    root spawn auditor;
    print("=== AUDIT ===");
    for line in auditor.report_lines {
        print(line);
    }

    # --- Run 2: fence enforcement + publication -------------------------------
    enforcer = FenceEnforcer();
    root spawn enforcer;
    pub = Publisher();
    root spawn pub;
    print("\n=== PUBLISHER OUTCOMES ===");
    print(f"live_attempt.state = {live_attempt.state}");
    print(f"stale_attempt.state = {stale_attempt.state}");
    print(f"bad_attempt.state = {bad_attempt.state}");

    # --- Run 3: cascade GC of provisional/orphaned artifacts ------------------
    gc = CascadeGC();
    root spawn gc;
    print("\n=== CASCADE GC ===");
    print(f"visited: {gc.visited}");

    # --- Run 4: replica reachability probe ------------------------------------
    probe = ReachabilityProbe();
    root spawn probe;
    print("\n=== REACHABILITY ===");
    print(f"reachable workers: {probe.reachable_workers}");
}
