```jac
"""Team hierarchy + per-team issue views: demonstrate that naive own-team
queries silently drop sub-team issues, then a roll-up walker that walks the
subtree to make the legibility gap observable.

Models the core complaint from jra3/linear-fuse #433:
``teams/{PARENT}/issues`` is backed by ``WHERE team_id = ?`` and so excludes
sub-team issues, with nothing in the generated README saying so.
"""

# ---------------------------------------------------------------------------
# Archetypes
# ---------------------------------------------------------------------------

node Team {
    has key: str = "";
    has name: str = "";
}

node Issue {
    has title: str = "";
    has status: str = "open";
    has assignee: str = "";
}

# Typed edges: the relationship carries meaning.
edge ParentOf { }     # parent team -> child team (subteam membership)
edge FiledAgainst { } # issue -> team it is filed against

# ---------------------------------------------------------------------------
# README legibility: a walker that *generates* the sentence the issue's
# step (1) asks for, so the "what does teams/{KEY}/issues mean" gap is at
# least documented next to the views themselves.
# ---------------------------------------------------------------------------

walker GenerateReadmeBlurb {
    has team_key: str = "";

    can start with Root entry {
        print(
            f"Team views for '{self.team_key}' are own-team-only: "
            f"teams/{self.team_key}/issues/ shows issues filed directly "
            f"against this team, not against its sub-teams. See "
            f"teams/{self.team_key}/subteams/ for descendants."
        );
        visit [-->] else {
            disengage;
        }
    }
}

# ---------------------------------------------------------------------------
# Own-team view: exactly the silent default the issue complains about.
#
# This walker only visits Issues connected to the *spawn* team by a
# FiledAgainst edge. It never descends through ParentOf, so sub-team issues
# are silently invisible — the legibility gap from #433.
# ---------------------------------------------------------------------------

walker OwnTeamIssues {
    has team_key: str = "";

    can start with Team entry {
        visit [->:FiledAgainst:->];
    }

    can collect with Issue entry {
        print(f"  [own-team {self.team_key}] {here.title} ({here.status})");
        visit [-->];
    }
}

# ---------------------------------------------------------------------------
# Roll-up view: subtree walker that traverses ParentOf edges and gathers
# every Issue filed against any team in the descendant set. Demonstrates
# the "roll-up surface" the issue's option (2) suggests.
#
# Cycle policy: parent_id chains in a real org are trees, but a malformed
# graph could loop. We carry an explicit visited set on the walker to bound
# the walk — cycle handling is domain logic and must survive the lift.
# ---------------------------------------------------------------------------

walker SubtreeRollup {
    has team_key: str = "";
    has visited: str = "";

    can start with Team entry {
        # Skip if already seen.
        already_seen = f"|{here.key}|" in f"|{self.visited}|";
        if already_seen {
            disengage;
        }
        self.visited = self.visited + "|" + here.key;
        print(f"  [roll-up {self.team_key}] team {here.key} ({here.name})");
        # Collect this team's own issues, then keep descending to sub-teams.
        visit [->:FiledAgainst:->];
        visit [->:ParentOf:->];
    }

    can collect with Issue entry {
        print(f"    issue: {here.title} ({here.status})");
        visit [-->];
    }
}

# ---------------------------------------------------------------------------
# Demo wiring
# ---------------------------------------------------------------------------

with entry {
    # Build the team tree:
    #   PLAT
    #     PLAT-API
    #     PLAT-WEB
    #       PLAT-WEB-INFRA
    plat     = Team(key="PLAT",        name="Platform");
    api      = Team(key="PLAT-API",    name="Platform API");
    web      = Team(key="PLAT-WEB",    name="Platform Web");
    webinfra = Team(key="PLAT-WEB-INFRA", name="Platform Web Infra");

    plat +>:ParentOf:+> api;
    plat +>:ParentOf:+> web;
    web  +>:ParentOf:+> webinfra;

    # Issues filed against various teams. Note the silent gap: PLAT only
    # owns two of these directly; the rest live under sub-teams.
    i_plat_a   = Issue(title="reorg RFC",              status="open",    assignee="alice");
    i_plat_b   = Issue(title="on-call rotation v3",    status="review",  assignee="bob");
    i_api_a    = Issue(title="rate-limit 429 spikes",  status="open",    assignee="carol");
    i_web_a    = Issue(title="SSO cookie domain",      status="done",    assignee="dan");
    i_webinfra = Issue(title="CDN cache key v2",       status="open",    assignee="erin");

    plat     +>:FiledAgainst:+> i_plat_a;
    plat     +>:FiledAgainst:+> i_plat_b;
    api      +>:FiledAgainst:+> i_api_a;
    web      +>:FiledAgainst:+> i_web_a;
    webinfra +>:FiledAgainst:+> i_webinfra;

    print("=== README legibility (issue #433 step 1) ===");
    root spawn GenerateReadmeBlurb(team_key="PLAT");

    print("\n=== Own-team issues for PLAT (the silent default) ===");
    plat spawn OwnTeamIssues(team_key="PLAT");

    print("\n=== Subtree roll-up for PLAT (issue #433 step 2 candidate) ===");
    plat spawn SubtreeRollup(team_key="PLAT");
}
