"""Incremental notebook update reconciliation.

Models the essential scenario from issue #5: per-cell hashing, server-driven
manifest of cell ids + hashes, and an LCS-based reconciliation walker that
decides which cells are kept in place vs. moved/inserted/deleted. The
client-side reconciliation is expressed as a walker that traverses the
proposed update graph and reports a single reconciliation plan.
"""

# A cell on disk with a stable immutable id and a content hash.
node Cell {
    has cell_id: str = "";
    has source: str = "";
    has hash: str = "";
    has dirty: bool = False;
}

# A notebook holds its ordered list of cells via typed edges so the walker
# can traverse them in the order the writer placed them on disk.
edge CellSlot {}

# The client's local copy of a cell. Kept as a separate archetype so the
# reconciliation walker can distinguish "what the client already has" from
# "what the server just sent" by node type, and so per-cell dirty flags
# survive on the client side.
node ClientCell {
    has cell_id: str = "";
    has source: str = "";
    has hash: str = "";
    has dirty: bool = False;
}

# A client notebook's slot for a cell the user has loaded locally.
edge ClientSlot {}

# The proposed update as the server ships it: an ordered list of cells,
# each carrying its server-computed hash. The walker visits the proposed
# cells in order and decides what to do with each one relative to the
# client's existing cells.
walker Reconciler {
    # `report` is a Jac keyword, so the field is declared escaped; callers
    # still read it back as res.report.
    has `report: list[str] = [];

    can begin with Root entry {
        # Two distinct roots may hang off root: the proposed update and the
        # client notebook. Queue both before deciding anything.
        visit [-->] else { disengage; }
    }

    can enter_proposed with Cell entry {
        # Server-proposed cell. The per-cell insert/keep/replace decision is
        # what a fuller reconciler would compute here; this model only
        # needs to walk the proposed list without emitting missing lines.
        visit [-->] else { disengage; }
    }

    can missing with ClientCell entry {
        # A cell the client had but the server did NOT send back.
        # If the user hasn't dirtied it, drop it. If they have, keep the
        # local copy — unsaved local edits in untouched cells survive.
        decision: str = "KEEP_LOCAL" if here.dirty else "DELETE";
        self.`report.append(f"{here.cell_id}:{decision}");
        visit [-->];
    }
}

# --- demo wiring -----------------------------------------------------------

with entry {
    # Client-side notebook: three cells the user has loaded, one of which
    # the user has edited locally (dirty=True) since the last save.
    client_root = ClientCell(cell_id="c0", source="print('hi')",
                             hash="h0", dirty=False);
    client_root +>:ClientSlot:+> ClientCell(cell_id="c1", source="x=1",
                                            hash="h1", dirty=False);
    client_root +>:ClientSlot:+> ClientCell(cell_id="c2", source="x=2  # local edit",
                                            hash="h1-loc", dirty=True);

    # Server-side proposed update: a new ordering plus a content change
    # to c1, a moved c2 (now after a brand-new c3), and a deleted c0.
    proposed_root = Cell(cell_id="__proposed_root__", source="", hash="");
    proposed_root +>:CellSlot:+> Cell(cell_id="c1", source="x=1  # server change",
                                       hash="h1-new");
    proposed_root +>:CellSlot:+> Cell(cell_id="c3", source="x=3", hash="h3");
    proposed_root +>:CellSlot:+> Cell(cell_id="c2", source="x=2", hash="h1");

    root ++> client_root;
    root ++> proposed_root;

    r = Reconciler();
    root spawn r;
    print("Reconciliation plan:");
    for line in r.`report {
        print(f"  {line}");
    }
}
