```jac
"""Incremental notebook updates: cell-by-cell reconciliation demo.

Models the essential scenario from the issue: a notebook is a sequence of
cells with stable ids, the server and client each compute per-cell hashes,
and a reconciler walker walks the diff between the two cell-id lists to
find the longest common subsequence (LCS). Cells in the LCS stay in place;
the rest are inserted, moved, or deleted. A cycle/visit guard prevents
infinite traversal if cells ever reference one another.
"""

node Cell {
    has cell_id: str = "";
    has source: str = "";
    has hash: str = "";
    has index: int = 0;
    has dirty: bool = False;

    def label() -> str {
        return f"#{self.index} {self.cell_id} ({self.hash})";
    }
}

# The notebook holds an ordered chain of cells via a typed Edge edge.
edge Edge { }

# A reconciler walker carries the server's proposed cell-id list and
# walks the client's current cells along the typed Edge chain. It
# computes an in-place LCS reconcile pass and reports the operations
# that would have been issued against the shared YNotebook.
walker Reconciler {
    has server_ids: list[str] = [];
    has ops: list[str] = [];
    has visited: set[str] = set();

    def is_visited(cid: str) -> bool {
        return cid in self.visited;
    }

    def mark_visited(cid: str) -> None {
        self.visited.add(cid);
    }

    def lcs_len(a: list[str], b: list[str]) -> int {
        n = len(a);
        m = len(b);
        # Build an (n+1) x (m+1) DP table in row-major order.
        dp: list[list[int]] = [];
        i = 0;
        while i <= n {
            row: list[int] = [];
            j = 0;
            while j <= m {
                row.append(0);
                j = j + 1;
            }
            dp.append(row);
            i = i + 1;
        }
        i = 1;
        while i <= n {
            j = 1;
            while j <= m {
                if a[i - 1] == b[j - 1] {
                    dp[i][j] = dp[i - 1][j - 1] + 1;
                } else {
                    left = dp[i - 1][j];
                    up = dp[i][j - 1];
                    dp[i][j] = left if left >= up else up;
                }
                j = j + 1;
            }
            i = i + 1;
        }
        return dp[n][m];
    }

    can start with Root entry {
        print(f"server proposed order: {self.server_ids}");
        visit [-->];
    }

    can sweep with Cell entry {
        cid = here.cell_id;
        if self.is_visited(cid) {
            # Cycle / revisit guard: skip, do not recurse further.
            disengage;
        }
        self.mark_visited(cid);

        server_idx = -1;
        k = 0;
        while k < len(self.server_ids) {
            if self.server_ids[k] == cid {
                server_idx = k;
            }
            k = k + 1;
        }

        if server_idx == -1 {
            op = f"DELETE {here.label()}";
            self.ops.append(op);
        } else {
            self.ops.append(f"KEEP   {here.label()} at server pos {server_idx}");
        }

        visit [-->];
    }

    can summarize with Root entry {
        client_ids: list[str] = [];
        i = 0;
        while i < len(self.server_ids) {
            cid = self.server_ids[i];
            if cid in self.visited {
                client_ids.append(cid);
            }
            i = i + 1;
        }
        lcs_size = self.lcs_len(client_ids, self.server_ids);

        print("operations:");
        i = 0;
        while i < len(self.ops) {
            print(f"  {self.ops[i]}");
            i = i + 1;
        }
        print(
            f"LCS length = {lcs_size}; "
            f"client kept {len(client_ids)}/{len(self.server_ids)} cells in place"
        );
    }
}

with entry {
    # Build a small notebook: 4 cells in the client's current order.
    c1 = Cell(cell_id="cell-A", source="x = 1", hash="h1", index=0);
    c2 = Cell(cell_id="cell-B", source="x = 2", hash="h2", index=1);
    c3 = Cell(cell_id="cell-C", source="x = 3", hash="h3", index=2);
    c4 = Cell(cell_id="cell-D", source="x = 4", hash="h4", index=3);

    # Client chain: A -> B -> C -> D
    c1 +>:Edge:+> c2 +>:Edge:+> c3 +>:Edge:+> c4;

    # Server proposes: B, C, D, E  (A deleted, E inserted, B/C/D kept)
    server_proposal: list[str] = ["cell-B", "cell-C", "cell-D", "cell-E"];

    r = Reconciler(server_ids=server_proposal);
    root spawn r;
}
```

```jac
"""QuickMail winget distribution: model release artifacts, installers, and
manifests as a graph; a walker audits which release versions are ready for
winget submission and which ones still need an installer or manifest update.

The issue complains about hand-rolled plumbing for keeping track of which
release has which installer files, which architectures are covered, and which
manifest triplet (version / defaultLocale / installer) still needs to be
authored. Here that plumbing is replaced by typed edges between Release,
Installer, Manifest, and Block nodes, traversed by walker abilities.
"""

# ---------- Edge archetypes (relationships carry meaning) ----------

edge ProvidesInstaller {
    has architecture: str = "";
    has url: str = "";
    has sha256: str = "";
}

edge TargetsManifest {
    has manifest_kind: str = "";
}

edge BlocksRelease {
    has reason: str = "";
}


# ---------- Node archetypes (entities) ----------

node Release {
    has tag: str = "";
    has version: str = "";
    has is_prerelease: bool = False;
    has arp_product_code: str = "";
}

node Installer {
    has architecture: str = "";
    has url: str = "";
    has sha256: str = "";
    has silent_install_ok: bool = False;
}

node Manifest {
    has package_id: str = "";
    has kind: str = "";
    has authored: bool = False;
    has submitted: bool = False;
}

node Block {
    has reason: str = "";
    has resolved: bool = False;
}


# ---------- Walker: audit a release for winget readiness ----------

walker ReleaseAuditor {
    has release_tag: str = "";
    has installer_count: int = 0;
    has manifest_count: int = 0;
    has blocking_count: int = 0;
    has ready: bool = True;

    can begin with Root entry {
        visit [-->];
    }

    can collect with Release entry {
        if self.release_tag == "" or here.tag == self.release_tag {
            print(f"Auditing release {here.tag} (version {here.version})");
            for inst in [here ->:ProvidesInstaller:->] {
                self.installer_count += 1;
                arch_ok = inst.architecture == "x64" or inst.architecture == "arm64";
                if arch_ok and inst.silent_install_ok {
                    print(f"  installer {inst.architecture} OK ({inst.url})");
                } else {
                    self.ready = False;
                    print(f"  installer {inst.architecture} not ready "
                          f"(silent_ok={inst.silent_install_ok})");
                }
            }
            for mf in [here ->:TargetsManifest:->] {
                self.manifest_count += 1;
                if mf.authored and mf.submitted {
                    print(f"  manifest {mf.kind} submitted");
                } else {
                    self.ready = False;
                    print(f"  manifest {mf.kind} pending "
                          f"(authored={mf.authored}, submitted={mf.submitted})");
                }
            }
            for blk in [here ->:BlocksRelease:->] {
                self.blocking_count += 1;
                if blk.resolved {
                    print(f"  resolved blocker: {blk.reason}");
                } else {
                    self.ready = False;
                    print(f"  BLOCKED: {blk.reason}");
                }
            }
            verdict = "READY for winget" if self.ready else "NOT READY";
            print(f"[{verdict}] tag={here.tag} "
                  f"installers={self.installer_count} "
                  f"manifests={self.manifest_count} "
                  f"blocks={self.blocking_count}");
        }
        visit [-->];
    }

    can pass_installer with Installer entry {
        visit [-->];
    }

    can pass_manifest with Manifest entry {
        visit [-->];
    }

    can pass_block with Block entry {
        visit [-->];
    }
}


# ---------- Walker: cascade-invalidate stale manifest entries ----------

# When a new release promotes, older manifests pointing at superseded
# installers must be invalidated. The sweep is computed up front from the
# release children of root so the summary is independent of traversal order;
# the traversal itself keeps walking the graph and flags any additional
# unsubmitted manifests hanging off deeper releases.

walker StaleManifestSweeper {
    has newest_version: str = "";
    has stale_count: int = 0;

    can begin with Root entry {
        for rel in [here -->] {
            if rel.version > self.newest_version {
                self.newest_version = rel.version;
            }
            for mf in [rel ->:TargetsManifest:->] {
                if not mf.submitted {
                    self.stale_count += 1;
                    mf.authored = False;
                    print(f"invalidating stale manifest {mf.kind} "
                          f"for {mf.package_id}");
                }
            }
        }
        print(f"sweeper invalidated {self.stale_count} stale manifest(s); "
              f"newest version on graph = {self.newest_version}");
        visit [-->];
    }

    can scan_release with Release entry {
        for mf in [here ->:TargetsManifest:->] {
            if not mf.submitted and mf.authored {
                self.stale_count += 1;
                mf.authored = False;
                print(f"invalidating stale manifest {mf.kind} "
                      f"for {mf.package_id}");
            }
        }
        visit [-->];
    }

    can sweep_manifest with Manifest entry {
        visit [-->];
    }
}


with entry {
    # ---- Build the demo graph ----
    v1 = Release(tag="v1.0.0", version="1.0.0", is_prerelease=False,
                 arp_product_code="{11111111-1111-1111-1111-111111111111}");
    v2 = Release(tag="v1.1.0", version="1.1.0", is_prerelease=False,
                 arp_product_code="{22222222-2222-2222-2222-222222222222}");

    inst_x64 = Installer(architecture="x64",
                         url="https://github.com/kellylford/QuickMail/releases/"
                             "download/v1.1.0/QuickMail-1.1.0-win.msi",
                         sha256="aaa...x64",
                         silent_install_ok=True);
    inst_arm = Installer(architecture="arm64",
                         url="https://github.com/kellylford/QuickMail/releases/"
                             "download/v1.1.0/QuickMail-1.1.0-win-arm64.msi",
                         sha256="bbb...arm",
                         silent_install_ok=True);

    mf_version = Manifest(package_id="KellyLford.QuickMail",
                          kind="version", authored=True, submitted=True);
    mf_locale = Manifest(package_id="KellyLford.QuickMail",
                         kind="defaultLocale", authored=True, submitted=True);
    mf_installer = Manifest(package_id="KellyLford.QuickMail",
                            kind="installer", authored=True, submitted=True);
    mf_stale = Manifest(package_id="KellyLford.QuickMail",
                        kind="installer", authored=True, submitted=False);

    block_velopack = Block(reason="ARP entry ownership unclear", resolved=False);

    # ---- Wire with typed edges (the relationship carries meaning) ----
    v2 +>:ProvidesInstaller(architecture="x64",
                            url=inst_x64.url,
                            sha256=inst_x64.sha256):+> inst_x64;
    v2 +>:ProvidesInstaller(architecture="arm64",
                            url=inst_arm.url,
                            sha256=inst_arm.sha256):+> inst_arm;
    v2 +>:TargetsManifest(manifest_kind="version"):+> mf_version;
    v2 +>:TargetsManifest(manifest_kind="defaultLocale"):+> mf_locale;
    v2 +>:TargetsManifest(manifest_kind="installer"):+> mf_installer;
    v2 +>:BlocksRelease(reason="ARP ownership"):+> block_velopack;

    v1 +>:TargetsManifest(manifest_kind="installer"):+> mf_stale;

    root ++> v1;
    root ++> v2;

    # ---- Run the audit walker ----
    print("--- ReleaseAuditor on v1.1.0 ---");
    root spawn ReleaseAuditor(release_tag="v1.1.0");

    # ---- Run the stale-manifest sweeper across the whole graph ----
    print("--- StaleManifestSweeper across graph ---");
    root spawn StaleManifestSweeper();
}
