```jac
"""Batch issue queue: defer an issue whose dependency is queued later in the
same batch instead of marking it dep_failed.

Models the Sharkrite bug where ``rite N2 N1`` skips N2 as dep_failed even
though N1 will complete later in the same batch. The parent-PR path solved
this with a PARENT_IN_QUEUE membership check; the dep-guard path must do the
same. A walker walks the queue in order and applies the dep-guard with the
queue-membership fix.
"""

# ---------------------------------------------------------------------------
# Node archetypes
# ---------------------------------------------------------------------------

node Issue {
    has number: int = 0;
    has title: str = "";
    has state: str = "open";
}

# A concrete placeholder for issues that close cleanly.
node ClosedIssue(Issue) {
    has state: str = "closed";
}

# An issue that is already dep_failed-skipped (terminal). Reusing Issue for
# state tracking keeps the model flat; the guard just sets state to
# "dep_failed".
node FailedIssue(Issue) {
    has state: str = "dep_failed";
}

# ---------------------------------------------------------------------------
# Edge archetypes
# ---------------------------------------------------------------------------

# Queue order: the typed edge that threads issues through the batch queue.
# Walking [->:QueuedAfter:->] from root follows the batch submission order.
edge QueuedAfter { }

# Dependency relationship between two issues.
edge DependsOn { }

# ---------------------------------------------------------------------------
# Walker: the batch driver
# ---------------------------------------------------------------------------

walker BatchDriver {
    # The list of issue numbers as they were submitted to ``rite``.
    # Used by the dep-guard to answer "is this dep queued later in the
    # same batch?" (the PARENT_IN_QUEUE pattern, ported).
    has queue_order: list[int] = [];
    # Per-issue disposition produced by the run.
    has log: list[str] = [];
    # Cycle / infinite-defer guard: an issue that has already been
    # deferred once must not be deferred again. Mirrors the existing
    # one-pass defer budget on the shell side.
    has deferred: list[int] = [];

    can start with Root entry {
        visit [->:QueuedAfter:->];
    }

    can drive with Issue entry {
        num = here.number;
        # Issues that have already been closed by an earlier step in this
        # batch are fine to "process" again as a no-op.
        if here.state == "closed" {
            self.log.append(f"#{num} already closed -> run");
            visit [-->];
            return;
        }

        # If this issue was already dep_failed-marked by a previous
        # budget exhaustion, skip processing.
        if here.state == "dep_failed" {
            visit [-->];
            return;
        }

        # Look at every DependsOn edge out of here.
        deps = [here->:DependsOn:->];
        for d in deps {
            dep_num = d.number;
            # 1. Dep already closed -> run immediately (pinned behavior).
            if d.state == "closed" {
                self.log.append(
                    f"#{num} depends on closed #{dep_num} -> run"
                );
                visit [-->];
                return;
            }
            # 2. Dep is OPEN. Check whether it is queued later in this
            #    same batch (PARENT_IN_QUEUE-style membership check).
            # Scan the queue: anything BEFORE num in the queue has already
            # been processed (so its dep relation has already been honored);
            # anything AT OR AFTER num is "still in flight" in this batch.
            # We want to know: does dep_num appear at or after num?
            later_in_batch = False;
            seen_self = False;
            for q in self.queue_order {
                if not seen_self {
                    if q == num {
                        seen_self = True;
                    }
                    continue;
                }
                if q == dep_num {
                    later_in_batch = True;
                    break;
                }
            }
            if later_in_batch {
                # Defer budget check: only one deferral per run.
                already_deferred = False;
                for x in self.deferred {
                    if x == num {
                        already_deferred = True;
                        break;
                    }
                }
                if already_deferred {
                    # Cannot defer twice: dep_failed (matches the
                    # one-pass budget of the shell driver).
                    here.state = "dep_failed";
                    self.log.append(
                        f"#{num} depends on open #{dep_num} queued later "
                        f"but already deferred once -> dep_failed"
                    );
                } else {
                    self.deferred.append(num);
                    self.log.append(
                        f"#{num} depends on open #{dep_num} queued later "
                        f"-> defer to after #{dep_num}"
                    );
                    # Issue stays open; the dependency will be honored
                    # when the driver walks back through the successor
                    # link on the deferred node (visit [-->] below).
                }
            } else {
                # 3. Dep is OPEN and NOT in the queue -> dep_failed.
                here.state = "dep_failed";
                self.log.append(
                    f"#{num} depends on open #{dep_num} not in queue "
                    f"-> dep_failed"
                );
            }
            visit [-->];
            return;
        }

        # No deps at all.
        self.log.append(f"#{num} has no deps -> run");
        visit [-->];
    }
}

# ---------------------------------------------------------------------------
# Demo wiring
# ---------------------------------------------------------------------------

with entry {
    # Fixture A: batch `N2 N1` where N2 depends on N1, both open.
    # Expect: N2 deferred, then N1 runs, then deferred-N2 runs.
    n1 = Issue(number=1, title="first");
    n2 = Issue(number=2, title="second, depends on N1");
    n2 +>:DependsOn:+> n1;

    # Fixture B: N2 depends on OPEN N1 that is NOT in the queue.
    # Expect: N2 dep_failed (pinned behavior).
    n3 = Issue(number=3, title="third, dep not in queue");
    orphan = Issue(number=99, title="orphan dep, open");
    n3 +>:DependsOn:+> orphan;

    # Fixture C: dep already CLOSED -> run immediately (pinned behavior).
    n4 = Issue(number=4, title="fourth, closed dep");
    closed_dep = ClosedIssue(number=50, title="already closed dep");
    n4 +>:DependsOn:+> closed_dep;

    # Build the queue in submission order. N1's dep cycle uses n2 then n1
    # which is exactly the bug-trigger sequence.
    root +>:QueuedAfter:+> n2;
    n2 +>:QueuedAfter:+> n1;
    root +>:QueuedAfter:+> n3;
    root +>:QueuedAfter:+> n4;

    driver = BatchDriver(queue_order=[2, 1, 3, 4]);
    root spawn driver;

    print("=== run log ===");
    for line in driver.log {
        print(line);
    }
    print("=== dispositions ===");
    print(f"#1 state = {n1.state}");
    print(f"#2 state = {n2.state}");
    print(f"#3 state = {n3.state}");
    print(f"#4 state = {n4.state}");
}
