```jac
"""Structured multi-agent planning and delegation demo.

Models the core AutoAgents proposal: a planner produces an AgentPlan
containing typed Agent and Task nodes connected by typed edges that
express assignment and dependencies. A PlanValidator walker traverses
the plan, detects cycles in the dependency graph, computes a
dependency-safe ordering, and reports validation results."""

node Agent {
    has name: str = "";
    has role: str = "";
    has goal: str = "";
}

node Task {
    has title: str = "";
    has expected_output: str = "";
    has assigned_to: str = "";
    has available: bool = True;
}

node AgentPlan {
    has title: str = "";
    has available: bool = True;
}

edge Assigns {
    has rationale: str = "";
}

edge DependsOn {
    has kind: str = "hard";
}

edge BelongsTo { }

walker PlanValidator {
    has visited_ids: list[str] = [];
    has order: list[str] = [];
    has cycle_found: bool = False;
    has cycle_path: list[str] = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can enter_plan with AgentPlan entry {
        visit [-->];
        all_nodes = [here];
        queue = [here];
        task_nodes = [];
        task_titles = [];
        while len(queue) > 0 {
            n = queue.pop(0);
            for m in [n -->] {
                if not (m in all_nodes) {
                    all_nodes.append(m);
                    queue.append(m);
                }
            }
            for m in [n ->:Assigns:->] + [n ->:DependsOn:->] {
                if not (m.title in task_titles) {
                    task_titles.append(m.title);
                    task_nodes.append(m);
                }
            }
        }
        visited = [];
        onstack_nodes = [];
        onstack_titles = [];
        dfs_nodes = [];
        dfs_idx = [];
        for t in task_nodes {
            if not (t.title in visited) and not self.cycle_found {
                dfs_nodes.append(t);
                dfs_idx.append(0);
                onstack_nodes.append(t);
                onstack_titles.append(t.title);
                while len(dfs_nodes) > 0 and not self.cycle_found {
                    nd = dfs_nodes[-1];
                    i = dfs_idx[-1];
                    children = [nd ->:DependsOn:->];
                    if i < len(children) {
                        dfs_idx[-1] = i + 1;
                        c = children[i];
                        if c.title in onstack_titles {
                            self.cycle_found = True;
                            si = onstack_titles.index(c.title);
                            self.cycle_path = onstack_titles[si:] + [c.title];
                        } elif not (c.title in visited) {
                            dfs_nodes.append(c);
                            dfs_idx.append(0);
                            onstack_nodes.append(c);
                            onstack_titles.append(c.title);
                        }
                    } else {
                        dfs_nodes.pop();
                        dfs_idx.pop();
                        onstack_nodes.pop();
                        onstack_titles.pop();
                        visited.append(nd.title);
                        self.order.append(nd.title);
                    }
                }
            }
        }
        if self.cycle_found {
            disengage;
        }
    }

    can scan_agent with Agent entry {
        if not (here.name in self.visited_ids) {
            self.visited_ids.append(here.name);
        }
        visit [-->];
    }

    can scan_task with Task entry {
        if not (here.title in self.visited_ids) {
            self.visited_ids.append(here.title);
            visit [-->];
        }
    }
}

with entry {
    plan = AgentPlan(title="Repo Performance Triage");
    planner = Agent(
        name="P-1",
        role="Planner",
        goal="Break a high-level request into tasks for specialists."
    );
    reviewer = Agent(name="R-1", role="Reviewer", goal="Final report sign-off.");
    coder = Agent(name="C-1", role="Coder", goal="Implement fixes.");
    tester = Agent(name="T-1", role="Tester", goal="Run the test suite.");

    analyze = Task(title="AnalyzeRepo", expected_output="perf-issue list");
    fix = Task(title="ImplementFix", expected_output="patch");
    test = Task(title="RunTests", expected_output="test report");
    review = Task(title="FinalReport", expected_output="signed report");

    root ++> plan;
    plan ++> planner;
    plan ++> reviewer;
    plan ++> coder;
    plan ++> tester;

    planner +>:Assigns(rationale="repo analysis"):+> analyze;
    coder +>:Assigns(rationale="apply patches"):+> fix;
    tester +>:Assigns(rationale="validate changes"):+> test;
    reviewer +>:Assigns(rationale="sign off"):+> review;

    fix +>:DependsOn:+> analyze;
    test +>:DependsOn:+> fix;
    review +>:DependsOn:+> test;

    analyze.assigned_to = "C-1";
    fix.assigned_to = "C-1";
    test.assigned_to = "T-1";
    review.assigned_to = "R-1";

    print("--- Plan graph wired ---");
    print(f"Plan '{plan.title}' has 4 tasks across 4 agents.");
    print("Dependency edges: AnalyzeRepo <- ImplementFix <- RunTests <- FinalReport");
    print("");

    validator = PlanValidator();
    root spawn validator;

    print("");
    if validator.cycle_found {
        print(f"VALIDATION FAILED: dependency cycle detected {validator.cycle_path}");
    } else {
        print("VALIDATION OK: no cycles in task dependencies.");
    }
    ready_count = len(validator.order);
    print(f"Tasks registered for parallel-ready ordering: {ready_count}");
    print(f"Execution order (dependency-safe): {validator.order}");
}
