    has review_ok: bool = False;
    has claim_boundary_approved: bool = False;
    has all_pass: bool = False;

    can start with Root entry {
        print(f"Auditing evidence package: {self.package_title}");
        visit [-->];
    }

    can gather_source with SourceArtifact entry {
