        self.review_ok = here.approved;
        visit [-->];
    }

    can gather_claim with ClaimBoundary entry {
        self.claim_boundary_approved = here.approved;
        visit [-->];
    }

    can judge with EvidencePackage entry {
        self.checksum_ok = here.sha256 != "";
        self.pkg_ref = here;
        visit [-->];
    }

    can propagate with DownstreamFigure entry {
        self.all_pass = self.source_authorized
            and self.checksum_ok
            and self.manifest_ok
            and self.portfolio_ok
            and self.role_scope_ok
            and self.claim_boundary_approved;
        if self.pkg_ref is not None {
