"""Studio call-graph validation: self-call surfaces live when selfId is wired; missing selfId is a client no-op."""

node PipelineVersion {
    has pipeline_id: str = "";
    has version_label: str = "";
}

edge Calls { }

walker CallGraphValidator {
    has self_id: str = "";
    has max_depth: int = 5;
    has depth: int = 0;
    has visited_ids: list[str] = [];
    has diagnostics: list[str] = [];

    can start with Root entry {
        if self.self_id == "" {
            print("[client] validateCallGraph: missing selfId — returning []");
            disengage;
        }
        visit [-->] else { disengage; }
    }

    can inspect with PipelineVersion entry {
        pid = here.pipeline_id;
        label = here.version_label;

        if pid == self.self_id {
            self.diagnostics += [f"LIVE@{label}: pipeline calls its own version ({pid})"];
        }

        already_seen = False;
        for vid in self.visited_ids {
            if vid == pid {
                already_seen = True;
            }
        }

        if already_seen {
            self.diagnostics += [f"CYCLE@{label}: re-entered {pid} in call graph"];
            disengage;
        }
        self.visited_ids += [pid];
        next_depth = self.depth + 1;
        if next_depth > self.max_depth {
            self.diagnostics += [
                f"DEPTH@{label}: exceeds MAX_CALL_DEPTH={self.max_depth}"
            ];
            disengage;
        }
        self.depth = next_depth;
        visit [->:Calls:->] else { disengage; }
    }
}

with entry {
    editor = PipelineVersion(pipeline_id="pipe-u20", version_label="U20-Slice2");
    service_a = PipelineVersion(pipeline_id="pipe-a", version_label="ServiceA");
    service_b = PipelineVersion(pipeline_id="pipe-b", version_label="ServiceB");

    root ++> editor;
    editor +>:Calls:+> editor;
    editor +>:Calls:+> service_a;
    service_a +>:Calls:+> service_b;
    service_b +>:Calls:+> service_a;

    print("=== Client canvas (no selfId): validator is a no-op ===");
    client = CallGraphValidator();
    root spawn client;
    print(f"diagnostics: {client.diagnostics}");

    print("\n=== Client canvas (selfId wired): live errors before save ===");
    live = CallGraphValidator(self_id="pipe-u20", max_depth=5);
    root spawn live;
    for issue in live.diagnostics {
        print(f"  {issue}");
    }
}
