```jac
"""Qwen M2 decode roofline: model per-token layer walks, routed expert pressure, and residency caps."""

node DecodeRun {
    has label: str = "";
    has token_count: int = 0;
}

node Token {
    has index: int = 0;
}

node ComputeStage {
    has stage_index: int = 0;
    has name: str = "";
}

node RoutedMoELayer(ComputeStage) {
    has top_k: int = 8;
}

node GDNLayer(ComputeStage) {
    has cost_ms: float = 155.0;
}

node Expert {
    has expert_id: int = 0;
    has resident: bool = False;
    has footprint_bytes: int = 1671168;
}

node ResidentPool {
    has cap_slots: int = 4;
    has top_k: int = 8;
    has assumed_slot_bytes: int = 2147483648;
    has actual_slot_bytes: int = 1671168;
}

edge Routes {
    has gate_weight: float = 1.0;
}

edge Pinned {
    has slot_index: int = 0;
}

walker ResidencyAuditor {
    has verdict: str = "";

    can start with Root entry {
        visit [-->];
    }

    can audit with ResidentPool entry {
        if here.cap_slots < here.top_k {
            self.verdict = (
                f"pathological: cap={here.cap_slots} < topk={here.top_k} "
                f"(heuristic {here.assumed_slot_bytes}B/slot vs "
                f"actual ~{here.actual_slot_bytes}B)"
            );
        } else {
            self.verdict = f"cap={here.cap_slots} OK for topk={here.top_k}";
        }
        visit [->:Pinned:->];
    }

    can note_pin with Expert entry {
        pin_state = "hot" if here.resident else "cold";
        print(f"  pool pin: expert {here.expert_id} ({pin_state})");
        visit [->:Pinned:->];
    }
}

walker UnfusedDecode {
    has routed_requests: int = 0;
    has physical_loads: int = 0;
    has cache_hits: int = 0;
    has host_syncs: int = 0;
    has gdn_ms: float = 0.0;
    has tokens_done: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can begin_run with DecodeRun entry {
        print(f"unfused decode: {here.label} ({here.token_count} tokens)");
        visit [-->];
    }

    can profile_token with Token entry {
        print(f"  token {here.index}: walking routed layers");
        visit [-->];
    }

    can drain_moe with RoutedMoELayer entry {
        self.host_syncs += 1;
        visit [->:Routes:->];
    }

    can tick_gdn with GDNLayer entry {
        self.gdn_ms += here.cost_ms;
        self.tokens_done += 1;
        visit [-->];
    }

    can touch_expert with Expert entry {
        self.routed_requests += 1;
        if here.resident {
            self.cache_hits += 1;
        } else {
            self.physical_loads += 1;
            self.host_syncs += 1;
        }
    }
}

walker FusedDecode {
    has routed_requests: int = 0;
    has physical_loads: int = 0;
    has cache_hits: int = 0;
    has layer_syncs: int = 0;
    has gdn_ms: float = 0.0;
    has tokens_done: int = 0;

    can start with Root entry {
