```jac
"""Reusable CI/CD workflows for the MWNF Website Platform.

Models the core entity types (Workflow, ConsumerRepo, Locale, Package) and
walks the dependency graph that ``viewer-workflows`` publishes — package
consumers, locale translators, and downstream dependents. The ``DownstreamAuditor``
walker replaces the hand-rolled dependents.json recursion the issue calls out.
"""

node Workflow {
    has name: str = "";
    has purpose: str = "";
    has blocking: bool = True;
}

node ConsumerRepo {
    has repo: str = "";
    has kind: str = "";
}

node Locale {
    has lang: str = "";
    has valid_json: bool = True;
    has keys_match: bool = True;
    has placeholders_match: bool = True;
    has html_free: bool = True;
}

node Package {
    has name: str = "";
    has version: str = "v0.0.0";
    has visibility: str = "public";
}

edge Consumes {
    has since: str = "";
}

edge Localizes {
}

edge DependsOn {
}

edge Releases {
    has tag: str = "";
}

walker LocaleValidator {
    can start with Root entry {
        visit [-->];
    }

    can review with Locale entry {
        ok = here.valid_json and here.keys_match and here.placeholders_match and here.html_free;
        status = "OK" if ok else "FAIL";
        print(f"[{status}] locale {here.lang}");
        visit [-->];
    }
}

walker DownstreamAuditor {
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with ConsumerRepo entry {
        if here.repo in self.visited {
            disengage;
        }
        self.visited.append(here.repo);
        print(f"consumer {here.repo} ({here.kind}) — installs via workflow_call");
        visit [->:Consumes:->];
        visit [->:DependsOn:->];
    }

    can audit_pkg with Package entry {
        if here.name in self.visited {
            disengage;
        }
        self.visited.append(here.name);
        print(f"package {here.name} {here.version} ({here.visibility})");
        visit [->:Releases:->];
    }

    can audit_wf with Workflow entry {
        if here.name in self.visited {
            disengage;
        }
        self.visited.append(here.name);
        flag = "blocking" if here.blocking else "advisory";
        print(f"workflow {here.name} — {flag}: {here.purpose}");
        visit [-->];
    }
}

walker WorkflowCatalog {
    can start with Root entry {
        visit [-->];
    }

    can list_wf with Workflow entry {
        flag = "blocking" if here.blocking else "advisory";
        print(f"workflow {here.name} — {flag}: {here.purpose}");
        visit [-->];
    }
}

with entry {
    wf_ci = Workflow(name="website-ci.yml", purpose="build/test/lint/audit for site repos", blocking=True);
    wf_locale = Workflow(name="locale-validate.yml", purpose="locale PR validation + auto-merge", blocking=True);
    wf_dep = Workflow(name="dependabot-automerge.yml", purpose="auto-merge minor/patch bumps", blocking=False);
    wf_pkg = Workflow(name="package-ci.yml", purpose="downstream matrix over dependents.json", blocking=True);

    website = ConsumerRepo(repo="metanull/website-portfolio", kind="website");
    docs = ConsumerRepo(repo="metanull/website-docs", kind="website");
    pkg_core = Package(name="@metanull/viewer-core", version="v1.0.0", visibility="private");
    pkg_layout = Package(name="@metanull/viewer-layout", version="v1.0.0", visibility="private");

    en = Locale(lang="en");
    fr = Locale(lang="fr", keys_match=False);
    de = Locale(lang="de", html_free=False);

    root ++> wf_ci ++> wf_locale ++> wf_dep ++> wf_pkg;
    wf_ci +>:Consumes(since="v1"):+> website;
    wf_ci +>:Consumes(since="v1"):+> docs;
    wf_pkg +>:Consumes(since="v1"):+> pkg_core;
    wf_pkg +>:Consumes(since="v1"):+> pkg_layout;
    wf_locale +>:Localizes:+> en;
    wf_locale +>:Localizes:+> fr;
    wf_locale +>:Localizes:+> de;
    pkg_core +>:Releases(tag="v1"):+> Workflow(name="package-release.yml", purpose="publish to GitHub Packages");
    pkg_layout +>:Releases(tag="v1"):+> Workflow(name="package-release.yml", purpose="publish to GitHub Packages");

    print("=== workflow catalog ===");
    root spawn WorkflowCatalog();

    print("=== locale validation ===");
    root spawn LocaleValidator();

    print("=== downstream consumer audit ===");
    root spawn DownstreamAuditor();
}
