"""Riverhog v1 bounded inventory: restartable segmented audit without --all enumeration."""

node Collection {
    has name: str = "";
    has authority_id: str = "";
    has inventory_sealed: bool = False;
}

node Segment {
    has segment_index: int = 0;
    has continuation_token: str = "";
    has artifact_id: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has indexed: bool = False;
}

edge Partition { }

edge Continues { }

walker CollectionAuditor {
    has batch_quota: int = 2;
    has processed: int = 0;
    has resume_token: str = "";
    has checkpoint: str = "";
    has indexed_count: int = 0;
    has collection_name: str = "";

    can start with Root entry {
        visit [-->];
    }

    can audit with Collection entry {
        self.collection_name = here.name;
        print(f"[AUTHORITY] {here.authority_id} bounded pages (no --all)");
        visit [->:Partition:->] else { disengage; };
    }

    can page with Segment entry {
        if self.resume_token != "" and here.continuation_token < self.resume_token {
            visit [->:Continues:->] else { disengage; };
        }
        if self.processed >= self.batch_quota {
            self.checkpoint = here.continuation_token;
            print(f"[QUOTA] defer checkpoint={self.checkpoint} (not completeness)");
            disengage;
        }
        if not here.indexed {
            here.indexed = True;
            self.processed += 1;
            self.indexed_count += 1;
            status = "IN" if here.available else "OUT";
            print(f"[INDEX] [{status}] {here.artifact_id} {here.title} ({here.year})");
        }
        self.checkpoint = here.continuation_token;
        visit [->:Continues:->] else {
            print(f"[SEALED] {self.collection_name} inventory complete this pass");
            disengage;
        };
    }
}

with entry {
    coll = Collection(
        name="riverhog-archive",
