```jac
"""Unresolved reviewer feedback backlog: model repos, PRs, and review threads as a graph.

A walker sweeps closed PRs across configured repos and collects unresolved
review threads, mirroring the automated weekly sweep that motivated the issue.
Traversal is done natively over typed edges (Root -BelongsTo-> Repo -FiledAgainst->
PR -ThreadOn-> ReviewThread) rather than via hand-rolled adjacency dicts or
recursive parent_id walks.
"""

node Repo {
    has name: str = "";
    has target_count: int = 0;
}

node PullRequest {
    has title: str = "";
    has closed: bool = False;
}

node ReviewThread {
    has severity: str = "";
    has resolved: bool = False;
    has body: str = "";
}

# Typed edges: the relationships carry meaning, so we name them.
edge BelongsTo { }
edge FiledAgainst { }
edge ThreadOn { }

walker BacklogSweeper {
    has label: str = "sweep";
    has lookback_days: int = 90;
    has collected: list = [];

    can start with Root entry {
        print(f"[{self.label}] sweeping closed PRs in last {self.lookback_days} days");
        visit [-->];
    }

    can tally with Repo entry {
        print(f"  repo {here.name}: {here.target_count} unresolved items");
        self.collected.append(here);
        # Repo -> PRs are reached via FiledAgainst edges.
        visit [->:FiledAgainst:->];
    }

    can audit with PullRequest entry {
        # Only closed PRs participate in the unresolved-feedback sweep.
        if here.closed {
            visit [->:ThreadOn:->];
        } else {
            print(f"    skip open PR: {here.title}");
        }
    }

    can grade with ReviewThread entry {
        if not here.resolved {
            self.collected.append(here);
            print(f"    [P?/{here.severity}] {here.body}");
        }
        visit [-->];
    }
}

with entry {
    # Two repos in the configured target list.
    site = Repo(name="nathanjohnpayne/nathanpaynedotcom", target_count=39);
    merger = Repo(name="nathanjohnpayne/mergepath", target_count=25);

    # Closed PRs on the site repo, each carrying unresolved review threads.
    pr_analytics = PullRequest(title="fix(analytics): create person profiles", closed=True);
    pr_blog = PullRequest(title="feat(blog): key takeaways box and CTA", closed=True);
    pr_open = PullRequest(title="wip: draft next post", closed=False);

    # Threads attached to the closed PRs.
    t_critical = ReviewThread(severity="P0", resolved=False,
        body="make the negative assertion ignore comments");
    t_yaml = ReviewThread(severity="P1", resolved=False,
        body="honor escaped YAML line breaks");
    t_emdash = ReviewThread(severity="P1", resolved=True,
        body="close up spaced em dashes in published prose");
    t_navigation = ReviewThread(severity="P1", resolved=False,
        body="let navigation tracks shrink below zero");
    t_schema = ReviewThread(severity="P2", resolved=False,
        body="document the new blog schema fields");

    # Closed PRs on the mergepath repo.
    pr_merge = PullRequest(title="refactor(merge): simplify path planner", closed=True);
    t_merge_a = ReviewThread(severity="P1", resolved=False,
        body="handle empty input sets without throwing");
    t_merge_b = ReviewThread(severity="P2", resolved=False,
        body="rename internal helper for clarity");

    # Wire the graph with typed edges.
    root +>:BelongsTo:+> site;
    root +>:BelongsTo:+> merger;

    site +>:FiledAgainst:+> pr_analytics;
    site +>:FiledAgainst:+> pr_blog;
    site +>:FiledAgainst:+> pr_open;

    pr_analytics +>:ThreadOn:+> t_critical;
    pr_blog +>:ThreadOn:+> t_yaml;
    pr_blog +>:ThreadOn:+> t_emdash;
    pr_blog +>:ThreadOn:+> t_navigation;
    pr_blog +>:ThreadOn:+> t_schema;

    merger +>:FiledAgainst:+> pr_merge;
    pr_merge +>:ThreadOn:+> t_merge_a;
    pr_merge +>:ThreadOn:+> t_merge_b;

    # Spawn the sweeper on root and walk the backlog.
    sweeper = BacklogSweeper(label="weekly-sweep", lookback_days=90);
    root spawn sweeper;

    unresolved = [n for n in sweeper.collected if isinstance(n, ReviewThread)];
    print(f"\nunresolved feedback collected: {len(unresolved)} threads");
}
