```jac
"""NewsSnap AI: feed pipeline with Redis-like cache, invalidation, and rate limiting.

Models the production pipeline as a typed-edge graph:
  Root -> Article -> (Summary, Translation, Snap)
A Cache node sits in front of feed/search endpoints; a RateLimiter guards users.
The CacheInvalidator walker demonstrates cascade invalidation (the hand-rolled
graph machinery the issue complains about) by walking the typed Topic edges
and flushing every dependent category cache entry in one pass.
"""

node Article {
    has title: str = "";
    has body: str = "";
    has lang: str = "en";
}

node Summary {
    has text: str = "";
    has word_count: int = 0;
}

node Translation {
    has text: str = "";
    has target_lang: str = "";
}

node Snap {
    has headline: str = "";
    has char_limit: int = 0;
}

node Topic {
    has name: str = "";
}

node CacheEntry {
    has key: str = "";
    has value: str = "";
    has hits: int = 0;
    has valid: bool = True;
}

node RateLimiter {
    has user_id: str = "";
    has limit_per_min: int = 100;
    has used: int = 0;
    has blocked: bool = False;
}

node RateLimitRoot {
    has label: str = "ratelimit-root";
}

edge Summarized {
    has model: str = "stub";
}

edge Translated {
    has engine: str = "stub";
}

edge Snapped {
    has style: str = "headline";
}

edge Tagged {
    has weight: float = 1.0;
}

edge Cached {
    has backend: str = "redis";
}

edge Owned {
    has tier: str = "free";
}

walker PipelineRunner {
    can start with Root entry {
        visit [-->];
    }

    can run with Article entry {
        print(f"[pipeline] article='{here.title}' lang={here.lang}");
        visit [-->];
    }

    can show_summary with Summary entry {
        print(f"  summary: {here.word_count} words");
    }

    can show_translation with Translation entry {
        print(f"  translation: -> {here.target_lang}");
    }

    can show_snap with Snap entry {
        print(f"  snap: '{here.headline}' (limit {here.char_limit})");
    }
}

walker CacheInvalidator {
    has invalidated: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can flush with CacheEntry entry {
        if here.valid {
            here.valid = False;
            self.invalidated += 1;
            print(f"[invalidate] cache key '{here.key}' flushed");
        }
        visit [-->];
    }

    can sweep with Topic entry {
        print(f"[invalidate] sweeping topic '{here.name}'");
        visit [-->];
    }
}

walker FeedReader {
    has requested_key: str = "";
    has served_from_cache: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can read with CacheEntry entry {
        if here.key == self.requested_key {
            here.hits += 1;
            if here.valid {
                self.served_from_cache = True;
                print(f"[feed] HIT '{here.key}' value='{here.value}' hits={here.hits}");
            } else {
                print(f"[feed] MISS (stale) '{here.key}'");
            }
        }
        visit [-->];
    }
}

walker RateGate {
    can start with Root entry {
        visit [-->];
    }

    can enter with RateLimitRoot entry {
        visit [-->];
    }

    can charge with RateLimiter entry {
        if here.used >= here.limit_per_min {
            here.blocked = True;
            print(f"[ratelimit] BLOCKED user={here.user_id} used={here.used}/{here.limit_per_min}");
        } else {
            here.used += 1;
            print(f"[ratelimit] ok user={here.user_id} used={here.used}/{here.limit_per_min}");
        }
    }
}

with entry {
    art = Article(title="Markets rally on Fed pause", body="...", lang="en");
    summ = Summary(text="short", word_count=42);
    tr = Translation(text="courte", target_lang="fr");
    sn = Snap(headline="Fed pause lifts markets", char_limit=80);
    root ++> art;
    art +>:Summarized(model="t5-small"):+> summ;
    art +>:Translated(engine="deepl"):+> tr;
    art +>:Snapped(style="headline"):+> sn;

    markets = Topic(name="markets");
    fed = Topic(name="fed");
    art +>:Tagged(weight=0.9):+> markets;
    art +>:Tagged(weight=0.7):+> fed;

    feed_cache = CacheEntry(key="feed:markets", value="...json...", hits=0);
    search_cache = CacheEntry(key="search:fed", value="...json...", hits=0);
    trending_cache = CacheEntry(key="trending", value="...json...", hits=0);
    categories_cache = CacheEntry(key="categories", value="...json...", hits=0);
    root ++> feed_cache ++> search_cache ++> trending_cache ++> categories_cache;

    rl_marker = RateLimitRoot();
    rl = RateLimiter(user_id="u-42", limit_per_min=100, used=0);
    root ++> rl_marker ++> rl;

    print("=== pipeline ===");
    root spawn PipelineRunner();

    print("=== feed read (cache HIT path) ===");
    root spawn FeedReader(requested_key="feed:markets");

    print("=== cascade invalidation across topics ===");
    root spawn CacheInvalidator();

    print("=== rate limiting ===");
    root spawn RateGate();
}
