```jac
"""Frontier retry guard demo: permanent Redis outage stalls silently; terminal MISCONF fails the run."""

node CrawlerRun {
    has run_id: str = "";
    has status: str = "running";
    has progress: int = 0;
    has error_msg: str = "";
}

node RedisFrontier {
    has name: str = "";
}

node RedisBackend {
    has host: str = "";
    has error_kind: str = "healthy";
    has error_detail: str = "";
}

edge Uses { }
edge ConnectsTo { }

walker Orchestrator {
    has active_run: CrawlerRun | None = None;
    has max_retries_shown: int = 3;

    can start with Root entry {
        visit [-->];
    }

    can drive with CrawlerRun entry {
        print(f"\n=== Run {here.run_id} (status={here.status}) ===");
        self.active_run = here;
        visit [->:Uses:->];
    }

    can at_frontier with RedisFrontier entry {
        print(f"  frontier '{here.name}' - queue empty, zero progress");
        visit [->:ConnectsTo:->];
    }

    can redis_op with RedisBackend entry {
        run = self.active_run;
        kind = here.error_kind;
        detail = here.error_detail;

        if run is None {
            disengage;
        } else {
            if kind == "healthy" {
                run.progress += 1;
                print(f"  Next OK - progress={run.progress}");
            } else {
                if kind == "terminal" {
                    run.status = "failed";
                    run.error_msg = detail;
                    print(f"  TERMINAL: {detail}");
                    print("  orchestrator marks run FAILED");
                } else {
                    blip_label = "transient blip" if kind == "transient" else "permanent outage";
                    attempt = 0;
                    while attempt < self.max_retries_shown {
                        attempt += 1;
                        print(f"  retry {attempt} [{blip_label}]: {detail}");
                        print(f"    run still '{run.status}', progress={run.progress}, no error recorded");
                    }
                    print("  [demo] ADR-0024 guard would loop forever - silent stall");
                }
            }
            visit [-->] else { disengage; };
        }
    }
}

with entry {
    run_stall = CrawlerRun(run_id="discovery-47m");
    frontier_stall = RedisFrontier(name="redis-frontier");
    redis_dead = RedisBackend(
        host="redis:6379",
        error_kind="permanent",
        error_detail="dial tcp: lookup redis on 127.0.0.11:53: no such host"
    );
    run_fail = CrawlerRun(run_id="batch-12");
    frontier_fail = RedisFrontier(name="redis-frontier");
    redis_misconf = RedisBackend(
        host="redis:6379",
        error_kind="terminal",
        error_detail="MISCONF Redis is configured to save RDB snapshots, but write against db failed"
    );

    root ++> run_stall +>:Uses:+> frontier_stall +>:ConnectsTo:+> redis_dead
        ++> run_fail +>:Uses:+> frontier_fail +>:ConnectsTo:+> redis_misconf;

    root spawn Orchestrator(max_retries_shown=3);
}
