```jac
"""Bulk recursive hard-delete model for service-level catalogs.

Demonstrates the OpenMetadata service-level bulk delete scenario using
native Jac graph machinery:

- Service -> Database -> DatabaseSchema -> Table hierarchy modeled as
  typed ``Contains`` edges.
- ``ChunkedBulkDelete`` walker: paginates traversal in fixed-size
  chunks, acquires a service-level lock (rejects other deleters),
  commits each chunk atomically, and skips per-entity satellite work
  when ``cascade_covered`` is true. Mirrors the bounded-memory +
  atomic-chunk + cascade-capability fix from the issue.
- ``UnboundedBulkDelete`` walker: the legacy path that hydrates every
  descendant into walker state and walks the whole subtree at once.
  Mirrors the pre-fix whole-level loading that OOMs the JVM.
"""

node Service {
    has name: str = "";
    has fqn: str = "";
    has cascade_covered: bool = False;
    has lock_holder: str = "";
    has deleted: bool = False;
}

node Database {
    has name: str = "";
    has fqn: str = "";
    has deleted: bool = False;
}

node DatabaseSchema {
    has name: str = "";
    has fqn: str = "";
    has deleted: bool = False;
}

node Table {
    has name: str = "";
    has fqn: str = "";
    has deleted: bool = False;
}

edge Contains {
    has depth: int = 0;
}

walker ChunkedBulkDelete {
    has chunk_size: int = 100;
    has max_depth: int = 8;
    has owner: str = "deleter";
    has purged_in_chunk: int = 0;
    has chunks_committed: int = 0;
    has total_purged: int = 0;
    has lock_held: bool = False;
    has finished: bool = False;
    has depth: int = 0;

    can start with Root entry {
        children = [root -->];
        if len(children) == 0 {
            print("no service under root");
            disengage;
        }
        svc = children[0];
        if svc.lock_holder != "" and svc.lock_holder != self.owner {
            print(f"ABORT: service {svc.name} locked by {svc.lock_holder}");
            disengage;
        }
        svc.lock_holder = self.owner;
        self.lock_held = True;
        print(f"acquired lock on service {svc.name} as {self.owner}");
        visit [-->];
    }

    can descend with Service entry {
        self.depth += 1;
        print(f"service {here.name} cascade_covered={here.cascade_covered} "
              f"chunk_size={self.chunk_size} max_depth={self.max_depth}");
        visit [-->] else {
            if not self.finished {
                self.finished = True;
                if self.lock_held {
                    print(f"releasing lock, total purged={self.total_purged} "
                          f"in {self.chunks_committed} atomic chunks");
                    self.lock_held = False;
                }
            }
            disengage;
        }
    }

    can drain with Database | DatabaseSchema | Table entry {
        self.depth += 1;
        if self.depth >= self.max_depth {
            print(f"  depth cap {self.max_depth} hit at {here.name}, stopping");
            disengage;
        }
        if self.purged_in_chunk >= self.chunk_size {
            self.chunks_committed += 1;
            print(f"--- chunk {self.chunks_committed} committed "
                  f"(purged={self.purged_in_chunk}) ---");
            self.purged_in_chunk = 0;
        }
        if not here.deleted {
            here.deleted = True;
            self.purged_in_chunk += 1;
            self.total_purged += 1;
            print(f"  purged {here.name} (fqn={here.fqn})");
        }
        visit [-->] else {
            if not self.finished {
                self.finished = True;
                if self.purged_in_chunk > 0 {
                    self.chunks_committed += 1;
                    print(f"--- final chunk {self.chunks_committed} committed "
                          f"(purged={self.purged_in_chunk}) ---");
                    self.purged_in_chunk = 0;
                }
                if self.lock_held {
                    print(f"releasing lock, total purged={self.total_purged} "
                          f"in {self.chunks_committed} atomic chunks");
                    self.lock_held = False;
                }
            }
            disengage;
        }
    }
}

walker UnboundedBulkDelete {
    has owner: str = "deleter-unbounded";
    has hydrated: list[str] = [];
    has reported: bool = False;

    can start with Root entry {
        children = [root -->];
        if len(children) == 0 {
            print("no service under root");
            disengage;
        }
        svc = children[0];
        print(f"UNBOUNDED: hydrating whole subtree of {svc.name} "
              f"(no chunking, no lock, all in walker state)");
        visit [-->];
    }

    can hydrate with Service entry {
        self.hydrated.append(here.name);
        visit [-->] else {
            if not self.reported {
                self.reported = True;
                print(f"UNBOUNDED done, hydrated {len(self.hydrated)} node names "
                      f"into walker state: {self.hydrated}");
                print("peak heap ~= N*sizeof(node), the whole level in RAM");
            }
            disengage;
        }
    }

    can load with Database | DatabaseSchema | Table entry {
        self.hydrated.append(here.name);
        visit [-->] else {
            if not self.reported {
                self.reported = True;
                print(f"UNBOUNDED done, hydrated {len(self.hydrated)} node names "
                      f"into walker state: {self.hydrated}");
                print("peak heap ~= N*sizeof(node), the whole level in RAM");
            }
            disengage;
        }
    }
}

with entry {
    svc = Service(name="analytics", fqn="svc.analytics",
                  cascade_covered=True);
    db = Database(name="warehouse", fqn="svc.analytics.warehouse");
    s1 = DatabaseSchema(name="raw", fqn="svc.analytics.warehouse.raw");
    s2 = DatabaseSchema(name="mart", fqn="svc.analytics.warehouse.mart");
    t1 = Table(name="events", fqn="svc.analytics.warehouse.raw.events");
    t2 = Table(name="users", fqn="svc.analytics.warehouse.raw.users");
    t3 = Table(name="kpi", fqn="svc.analytics.warehouse.mart.kpi");

    root ++> svc
        +>:Contains(depth=1):+> db
        +>:Contains(depth=2):+> s1
        +>:Contains(depth=2):+> s2
        +>:Contains(depth=3):+> t1
        +>:Contains(depth=3):+> t2
        +>:Contains(depth=3):+> t3;

    print("=== CHUNKED + CASCADE-COVERED PATH ===");
    root spawn ChunkedBulkDelete(chunk_size=3, max_depth=8, owner="op-1");

    print("");
    print("=== UNBOUNDED PATH (legacy whole-level load) ===");
    root spawn UnboundedBulkDelete(owner="legacy");
}
```

```jac
"""Session archive discovery: model how a compressed archive loses its real session id
because the materialized decompression cache filename shadows the original archive name.

The bug: when an archive is compressed (e.g. .jsonl.deleted....zst), the discovery
pipeline substitutes the materialized cache path (ending in .jsonl) for the original
archive path. The session id parser then sees a stem like
"<sha256>-<size>-<mtimeMs>.jsonl" instead of the real id like "sess-zstd", so the
discovered entry cannot be matched back to its session store record.

This demo models the two archive kinds as nodes, the discovery walker, and the
identity-preserving vs. identity-losing paths.
"""

node SessionStoreEntry {
    has session_id: str = "";
    has label: str = "";
}

node Archive {
    has archive_name: str = "";
    has is_compressed: bool = False;
    has cache_filename: str = "";
}

node DiscoveryResult {
    has reported_session_id: str = "";
    has true_session_id: str = "";
    has parsed_basename: str = "";
    has first_user_message: str = "";
}

edge DiscoveredFrom {
    has reason: str = "";
}

walker DiscoverAllSessions {
    can start with Root entry {
        visit [-->];
    }

    can scan with Archive entry {
        parsed_stem = here.cache_filename if here.is_compressed else here.archive_name;
        here ++> DiscoveryResult(
            parsed_basename=parsed_stem,
            true_session_id=here.archive_name,
            reported_session_id=parsed_stem,
            first_user_message="hello from " + here.archive_name
        );
        visit [-->];
    }
}

walker UsageMatcher {
    can start with Root entry {
        visit [-->];
    }

    can descend with Archive entry {
        visit [-->];
    }

    can linkStore with DiscoveryResult entry {
        here +>:DiscoveredFrom(reason="found"):+> SessionStoreEntry(
            session_id=here.true_session_id,
            label="Session " + here.true_session_id
        );
        visit [-->];
    }
}

walker ReportDrift {
    has mismatches: int = 0;
    has matches: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can descend with Archive entry {
        visit [-->];
    }

    can audit with DiscoveryResult entry {
        ok = here.reported_session_id == here.true_session_id;
        verdict = "OK" if ok else "BUG";
        print(f"[{verdict} archive={here.true_session_id} "
              f"reported={here.reported_session_id} "
              f"parsed_basename={here.parsed_basename} "
              f"msg={here.first_user_message}");
        if ok {
            self.matches += 1;
        } else {
            self.mismatches += 1;
        }
        visit [-->];
    }
}

with entry {
    plain = Archive(
        archive_name="sess-plain",
        is_compressed=False,
        cache_filename=""
    );
    zstd = Archive(
        archive_name="sess-zstd",
        is_compressed=True,
        cache_filename="39b057f078c548c5475e5708852cddb4-128-1787836665594.jsonl"
    );

    root ++> plain;
    root ++> zstd;

    root spawn DiscoverAllSessions();
    root spawn UsageMatcher();
    audit = root spawn ReportDrift();
    print(f"summary: matches={audit.matches} mismatches={audit.mismatches}");
}
