```jac
"""forjar apply --plan-file confirmation model."""

node ApplyConfig {
    has yes_flag: bool = False;
    has tty: bool = True;
}

node ApplyMode {
    has name: str = "";
    has calls_preflight: bool = False;
}

node Preflight {
    has confirm_destructive: bool = False;
    has dry_run: bool = False;
}

node Plan {
    has to_destroy: int = 0;
    has minutes_old: int = 0;
}

edge RoutedThrough {}

walker NormalApply {
    has prompted: bool = False;
    has aborted: bool = False;
    has yes_flag: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can step with ApplyConfig entry {
        self.yes_flag = here.yes_flag;
        visit [-->];
    }

    can branch with ApplyMode entry {
        visit [-->];
    }

    can gate with Preflight entry {
        needs_confirm = here.confirm_destructive
            and not here.dry_run
            and not self.yes_flag;
        if needs_confirm {
            self.prompted = True;
            visit [-->];
        } else {
            visit [-->];
        }
    }

    can execute with Plan entry {
        if self.prompted and not self.yes_flag and here.to_destroy > 0 {
            self.aborted = True;
            print(
                f"[normal] prompt raised for to_destroy={here.to_destroy}; "
                f"apply halted pending confirmation"
            );
            disengage;
        }
        print(
            f"[normal] executing plan: to_destroy={here.to_destroy}, "
            f"minutes_old={here.minutes_old}"
        );
    }
}

walker PlanFileApply {
    has prompted: bool = False;
    has aborted: bool = False;
    has yes_flag: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can step with ApplyConfig entry {
        self.yes_flag = here.yes_flag;
        visit [-->];
    }

    can branch with ApplyMode entry {
        # Plan-file path: the mode is "from_plan_file" (calls_preflight=False).
        # We walk all reachable nodes; the Preflight-skipping ability below
        # handles filtering so the preflight never fires.
        visit [-->];
    }

    # Plan-file path SKIPS Preflight entirely — no prompt ability fires.
    # This ability moves past any Preflight node without raising the prompt,
        # mirroring the Rust call graph where cmd_apply_from_plan never
    # references apply_preflight.
    can skip_preflight with Preflight entry {
        visit [-->];
    }

    can execute with Plan entry {
        # The "plan is the confirmation" reading lives here: the walker
        # proceeds without a prompt, regardless of to_destroy.
        print(
            f"[plan-file] executing plan WITHOUT prompt: "
            f"to_destroy={here.to_destroy}, minutes_old={here.minutes_old}"
        );
    }
}

with entry {
    cfg = ApplyConfig(yes_flag=False, tty=True);
    normal_mode = ApplyMode(name="normal", calls_preflight=True);
    plan_mode = ApplyMode(name="from_plan_file", calls_preflight=False);
    preflight = Preflight(confirm_destructive=True, dry_run=False);
    plan = Plan(to_destroy=3, minutes_old=0);

    cfg +>:RoutedThrough:+> normal_mode;
    cfg +>:RoutedThrough:+> plan_mode;
    normal_mode +>:RoutedThrough:+> preflight;
    plan_mode +>:RoutedThrough:+> preflight;
    preflight +>:RoutedThrough:+> plan;

    print("=== Normal apply path (should prompt) ===");
    NormalApply() spawn cfg;

    print("");
    print("=== Plan-file apply path (currently does NOT prompt) ===");
    PlanFileApply() spawn cfg;

    print("");
    print("=== Same plan, stale, through plan-file path ===");
    stale = Plan(to_destroy=1, minutes_old=1440);
    preflight2 = Preflight(confirm_destructive=True, dry_run=False);
    plan_mode2 = ApplyMode(name="from_plan_file", calls_preflight=False);
    preflight2 +>:RoutedThrough:+> stale;
    plan_mode2 +>:RoutedThrough:+> preflight2;
    cfg +>:RoutedThrough:+> plan_mode2;
    PlanFileApply() spawn cfg;
}
