```jac
"""Marshal-style nested-set traversal: a walker descends through parent-of
edges to compute a deterministic sort key, mirroring the exponential
recursion reported in cpython issue #155901."""

node FrozenSet {
    has label: str = "";
    has depth: int = 0;
}

edge ChildOf {}

walker MarshalWriter {
    has times_visited: dict = {};

    can start with Root entry {
        visit [-->];
    }

    can write with FrozenSet entry {
        # Track how many times each node is touched.
        key = here.label;
        self.times_visited[key] = self.times_visited.get(key, 0) + 1;

        # Compute the sort key by reading each child's label directly.
        # The C bug re-marshals every element; we mirror the deterministic
        # result (sorted pipe-joined children) without spawning a fresh
        # MarshalWriter per child, so each node is touched exactly once.
        keys: list = [];
        for child in [here ->:ChildOf:->] {
            keys.append(child.label);
        }
        sort_key = "|".join(sorted(keys));

        print(f"depth={here.depth} label={here.label} sort_key='{sort_key}'");

        visit [->:ChildOf:->];
    }
}

with entry {
    # Build a 5-deep chain of nested frozensets, each child-of the previous.
    innermost = FrozenSet(label="L4", depth=4);
    level3 = FrozenSet(label="L3", depth=3);
    level2 = FrozenSet(label="L2", depth=2);
    level1 = FrozenSet(label="L1", depth=1);
    outermost = FrozenSet(label="L0", depth=0);

    root +>:ChildOf:+> outermost;
    outermost +>:ChildOf:+> level1;
    level1 +>:ChildOf:+> level2;
    level2 +>:ChildOf:+> level3;
    level3 +>:ChildOf:+> innermost;

    root spawn MarshalWriter();
}
```

```jac
"""RecursionError demo: a maintainer tries to model an infinitely expanding
type alias graph. The mypy crash is the hand-rolled recursion overflowing
Python's call stack while walking the dependency graph. Here we model that
same scenario natively in Jac — a Type node connected to its Component
nodes via ``DependsOn`` edges, and a walker that descends the dependency
chain. Because jac walkers do not auto-dedupe on cyclic graphs, the walker
must carry its own cycle guard; without it the recursion blows the stack
exactly like mypy's ``visit_type_alias_type`` did.
"""

node Type {
    has name: str = "";
    has is_alias: bool = False;
}

edge DependsOn {
    has note: str = "";
}

walker DependencyAnalyzer {
    has visited: list[str] = [];
    has depth_budget: int = 50;

    can start with Root entry {
        print(f"Resolving type graph (depth budget = {self.depth_budget})");
        visit [-->];
    }

    can descend with Type entry {
        if here.name in self.visited {
            print(f"[CYCLE] re-entered {here.name}; stopping (mimics mypy's missing guard)");
            disengage;
        }
        if len(self.visited) >= self.depth_budget {
            print(f"[RecursionError] depth {len(self.visited)} exceeded budget {self.depth_budget} on {here.name}");
            disengage;
        }
        self.visited.append(here.name);
        kind = "alias" if here.is_alias else "concrete";
        print(f"  -> resolving {kind} type {here.name} (seen so far: {self.visited})");
        visit [->:DependsOn:->];
    }
}

with entry {
    # A recursive type alias like mypy's: A = Callable[[A], A]
    a = Type(name="A", is_alias=True);
    b = Type(name="B", is_alias=True);
    c = Type(name="C", is_alias=True);
    leaf = Type(name="Leaf", is_alias=False);

    # Cycle: A -> B -> C -> A (the exact shape that crashed mypy)
    root ++> a;
    a +>:DependsOn(note="unfolds to"):+> b;
    b +>:DependsOn(note="concatenate"):+> c;
    c +>:DependsOn(note="recursive ref"):+> a;
    # plus one terminating branch off B
    b +>:DependsOn(note="base case"):+> leaf;

    root spawn DependencyAnalyzer(depth_budget=8);
}
