```jac
"""Ontology shortest-path finder.

Models the scenario from issue #176: pick a source and target entity in an
ontology graph and have a walker find the shortest path between them along
``subClassOf`` (and optionally other object properties). The walker
preserves the cycle guard that the hand-rolled ``rdflib`` + ``networkx``
script needs (and that the project author flagged as something to keep
robust) by tracking a visited set explicitly, and falls back to a clean
"no path" report when the two entities live in disconnected components.
"""

# --- Edge archetypes ----------------------------------------------------
# Every relationship in the graph carries meaning, so each is a typed edge.
# The payload is the property name so the printed path can label each hop.

edge SubClassOf {
    has property_name: str = "subClassOf";
}

edge EquivalentTo {
    has property_name: str = "equivalentClass";
}

edge RelatedTo {
    has property_name: str = "related";
}

# A polymorphic base so the union ability in ``PathFinder`` can touch
# every entity through one trigger. Mirrors the "is this a real entity?"
# check the original networkx script performs before adding nodes.

node _EntityBase {
    has name: str = "";
}

node ClassNode(_EntityBase) {
    has label: str = "";
}

node IndividualNode(_EntityBase) {
    has label: str = "";
    has of_class: str = "";
}

node SKOSNode(_EntityBase) {
    has pref_label: str = "";
}

# --- Walker -------------------------------------------------------------
# A BFS that records the trail. The issue is explicit: "Keep it robust for
# large graphs (bound the work, handle disconnected components)." So the
# walker uses an explicit visited set (jac 0.36.1 has no built-in
# dedupe-on-visit) and reports a clean failure when no path exists.
#
# The walker first locates the source node, then performs a BFS from
# there. This ensures that disconnected components attached to ``root``
# are never explored — the search is scoped to the source's component.

walker PathFinder {
    has source: str = "";
    has target: str = "";
    has max_depth: int = 32;
    has visited: list[str] = [];
    has trail: list[str] = [];
    has found: bool = False;
    has hops: int = -1;

    can start with Root entry {
        self.visited = [];
        self.trail = [];
        self.found = False;
        self.hops = -1;
        # Find the source node by name and start the BFS there.
        for child in [-->] {
            if not self.found and child.name == self.source {
                visit child;
            }
        }
    }

    can step with _EntityBase entry {
        if self.found {
            disengage;
        }
        name = here.name;
        if name in self.visited {
            # Cycle guard — hand-rolled BFS keeps an explicit seen set,
            # the walker has to do the same on jac 0.36.1.
            visit [-->];
            disengage;
        }
        self.visited = self.visited + [name];
        self.trail = self.trail + [name];

        if name == self.target {
            self.found = True;
            self.hops = len(self.trail) - 1;
            visit [-->];
            disengage;
        }

        if len(self.trail) > self.max_depth {
            # Bound the work, as the issue requested for large graphs.
            self.trail = self.trail[:-1];
            visit [-->];
            disengage;
        }

        visit [-->];
    }
}

# --- Demo graph ---------------------------------------------------------
# A tiny ontology that exercises every relationship the issue calls out.
# Demonstrates that disconnected components are handled cleanly.

with entry {
    # Helper to create a labelled entity node.
    def make_node(label: str, kind: str) -> _EntityBase {
        if kind == "class" {
            return ClassNode(name=label, label=label);
        }
        if kind == "individual" {
            return IndividualNode(name=label, label=label, of_class="");
        }
        return SKOSNode(name=label, pref_label=label);
    }

    # Build the graph. Each "+>:" line is the typed-edge form the issue
    # is essentially asking us to adopt: the relationship is part of the
    # graph, not something we reconstruct from a parent_id field.
    cat_node = make_node("Cat", "class");
    animal_node = make_node("Animal", "class");
    dog_node = make_node("Dog", "class");
    person_node = make_node("Person", "class");
    human_node = make_node("Human", "class");
    concept_node = make_node("Concept", "class");
    isolated_node = make_node("Unrelated", "class");

    root ++> cat_node
        +>:SubClassOf:+> animal_node
        +>:SubClassOf:+> dog_node
        +>:SubClassOf:+> person_node
        +>:EquivalentTo:+> human_node
        +>:RelatedTo:+> concept_node;
    root ++> isolated_node;

    # --- Case 1: a path that exists ---------------------------------
    finder = PathFinder(source="Cat", target="Person");
    root spawn finder;

    if finder.found {
        print(f"Path: {' -> '.join(finder.trail)} "
              f"({finder.hops} hops)");
    } else {
        print("no path found");
    }

    # --- Case 2: a target in a disconnected component --------------
    finder2 = PathFinder(source="Cat", target="Unrelated");
    root spawn finder2;

    if finder2.found {
        print(f"Path: {' -> '.join(finder2.trail)}");
    } else {
        print(f"no path between {finder2.source} and {finder2.target} "
              f"(disconnected components)");
    }
}
```

```jac
"""Tree table traversal hardened against malformed input.

Models the issue's scenario natively: a consumer/producer tree walker
that flattens `children` references. The source code recursed blindly,
so a cyclic `children` link would overflow the stack and a null child
would crash with a TypeError inside the computed row.

This demo replaces the recursion with an explicit walker that:
  * walks typed `ChildOf` edges,
  * carries a per-walker `visited` set so cycles surface as a clear
    "cycle detected" diagnostic instead of a stack overflow,
  * skips null/invalid entries with an explicit "invalid node" report,
  * flags shared references (the same subtree reached twice) so callers
    see which branch produced the duplicate trackBy key.
"""

node Row {
    has title: str = "";
    has track_by: str = "";
    has payload: str = "";
    has expanded: bool = False;
    # Direct children references, kept as the original "malformed"
    # public API. The walker never recurses through this field; it
    # walks typed ChildOf edges instead.
    has children: list = [];
}

edge ChildOf {
    has position: int = 0;
}

walker Flatten {
    # Per-walker cycle guard. Required because jac has no
    # built-in once-per-node visitation — `visit [-->]` on a cycle
    # would loop forever.
    has visited: list = [];
    has rows: list = [];
    has dup_count: int = 0;

    can start with Root entry {
        print("Flatting tree...");
        visit [-->] else {
            print("  (no rows attached)");
            disengage;
        }
    }

    can descend with Row entry {
        # Null / non-Row guard. A malformed entry would have raised
        # TypeError inside the computed; here we surface it.
        if here.track_by == "" and here.title == "" {
            print(f"  [invalid node] empty row encountered at depth "
                  f"{len(self.visited)}");
            return;
        }

        # Cycle guard. The walker carries its own visited set so a
        # self-loop or back-edge is reported, not stacked into oblivion.
        seen = False;
        for key in self.visited {
            if key == here.track_by {
                seen = True;
                break;
            }
        }
        if seen {
            print(f"  [cycle detected] row '{here.title}' "
                  f"(trackBy={here.track_by}) already visited");
            self.dup_count += 1;
            return;
        }
        self.visited.append(here.track_by);

        # Shared-reference guard. If we re-enter an expanded parent
        # whose subtree is already on the stack, we still traverse once
        # but note the duplicate trackBy key that would have rendered
        # stale in the table.
        if here.expanded {
            print(f"  row: {here.title} ({here.track_by}) [expanded]");
        } else {
            print(f"  row: {here.title} ({here.track_by})");
        }
        self.rows.append(here.track_by);

        # Walk only the typed ChildOf edges — no manual recursion over
        # `here.children` (the original failure mode). Do NOT disengage
        # when the frontier is empty: that would abort the walk and
        # skip any sibling branches still to be visited.
        visit [->:ChildOf:->];
    }
}

with entry {
    # Build a tree:
    #         root
    #          |
    #        rootR (expanded)
    #        /    \
    #   childA    childB (expanded)
    #               |
    #             leafC
    #
    # Then deliberately introduce the three pathological shapes from
    # the issue on a second graph attached to root:
    #   * a cyclic edge childB -> rootR
    #   * a null / empty Row hanging off childA
    #   * a shared leaf referenced from two expanded parents
    rootR = Row(title="Root", track_by="r1", expanded=True);
    childA = Row(title="Child A", track_by="a1");
    childB = Row(title="Child B", track_by="b1", expanded=True);
    leafC = Row(title="Leaf C", track_by="c1");

    root ++> rootR;
    rootR +>:ChildOf(position=0):+> childA;
    rootR +>:ChildOf(position=1):+> childB;
    childB +>:ChildOf(position=0):+> leafC;

    # Pathological graph 1: cycle (cycleNode -> rootR) plus a null/empty
    # row under childA.
    cycleNode = Row(title="Cycle Node", track_by="x1");
    ghost = Row(title="", track_by="");  # malformed: empty fields
    childA +>:ChildOf:+> cycleNode;
    childA +>:ChildOf:+> ghost;
    cycleNode +>:ChildOf:+> rootR;  # back-edge -> cycle

    # Pathological graph 2: shared subtree. `leafC` is already under
    # childB; attach it under a second expanded parent to demonstrate
    # the duplicate-trackBy detection.
    sharedParent = Row(title="Shared Parent", track_by="sp1", expanded=True);
    rootR +>:ChildOf:+> sharedParent;
    sharedParent +>:ChildOf:+> leafC;

    print("=== well-formed subtree first ===");
    flattener = Flatten();
    root spawn flattener;
    rows_len = len(flattener.rows);
    visited_len = len(flattener.visited);
    print(f"flattener collected {rows_len} row(s); "
          f"duplicates flagged: {flattener.dup_count}");
    print(f"visited set size: {visited_len}");

    print("");
    print("=== pathological subtree survives without crashing ===");
    flattener2 = Flatten();
    root spawn flattener2;
    rows_len2 = len(flattener2.rows);
    visited_len2 = len(flattener2.visited);
    print(f"flattener2 collected {rows_len2} row(s); "
          f"duplicates flagged: {flattener2.dup_count}");
    print(f"visited set size: {visited_len2}");
}
