"""VST3 beginEdit/getState deadlock: synchronous yabridge calls vs mutual recursion."""

node DAWHost {
    has name: str = "";
}

node BridgeProxy {
    has mutual_recursion: bool = False;
    has begin_edit_in_flight: bool = False;
    has get_state_in_flight: bool = False;

    def would_deadlock() -> bool {
        return (
            self.begin_edit_in_flight
            and self.get_state_in_flight
            and not self.mutual_recursion
        );
    }
}

node PluginSandbox {
    has plugin_name: str = "";
    has editor_frozen: bool = False;
}

node VstParameter {
    has param_id: int = 0;
    has label: str = "";
}

edge SandboxLink { }
edge HostLink { }
edge ParameterLink { }

walker EditStateRace {
    has trace: list[str] = [];
    has outcome: str = "pending";
    has target_param_id: int = 0;
    has returning: bool = False;
    has printed: bool = False;

    def dump() -> None {
        if self.printed {
            return;
        }
        self.printed = True;
        for line in self.trace {
            print(line);
        }
    }

    can begin_edit with PluginSandbox entry {
        if self.returning {
            here.editor_frozen = True;
            self.trace.append(
                f"[{here.plugin_name}] editor frozen; host will kill unresponsive sandbox"
            );
            self.outcome = "DEADLOCK";
            self.dump();
            disengage;
        } else {
            self.trace.append(
                f"[{here.plugin_name}] plugin -> host: IComponentHandler::beginEdit(id={self.target_param_id})"
            );
            visit [->:SandboxLink:->] else { disengage; };
        }
    }

    can cross_bridge with BridgeProxy entry {
        here.begin_edit_in_flight = True;
        self.trace.append("[bridge] beginEdit sent via synchronous send_message()");
        self.trace.append("[bridge] host concurrently issues getState on plugin thread");
        here.get_state_in_flight = True;
        if here.would_deadlock() {
            self.trace.append(
                "[bridge] beginEdit and getState both blocked — neither callback returns"
            );
            self.returning = True;
            visit [<--] else { disengage; };
        } else {
            self.trace.append(
                "[bridge] send_mutually_recursive_message: getState reenters during beginEdit"
            );
            self.trace.append(
                "[bridge] send_mutually_recursive_message: beginEdit returns kResultOk"
            );
            visit [->:HostLink:->] else { disengage; };
        }
    }

    can finish_state_read with DAWHost entry {
        iface = "IComponent,IEditController";
        self.trace.append(f"[{here.name}] host -> plugin: {iface}::getState()");
        self.trace.append(
            f"[{here.name}] host <- plugin: kResultOk, IBStream bytes=2656"
        );
        if self.outcome == "pending" {
            self.outcome = "kResultOk";
        }
        self.dump();
        disengage;
    }
}

with entry {
    host = DAWHost(name="Bitwig Studio 6.0.11");

    broken_bridge = BridgeProxy(mutual_recursion=False);
    spaced = PluginSandbox(plugin_name="BABY Audio Spaced Out");
    spaced +>:ParameterLink:+> VstParameter(param_id=1810360849, label="main XY");
    spaced +>:SandboxLink:+> broken_bridge +>:HostLink:+> host;

    fixed_bridge = BridgeProxy(mutual_recursion=True);
    soothe = PluginSandbox(plugin_name="soothe2");
    soothe +>:ParameterLink:+> VstParameter(param_id=280860833, label="mixer anchor");
    soothe +>:SandboxLink:+> fixed_bridge +>:HostLink:+> host;

    root ++> spaced;
    root ++> soothe;

    print("=== Issue #504: sync beginEdit deadlocks with concurrent getState ===");
    fail_race = EditStateRace(target_param_id=1810360849) spawn spaced;
    if not fail_race.printed {
        for line in fail_race.trace {
            print(line);
        }
    }
    print(f"outcome={fail_race.outcome}, editor_frozen={spaced.editor_frozen}");

    print("");
    print("=== Patched: beginEdit uses send_mutually_recursive_message ===");
    ok_race = EditStateRace(target_param_id=280860833) spawn soothe;
    if not ok_race.printed {
        for line in ok_race.trace {
            print(line);
        }
    }
    print(f"outcome={ok_race.outcome}, editor_frozen={soothe.editor_frozen}");
}
