```jac
"""Skill-sniffer `--follow-refs` model.

Models the core scenario from issue #45: a skill manifest references
bundled scripts/resources, and a walker follows those references to
lint the referenced payload. Findings on referenced nodes roll up
into the parent skill's report. The walker carries an explicit cycle
guard and depth cap (the domain logic the issue requires).
"""

# ---- Entity archetypes ----------------------------------------------------

node Skill {
    has name: str = "";
    has score: int = 100;
    has findings: list[str] = [];
}

node Script {
    has path: str = "";
    has kind: str = "shell";
    has findings: list[str] = [];
    # A `Script` is itself a smell whenever its payload matches a
    # dangerous pattern (curl|bash, embedded token, etc.). Real
    # detection lives in the rules engine; this is a faithful stub.
    has suspicious: bool = False;
}

node ReferenceDoc {
    has path: str = "";
    has findings: list[str] = [];
    has suspicious: bool = False;
}

# ---- Typed edges ----------------------------------------------------------
#
# `BundledRef` is the typed edge the `--follow-refs` feature rides on.
# Its presence on a Skill is exactly the structural fact the issue
# is asking us to traverse: "this skill references that file".

edge BundledRef {
    has rel_path: str = "";
}

# ---- The walker -----------------------------------------------------------

walker FollowRefs {
    has max_depth: int = 5;
    has depth: int = 0;
    # Cycle guard. Walkers in jac do not dedupe on cyclic
    # graphs, so we carry an explicit visited set —
    # this is domain logic, not scaffolding.
    has visited: list[str] = [];
    # Track the parent skill we're rolling findings up into.
    has parent: Skill | None = None;

    can start with Root entry {
        # Find the skill off root and remember it as the rollup target.
        skills = [-->];
        if len(skills) > 0 {
            self.parent = skills[0];
        }
        visit [-->];
    }

    can load_skill with Skill entry {
        # Establish the skill as the rollup target and follow its refs.
        self.parent = here;
        visit [->:BundledRef:->];
    }

    # A Skill may bundle Scripts and ReferenceDocs via typed refs.
    # The single union ability touches only fields common to both
    # target types (path, findings, suspicious), declared on each.
    can audit_bundled with Script | ReferenceDoc entry {
        if self.depth >= self.max_depth {
            print(f"[depth-cap] stopped at depth {self.depth} on {here.path}");
            disengage;
        }
        if here.path in self.visited {
            print(f"[cycle] already audited {here.path}; skipping");
            disengage;
        }
        self.visited.append(here.path);

        here.findings = self.scan(here.path, here.suspicious);

        # Roll every finding on a referenced node up into the parent
        # skill. The walker has accumulated these findings across
        # every bundled node it visited.
        if self.parent is not None {
            skill = self.parent;
            skill.findings.extend(here.findings);
            skill.score = self.recompute(skill);
            print(f"[rollup] {skill.name} score now {skill.score} "
                  f"after {len(here.findings)} finding(s) from {here.path}");
        }

        # Continue to the next bundled ref, if any.
        self.depth += 1;
        visit [->:BundledRef:->];
    }

    # Stub rule engine: a path containing `secret` is treated as
    # containing an embedded token; a suspicious .sh is the
    # canonical "curl|bash a remote URL" payload the issue names.
    def scan(path: str, suspicious: bool) -> list[str] {
        out: list[str] = [];
        if suspicious {
            label = "INJECTION" if path.endswith(".sh") else "BLOAT";
            out.append(f"{label}: {path}");
        }
        if "secret" in path {
            out.append(f"SECRET: {path}");
        }
        return out;
    }

    def recompute(skill: Skill) -> int {
        new_score = 100 - 10 * len(skill.findings);
        return new_score if new_score > 0 else 0;
    }
}

# ---- Demo wiring ----------------------------------------------------------

with entry {
    # A clean-looking SKILL.md that references two bundled files.
    skill = Skill(name="setup-helper", score=100, findings=[]);
    root ++> skill;

    # Bundled payload: a script with a curl|bash pattern, plus a
    # reference doc with an embedded token. These mirror the issue's
    # acceptance test ("clean SKILL.md that references a script
    # containing a secret").
    bad_script = Script(path="scripts/setup.sh", kind="shell",
                    findings=[], suspicious=True);
    ref_doc = ReferenceDoc(path="references/api.md", findings=[],
                       suspicious=False);
    secret_script = Script(path="scripts/secret-loader.sh", kind="shell",
                       findings=[], suspicious=False);

    # Typed edges: the relationship is "this skill bundles that file".
    skill +>:BundledRef(rel_path="scripts/setup.sh"):+> bad_script;
    skill +>:BundledRef(rel_path="references/api.md"):+> ref_doc;
    skill +>:BundledRef(rel_path="scripts/secret-loader.sh"):+> secret_script;

    # A cycle: the reference doc claims to reference its own parent
    # skill back. The walker's visited set must catch this; without
    # it, the walker would loop forever.
    ref_doc +>:BundledRef:+> skill;

    root spawn FollowRefs(max_depth=5);

    print(f"\nfinal: {skill.name} score={skill.score}");
    for note in skill.findings {
        print(f"  - {note}");
    }
}
