```jac
"""Provenance-aware findings walk: collect every finding attributable to a
boefje through normalizer results and bit inference chains.

Models the OpenKAT scenario where a boefje produces observations directly
(via its normalizer) and indirectly (via bits that consume its data). A
walker seeded at root fans out from the matching boefje across
Origin -> Result -> Finding, then loops through inference origins (whose
source or parameters descend from a collected result) until no new
findings are discovered.
"""

node Boefje {
    has name: str = "";
}

node Origin {
    has method: str = "";
    has task_id: str = "";
    has visited: bool = False;
}

node InferenceOrigin {
    has method: str = "";
    has visited: bool = False;
}

node OriginParameter {
    has key: str = "";
    has visited: bool = False;
}

node Result {
    has kind: str = "";
    has visited: bool = False;
}

node Finding {
    has severity: str = "";
    has muted: bool = False;
    has visited: bool = False;
}

edge ProducedBy { has boefje_name: str = ""; }
edge ResultOf { }
edge InputOf { }
edge SourcedFrom { }
edge Flagged { }

walker BoefjeFindings {
    has target_name: str = "";
    has findings_seen: list = [];
    has results_seen: list = [];
    has origins_seen: list = [];
    has found: bool = False;
    has started: bool = False;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can collect with Boefje entry {
        if here.name == self.target_name {
            self.found = True;
            self.started = True;
            print(f"Collecting findings contributed by boefje '{here.name}'");
            visit [->:ProducedBy:->];
        }
    }

    can seed with Origin entry {
        if not here.visited {
            here.visited = True;
            self.origins_seen.append(here);
            visit [->:ResultOf:->];
        }
    }

    can absorb with Result entry {
        if not here.visited {
            here.visited = True;
            self.results_seen.append(here);
            visit [->:ResultOf:->];
            visit [->:SourcedFrom:->];
            visit [->:Flagged:->];
        }
    }

    can grow with InferenceOrigin entry {
        if not here.visited {
            here.visited = True;
            self.origins_seen.append(here);
            visit [->:ResultOf:->];
            visit [->:InputOf:->];
        }
    }

    can hop with OriginParameter entry {
        if not here.visited {
            here.visited = True;
            visit [->:Flagged:->];
        }
    }

    can record with Finding entry {
        if not here.visited {
            here.visited = True;
            self.findings_seen.append(here);
        }
        visit [-->];
    }

    can summarize with exit {
        if self.started {
            print(f"Total attributable findings: {len(self.findings_seen)}");
            for f in self.findings_seen {
                mute = "muted" if f.muted else "open";
                print(f"  - [{f.severity}/{mute}] finding");
            }
        } elif not self.found {
            print(f"No boefje named {self.target_name}");
        }
    }
}

with entry {
    b1 = Boefje(name="ssl_scanner");

    o_normalizer = Origin(method="normalizer", task_id="norm-1");
    o_bit_a = InferenceOrigin(method="bit-a");
    o_bit_b = InferenceOrigin(method="bit-b");
    o_param_holder = OriginParameter(key="primary");
    o_unrelated = Origin(method="normalizer", task_id="norm-other");

    r_direct = Result(kind="observation");
    r_bit_a = Result(kind="declaration");
    r_bit_b = Result(kind="declaration");
    r_indirect = Result(kind="affirmation");
    r_other = Result(kind="observation");

    f1 = Finding(severity="high");
    f2 = Finding(severity="medium", muted=True);
    f3 = Finding(severity="low");
    f_unrelated = Finding(severity="critical");

    b1 +>:ProducedBy(boefje_name=b1.name):+> o_normalizer;
    o_normalizer +>:ResultOf:+> r_direct;
    o_unrelated +>:ResultOf:+> r_other;

    r_direct +>:ResultOf:+> o_bit_a;
    o_bit_a +>:ResultOf:+> r_bit_a;
    o_bit_a +>:InputOf:+> o_param_holder;
    o_param_holder +>:Flagged:+> r_direct;
    r_bit_a +>:SourcedFrom:+> o_bit_b;
    o_bit_b +>:ResultOf:+> r_bit_b;
    r_bit_b +>:ResultOf:+> r_indirect;

    r_direct +>:Flagged:+> f1;
    r_bit_a +>:Flagged:+> f2;
    r_indirect +>:Flagged:+> f3;
    r_other +>:Flagged:+> f_unrelated;

    root ++> b1;
    root ++> Boefje(name="other_boefje") +>:ProducedBy(boefje_name="other_boefje"):+> o_unrelated;
    root spawn BoefjeFindings(target_name="ssl_scanner");
}
