```jac
"""CI baseline repair model: linter drift propagation across release lines.

The real issue (CTRL-CI-CLIPPY-MASTER-01) is a release-line CI baseline that
passed on a previous toolchain and now fails because a newer linter rejects
test expressions. The domain entities are: a release line (master / develop),
CI runs, lint checks with a toolchain version, and the source-level repair
that closes the defect. This program models the same flow natively: nodes
represent release lines, CI runs, linter versions, the source blob under
inspection, and the patch; a walker replays the propagation walk that a
maintainer would do by hand (master fail -> find reviewed fix on develop ->
propagate only the reviewed correction, with a cycle guard so we never loop
between branches). The relationships carry meaning, so they get typed edges.
"""

node ReleaseLine {
    has name: str = "";
    has head_sha: str = "";
    has baseline_passing: bool = True;
}

node LintCheck {
    has tool: str = "clippy";
    has toolchain_version: str = "";
    has rule: str = "";
    has outcome: str = "PASS";
    has blob_sha: str = "";
}

node RepairCommit {
    has sha: str = "";
    has summary: str = "";
    has reviewed: bool = False;
    has merged: bool = False;
}

node Patch {
    has source_sha: str = "";
    has target_sha: str = "";
    has rationale: str = "";
}

edge Runs {
    has run_id: str = "";
}

edge InspectedBy {
    has run_id: str = "";
}

edge HasFix {
}

edge CherryPicks {
}

walker PropagateFix {
    has seen: list[str] = [];
    has patch_lines: int = 0;
    has changelog_lines: int = 0;

    can start with Root entry {
        print("starting propagation walk");
        visit [-->];
    }

    can scan with ReleaseLine entry {
        if here.name in self.seen {
            print(f"  cycle hit on {here.name}, disengaging");
            skip;
        }
        self.seen.append(here.name);
        status = "GREEN" if here.baseline_passing else "RED";
        print(f"  release line {here.name} @ {here.head_sha[:8]} -> CI {status}");
        visit [-->];
    }

    can read with LintCheck entry {
        verdict = "ok" if here.outcome == "PASS" else "broken";
        print(f"    lint {here.tool} {here.toolchain_version} on {here.rule} -> {verdict} (blob {here.blob_sha[:8]})");
        visit [-->];
    }

    can collect with RepairCommit entry {
        if not here.reviewed or not here.merged {
            print(f"    skipping un-reviewed/un-merged commit {here.sha[:8]}");
            skip;
        }
        print(f"    authoritative fix {here.sha[:8]}: {here.summary}");
        visit [-->];
    }

    can apply with Patch entry {
        self.patch_lines += 3;
        self.changelog_lines += 1;
        print(f"    applying patch {here.source_sha[:8]} -> {here.target_sha[:8]}: {here.rationale}");
    }
}

with entry {
    master  = ReleaseLine(name="master",  head_sha="40e9c06d4ab76217c3ef277dd539d3b5580e2bb8", baseline_passing=False);
    develop = ReleaseLine(name="develop", head_sha="5444081aba7adafb17822cb17fe67e6326828a79", baseline_passing=True);

    master_fail = LintCheck(
        toolchain_version="1.98",
        rule="clippy::useless_format",
        outcome="FAIL",
        blob_sha="45353520bf4d0ed199c1757b692f43bdbff8f389"
    );

    develop_pass = LintCheck(
        toolchain_version="1.98",
        rule="clippy::useless_format",
        outcome="PASS",
