    root +>:ChildOf:+> guides +>:ChildOf:+> intro +>:ChildOf:+> overview;
    intro +>:ChildOf:+> setup;
    root +>:ChildOf:+> docs +>:ChildOf:+> getting_started;

    print("=== Initial tree ===");
