```jac
"""Velero storage-full deadlock model.

The bug report describes a circular dependency in Velero when the object
store runs out of space: a backup cannot finalize (PutObject fails with
HTTP 507), a delete request cannot finalize either (PutObject for the
status also fails), and repository maintenance cannot write its lock.
Result: nothing can transition to a terminal state, so nothing frees
space, so storage stays full forever.

This demo lifts that scenario into idiomatic Jac: backups, their
DataUploads, DeleteBackupRequests and RepoMaintenance jobs are node
archetypes; the dependency relationships are typed edges; a walker
walks the dependency chain so we can see which writes are blocked by
which upstream failures, exposing the circular dependency the issue
describes.
"""

node Auditable {
    has name: str = "";
    has phase: str = "New";
    has terminal: bool = False;
    has write_attempts: int = 0;

    def _kind() -> str {
        return "Auditable";
    }

    def _blocked_phase() -> str {
        return "Blocked";
    }
}

node Backup(Auditable) {
    has store_free_mb: int = 0;

    override def _kind() -> str {
        return "Backup";
    }

    override def _blocked_phase() -> str {
        return "FinalizingPartiallyFailed";
    }
}

node DataUpload(Auditable) {
    override def _kind() -> str {
        return "DataUpload";
    }

    override def _blocked_phase() -> str {
        return "Failed";
    }
}

node DeleteRequest(Auditable) {
    has frees_mb: int = 0;

    override def _kind() -> str {
        return "DeleteBackupRequest";
    }

    override def _blocked_phase() -> str {
        return "InProgress";
    }
}

node RepoMaintenance(Auditable) {
    override def _kind() -> str {
        return "RepoMaintenance";
    }

    override def _blocked_phase() -> str {
        return "Failed";
    }
}

edge NeedsFinalizeWrite { }
edge OwnsUpload { }
edge TargetsBackup { }
edge MaintainsRepo { }

walker StorageAuditor {
    has store_full: bool = True;
    has retry_limit: int = 3;
    has deadlocked: list[str] = [];

    can start with Root entry {
        print(f"store_full={self.store_full} retry_limit={self.retry_limit}");
        visit [-->] else { disengage; }
    }

    can probe with Auditable entry {
        here.write_attempts = here.write_attempts + 1;

        if self.store_full {
            here.terminal = False;
            blocked = here._blocked_phase();
            here.phase = blocked;
            self.deadlocked.append(here.name);
            print(
                f"BLOCKED {here.name} ({here._kind()}): cannot PUT "
                f"finalize/status blob -> HTTP 507 storage full"
            );
        } else {
            here.terminal = True;
            here.phase = "Completed";
            print(f"OK    {here.name} ({here._kind()}): finalized cleanly");
        }

        visit [-->] else { disengage; }
    }
}

walker DeleteCascade {
    can start with Root entry {
        print("\n--- delete-cascade walk ---");
        visit [-->] else { disengage; }
    }

    can audit_delete with DeleteRequest entry {
        print(
            f"DeleteRequest {here.name} phase={here.phase} "
            f"frees_mb={here.frees_mb}"
        );
        visit [->:TargetsBackup:->] else { disengage; }
    }

    can audit_backup with Backup entry {
        print(f"  -> Backup {here.name} phase={here.phase}");
        visit [->:OwnsUpload:->] else { disengage; }
    }

    can audit_upload with DataUpload entry {
        print(f"     -> DataUpload {here.name} phase={here.phase}");
        visit [-->];
    }
}

with entry {
    b1 = Backup(name="backup1", phase="Completed", terminal=True, store_free_mb=541);
    b2 = Backup(name="backup2", phase="Completed", terminal=True, store_free_mb=541);
    b3 = Backup(name="backup3", phase="Completed", terminal=True, store_free_mb=541);
    b4 = Backup(name="backup4", phase="Completed", terminal=True, store_free_mb=541);
    b5 = Backup(name="backup5", phase="FinalizingPartiallyFailed", terminal=False, store_free_mb=541);

    b1_u1 = DataUpload(name="b1-u1", phase="Completed", terminal=True);
    b1_u2 = DataUpload(name="b1-u2", phase="Completed", terminal=True);
    b2_u1 = DataUpload(name="b2-u1", phase="Completed", terminal=True);
    b3_u1 = DataUpload(name="b3-u1", phase="Completed", terminal=True);
    b4_u1 = DataUpload(name="b4-u1", phase="Completed", terminal=True);
    b5_u1 = DataUpload(name="b5-u1", phase="Failed", terminal=True);
    b5_u2 = DataUpload(name="b5-u2", phase="Failed", terminal=True);

    del4 = DeleteRequest(name="del-backup4", phase="InProgress", terminal=False, frees_mb=12000);

    maint = RepoMaintenance(name="kopia-maintenance", phase="Failed", terminal=False);

    root ++> b1 ++> b2 ++> b3 ++> b4 ++> b5;
    b1 +>:OwnsUpload:+> b1_u1;
    b1 +>:OwnsUpload:+> b1_u2;
    b2 +>:OwnsUpload:+> b2_u1;
    b3 +>:OwnsUpload:+> b3_u1;
    b4 +>:OwnsUpload:+> b4_u1;
    b5 +>:OwnsUpload:+> b5_u1;
    b5 +>:OwnsUpload:+> b5_u2;

    b1 +>:NeedsFinalizeWrite:+> b5;
    b2 +>:NeedsFinalizeWrite:+> b5;
    b3 +>:NeedsFinalizeWrite:+> b5;

    del4 +>:TargetsBackup:+> b4;

    root +>:MaintainsRepo:+> maint;

    print("=== StorageAuditor with store_full=True (the deadlock) ===");
    auditor = StorageAuditor(store_full=True, retry_limit=10);
    root spawn auditor;
    joined = ", ".join(auditor.deadlocked);
    print(f"\ndeadlocked entities: {joined}");

    print("\n=== StorageAuditor with store_full=False (storage freed) ===");
    root spawn StorageAuditor(store_full=False, retry_limit=10);

    print("\n=== DeleteCascade: what a delete would need to clean up ===");
    root spawn DeleteCascade();
}
