"""Zoom unsigned guest join: Firefox lane routing, bounded guest-name entry, RTMS policy wall classification, and teardown honesty."""

node GraphEntity {
    def tag() -> str {
        return "entity";
    }
}

node JoinProfile {
    has profile_name: str = "";
    has unsigned_guest: bool = False;
    has authenticated: bool = False;
}

node MeetingRoom(GraphEntity) {
    has label: str = "";
    has platform: str = "";
    has protected_room: bool = False;
    override def tag() -> str {
        return f"meeting:{self.platform}:{self.label}";
    }
}

node BrowserLane(GraphEntity) {
    has product: str = "";
    has generation: int = 0;
    has playwright: str = "";
    has revision: str = "";
    has stock_image: bool = True;
    override def tag() -> str {
        return f"lane:{self.product}-{self.generation}";
    }
}

node GuestNameField {
    has target_name: str = "";
    has read_value: str = "";
    has settled: bool = False;
    has attempt_index: int = 0;
    has needs_repair: bool = False;

    def apply_write() {
        self.read_value = self.target_name;
    }

    def verify_twice() -> bool {
        first_ok = self.read_value == self.target_name;
        second_ok = self.read_value == self.target_name and not self.needs_repair;
        return first_ok and second_ok;
    }

    def repair_once() {
        self.needs_repair = False;
        self.read_value = self.target_name;
    }
}

node RtmsClause {
    has clause_text: str = "";
    has detected: bool = False;
}

node JoinSession {
    has admission: str = "waiting";
    has bot_left: bool = False;
    has teardown_reported: bool = False;
}

edge PlatformTarget { }
edge CandidateLane { }
edge PrejoinStage { has order: int = 0; }
edge RtmsLink { }
edge SessionFor { }

walker LaneRouter {
    has want_firefox: bool = False;
    has selected_lane: str = "";

    can start with Root entry {
        visit [-->];
    }

    can read_profile with JoinProfile entry {
        self.want_firefox = here.unsigned_guest and not here.authenticated;
        visit [->:PlatformTarget:->] else { disengage; }
    }

    can enter_meeting with MeetingRoom entry {
        visit [->:CandidateLane:->] else { disengage; }
    }

    can pick with BrowserLane entry {
        firefox_ok = self.want_firefox and here.product == "Firefox";
        chromium_ok = not self.want_firefox and here.product == "Chromium";
        if firefox_ok or chromium_ok {
            self.selected_lane = here.tag();
            disengage;
        }
    }
}

walker GuestNameAuditor {
    has terminal: str = "pending";
    has repairs_used: int = 0;
    has max_repairs: int = 1;
    has max_attempts: int = 3;

    can start with Root entry {
        visit [->:PrejoinStage:->] else { disengage; }
    }

    can try_entry with GuestNameField entry {
        if here.attempt_index > self.max_attempts {
            self.terminal = "name_entry_exhausted";
            disengage;
        }
        here.apply_write();
        if here.needs_repair and self.repairs_used < self.max_repairs {
            self.repairs_used += 1;
            here.repair_once();
        }
        verified = here.verify_twice();
        if verified {
            here.settled = True;
            self.terminal = "join_enabled";
            disengage;
        } else {
            visit [->:PrejoinStage:->] else {
                self.terminal = "name_entry_failed";
                disengage;
            }
        }
    }
}

walker PolicyClassifier {
    has required_clauses: int = 3;
    has matched_clauses: int = 0;
    has verdict: str = "clear";

    can start with Root entry {
        visit [-->];
    }

    can scan with MeetingRoom entry {
        count = 0;
        frontier = [here ->:RtmsLink:->];
        while len(frontier) > 0 {
            upcoming = [];
            for clause_node in frontier {
                if clause_node.detected {
                    count += 1;
                }
                upcoming += [clause_node ->:RtmsLink:->];
            }
            frontier = upcoming;
        }
        self.matched_clauses = count;
        if count >= self.required_clauses {
            self.verdict = "rtms_policy_wall";
        } else {
            partial_label = "partial_signals" if count > 0 else "no_policy_wall";
            self.verdict = partial_label;
        }
    }
}

walker TeardownGuard {
    has violations: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with JoinSession entry {
        if here.teardown_reported and not here.bot_left {
            self.violations += 1;
            print(f"invalid teardown before leave on session admission={here.admission}");
        }
        visit [-->];
    }
}

walker StatusReporter {
    can start with Root entry {
        visit [-->];
    }

    can describe with MeetingRoom | BrowserLane entry {
        entity_tag = here.tag();
        print(f"join graph entity {entity_tag}");
        visit [-->];
    }

    can hop with JoinProfile entry {
        visit [-->];
    }
}

with entry {
    profile = JoinProfile(
        profile_name="unsigned_guest",
        unsigned_guest=True,
        authenticated=False
    );
    meeting = MeetingRoom(
        label="protected_legacy",
        platform="zoom",
        protected_room=True
    );
    chromium = BrowserLane(
        product="Chromium",
        generation=141,
        playwright="1.56.0",
        revision="1122",
        stock_image=True
    );
    firefox = BrowserLane(
        product="Firefox",
        generation=151,
        playwright="1.61.1",
        revision="1532",
        stock_image=True
    );
    guest_try1 = GuestNameField(
        target_name="Elena Costa",
        attempt_index=1,
        needs_repair=True
    );
    guest_try2 = GuestNameField(
        target_name="Elena Costa",
        attempt_index=2,
        needs_repair=False
    );
    clause_bot = RtmsClause(clause_text="detected a bot", detected=True);
    clause_auto = RtmsClause(
        clause_text="automated bots are not allowed",
        detected=True
    );
    clause_rtms = RtmsClause(clause_text="use Zoom RTMS", detected=True);
    bad_session = JoinSession(
        admission="blocked",
        bot_left=False,
        teardown_reported=True
    );
    good_session = JoinSession(
        admission="admitted",
        bot_left=True,
        teardown_reported=True
    );

    root ++> profile;
    profile +>:PlatformTarget:+> meeting;
    meeting +>:CandidateLane:+> chromium;
    meeting +>:CandidateLane:+> firefox;
    meeting +>:PrejoinStage(order=1):+> guest_try1;
    guest_try1 +>:PrejoinStage(order=2):+> guest_try2;
    meeting +>:RtmsLink:+> clause_bot;
    clause_bot +>:RtmsLink:+> clause_auto;
    clause_auto +>:RtmsLink:+> clause_rtms;
    profile +>:SessionFor:+> bad_session;
    profile +>:SessionFor:+> good_session;

    router = LaneRouter();
    root spawn router;
    print(f"lane router selected {router.selected_lane}");

    reporter = StatusReporter();
    root spawn reporter;

    auditor = GuestNameAuditor();
    root spawn auditor;
    print(f"guest name auditor terminal {auditor.terminal}");

    classifier = PolicyClassifier();
    root spawn classifier;
    print(f"policy classifier verdict {classifier.verdict}");

    guard = TeardownGuard();
    root spawn guard;
    print(f"teardown guard violations {guard.violations}");
}
