```jac
"""Fuel-cost model future hardening: mutual-recursion cycle diagnostics.

Models the M3 follow-up scenario natively:
- Function-like nodes represent callers/callees that declare a fuel bound.
- A typed ``Calls`` edge records the static call-site relationship.
- A walker traverses the call graph, accumulates declared bounds, and
  detects mutual-recursion cycles that the over-approximating cost model
  charges only one level deep — exactly the diagnostic gap described in
  issue #267 section 1.

The walker uses an explicit visited set (Jac walkers have no built-in
cycle guard) and emits a ``recursive call``-style report for every cycle it
discovers, plus an aggregate total fuel for the reachable call subgraph.
"""

node Routine {
    has name: str = "";
    has declared_bound: int = 0;
    has visited: bool = False;
}

edge Calls {
    has call_site: str = "static";
}

walker FuelAuditor {
    has path_stack: list[str] = [];
    has total_fuel: int = 0;
    has cycles_found: int = 0;

    can start with Root entry {
        print("Fuel auditor starting; bound model = declared-cost over Calls edges");
        visit [-->];
    }

    can audit with Routine entry {
        if here.visited {
            # Re-entry means a cycle; charge declared bound of the callee
            # (the broken one-level-deep model) and report.
            cycle = self.path_stack + [here.name];
            # Distinguish self (here.name is on top of stack) from mutual
            # (here.name appears earlier in stack but not at top).
            occurrences = len([n for n in self.path_stack if n == here.name]);
            is_self = (occurrences >= 1) and (self.path_stack[-1] == here.name);
            label = "self" if is_self else "a->b->a";
            self.cycles_found += 1;
            print(f"[CYCLE {label}] {cycle} — declared bound {here.declared_bound} "
                  f"charged once instead of walked");
            self.total_fuel += here.declared_bound;
            disengage;
        }
        here.visited = True;
        self.path_stack.append(here.name);
        self.total_fuel += here.declared_bound;
        print(f"[enter] {here.name} (declared bound +{here.declared_bound})");
        visit [->:Calls:->];
        self.path_stack.pop();
    }
}

with entry {
    # Build a tiny call graph with a mutual-recursion cycle:
    #   main -> A -> B -> A   (mutual cycle between A and B)
    #   main -> leaf          (acyclic leaf, charged correctly)
    main = Routine(name="main", declared_bound=1);
    a_node = Routine(name="A", declared_bound=5);
    b_node = Routine(name="B", declared_bound=7);
    leaf = Routine(name="leaf", declared_bound=2);

    root ++> main;
    main +>:Calls(call_site="main->A"):+> a_node;
    main +>:Calls(call_site="main->leaf"):+> leaf;
    a_node +>:Calls(call_site="A->B"):+> b_node;
    b_node +>:Calls(call_site="B->A"):+> a_node;

    auditor = FuelAuditor();
    root spawn auditor;

    print(f"cycles detected: {auditor.cycles_found}");
    print(f"total fuel charged (declared-bound model): {auditor.total_fuel}");
}
