```jac
"""x402-doctor: conformance walker over a protected resource graph.

Models the essential scenario from x402-foundation/x402 issue #3104:
a protected resource advertises a Bazaar discovery record, and the
doctor walker traverses the (Resource -> Bazaar record -> declared
crawler request) chain to verify that the live v2 challenge, the
indexed declaration, and the extension responses all agree.
"""

node Resource {
    has title: str = "";
    has url: str = "";
    has live_challenge_digest: str = "";
    has challenge_valid: bool = False;
    has crawler_request_status: int = 0;
}

node BazaarRecord {
    has resource_id: str = "";
    has declared_digest: str = "";
    has declared_input_url: str = "";
    has examples_valid: bool = False;
    has schema_valid: bool = False;
}

node ExtensionResponse {
    has extension_name: str = "";
    has visible: bool = False;
    has response_status: int = 0;
}

node Finding {
    has severity: str = "info";
    has code: str = "";
    has message: str = "";
}

edge Declares { }
edge CrawlsTo { }
edge ReportsExtension { }
edge Emits { }

walker Doctor {
    has findings: list = [];

    can start with Root entry {
        visit [->:Declares:->] else {
            disengage;
        }
    }

    can audit_resource with Resource entry {
        if not here.challenge_valid {
            f = Finding(severity="error", code="CHALLENGE_INVALID",
                    message=f"resource {here.title} did not return a valid v2 PAYMENT-REQUIRED challenge");
            self.findings.append(f);
            print(f"[{f.severity}] {f.code}: {f.message}");
        }
        if here.crawler_request_status != 402 {
            f = Finding(severity="error", code="CRAWLER_NOT_402",
                    message=f"declared crawler request returned {here.crawler_request_status} instead of 402 for {here.title}");
            self.findings.append(f);
            print(f"[{f.severity}] {f.code}: {f.message}");
        }
        visit [here->:Declares:->];
    }

    can audit_record with BazaarRecord entry {
        if not here.examples_valid {
            f = Finding(severity="error", code="BAZAAR_EXAMPLES_INVALID",
                    message=f"Bazaar record for {here.resource_id} has invalid examples");
            self.findings.append(f);
            print(f"[{f.severity}] {f.code}: {f.message}");
        }
        if not here.schema_valid {
            f = Finding(severity="error", code="BAZAAR_SCHEMA_INVALID",
                    message=f"Bazaar record for {here.resource_id} fails JSON Schema");
            self.findings.append(f);
            print(f"[{f.severity}] {f.code}: {f.message}");
        }
        visit [here->:CrawlsTo:->];
    }

    can check_extensions with ExtensionResponse entry {
        if here.extension_name == "bazaar" and not here.visible {
            f = Finding(severity="warning", code="EXTENSION_RESPONSES_HIDDEN",
                    message=f"EXTENSION-RESPONSES not observable for {here.extension_name}");
            self.findings.append(f);
            print(f"[{f.severity}] {f.code}: {f.message}");
        }
        visit [-->];
    }
}

walker DigestCompare {
    has live_digest: str = "";
    has indexed_digest: str = "";
    has matches: bool = False;

    can start with Root entry {
        visit [->:Declares:->] else {
            disengage;
        }
    }

    can compare with Resource entry {
        self.live_digest = here.live_challenge_digest;
        visit [here->:Declares:->] else {
            disengage;
        }
    }

    can decide with BazaarRecord entry {
        self.indexed_digest = here.declared_digest;
        self.matches = self.live_digest == self.indexed_digest;
    }
}

