"""FCMP++ curve-tree hash dependency review.

Models the security review's central concern: a curve-tree primitive that
depends on upstream generator constants (Helios/Selene hash inits and
generator sets) drawn from a git revision that a maintainer says is
superseded. The walker audits the dependency chain the way the issue
walks it: from the pinned Cargo rev, through the load-bearing constants,
to the FFI entry points and the sole unit test caller.
"""

# A pinned upstream git revision. The whole review turns on this value.
node CargoRev {
    has rev: str = "";
    has is_superseded: bool = False;
}

# Load-bearing constants the curve-tree hash is defined by.
node Constant {
    has name: str = "";
    has value_kind: str = "";
    has source: str = "";
}

# A Rust FFI entry point that pulls one or more constants.
node FfiEntry {
    has fn_name: str = "";
}

# A factory that wires concrete curves into the test surface.
node CurveTreesV1 {
    has label: str = "curve_trees_v1()";
}

# The C++ side: the abstract Curve and its concrete subclasses.
node CurveBase {
    has kind: str = "abstract";
}

node Selene {
    has kind: str = "Selene";
}

node Helios {
    has kind: str = "Helios";
}

# The unit test that is the sole caller of the whole new surface.
node UnitTest {
    has path: str = "tests/unit_tests/curve_trees.cpp";
    has line: int = 0;
}

# Typed edges carry the line-number metadata the reviewer cited.
edge DependsOn {
    has at_line: int = 0;
}

edge Exposes {
    has symbol: str = "";
}

edge Instantiates {
    has width: int = 0;
}

edge Invokes {
    has call_site: str = "";
}

edge TestedBy {
    has line: int = 0;
}

walker DependencyAuditor {
    has findings: list = [];
    has seen: list = [];

    def summarize() {
        print(f"audit complete with {len(self.findings)} finding(s)");
    }

    can start with Root entry {
        print("Auditing FCMP++ curve-tree hash dependency chain");
        visit [-->] else { self.summarize(); disengage; }
    }

    can audit_rev with CargoRev entry {
        if here in self.seen {
            self.summarize();
            disengage;
        } else {
            self.seen.append(here);
            tag = "SUPERSEDED" if here.is_superseded else "CURRENT";
            print(f"[CargoRev {tag}] {here.rev}");
            self.findings.append(f"pinned upstream rev {here.rev} is {tag.lower()}");
            visit [-->] else { self.summarize(); disengage; }
        }
    }

    can audit_constant with Constant entry {
        if here in self.seen {
            self.summarize();
            disengage;
        } else {
            self.seen.append(here);
            print(f"  constant {here.name} ({here.value_kind}) <- {here.source}");
            visit [-->] else { self.summarize(); disengage; }
        }
    }

    can audit_ffi with FfiEntry entry {
        if here in self.seen {
            self.summarize();
            disengage;
        } else {
            self.seen.append(here);
            print(f"  ffi entry {here.fn_name}");
            visit [-->] else { self.summarize(); disengage; }
        }
    }

    can audit_factory with CurveTreesV1 entry {
        if here in self.seen {
            self.summarize();
            disengage;
        } else {
            self.seen.append(here);
            print(f"factory {here.label}");
            visit [-->] else { self.summarize(); disengage; }
        }
    }

    can audit_curve with CurveBase | Selene | Helios entry {
        if here in self.seen {
            self.summarize();
            disengage;
        } else {
            self.seen.append(here);
            print(f"  curve class: {here.kind}");
            visit [-->] else { self.summarize(); disengage; }
        }
    }

    can audit_test with UnitTest entry {
        if here in self.seen {
            self.summarize();
            disengage;
        } else {
            self.seen.append(here);
            print(f"sole caller: {here.path}:{here.line}");
            visit [-->] else { self.summarize(); disengage; }
        }
    }
}

with entry {
    # The pinned upstream rev the reviewer is worried about.
    pinned_rev = CargoRev(
        rev="71da8f03a87f596db674258cda74553068a57bcd",
        is_superseded=True
    );

    # The four load-bearing constants that define the curve-tree hash.
    helios_hash_init = Constant(
        name="HELIOS_HASH_INIT",
        value_kind="hash_init",
        source="monero-fcmp-plus-plus"
    );
    selene_hash_init = Constant(
        name="SELENE_HASH_INIT",
        value_kind="hash_init",
        source="monero-fcmp-plus-plus"
    );
    helios_gens = Constant(
        name="HELIOS_FCMP_GENERATORS.generators",
        value_kind="generators",
        source="monero-fcmp-plus-plus-generators"
    );
    selene_gens = Constant(
        name="SELENE_FCMP_GENERATORS.generators",
        value_kind="generators",
        source="monero-fcmp-plus-plus-generators"
    );

    # Two of the ten new FFI entry points cited in the review.
    hash_grow = FfiEntry(fn_name="hash_grow");
    curve_trees_v1_factory = CurveTreesV1(label="curve_trees_v1()");

    # The C++ class hierarchy: abstract Curve and concrete subclasses.
    abstract_curve = CurveBase(kind="abstract");
    selene = Selene(kind="Selene");
    helios = Helios(kind="Helios");

    # The sole caller: the new unit test at curve_trees.cpp:57.
    test_node = UnitTest(path="tests/unit_tests/curve_trees.cpp", line=57);

    # Wire the dependency graph the way the reviewer traced it.
    root ++> pinned_rev
        ++> helios_hash_init
        ++> selene_hash_init
        ++> helios_gens
        ++> selene_gens
        ++> hash_grow
        ++> curve_trees_v1_factory
        ++> abstract_curve
        ++> selene
        ++> helios
        ++> test_node;

    # Typed edges where the relationship carries meaning.
    hash_grow +>:DependsOn(at_line=178):+> helios_hash_init;
    hash_grow +>:DependsOn(at_line=184):+> selene_hash_init;
    hash_grow +>:DependsOn(at_line=209):+> helios_gens;
    hash_grow +>:DependsOn(at_line=215):+> selene_gens;
    hash_grow +>:Exposes(symbol="hash_grow"):+> abstract_curve;
    curve_trees_v1_factory +>:Instantiates(width=2):+> selene;
    curve_trees_v1_factory +>:Instantiates(width=2):+> helios;
    curve_trees_v1_factory +>:Invokes(call_site="curve_trees_v1"):+> hash_grow;
    test_node +>:TestedBy(line=57):+> curve_trees_v1_factory;

    auditor = DependencyAuditor();
    root spawn auditor;
}
