```jac
"""Release-cut traceability: model a project's release line as commit and tag
nodes, then walk the commit graph to decide whether a motivating fix is already
enclosed by an existing release tag."""

node Commit {
    has sha: str = "";
    has summary: str = "";
    has is_fix: bool = False;
}

node Tag {
    has label: str = "";
    has date: str = "";
    has version: str = "";
}

edge ParentOf {
    has order: int = 0;
}

edge Cuts {
    has version: str = "";
}

walker ReleaseAuditor {
    has visited: list[str] = [];
    has fix_sha: str = "";
    has found_in_tag: str = "";
    has tag_version: str = "";
    has tag_date: str = "";
    has cut_sha: str = "";
    has remaining: int = 0;
    has reported: bool = False;

    def finish() {
        if self.reported == False {
            self.reported = True;
            if self.fix_sha != "" and self.tag_version != "" {
                fix_pos = -1;
                cut_pos = -1;
                pos = 0;
                for sha in self.visited {
                    if sha == self.fix_sha {
                        fix_pos = pos;
                    }
                    if sha == self.cut_sha {
                        cut_pos = pos;
                    }
                    pos += 1;
                }
                verdict = "CONTAINED" if fix_pos >= 0 and cut_pos >= fix_pos else "MISSING";
                self.found_in_tag = verdict;
                print(f"  tag {self.tag_version} ({self.tag_date}): fix {verdict}");
            }
            print(f"audit complete: {len(self.visited)} commits traversed");
            if self.found_in_tag == "MISSING" {
                print("RECOMMENDATION: cut a new release on the Scala 3 line");
            } elif self.found_in_tag == "CONTAINED" {
                print("fix already shipped in a tagged release");
            } else {
                print("no motivating fix located");
            }
        }
    }

    can launch with Root entry {
        self.remaining = len([here-->]);
        visit [-->]
        else {
            self.finish();
        }
    }

    can inspect_tag with Tag entry {
        self.remaining = self.remaining - 1;
        self.tag_version = here.version;
        self.tag_date = here.date;
        for target in [here ->:Cuts:->] {
            self.cut_sha = target.sha;
        }
        if self.remaining == 0 {
            self.finish();
        }
    }

    can scan with Commit entry {
        self.remaining = self.remaining - 1;
        if here.sha in self.visited {
            if self.remaining == 0 {
                self.finish();
            }
        } else {
            self.visited.append(here.sha);
            if here.is_fix and self.fix_sha == "" {
                self.fix_sha = here.sha;
                print(f"  found motivating fix: {here.sha} — {here.summary}");
            }
            self.remaining = self.remaining + len([here-->]);
            visit [-->]
            else {
                if self.remaining == 0 {
                    self.finish();
                }
            }
        }
    }
}

with entry {
    head = Commit(sha="HEAD", summary="HEAD snapshot");
    c1 = Commit(sha="c0001", summary="docs: tidy");
    c2 = Commit(sha="c0002", summary="perf(macros): reduce redundant implicit searches in ctx.run() pipeline", is_fix=True);
    c3 = Commit(sha="c0003", summary="ci: bump sbt");
    c4 = Commit(sha="c0004", summary="refactor: split encoder");
    v486 = Tag(label="v4.8.6", date="2024-10-30", version="4.8.6");

    root ++> v486;
    root ++> head;
    head +>:ParentOf(order=1):+> c1;
    c1 +>:ParentOf(order=2):+> c2;
    c2 +>:ParentOf(order=3):+> c3;
    c3 +>:ParentOf(order=4):+> c4;

    print("release audit: zio-protoquill Scala 3 line");
    print("------------------------------------------");
    root spawn ReleaseAuditor();
}
