```jac
"""Grading run: typed reports declared right on the walker.

Declaring `has reports: list[int]` makes every `report` statement
type-checked, so a stray string score fails at compile time instead
of polluting results. The grader collects each score it walks into
`collected`, applies a small class curve, and prints the collected
list plus the class average whenever a visit runs out of frontier.
"""

node Quiz {
    has student: str = "";
    has score: int = 0;
}

walker Grader {
    # Typed reports: only int values may be reported from this walker.
    has reports: list[int] = [];
    has collected: list[int] = [];
    has graded: int = 0;
    has total: int = 0;
    has curve: float = 5.75;

    can start with Root entry {
        visit [-->]
        else {
            average = (self.total / self.graded + self.curve) if self.graded else 0;
            print(f"Graded {self.collected}");
            print(f"Class average: {average:.1f}");
            disengage;
        }
    }

    can grade with Quiz entry {
        report here.score;
        self.collected.append(here.score);
        self.graded += 1;
        self.total += here.score;
        visit [-->]
        else {
            average = (self.total / self.graded + self.curve) if self.graded else 0;
            print(f"Graded {self.collected}");
            print(f"Class average: {average:.1f}");
        }
    }
}

with entry {
    root ++> Quiz(student="Ana", score=92)
        ++> Quiz(student="Ben", score=78)
        ++> Quiz(student="Chloe", score=88)
        ++> Quiz(student="Dev", score=95);

    root spawn Grader();
}
