    root ++> Order(label="ORD-001", amount=120.50, valid=True)
        ++> Order(label="ORD-002", amount=75.00, valid=False)
        ++> Order(label="ORD-003", amount=999.99, valid=True, fraud=True)
        ++> Order(label="ORD-004", amount=42.10, valid=True);

    root spawn OrderAuditor();
}
