```jac
"""Order auditor with two flavors of early return: skip (continue) vs halt (disengage).

Orders are nodes carrying an amount, a validity flag, and a fraud flag.
- An invalid (valid=False) order is *skipped* — the audit keeps walking
  through later orders.
- A fraud-flagged order *halts* the whole walk immediately via
  ``disengage;``.

The walker traverses the order chain using ``visit [-->]`` and reports
which action fired for each node it actually inspects.
"""

node Order {
    has order_id: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud_flag: bool = False;
}

walker OrderAuditor {
    has audited_count: int = 0;
    has skipped_count: int = 0;
    has halted: bool = False;

    can begin with Root entry {
        print(f"Auditor starting walk over order chain");
        visit [-->];
    }

    can audit with Order entry {
        # Fraud short-circuits the entire walk.
        if here.fraud_flag {
            self.halted = True;
            print(f"[HALT]  order={here.order_id} amount={here.amount} fraud flagged");
            disengage;
        } elif not here.valid {
            # Invalid orders are skipped; traversal continues to next order.
            self.skipped_count += 1;
            print(f"[SKIP]  order={here.order_id} amount={here.amount} invalid");
            visit [-->];
        } else {
            self.audited_count += 1;
            print(f"[AUDIT] order={here.order_id} amount={here.amount}");
            visit [-->];
        }
    }
}

with entry {
    root ++> Order(order_id="A-001", amount=120.50, valid=True)
        ++> Order(order_id="A-002", amount=45.00, valid=False)
        ++> Order(order_id="A-003", amount=999.99, valid=True, fraud_flag=True)
        ++> Order(order_id="A-004", amount=15.00, valid=True);

    auditor = OrderAuditor();
    root spawn auditor;

    if auditor.halted {
        print(f"Walk halted after auditing={auditor.audited_count}, "
              f"skipped={auditor.skipped_count}");
    } else {
        print(f"Walk completed: audited={auditor.audited_count}, "
              f"skipped={auditor.skipped_count}");
    }
}
