```jac
"""Neighborhood buddies: mutual friendship links proven both ways.

`House` nodes are homes and `Buddy` edges are friendships. Because
friendship is mutual, ONE statement -- `a <+: Buddy() :+> b` -- wires
the link in both directions at once. To prove the link really points
both ways, a `Greeter` walker is spawned at each of the two houses and
traverses forward only (`visit [-->];`). Each greeter steps onto its
own starting home WITHOUT greeting it, crosses the buddy edge, and
greets the other owner exactly once. The `seen` list guards against
bouncing back and forth across the bidirectional edge forever, while
`met` records only the houses actually greeted.
"""

node House {
    has owner: str = "";
}

edge Buddy {
    has since: int = 2021;
}

walker Greeter {
    has who: str = "";
    has met: list[str] = [];
    has seen: list[str] = [];
    has first: bool = True;
    has reports: list[str] = [];

    can greet with House entry {
        if here.owner in self.seen {
            disengage;
        }
        self.seen.append(here.owner);
        if self.first {
            self.first = False;
        } else {
            self.met.append(here.owner);
            print(f"{self.who} waves hello to {here.owner}'s house");
            report here.owner;
        }
        visit [-->];
    }
}

with entry {
    ana_house = House(owner="Ana");
    leo_house = House(owner="Leo");

    root ++> ana_house;
    root ++> leo_house;

    # One statement creates BOTH Ana->Leo and Leo->Ana buddy edges.
    ana_house <+: Buddy(since=2023) :+> leo_house;

    ana_side = ana_house spawn Greeter(who="Ana");
    leo_side = leo_house spawn Greeter(who="Leo");

    print(f"Ana greeted: {ana_side.reports}");
    print(f"Leo greeted: {leo_side.reports}");
}
```

