```jac
"""Mutual friendships in a neighborhood: houses linked by bidirectional buddy edges."""

node House {
    has name: str = "";
    has occupant: str = "";
}

edge Buddy {
    has since: int = 2024;
}

walker Greeter {
    has seen: list[str] = [];

    can greet with House entry {
        if here.name in self.seen {
            disengage;
        }
        self.seen.append(here.name);
        print(f"  Greeter visited {here.name} (home of {here.occupant})");
        buddies = [here ->:Buddy:->];
        for nxt in buddies {
            if nxt.name not in self.seen {
                visit [nxt];
            }
        }
    }
}

with entry {
    alice_house = House(name="Alice's House", occupant="Alice");
    bob_house = House(name="Bob's House", occupant="Bob");
    carol_house = House(name="Carol's House", occupant="Carol");

    alice_house +>:Buddy:+> bob_house;
    bob_house +>:Buddy:+> alice_house;
    bob_house +>:Buddy:+> carol_house;
    carol_house +>:Buddy:+> bob_house;
    alice_house +>:Buddy:+> carol_house;
    carol_house +>:Buddy:+> alice_house;

    root ++> alice_house;

    print("From Alice's House:");
    root spawn Greeter();

    print("From Bob's House:");
    bob_house spawn Greeter();
}
