"""Road-trip playlist: chain three tracks off the root and have a player walker play them in order, printing now-playing lines and the running total runtime."""

node Track {
    has title: str = "";
    has artist: str = "";
    has runtime: int = 0;
}

walker Player {
    has total_runtime: int = 0;

    can start with Root entry {
        print("Kicking off the road-trip playlist...");
        visit [-->];
    }

    can play with Track entry {
        self.total_runtime = self.total_runtime + here.runtime;
        print(f"Now playing: {here.title} by {here.artist} [{here.runtime} min] | runtime so far: {self.total_runtime} min");
        visit [-->];
    }

    can wrap with Root exit {
        print(f"End of queue. Total runtime: {self.total_runtime} min");
        disengage;
    }
}

with entry {
    (root ++> Track(title="Life is a Highway", artist="Red Hot Chili Peppers", runtime=267)
        ++> Track(title="Take It Easy", artist="Eagles", runtime=212)
        ++> Track(title="Born to Run", artist="Bruce Springsteen", runtime=270));
    root spawn Player();
}
