```jac
"""Gallery security console.

Every visitor triggers a generic room log; a curator adds an official
inspection record under their name and counts rooms inspected. The
difference between a tourist and a curator is shown by running one of
each through two rooms.
"""

node Room {
    has name: str = "";

    # Generic entry log: fires for ANY visitor walker archetype.
    can log_entry with VisitorWalker entry {
        print(f"[log] {visitor.kind} entered {self.name}");
        visitor.rooms_visited += 1;
    }

    # Curator-specific inspection: fires ONLY when the visitor walker
    # is a Curator (a VisitorWalker subtype).
    can record_inspection with Curator entry {
        visitor.inspections += 1;
        print(f"[inspection] {visitor.name} inspected {self.name} "
              f"(#{visitor.inspections})");
    }
}

walker VisitorWalker {
    has kind: str = "Visitor";
    has name: str = "guest";
    has rooms_visited: int = 0;
    has inspections: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can walk with Room entry {
        visit [-->];
    }
}

walker Tourist(VisitorWalker) {
    has kind: str = "Tourist";
}

walker Curator(VisitorWalker) {
    has kind: str = "Curator";
}

with entry {
    gallery_a = Room(name="Gallery A");
    gallery_b = Room(name="Gallery B");
    root ++> gallery_a ++> gallery_b;

    print("--- Tourist walk ---");
    tourist = Tourist(name="Alex");
    root spawn tourist;

    print("--- Curator walk ---");
    curator = Curator(name="Dr. Bell");
    root spawn curator;

    print(f"Summary: tourist visited {tourist.rooms_visited} rooms with "
          f"{tourist.inspections} inspections; curator visited "
          f"{curator.rooms_visited} rooms with "
          f"{curator.inspections} inspections.");
}
