"""Hotel charges: guests walk past service desks and each desk charges the guest at checkout."""

node Guest {
    has name: str = "";
    has total: float = 0.0;
    has open_tab: bool = False;
    has closed_tab: bool = False;
}

node Service {
    has service_name: str = "";
    has price: float = 0.0;
    has owner_name: str = "";
}

walker TagOwner {
    has owner: str = "";
    has started: bool = False;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can at_guest with Guest entry {
        if self.started {
            disengage;
        } else {
            self.started = True;
            visit [-->];
        }
    }

    can tag with Service entry {
        if here.owner_name == "" {
            here.owner_name = self.owner;
        }
        visit [-->];
    }
}

walker ChargeWalker {
    has tabs: dict = {};

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can guest_stop with Guest entry {
        if not here.open_tab and not here.closed_tab {
            here.open_tab = True;
            self.tabs[here.name] = here.total;
            print(f"Guest {here.name} begins checkout");
            here spawn TagOwner(owner=here.name);
            visit [-->];
        } else {
            if here.open_tab {
                here.open_tab = False;
                here.closed_tab = True;
                here.total = self.tabs[here.name];
                print(f"Checkout: {here.name} owes ${here.total}");
            }
        }
    }

    can charge with Service entry {
        self.tabs[here.owner_name] = self.tabs[here.owner_name] + here.price;
        print(f"  + {here.service_name} (${here.price}) -> running total ${self.tabs[here.owner_name]}");
        visit [-->];
    }
}

with entry {
    alice = Guest(name="Alice");
    bob = Guest(name="Bob");

    spa = Service(service_name="Spa Session", price=80.0);
    dinner = Service(service_name="Room-Service Dinner", price=45.0);
    laundry = Service(service_name="Express Laundry", price=25.0);
    bob_laundry = Service(service_name="Express Laundry", price=25.0);

    root ++> alice;
    alice ++> spa;
    spa ++> dinner;
    dinner ++> laundry;
    laundry ++> alice;

    root ++> bob;
    bob ++> bob_laundry;
    bob_laundry ++> bob;

    root spawn ChargeWalker();
}
