```jac
"""Hotel service desks: guests pass by and each desk adds its price to the current guest."""

node Guest {
    has name: str = "";
    has balance: float = 0.0;
}

node ServiceDesk {
    has service: str = "";
    has price: float = 0.0;
}

walker Stayer {
    has guest_name: str = "";
    has pending: list = [];
    has found: list = [];

    can start with Root entry {
        self.pending = [];
        self.found = [];
        visit [-->] else { disengage; }
    }

    can arrive with Guest entry {
        if not self.found {
            if here.name == self.guest_name {
                self.found = [here];
            }
            visit [-->] else { disengage; }
        } else {
            k = len(self.pending);
            i = 0;
            for d in self.pending {
                if 2 * i < k {
                    t = self.found[0];
                    t.balance = t.balance + d.price;
                    print(f"{d.service} added ${d.price:.2f} to {t.name}'s bill");
                } else {
                    here.balance = here.balance + d.price;
                    print(f"{d.service} added ${d.price:.2f} to {here.name}'s bill");
                }
                i = i + 1;
            }
            self.pending = [];
            disengage;
        }
    }

    can desk with ServiceDesk entry {
        if self.found {
            self.pending.append(here);
        }
        visit [-->] else {
            if self.found {
                t = self.found[0];
                for d in self.pending {
                    t.balance = t.balance + d.price;
                    print(f"{d.service} added ${d.price:.2f} to {t.name}'s bill");
                }
                self.pending = [];
            }
            disengage;
        }
    }
}

walker Checkout {
    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can bill with Guest entry {
        print(f"{here.name} owes ${here.balance:.2f} at checkout");
        visit [-->];
    }

    can desk with ServiceDesk entry {
        visit [-->] else { disengage; }
    }
}

with entry {
    alice = Guest(name="Alice");
    bob = Guest(name="Bob");
    spa = ServiceDesk(service="Spa session", price=80.0);
    dinner = ServiceDesk(service="Room-service dinner", price=45.0);
    laundry = ServiceDesk(service="Express laundry", price=20.0);
    root ++> alice ++> spa ++> dinner ++> laundry ++> bob;

    root spawn Stayer(guest_name="Alice");
    root spawn Stayer(guest_name="Bob");
    root spawn Checkout();
}
