"""Warehouse packing line: stations announce their serving robot and robots
announce each station they stop at; tally stops per robot and boxes per station."""

node Station {
    has name: str = "";
    has boxes_packed: int = 0;
}

node Robot {
    has name: str = "";
    has stops: int = 0;
    has announced: str = "";
}

edge Serves {
    has announced: str = "";
}

walker Announcer {
    has robot_name: str = "";
    has served_any: bool = False;

    can start with Root entry {
        print(f"Broadcasting service on the packing line");
        visit [-->];
    }

    can greet_station with Station entry {
        if len([here ->:Serves:->]) == 0 {
            allowed = not self.served_any;
            if not allowed {
                for prev in [here <--] {
                    bots = [prev ->:Serves:->];
                    if len(bots) > 0 and bots[0].name == self.robot_name {
                        allowed = True;
                    }
                }
            }
            if allowed {
                announcement = f"{self.robot_name} now serving {here.name}";
                here +>:Serves(announced=announcement):+> Robot(name=self.robot_name, announced=announcement);
                here.boxes_packed += 1;
                self.served_any = True;
                print(announcement);
            }
        }
        visit [-->] else { disengage; }
    }
}

walker Tally {
    can start with Root entry {
        print("Tallying stops and packed boxes");
        visit [-->];
    }

    can count_robot with Robot entry {
        here.stops += 1;
        print(f"{here.name} made a stop (total stops: {here.stops})");
        visit [-->];
    }

    can report_station with Station entry {
        print(f"{here.name} packed {here.boxes_packed} boxes");
        visit [-->];
    }
}

with entry {
    station_a = Station(name="Pack-A");
    station_b = Station(name="Pack-B");
    station_c = Station(name="Pack-C");
    root ++> station_a ++> station_b ++> station_c;

    root spawn Announcer(robot_name="R2-D2");
    root spawn Tally();
}
