```jac
"""Warehouse packing line: stations announce the robot they serve, robots announce each station they stop at.

Each station keeps a tally of boxes packed, and each robot keeps a tally of stops it has made.
A single ``OrderAuditor`` walker traverses the line and triggers union abilities on stations
and robots. Because several distinct Robot nodes can share the same name (each announcement
edge creates its own node), the walker accumulates stop counts keyed by robot name so that
all of a robot's announced stops roll up into one tally.
"""

node Station {
    has name: str = "";
    has boxes_packed: int = 0;
}

node Robot {
    has name: str = "";
    has stops: int = 0;
}

# Edge carries the announcement payload: a station says "serving robot R"
# and a robot says "stopped at station S".
edge Serves { has robot_name: str = ""; }
edge StopsAt { has station_name: str = ""; }

walker OrderAuditor {
    # Per-name stop tally: many Robot nodes may share one name, so stops
    # are counted by name rather than per node instance.
    has stop_counts: dict[str, int] = {};

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    # Union trigger: fires for a Station OR a Robot as we walk the line.
    # Stations tally boxes packed; robots tally stops made (by name).
    can audit with Station | Robot entry {
        if isinstance(here, Station) {
            here.boxes_packed += 1;
            print(f"Station {here.name} packed a box (total {here.boxes_packed})");
        } else {
            if here.name in self.stop_counts {
                self.stop_counts[here.name] += 1;
            } else {
                self.stop_counts[here.name] = 1;
            }
            here.stops = self.stop_counts[here.name];
            print(f"Robot {here.name} made a stop (total {here.stops})");
        }
        visit [-->];
    }
}

with entry {
    # Build the three-station line: root -> S1 -> S2 -> S3.
    s1 = Station(name="S1");
    s2 = Station(name="S2");
    s3 = Station(name="S3");
    root ++> s1 ++> s2 ++> s3;

    # Robot R1 serves stations S1 and S2.
    s1 +>:Serves(robot_name="R1"):+> Robot(name="R1");
    s2 +>:Serves(robot_name="R1"):+> Robot(name="R1");

    # Robot R2 serves station S3.
    s3 +>:Serves(robot_name="R2"):+> Robot(name="R2");

    # Robots also announce their own stops back at the stations.
    s1 +>:StopsAt(station_name="S1"):+> Robot(name="R1");
    s2 +>:StopsAt(station_name="S2"):+> Robot(name="R1");
    s3 +>:StopsAt(station_name="S3"):+> Robot(name="R2");

    root spawn OrderAuditor();
}
