"""Warehouse packing-line audit: stations announce which robot they serve,
robots announce each station they stop at. Walks the line and tallies
stops-per-robot and boxes-per-station across a three-station line."""

node Station {
    has name: str = "";
    has robots_served: list[str] = [];
    has boxes_packed: int = 0;
}

node Robot {
    has name: str = "";
    has stations_visited: list[str] = [];
    has stops: int = 0;
}

walker StationAnnouncer {
    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can announce with Station entry {
        visit [-->];
        if len(here.robots_served) > 0 {
            print(f"[{here.name}] serving: {here.robots_served}");
        } else {
            print(f"[{here.name}] idle");
        }
    }
}

walker RobotAnnouncer {
    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can announce with Robot entry {
        visit [-->];
        print(f"[{here.name}] stops={here.stops} "
              f"stations={here.stations_visited}");
    }
}

walker LineAuditor {
    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can audit_station with Station entry {
        print(f"{here.name} packed {here.boxes_packed} box(es); "
              f"robots served: {here.robots_served}");
        visit [-->];
    }

    can audit_robot with Robot entry {
        print(f"{here.name} made {here.stops} stop(s); "
              f"stations visited: {here.stations_visited}");
        visit [-->];
    }
}

with entry {
    s1 = Station(name="Pack-1", robots_served=["R2", "R1"],
                 boxes_packed=3);
    s2 = Station(name="Pack-2", robots_served=["R1", "R3"],
                 boxes_packed=2);
    s3 = Station(name="Pack-3", robots_served=["R2"],
                 boxes_packed=1);

    r1 = Robot(name="R1", stations_visited=["Pack-1", "Pack-2"],
               stops=2);
    r2 = Robot(name="R2", stations_visited=["Pack-1", "Pack-3"],
               stops=2);
    r3 = Robot(name="R3", stations_visited=["Pack-2"], stops=1);

    root ++> s1 ++> s2 ++> s3;
    root ++> r1 ++> r2 ++> r3;

    print("=== Station announcements ===");
    root spawn StationAnnouncer();
    print("=== Robot announcements ===");
    root spawn RobotAnnouncer();
    print("=== Line audit ===");
    root spawn LineAuditor();
}
