"""Rental shop media shelf audit.

Books report title + author, DVDs report title + runtime, and any
unclassified media (e.g. an old archive reel) falls through to a default
handler. A single union ability handles books and DVDs by calling a
shared ``describe`` method on a common base node; a separate default
ability catches anything that doesn't match.
"""

node Media {
    has title: str = "";
    has available: bool = True;

    def describe() -> str {
        return self.title;
    }
}

node Book(Media) {
    has author: str = "";

    def describe() -> str {
        return f"{self.title} by {self.author}";
    }
}

node DVD(Media) {
    has runtime: int = 0;

    def describe() -> str {
        return f"{self.title} ({self.runtime} min)";
    }
}

node ArchiveReel(Media) {
    has format: str = "";
}

walker ShelfAuditor {
    has total: int = 0;
    has defaults: int = 0;

    def summarize() {
        print(f"Audit complete: {self.total} items, {self.defaults} needed the default path");
    }

    can start with Root entry {
