"""Factory zone patrol: walk temperature and smoke sensors, flagging out-of-range readings."""

node Sensor {
    has zone: str = "";
    has reading: float = 0.0;
    has kind: str = "temp";
    has limit: float = 75.0;
}

walker Patrol {
    has alerts: list = [];

    can begin with Root entry {
        print("Starting factory zone patrol...");
        visit [-->] else {
            here ++> Sensor(zone="Zone-A", reading=68.5, kind="temp", limit=75.0)
                ++> Sensor(zone="Zone-A", reading=82.0, kind="temp", limit=75.0)
                ++> Sensor(zone="Zone-A", reading=42.0, kind="smoke", limit=50.0)
                ++> Sensor(zone="Zone-B", reading=55.5, kind="smoke", limit=50.0)
                ++> Sensor(zone="Zone-B", reading=71.2, kind="temp", limit=75.0)
                ++> Sensor(zone="Zone-B", reading=90.0, kind="smoke", limit=50.0);
            visit [-->];
        }
    }

    can check with Sensor entry {
        flagged = here.reading > here.limit and (here.kind == "temp" or here.zone == "Zone-B");
        status = "ALERT" if flagged else "nominal";
        unit = "C" if here.kind == "temp" else "ppm";
        print(f"[{status}] {here.zone} {here.kind}: {here.reading} {unit} (limit {here.limit} {unit})");
        if flagged {
            self.alerts.append(f"{here.zone} {here.kind} {here.reading} {unit}");
        }
        visit [-->] else {
            print("");
            print("=== Patrol Summary ===");
            print(f"Total alerts: {len(self.alerts)}");
            for alert in self.alerts {
                print(f" - {alert}");
            }
            disengage;
        }
    }
}

with entry {
    root spawn Patrol();
}
