"""Game account moderation sweep.

Members are audited normally, admins get a reputation boost of +5, and the
welcome desk greets every walker that passes through regardless of which
staff member arrived — using a union trigger on the node side.
"""

node Account {
    has label: str = "";
    has reputation: int = 0;
}

node Member(Account) {
    has joined: int = 2020;
}

node Admin(Account) {
    has clearance: str = "low";
}

node Bot {
    has serial: str = "";
}

walker Moderator {
    has boost: int = 5;
    has seen_first_member: bool = False;
    has pending_members: list = [];

    can start with Root entry {
        print("Moderation sweep begins...");
        visit [-->];
    }

    can audit_account with Member entry {
        print(f"audit: {here.label} (rep={here.reputation})");
        if self.seen_first_member {
            self.pending_members.append(here);
        } else {
            self.seen_first_member = True;
        }
        visit [-->];
    }

    can boost_admin with Admin entry {
        here.reputation = here.reputation + self.boost;
        # Re-anchor the audited accounts directly under root so the sweep
        # leaves every account reachable from the top of the graph.
        root ++> here;
        for member in self.pending_members {
            root ++> member;
        }
        print(f"admin pass: {here.label} rep boosted to {here.reputation}");
        visit [-->];
    }

    can greet with Bot entry {
        print(f"welcome bot {here.serial}!");
        visit [-->];
    }
}

walker Greeter {
    can start with Root entry {
        print("Greeter is at the welcome desk.");
        visit [-->];
    }

    # The greeter does not audit accounts, but it still walks past member
    # and admin nodes so it can reach the bots deeper in the graph.
    can pass_through with Member | Admin entry {
        visit [-->];
    }

    can greet with Bot entry {
        print(f"hello, bot {here.serial}!");
        visit [-->];
    }
}

# A single union ability on the welcome desk handles every walker that
# arrives, so the desk greeting stays consistent regardless of which staff
# member passes by.
node WelcomeDesk {
    has reputation: int = 0;

    can greet_any with Moderator | Greeter entry {
        print("welcome desk greets the incoming visitor");
        visit [-->];
    }
}

with entry {
    root ++> Member(label="alice", joined=2021)
        ++> Member(label="bob", joined=2022)
        ++> Admin(label="carol", clearance="high")
        ++> Bot(serial="BX-001");

    desk = WelcomeDesk();
    root ++> desk ++> Bot(serial="BX-002");

    root spawn Moderator();
    print("---");
    root spawn Greeter();
}
