"""Wildlife park feeding rounds.

A tour-party walker triggers a kiosk greeting on every animal node,
zookeepers feed each animal its species-appropriate meal, and school
groups only watch the animals. Union triggers let one ability handle
both kinds of visitors without duplicating logic.
"""

node Animal {
    has species: str = "";
    has meal: str = "";
    has fed: bool = False;
}

node Lion {
    has species: str = "";
    has meal: str = "";
    has fed: bool = False;
}

node Parrot {
    has species: str = "";
    has meal: str = "";
    has fed: bool = False;
}

# A non-typed feeder walker that serves any animal its species meal.
walker Zookeeper {
    has meals_served: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can cross_kiosk with Kiosk entry {
        visit [-->];
    }

    can feed with Lion | Parrot | Animal entry {
        chosen_meal = "standard feed";
        if here.species == "African lion" {
            chosen_meal = "meat";
        } elif here.species == "Scarlet macaw" {
            chosen_meal = "seed";
        }
        here.meal = chosen_meal;
        here.fed = True;
        self.meals_served += 1;
        print(f"Zookeeper served {here.meal} to {here.species}");
        visit [-->];
    }
}

# The kiosk greets every tour party that walks past, regardless of who
# they are — zookeepers, school groups, anyone in the union. Tourists
# are not in the trigger union, so the kiosk stays silent for them.
node Kiosk {
    has greeting: str = "Welcome to the wildlife park!";

    can greet with Zookeeper | SchoolGroup entry {
        print(self.greeting);
    }
}

walker SchoolGroup {
    has animals_watched: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can cross_kiosk with Kiosk entry {
        visit [-->];
    }

    can watch with Lion | Parrot | Animal entry {
        self.animals_watched += 1;
        print(f"School group watches the {here.species}");
        visit [-->];
    }
}

# The simplest visitor: just walks the park. No output at all — the
# kiosk greeting does not fire for Tourist, and wander prints nothing.
walker Tourist {
    can start with Root entry {
        visit [-->];
    }

    can cross_kiosk with Kiosk entry {
        visit [-->];
    }

    can wander with Lion | Parrot | Animal entry {
        visit [-->];
    }
}

with entry {
    info = Kiosk();
    simba = Lion(species="African lion");
    polly = Parrot(species="Scarlet macaw");
    bunny = Animal(species="European rabbit");

    root ++> info ++> simba ++> polly ++> bunny;

    keeper = Zookeeper();
    root spawn keeper;

    students = SchoolGroup();
    root spawn students;

    visitor = Tourist();
    root spawn visitor;

    print(f"Zookeeper served {keeper.meals_served} meals; "
          f"school group watched {students.animals_watched} animals");
}
