"""Data center clearance walk: technicians traverse server rooms and are granted or denied per clearance level."""

node ServerRoom {
    has name: str = "";
    has required_level: int = 0;
}

node Corridor {
    has label: str = "";
}

walker Technician {
    has name: str = "Tech";
    has clearance: int = 0;
    has rooms_reached: int = 0;
    has denied_here: bool = False;
    has active: bool = True;

    def report_summary {
        final_count = self.rooms_reached;
        outcome = "DENIED mid-walk" if self.denied_here else "completed full walk";
        print(f"Technician {self.name} reached {final_count} room(s) ({outcome})");
    }

    can start with Root entry {
        print(f"Technician {self.name} (clearance {self.clearance}) begins walkthrough");
        visit [-->];
    }

    can enter_corridor with Corridor entry {
        if not self.active {
            disengage;
        }
        print(f"  Walking through corridor: {here.label}");
        visit [-->];
    }

    can check_room with ServerRoom entry {
        if not self.active {
            disengage;
        }
        if self.clearance >= here.required_level {
            self.rooms_reached += 1;
            print(f"  GRANTED [{self.clearance}>={here.required_level}] -> {here.name}");
            visit [-->];
        } else {
            self.denied_here = True;
            print(f"  DENIED  [{self.clearance}<{here.required_level}] -> {here.name} -- ending walk");
            self.active = False;
            self.report_summary();
            disengage;
        }
    }

    can summarize with exit {
        if self.active {
            self.report_summary();
        }
    }
}

walker Reporter {
    can start with Root entry {
        print("=== Clearance Walkthrough Report ===");
        visit [-->];
    }
}

with entry {
    root ++> Corridor(label="Outer Hall")
        ++> ServerRoom(name="Lobby Server Closet", required_level=1)
        ++> ServerRoom(name="Mail Server Room", required_level=2)
        ++> ServerRoom(name="App Server Room", required_level=3)
        ++> ServerRoom(name="DB Server Room", required_level=4)
        ++> ServerRoom(name="Root Datacenter", required_level=5);

    root spawn Technician(name="Alice", clearance=1);
    root spawn Technician(name="Bob", clearance=3);
    root spawn Technician(name="Carol", clearance=5);
}
