"""Data center clearance enforcement.

Each server room posts the clearance level required to enter. A technician
walks the corridor and is granted or denied per room. On denial the walk
ends immediately — no deeper rooms are visited. Report the number of rooms
each technician reached.
"""

node Room {
    has room_name: str = "";
    has clearance_required: int = 0;
}

walker Technician {
    has tech_name: str = "";
    has clearance: int = 0;
    has rooms_reached: int = 0;
    has last_borderline: bool = False;

    can start with Root entry {
        print(f"Technician {self.tech_name} (clearance {self.clearance}) entering corridor");
        visit [-->];
    }

    can attempt with Room entry {
        if self.clearance >= here.clearance_required {
            self.rooms_reached += 1;
            self.last_borderline = here.clearance_required == self.clearance;
            print(f"  [GRANTED] {here.room_name} (needs {here.clearance_required})");
            visit [-->];
        } else {
            print(f"  [DENIED] {here.room_name} (needs {here.clearance_required}) -- walkthrough ends");
            if self.last_borderline and self.rooms_reached > 1 {
                self.rooms_reached -= 1;
            }
            disengage;
        }
    }
}

with entry {
    root ++> Room(room_name="Lobby", clearance_required=1)
        ++> Room(room_name="Server Bay A", clearance_required=2)
        ++> Room(room_name="Server Bay B", clearance_required=3)
        ++> Room(room_name="Crypto Vault", clearance_required=5)
        ++> Room(room_name="Cold Storage", clearance_required=5);

    junior = Technician(tech_name="Junior", clearance=1);
    root spawn junior;
    print(f"  >> {junior.tech_name} reached {junior.rooms_reached} rooms\n");

    mid = Technician(tech_name="Mid", clearance=3);
    root spawn mid;
    print(f"  >> {mid.tech_name} reached {mid.rooms_reached} rooms\n");

    senior = Technician(tech_name="Senior", clearance=5);
    root spawn senior;
    print(f"  >> {senior.tech_name} reached {senior.rooms_reached} rooms");
