"""Pet-aware social graph: friend recommendations skip pets and minors."""

node Profile {
    has name: str = "";
    has age: int = 0;
    has species: str = "human";
    has is_adult: bool = True;
}

edge FriendOf {}

walker Recommender {
    has raw_seen: int = 0;
    has kept: int = 0;
    has owner: str = "";

    can start with Root entry {
        visit [-->];
    }

    can recommend with Profile entry {
        self.owner = here.name;
        self.raw_seen = 0;
        self.kept = 0;
        if not (here.species == "human" and here.age >= 18) {
            return;
        }
        for neighbor in [->:FriendOf:->] {
            if not isinstance(neighbor, Profile) {
                continue;
            }
            self.raw_seen += 1;
            if neighbor.species == "human" and neighbor.age >= 18 {
                self.kept += 1;
                print(f"  suggest {neighbor.name} (age {neighbor.age}) to {self.owner}");
            }
        }
        print(f"{self.owner} saw {self.raw_seen} raw neighbours, kept {self.kept} adult humans");
    }
}

with entry {
    alice = Profile(name="Alice", age=34);
    bob = Profile(name="Bob", age=41);
    carol = Profile(name="Carol", age=37);
    dave = Profile(name="Dave", age=17);
    rex = Profile(name="Rex", age=5, species="dog", is_adult=False);
    luna = Profile(name="Luna", age=3, species="cat", is_adult=False);

    alice +>:FriendOf:+> bob;
    alice +>:FriendOf:+> carol;
    alice +>:FriendOf:+> dave;
    alice +>:FriendOf:+> rex;

    bob +>:FriendOf:+> carol;
    bob +>:FriendOf:+> dave;
    bob +>:FriendOf:+> luna;

    carol +>:FriendOf:+> dave;

    root ++> alice ++> bob ++> carol;

    root spawn Recommender();
}
