```jac
"""Project folder audit: depth-first walk that flags files larger than 100 KB.

The walker keeps an explicit stack of pending entries plus a stack of the
folders whose subtrees are still open. Each visit pops exactly one node, so
a subdirectory is always fully explored (entering, children, exiting) before
the walk moves on to the next sibling. The entry trail is recorded in dive
order with indentation matching the depth of the descent.
"""

node Entry {
    has name: str = "";
    has size: int = 0;
    has depth: int = 0;

    def describe() -> str {
        return self.name;
    }
}

node Folder(Entry) {
    override def describe() -> str {
        return f"[DIR]  {self.name}";
    }
}

node File(Entry) {
    override def describe() -> str {
        return f"[FILE] {self.name} ({self.size} B)";
    }
}

edge Contains {}

walker Auditor {
    has threshold: int = 102400;
    has trail: list[str] = [];
    has pending: list = [];
    has open_folders: list = [];

    can start with Root entry {
        kids = [->:Contains:->];
        i = len(kids) - 1;
        while i >= 0 {
            kids[i].depth = 0;
            self.pending.append(kids[i]);
            i -= 1;
        }
        if len(self.pending) > 0 {
            nxt = self.pending.pop();
            visit nxt;
        } else {
            disengage;
        }
    }

    can descend with Folder entry {
        while len(self.open_folders) > 0
            and self.open_folders[len(self.open_folders) - 1].depth >= here.depth {
            done = self.open_folders.pop();
            print(f"{'  ' * done.depth}{done.describe()} -- exiting");
        }
        indent = "  " * here.depth;
        self.trail.append(f"{indent}{here.describe()}");
        print(f"{indent}{here.describe()} -- entering {here.name}");
        self.open_folders.append(here);
        kids = [->:Contains:->];
        i = len(kids) - 1;
        while i >= 0 {
            kids[i].depth = here.depth + 1;
            self.pending.append(kids[i]);
            i -= 1;
        }
        if len(self.pending) > 0 {
            nxt = self.pending.pop();
            visit nxt;
        } else {
            while len(self.open_folders) > 0 {
                done = self.open_folders.pop();
                print(f"{'  ' * done.depth}{done.describe()} -- exiting");
            }
            disengage;
        }
    }

    can inspect with File entry {
        while len(self.open_folders) > 0
            and self.open_folders[len(self.open_folders) - 1].depth >= here.depth {
            done = self.open_folders.pop();
            print(f"{'  ' * done.depth}{done.describe()} -- exiting");
        }
        indent = "  " * here.depth;
        self.trail.append(f"{indent}{here.describe()}");
        marker = "FLAG" if here.size > self.threshold else "ok";
        print(f"{indent}{here.describe()} [{marker}]");
        if len(self.pending) > 0 {
            nxt = self.pending.pop();
            visit nxt;
        } else {
            while len(self.open_folders) > 0 {
                done = self.open_folders.pop();
                print(f"{'  ' * done.depth}{done.describe()} -- exiting");
            }
            disengage;
        }
    }
}

with entry {
    project = Folder(name="project");
    src = Folder(name="src");
    docs = Folder(name="docs");
    extras = Folder(name="assets");

    root +>:Contains:+> project;
    project +>:Contains:+> src;
    project +>:Contains:+> docs;
    project +>:Contains:+> extras;

    src +>:Contains:+> File(name="main.jac", size=2048);
    src +>:Contains:+> File(name="huge.bin", size=512000);
    src +>:Contains:+> File(name="util.jac", size=8192);

    docs +>:Contains:+> File(name="readme.md", size=4096);
    docs +>:Contains:+> File(name="guide.md", size=1536);

    extras +>:Contains:+> File(name="tiny.txt", size=128);
    extras +>:Contains:+> File(name="big.log", size=204800);

    a = Auditor();
    root spawn a;
    print("--- dive trail ---");
    for entry in a.trail {
        print(entry);
    }
}
