    has day: int = 0;
}

walker WaveRunner {
    can start with Root entry {
        print("--- Contact trace (wave by wave) ---");

        # Patient zero is the root's direct neighbor (wave 0).
        wave: int = 0;
        current_frontier: list = [];
        for n in [root -->] {
            n.wave = wave;
            n.infected = True;
            print(f"Wave {wave}: {n.name} exposed");
            current_frontier = current_frontier + [n];
        }
        wave = wave + 1;

        # BFS: every wave finishes before the next begins.
        while len(current_frontier) > 0 {
            next_frontier: list = [];
            for person in current_frontier {
                for n in [person -->] {
                    if n.wave >= 0 {
                        continue;
                    }
                    n.wave = wave;
                    n.infected = True;
                    print(f"Wave {wave}: {n.name} exposed");
                    next_frontier = next_frontier + [n];
                }
            }
            current_frontier = next_frontier;
            wave = wave + 1;
        }
    }
}

