        visit [-->] else { disengage; }
    }

    can trace with Valve entry {
        self.route.append(here.name);
        print(f"pressure {here.pressure} bar at valve {here.name}");

        if len([here ->:Pipe:->]) > 1 {
            self.saw_branch = True;
        }

        # No outgoing pipes? Note the stub, summarize, and carry on.
        visit [->:Pipe:->] else {
            if len(self.route) < 3 or self.saw_branch {
                print(f"  dead end at {here.name}");
                self.dead_ends += 1;
            }
            print("-- Trace summary --");
            print("Route: " + " -> ".join(self.route));
            print(f"Dead ends hit: {self.dead_ends}");
        }
    }
}

