```jac
"""Pipeline tracer: trace water flow from the intake valve, recording the
route and counting dead-end stubs along the way.

A capped valve is always a dead end. An open valve with no outgoing pipe
is also a dead end unless it is the terminal outlet where the water
discharges. Valves already traced by an earlier run are passed through
without being recorded again.
"""

node Valve {
    has label: str = "";
    has capped: bool = False;
    has depth: int = 0;
    has traced: bool = False;
}

walker Tracer {
    has route: list[str] = [];
    has dead_ends: list[str] = [];
    has depth: int = 0;

    can start with Root entry {
        print(f"=== Pipeline trace starting at intake ===");
        visit [-->] else { disengage; }
    }

    can advance with Valve entry {
        if here.traced {
            # Already recorded by an earlier run: log nothing again, but
            # keep pushing downstream so untraced pipes are still found.
            visit [-->];
        } else {
            self.route.append(here.label);
            here.depth = self.depth;
            self.depth = self.depth + 1;
            here.traced = True;

            if here.capped {
                self.dead_ends.append(here.label);
                print(f"  [dead end] {here.label} (no outgoing pipe)");
