```jac
"""Count every build task in a dependency DAG that contains diamonds.

Shared libraries are depended on by several modules, so the graph has
diamonds: separate visit steps can enqueue the same logical task twice
(e.g. two distinct Task instances sharing the same name+minutes). The
auditor guards with a seen-set keyed on the value pair (name, minutes)
so each logical task is counted exactly once while distinct instances
with different attributes are still tracked separately.
"""

node Task {
    has name: str;
    has minutes: int;
}

edge Needs {}

walker Auditor {
    has seen: set = set();
    has total_minutes: int = 0;
    has double_enqueue_avoided: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can audit with Task entry {
        key = (here.name, here.minutes);
        # Diamond in the DAG: this logical task may already have been
        # enqueued from two different parents -- count it once
        if key in self.seen {
            print(f"{here.name}: already audited via another path, skipping");
            self.double_enqueue_avoided = True;
            skip;
        }
        self.seen.add(key);
        self.total_minutes += here.minutes;
        print(f"auditing {here.name} ({here.minutes} min, running total {self.total_minutes})");

        visit [->:Needs:->];
    }

    can finish with Root exit {
        print(f"-- Audit: {len(self.seen)} unique task(s), total {self.total_minutes} min --");
        if self.double_enqueue_avoided {
            print("Seen-guard caught at least one diamond re-entry");
        }
    }
}

with entry {
    app = Task(name="build-app", minutes=5);
    web = Task(name="compile-web", minutes=8);
    api = Task(name="compile-api", minutes=12);
    core = Task(name="link-core", minutes=20);

    root ++> app;
    app +>: Needs() :+> web;
    app +>: Needs() :+> api;
    web +>: Needs() :+> core;
    api +>: Needs() :+> core;

    root spawn Auditor();
}
