"""Build dependency auditor.

Models a build system where tasks depend on shared libraries (diamond
dependencies). A walker descends the dependency graph and audits each
task exactly once, even when the same task is reachable by multiple
paths, summing its build minutes.
"""

node Task {
    has title: str = "";
    has minutes: int = 0;
}

walker BuildAuditor {
    has total_minutes: int = 0;
    has audited: list[str] = [];

    def summarize() {
        print(f"Total audited build minutes: {self.total_minutes}");
    }

    can start with Root entry {
        visit [-->] else { self.summarize(); disengage; }
    }

    can descend with Task entry {
        # Queue children first so a duplicate never strands the
        # remaining frontier; then audit only if not already seen.
        if here.title not in self.audited {
            self.audited.append(here.title);
            self.total_minutes += here.minutes;
            print(f"audited {here.title} ({here.minutes} min) — running total {self.total_minutes}");
        }
        # No disengage here: a leaf (or revisited diamond node) must let
        # the queued frontier keep walking so siblings still get audited.
        visit [-->] else { self.summarize(); }
    }
}

with entry {
    lib_a = Task(title="lib_a", minutes=5);
    lib_b = Task(title="lib_b", minutes=7);
    lib_c = Task(title="lib_c", minutes=3);
    shared = Task(title="shared_util", minutes=4);
    app = Task(title="app", minutes=11);
    test = Task(title="integration_test", minutes=6);

    # Diamond: app depends on shared_util via two paths, and so does
    # the integration test, but each task should only be counted once.
    app ++> shared;
    test ++> shared;
    lib_a ++> shared;
    lib_b ++> shared;
    lib_c ++> shared;

    root ++> app ++> test ++> lib_a ++> lib_b ++> lib_c;

    root spawn BuildAuditor();
}
