"""Build-system dependency audit: count total build minutes across a diamond-shaped task graph, deduplicating tasks that are reachable through multiple paths."""

node BuildTask {
    has title: str = "";
    has minutes: int = 0;
}

edge DependsOn {}

walker BuildAuditor {
    has audited_titles: list[str] = [];
    has total_minutes: int = 0;
    has path: list[str] = [];
    has reported: bool = False;

    def already_audited(title: str) -> bool {
        seen = False;
        for t in self.audited_titles {
            if t == title {
                seen = True;
            }
        }
        return seen;
    }

    def summarize() -> None {
        print(
            f"\nAudit complete: {len(self.path)} unique tasks, "
            f"{self.total_minutes} total build minutes"
        );
        print(f"Path order: {self.path}");
    }

    can start with Root entry {
        print("Starting build dependency audit");
        visit [-->] else { disengage; }
    }

    can audit with BuildTask entry {
        if self.already_audited(here.title) {
            print(f"  skip (already audited): {here.title}");
        } else {
            self.audited_titles.append(here.title);
            self.total_minutes += here.minutes;
            self.path.append(here.title);
            print(f"  auditing: {here.title} (+{here.minutes} min)");
        }
        visit [-->] else {
            if not self.reported {
                self.reported = True;
                self.summarize();
            }
        }
    }
}

with entry {
    # Diamond DAG: shared 'core_lib' is reachable via three different paths
    # app -> ui  -> core_lib
    #         \-> net -> core_lib
    # app -> packager -> core_lib
    app = BuildTask(title="compile_app", minutes=10);
    ui = BuildTask(title="compile_ui", minutes=15);
    net = BuildTask(title="compile_net", minutes=20);
    core_lib = BuildTask(title="build_core_lib", minutes=30);
    packager = BuildTask(title="package_release", minutes=5);

    root ++> app;
    app +>:DependsOn:+> ui;
    app +>:DependsOn:+> net;
    app +>:DependsOn:+> packager;
    ui +>:DependsOn:+> core_lib;
    net +>:DependsOn:+> core_lib;
    packager +>:DependsOn:+> core_lib;

    auditor = BuildAuditor();
    root spawn auditor;
}
