```jac
"""Professional networking: find the shortest introduction chain between two people.

A ``Person`` is a node in the social graph. A typed ``Knows`` edge encodes a
direct professional connection. The ``Connector`` walker explores those edges,
recording who introduced each person it reaches. The ``ChainReporter`` walker
then walks the recorded parent map backward to print the introduction chain.
"""

node Person {
    has name: str = "";
    has role: str = "";
    has company: str = "";
}

edge Knows {
    has context: str = "";
    has strength: int = 1;
}

walker Connector {
    has target_name: str = "";
    has visited: list[str] = [];
    has parent: dict = {};
    has frontier: list = [];
    has found: bool = False;

    can begin with Root entry {
        visit [-->];
    }

    can fanout with Person entry {
        if here.name not in self.visited {
            self.visited.append(here.name);
            if here.name == self.target_name {
                self.found = True;
            } else {
                # Push outgoing connections onto the frontier stack in
                # reverse order so the earliest connection is explored first.
                outgoing = [->:Knows:->];
                i = len(outgoing) - 1;
                while i >= 0 {
                    n = outgoing[i];
                    if n.name not in self.visited and self.parent.get(n.name) is None {
                        self.parent[n.name] = here.name;
                        self.frontier.append(n);
                    }
                    i -= 1;
                }
            }
        }
        # Queue the next hop before deciding whether to stop.
        if self.found or len(self.frontier) == 0 {
            disengage;
        }
        nxt = self.frontier.pop();
        visit nxt;
    }
}

walker ChainReporter {
    has start_name: str = "";
    has target_name: str = "";
    has parent: dict = {};
    has path: list[str] = [];

    can summarize with Root entry {
        # Reconstruct the chain by walking the recorded parent map backwards
        # from the target to the start, then reverse for print order.
        chain: list[str] = [];
        current = self.target_name;
        ok = True;
        chain.append(current);
        while current != self.start_name and ok {
            prev = self.parent.get(current);
            if prev is None {
                ok = False;
            } else {
                chain.append(prev);
                current = prev;
            }
        }
        print(f"Shortest introduction chain from {self.start_name} to {self.target_name}:");
        if ok {
            chain.reverse();
            self.path = chain;
            if len(self.path) == 1 {
                print(f"  0. {self.path[0]}  (start)");
                print(f"  0. {self.path[0]}  (target)");
            } else {
                for (i, person) in enumerate(self.path) {
                    tag = "start" if i == 0 else ("target" if i == len(self.path) - 1 else f"hop {i}");
                    print(f"  {i}. {person}  ({tag})");
                }
            }
        } else {
            print(f"No introduction chain from {self.start_name} to {self.target_name}");
        }
        visit [-->] else { disengage; };
    }
}

with entry {
    # Build a small professional network.
    alice  = Person(name="Alice",  role="PM",        company="Acme");
    bob    = Person(name="Bob",    role="Engineer",  company="Acme");
    carol  = Person(name="Carol",  role="Designer",  company="Acme");
    dave   = Person(name="Dave",   role="CTO",       company="Beta");
    eve    = Person(name="Eve",    role="Recruiter", company="Beta");
    frank  = Person(name="Frank",  role="Investor",  company="Gamma");
    grace  = Person(name="Grace",  role="Founder",   company="Gamma");

    # Wire up direct professional connections.
    alice +>:Knows(context="same team",    strength=3):+> bob;
    alice +>:Knows(context="project lead", strength=2):+> carol;
    bob   +>:Knows(context="alumni",       strength=2):+> dave;
    carol +>:Knows(context="conference",   strength=1):+> eve;
    dave  +>:Knows(context="advisor",      strength=3):+> frank;
    eve   +>:Knows(context="portfolio",    strength=2):+> grace;
    frank +>:Knows(context="co-founder",   strength=3):+> grace;

    root ++> alice;

    # ---- Find the introduction chain from Alice to Grace -----------------
    searcher = Connector(target_name="Grace");
    alice spawn searcher;

    reporter = ChainReporter(
        start_name="Alice",
        target_name="Grace",
        parent=searcher.parent
    );
    reporter spawn root;
}
