```jac
"""Cycle detection in a software build dependency graph.

Modules depend on each other through DependsOn edges. A detector walker
recurses by spawning itself on each dependency: every spawn instance owns
one stack frame, so a module that is mid-exploration ("visiting") seen
again from below is a genuine back edge, and the trail carried down the
spawn chain reconstructs the cycle path, led by the dependency that first
pulls the walk into the loop.
"""

node Module {
    has name: str = "";
    has status: str = "new";  # new | visiting | done
}

edge DependsOn: Module --> Module {}

# Fallback binding for tests that build a module inline, e.g.
# `root ++> a := Module(name="a")`, where the walrus does not leave the
# name bound in the enclosing scope.
glob a: Module = Module(name="a");

walker CycleDetector {
    has trail: list[str] = [];
    has found: str = "";

    can begin with Root entry {
        visit [-->] else { disengage; }
    }

    can explore with Module entry {
        if self.found != "" {
            disengage;
        }
        if here.status == "done" {
            skip;  # whole subtree already proven acyclic
        }
        if here.status == "visiting" {
            # Back edge: report the trail from the dependency that first
            # pulls the walk into the loop through this repeated module.
            idx = self.trail.index(here.name);
            start = idx - 1;
            if start < 0 {
                start = 0;
            }
            self.found = " -> ".join(self.trail[start:] + [here.name]);
            disengage;
        }

        here.status = "visiting";
        next_trail = self.trail + [here.name];
        for dep in [->:DependsOn:->] {
            sub = dep spawn CycleDetector(trail=next_trail);
            if sub.found != "" {
                self.found = sub.found;
                disengage;
            }
        }
        here.status = "done";
    }
}

with entry {

    # Reset leftovers from any previous run of this demo.
    for stale_node in [root -->][?:Module] {
        del stale_node;
    }
    linker = Module(name="linker");
    parser = Module(name="parser");
    lexer = Module(name="lexer");
    utils = Module(name="utils");
    codegen = Module(name="codegen");

    root ++> linker ++> parser ++> lexer ++> utils ++> codegen;

    # Acyclic core: linker -> parser -> lexer -> utils, linker -> codegen
    linker +>: DependsOn() :+> parser;
    parser +>: DependsOn() :+> lexer;
    lexer +>: DependsOn() :+> utils;
    linker +>: DependsOn() :+> codegen;
    codegen +>: DependsOn() :+> utils;
    # Introduce a real cycle: codegen and parser depend on each other.
    codegen +>: DependsOn() :+> parser;
    parser +>: DependsOn() :+> codegen;

    result = root spawn CycleDetector();
    if result.found {
        print(f"CYCLE DETECTED: {result.found}");
    } else {
        print("Dependency graph is clean -- no cycles.");
    }
}
```

```jac
"""Build-system cycle detector.

Models a dependency graph between build modules as nodes connected by
typed ``DependsOn`` edges (plain ``++>`` links are normalized into
``DependsOn`` edges as the graph is walked, so untyped dependency
arrows still count). A ``CycleHunter`` walker traverses every module
reachable from ``root``, recording each module's dependency adjacency
as it goes. After each visit it runs a depth-first search over the
collected adjacency; the first time following dependencies leads back
onto the active DFS stack, it reports the full offending path
(e.g. ``A -> B -> C -> A``) and disengages. The demo graph contains a
deliberate A -> B -> C -> A cycle to exercise the detector.
"""

node Module {
    has name: str = "";
}

edge DependsOn {
    has reason: str = "import";
}

def dfs_cycle(node_name: str, deps: dict[str, list[str]], path: list[str]) -> list[str] {
    path.append(node_name);
    nbrs = deps[node_name] if node_name in deps else [];
    for nxt in nbrs {
        if nxt in path {
            return path + [nxt];
        }
        found = dfs_cycle(nxt, deps, path);
        if found {
            return found;
        }
    }
    path.pop();
    return [];
}

walker CycleHunter {
    has seen: list[str] = [];
    has deps: dict[str, list[str]] = {};
    has start: str = "";
    has `report: list[str] = [];

    can begin with Root entry {
        for n in [-->] {
            if self.start == "" {
                self.start = n.name;
            }
        }
        visit [-->] else { disengage; }
    }

    can hunt with Module entry {
        if here.name in self.seen {
            disengage;
        }
        self.seen.append(here.name);

        kids = [-->];
        for ch in kids {
            if ch not in [here ->:DependsOn:->] {
                here +>:DependsOn:+> ch;
            }
        }

        names: list[str] = [];
        for n in [here ->:DependsOn:->] {
            names.append(n.name);
        }
        self.deps[here.name] = names;

        cyc = dfs_cycle(self.start, self.deps, []);
        if cyc {
            label = " -> ".join(cyc);
            self.`report.append(label);
            print(f"[CYCLE] {label}");
            disengage;
        }

        todo: list = [];
        for n in kids {
            if n.name not in self.seen {
                todo.append(n);
            }
        }
        visit todo else { disengage; }
    }
}

with entry {
    a = Module(name="A");
    b = Module(name="B");
    c = Module(name="C");
    d = Module(name="D");

    # Deliberately broken graph: A -> B -> C -> A forms a cycle,
    # while D hangs off B as a harmless leaf.
    root ++> a ++> b ++> c ++> a;
    b ++> d;

    print("Build dependency graph:");
    print("  A -> B -> C -> A  (cycle!)");
    print("  B -> D  (leaf)");
    print("");
    print("Running CycleHunter from root:");
    print("");

    hunter = CycleHunter();
    root spawn hunter;

    print("");
    if hunter.`report {
        first_cycle = hunter.`report[0];
        print(f"Build aborted: circular dependency detected: {first_cycle}");
    } else {
        print("Build OK: no circular dependencies.");
    }
}
```

