```jac
"""Org chart payroll rollup.

Each employee has a salary and reports to a manager through a typed
``ReportsTo`` edge. A ``PayrollAuditor`` walker descends to the leaves
first, then on the way back up it computes each manager's subtree
totals from scratch from the already-folded child node values. Because
totals are overwritten (not accumulated) on every spawn, re-running
the audit on the same graph produces the same result.
"""

node Employee {
    has name: str = "";
    has salary: float = 0.0;
    has headcount: int = 0;
    has subtree_payroll: float = 0.0;
}

edge ReportsTo {}

walker PayrollAuditor {
    can start with Root entry {
        visit [-->];
    }

    # Bottom-up: visit reports first so their totals are already folded
    # in when we audit the current manager.
    can descend with Employee entry {
        visit [-->];
    }

    # On exit, compute this node's subtree totals deterministically from
    # its direct reports' already-computed subtree values, then include
    # ``here`` itself. We overwrite (assign) rather than accumulate so
    # repeated spawns are idempotent.
    can fold with Employee exit {
        total_headcount = 1;
        total_payroll = here.salary;
        for r in [-->] {
            total_headcount += r.headcount;
            total_payroll += r.subtree_payroll;
        }
        here.headcount = total_headcount;
        here.subtree_payroll = total_payroll;
        report here;
    }
}

with entry {
    # Sample org: CEO <- VP Eng <- Eng Lead <- Eng1
    #                          |
    #                          +-- Eng2
    #             VP Sales <- Sales1
    ceo = Employee(name="Alice (CEO)", salary=250000.0);
    vp_eng = Employee(name="Bob (VP Eng)", salary=180000.0);
    vp_sales = Employee(name="Carla (VP Sales)", salary=170000.0);
    eng_lead = Employee(name="Dan (Eng Lead)", salary=140000.0);
    eng1 = Employee(name="Eve (Eng1)", salary=120000.0);
    eng2 = Employee(name="Frank (Eng2)", salary=115000.0);
    sales1 = Employee(name="Grace (Sales1)", salary=95000.0);

    root ++> ceo;
    ceo +>:ReportsTo:+> vp_eng;
    ceo +>:ReportsTo:+> vp_sales;
    vp_eng +>:ReportsTo:+> eng_lead;
    eng_lead +>:ReportsTo:+> eng1;
    eng_lead +>:ReportsTo:+> eng2;
    vp_sales +>:ReportsTo:+> sales1;

    PayrollAuditor() spawn root;

    print("Subtree rollups (headcount includes the manager):");
    print(f"  {ceo.name}: headcount={ceo.headcount}, payroll=${ceo.subtree_payroll:,.0f}");
    print(f"  {vp_eng.name}: headcount={vp_eng.headcount}, payroll=${vp_eng.subtree_payroll:,.0f}");
    print(f"  {vp_sales.name}: headcount={vp_sales.headcount}, payroll=${vp_sales.subtree_payroll:,.0f}");
    print(f"  {eng_lead.name}: headcount={eng_lead.headcount}, payroll=${eng_lead.subtree_payroll:,.0f}");
    print(f"  {eng1.name}: headcount={eng1.headcount}, payroll=${eng1.subtree_payroll:,.0f}");
    print(f"  {eng2.name}: headcount={eng2.headcount}, payroll=${eng2.subtree_payroll:,.0f}");
    print(f"  {sales1.name}: headcount={sales1.headcount}, payroll=${sales1.subtree_payroll:,.0f}");
