```jac
"""CI pipeline task scheduler with dependency-aware ordering.

Tasks point at the tasks that need them via Needs edges (prerequisite -->
dependent). A Scheduler walker spawned on root first walks the entire
reachable graph, collecting every task it touches into its own task list --
this way tasks reachable only through Needs edges (not just direct root
children) are included. When the walk completes, the Root exit ability runs
Kahn's algorithm: it recomputes each task's remaining-prerequisite count,
repeatedly schedules every task whose count is zero, and prints the order
with the serial total time -- or a cycle warning when no task can progress.
"""

node Task {
    has name: str = "";
    has duration: int = 5;
    has indegree: int = 0;  # prerequisites not yet scheduled
    has seen: bool = False;
}

edge Needs: Task --> Task {}

walker Scheduler {
    has order: list[str] = [];
    has tasks: list[Task] = [];

    can start with Root entry {
        visit [-->];
    }

    can gather with Task entry {
        if not here.seen {
            here.seen = True;
            self.tasks.append(here);
            visit [-->];
        }
        # Already-seen tasks are neither re-collected nor re-traversed,
        # which is what lets a cyclic graph terminate the gather phase.
    }

    can plan with Root exit {
        # Deferred until the whole graph has been gathered.
        for t in self.tasks {
            t.indegree = len([t <-:Needs:<-]);
        }

        done: list[str] = [];
        remaining = len(self.tasks);
        total_time = 0;
        while remaining > 0 {
            progressed = False;
            for t in self.tasks {
                if t.indegree != 0 or t.name in done {
                    continue;
                }
                self.order.append(t.name);
                done.append(t.name);
                total_time += t.duration;
                remaining -= 1;
                progressed = True;
                for dependent in [t ->:Needs:->] {
                    dependent.indegree -= 1;
                }
            }
            if not progressed {
                print("Dependency cycle among remaining tasks -- stuck.");
                break;
            }
        }

        print(f"Build order ({len(self.order)} of {len(self.tasks)} tasks, {total_time} min total):");
        for i in range(len(self.order)) {
            step = self.order[i];
            print(f"  {i + 1}. {step}");
        }
    }
}

with entry {
    # Reset anything a previous run left behind so the demo repeats
    # cleanly on the persistent root.
    for stale in [root -->][?:Task] {
        del stale;
    }

    setup = Task(name="setup", duration=5);
    compile_src = Task(name="compile", duration=20);
    gen_docs = Task(name="docs", duration=10);
    run_tests = Task(name="tests", duration=15);
    package = Task(name="package", duration=8);
    publish = Task(name="publish", duration=4);

    root ++> [
        setup,
        compile_src,
        gen_docs,
        run_tests,
        package,
        publish,
    ];

    # Edge direction: prerequisite --> dependent.
    setup +>: Needs() :+> compile_src;
    compile_src +>: Needs() :+> gen_docs;
    compile_src +>: Needs() :+> run_tests;
    compile_src +>: Needs() :+> package;
    gen_docs +>: Needs() :+> package;
    package +>: Needs() :+> publish;

    root spawn Scheduler();
}
