```jac
"""Family tree: enumerate ancestors by generation, walking against child links."""

node Person {
    has name: str = "";
    has birth_year: int = 0;
}

edge ChildOf {
    has birth_order: int = 0;
}

walker AncestorCensus {
    has generations: list[list[str]] = [];
    has current_gen: list[str] = [];
    has level_left: int = 0;
    has next_level: int = 0;

    can start with Root entry {
        seeds = [-->];
        self.level_left = len(seeds);
        visit seeds else {
            print("Ancestor generations:");
            disengage;
        }
    }

    can ascend with Person entry {
        # ChildOf edges point from each person up to their parents.
        parents = [->:ChildOf:->];
        self.next_level += len(parents);
        for p in parents {
            if p.name != "" and p.name not in self.current_gen {
                self.current_gen.append(p.name);
            }
        }
        self.level_left -= 1;
        if self.level_left == 0 {
            if len(self.current_gen) > 0 {
                self.generations.append(self.current_gen);
                self.current_gen = [];
            }
            self.level_left = self.next_level;
            self.next_level = 0;
            if self.level_left == 0 {
                print("Ancestor generations:");
                for (i, gen) in enumerate(self.generations) {
                    label = "parents" if i == 0 else ("grandparents" if i == 1 else f"great-grandparents (gen {i + 1})");
                    print(f"  {label}: {gen}");
                }
                disengage;
            }
        }
        if len(parents) > 0 {
            visit parents;
        }
    }
}

with entry {
    # Build a three-generation family:
    # children --(ChildOf)--> parents --(ChildOf)--> grandparents
    grandpa1 = Person(name="Arthur", birth_year=1940);
    grandma1 = Person(name="Beatrice", birth_year=1942);
    grandpa2 = Person(name="Cyrus", birth_year=1938);
    grandma2 = Person(name="Delia", birth_year=1941);

    parent1 = Person(name="Ethan", birth_year=1970);
    parent2 = Person(name="Fiona", birth_year=1972);
    parent3 = Person(name="George", birth_year=1975);
    parent4 = Person(name="Hazel", birth_year=1977);

    child1 = Person(name="Iris", birth_year=2000);
    child2 = Person(name="Jules", birth_year=2002);

    # Connect parents to grandparents via ChildOf edges.
    parent1 +>:ChildOf(birth_order=1):+> grandpa1;
    parent1 +>:ChildOf(birth_order=2):+> grandma1;
    parent2 +>:ChildOf(birth_order=1):+> grandpa1;
    parent2 +>:ChildOf(birth_order=2):+> grandma2;
    parent3 +>:ChildOf(birth_order=1):+> grandpa2;
    parent3 +>:ChildOf(birth_order=2):+> grandma1;
    parent4 +>:ChildOf(birth_order=1):+> grandpa2;
    parent4 +>:ChildOf(birth_order=2):+> grandma2;

    # Connect children to their parents via ChildOf edges.
    child1 +>:ChildOf:+> parent1;
    child1 +>:ChildOf:+> parent2;
    child2 +>:ChildOf:+> parent3;
    child2 +>:ChildOf:+> parent4;

    # Seed the graph from root so the walker has somewhere to start.
    root ++> child1;
    root ++> child2;

    root spawn AncestorCensus();
