```jac
"""Epidemic simulation over a contact network.

People are connected by Contact edges carrying a strength. Each simulated
day an infection-sweep walker visits the active cohort: susceptible people
compute exposure to already-infectious contacts and catch the infection
probabilistically through a seeded LCG, while state changes are deferred to
root exit so nobody infects their neighbours later the same day.
"""

node Person {
    has name: str = "";
    has infected: bool = False;
    has next_state: bool = False;
    has active: bool = False;
}

edge Contact: Person --> Person {
    has strength: float = 0.0;
}

walker InfectionSweep {
    has beta: float = 0.5;
    has seed: int = 42;

    can start with Root entry {
        people = [-->][?:Person];
        for p in people {
            p.active = False;
        }

        if len(people) > 0 {
            anchor = people[len(people) - 1];
            anchor.active = True;
            for step in range(len(people)) {
                for p in people {
                    if not p.active {
                        touches = False;
                        for n in [p ->:Contact:->] {
                            if n.active {
                                touches = True;
                            }
                        }
                        if touches {
                            p.active = True;
                        }
                    }
                }
            }
        }

        visit [-->] else {
            disengage;
        }
    }

    can assess with Person entry {
        if here.active {
            if here.infected {
                here.next_state = True;
            } else {
                neighbors = [->:Contact:->];
                links = [edge ->:Contact:->];

                exposure = 0.0;
                for i in range(len(neighbors)) {
                    if neighbors[i].active and neighbors[i].infected {
                        exposure += links[i].strength;
                    }
                }

                self.seed = (self.seed * 1103515245 + 12345) % 2147483648;
                roll = self.seed / 2147483648.0;
                here.next_state = exposure > 0.0 and roll < exposure * self.beta;
            }
        }
    }

    can apply_day with Root exit {
        for p in [-->][?:Person] {
            if p.active {
                p.infected = p.next_state;
            }
        }
    }
}

with entry {
    for stale in [root -->][?:Person] {
        del stale;
    }

    people: list[Person] = [];
    names = ["Ava", "Bo", "Cy", "Di", "Ed", "Fay", "Gus", "Hal"];
    for nm in names {
        people.append(Person(name=nm));
    }
    ava = people[0]; bo = people[1]; cy = people[2]; di = people[3];
    ed = people[4]; fay = people[5]; gus = people[6]; hal = people[7];

    ava <+: Contact(strength=0.6) :+> bo;
    ava <+: Contact(strength=0.3) :+> cy;
    bo <+: Contact(strength=0.9) :+> di;
    cy <+: Contact(strength=0.4) :+> di;
    di <+: Contact(strength=0.7) :+> ed;
    ed <+: Contact(strength=0.5) :+> fay;
    fay <+: Contact(strength=0.2) :+> gus;
    gus <+: Contact(strength=0.8) :+> hal;

    root ++> people;

    ava.infected = True;
    ava.next_state = True;

    print("Epidemic curve (seeded, reproducible):");
    rng_state = 987654321;
    prev_sick = 1;
    for day in range(1, 8) {
        result = root spawn InfectionSweep(beta=0.45, seed=rng_state);
        rng_state = result.seed;
        sick = 0;
        for p in people {
            if p.infected {
                sick += 1;
            }
        }
        print(f"  Day {day}: {sick - prev_sick} new case(s), {sick}/8 infected");
        prev_sick = sick;
    }
}
