```jac
"""Maze solver: grid of open cells surrounded by walls, depth-first search from entrance until reaching the exit, reporting the route taken."""

node Cell {
    has row: int = 0;
    has col: int = 0;
    has is_entrance: bool = False;
    has is_exit: bool = False;
    has visited: bool = False;
    has label: str = "";
}

edge Open {
    has weight: int = 1;
}

walker MazeSolver {
    has path_taken: list = [];
    has found: bool = False;

    can begin with Cell entry {
        if self.found {
            disengage;
        }

        here.visited = True;
        self.path_taken.append(here.label);

        if here.is_exit {
            self.found = True;
            print(f"Reached exit at {here.label}!");
            print("Route taken:");
            for step in self.path_taken {
                print(f"  -> {step}");
            }
            disengage;
        }

        # Collect all unvisited neighbors reachable via Open edges.
        unvisited = [];
        for neighbor in [here ->:Open:-> ] {
            if not neighbor.visited {
                unvisited.append(neighbor);
            }
        }

        if len(unvisited) > 0 {
            visit unvisited;
        } else {
            # Dead end: pop this cell off the recorded path.
            self.path_taken.pop();
        }
    }

    can backtrack with Cell exit {
        if self.found {
            disengage;
        }

        # Collect unvisited neighbors reachable via Open edges from the
        # cell we just returned to.
        unvisited = [];
        for neighbor in [here ->:Open:-> ] {
            if not neighbor.visited {
                unvisited.append(neighbor);
            }
        }

        if len(unvisited) > 0 {
            visit unvisited;
        } else {
            # No more options from this cell either: pop it from the path
            # so the next outer backtrack handler can continue searching.
            self.path_taken.pop();
        }
    }
}

with entry {
    # Build a simple 3x3 maze grid with walls conceptually surrounding all cells.
    # Connections represent open passages between adjacent open cells.
    c00 = Cell(row=0, col=0, is_entrance=True, label="(0,0) ENTRANCE");
    c01 = Cell(row=0, col=1, label="(0,1)");
    c02 = Cell(row=0, col=2, is_exit=True, label="(0,2) EXIT");

    c10 = Cell(row=1, col=0, label="(1,0)");
    c11 = Cell(row=1, col=1, label="(1,1)");
    c12 = Cell(row=1, col=2, label="(1,2)");

    c20 = Cell(row=2, col=0, label="(2,0)");
    c21 = Cell(row=2, col=1, label="(2,1)");
    c22 = Cell(row=2, col=2, label="(2,2)");

    root ++> c00;
    root ++> c01;
    root ++> c02;
    root ++> c10;
    root ++> c11;
    root ++> c12;
    root ++> c20;
    root ++> c21;
    root ++> c22;

    # Wire up adjacent open passages between cells using the Open edge type.
    c00 +>:Open:+> c01;
    c00 +>:Open:+> c10;
    c01 +>:Open:+> c02;
    c01 +>:Open:+> c11;
    c10 +>:Open:+> c11;
    c11 +>:Open:+> c12;
    c11 +>:Open:+> c21;
    c12 +>:Open:+> c02;
    c20 +>:Open:+> c21;
    c21 +>:Open:+> c22;

    # Spawn solver on the entrance cell.
    c00 spawn MazeSolver();
}
