```jac
"""Micro-blog reader: traverse the public commons and list posts in creation order.

Anonymous callers walk the shared graph root to root, collecting posts in
the order they were published. The publisher walker is included so the
module runs standalone as a self-contained demo.
"""

node Post {
    has title: str = "";
    has body: str = "";
    has author: str = "anon";
    has created_at: int = 0;
    has published: bool = False;
}

node PublicBoard {
    has board_name: str = "commons";
}

walker Publisher {
    has board_label: str = "commons";

    can start with Root entry {
        print(f"Publishing to the {self.board_label} board");
        visit [-->];
    }

    can place with PublicBoard entry {
        body1 = Post(
            title="Hello, world",
            body="First post on the shared board.",
            author="ada",
            created_at=1,
            published=True
        );
        body2 = Post(
            title="Second post",
            body="Another one for the commons.",
            author="grace",
            created_at=2,
            published=True
        );
        body3 = Post(
            title="Draft",
            body="Not yet released.",
            author="linus",
            created_at=3,
            published=False
        );
        here ++> body1;
        here ++> body2;
        here ++> body3;
        print(f"Placed 3 posts on {here.board_name}");
        visit [-->];
    }
}

walker Reader {
    can start with Root entry {
        print("Anonymous reader browsing the public commons");
        visit [-->];
    }

    can browse with PublicBoard entry {
        print(f"--- Posts on '{here.board_name}' (creation order) ---");
        visit [-->];
    }

    can read with Post entry {
        visibility = "PUB" if here.published else "DRAFT";
        print(f"[{visibility}] #{here.created_at} {here.title} by {here.author}");
    }
}

with entry {
    board = PublicBoard(board_name="commons");
    root ++> board;

    root spawn Publisher(board_label="commons");
    root spawn Reader();
}
