```jac
"""Journal share-link controller: arm and revoke a READ grant on a note.

Models a note as a graph node carrying a ``shared`` flag, plus typed edges
for the owner relationship and the READ grant. A ``ShareController`` walker
walks the graph and toggles the grant on each note it visits, printing the
transition so the caller can see the flag flip.
"""

node Note {
    has title: str = "";
    has year: int = 2024;
    has shared: bool = False;
}

node Person {
    has name: str = "";
}

edge Owns {}
edge ReadGrant {}

walker ShareController {
    has action: str = "share";

    can start with Root entry {
        print(f"Arming share-link controller in '{self.action}' mode");
        visit [-->];
    }

    can act with Note entry {
        if self.action == "share" {
            here.shared = True;
        } else {
            here.shared = False;
        }
        label = "SHARED" if here.shared else "PRIVATE";
        verb = "armed" if self.action == "share" else "revoked";
        print(f"[{label}] {verb} READ grant on '{here.title}' ({here.year})");
        visit [-->];
    }

    can walk_owner with Person entry {
        visit [->:Owns:->];
    }
}

walker ShareRevoker {
    can start with Root entry {
        print("Revoking share-link controller");
        visit [-->];
    }

    can act with Note entry {
        here.shared = False;
        print(f"[PRIVATE] revoked READ grant on '{here.title}' ({here.year})");
        visit [-->];
    }

    can walk_owner with Person entry {
        visit [->:Owns:->];
    }
}

with entry {
    alice = Person(name="Alice");
    note_one = Note(title="Morning pages", year=2024);
    note_two = Note(title="Field notes", year=2025);
    note_three = Note(title="Dream log", year=2024, shared=True);

    alice +>:Owns:+> note_one;
    alice +>:Owns:+> note_two;
    alice +>:Owns:+> note_three;

    note_one +>:ReadGrant:+> Person(name="Bob");
    note_two +>:ReadGrant:+> Person(name="Carol");
    note_three +>:ReadGrant:+> Person(name="Dave");

    root ++> alice;

    print("--- arming ---");
    root spawn ShareController(action="share");
    print("--- revoking ---");
    root spawn ShareRevoker();
}
```

```jac
"""Journal share-link toggle: arm and revoke a READ grant on a note.

A walker arms a share link on a note (granting READ access) and another
revokes it, returning the note to owner-only. A ``shared`` flag on the
note flips with each transition so the output reflects the new state.
"""

node Note {
    has title: str = "";
    has owner: str = "";
    has shared: bool = False;
}

walker ArmShare {
    can start with Root entry {
        visit [-->];
    }

    can arm with Note entry {
        here.shared = True;
        print(f"[ARM]   {here.title} ({here.owner}) -> shared={here.shared}");
        visit [-->];
    }
}

walker RevokeShare {
    can start with Root entry {
        visit [-->];
    }

    can revoke with Note entry {
        here.shared = False;
        print(f"[REVOKE] {here.title} ({here.owner}) -> shared={here.shared}");
        visit [-->];
    }
}

with entry {
    journal = Note(title="Trip to Lisbon", owner="Ada");
    root ++> journal;
    root ++> Note(title="Grocery list", owner="Ada");
    root ++> Note(title="Meeting notes", owner="Lin", shared=True);

    print("--- arming share link ---");
    root spawn ArmShare();

    print("--- revoking share link ---");
    root spawn RevokeShare();
}
