```jac
"""Reports access policy.

Published reports are world-readable; unpublished ones fall back to
per-instance grants. The archetype hook returns a READ level when
published and ``None`` otherwise. A ``Publish`` walker flips the flag
and drops the now-redundant grant edge.
"""

node Reader {
    has name: str = "";
}

node Report {
    has title: str = "";
    has published: bool = False;

    # Archetype hook: world-readable when published, else defer to grants.
    def access_level() -> str | None {
        if self.published {
            return "READ";
        }
        return None;
    }
}

edge Grant { has level: str = "READ"; }

walker Publish {
    can start with Root entry {
        visit [-->];
    }

    can flip with Report entry {
        here.published = True;
        # Drop the now-redundant grant edge(s) attached to this report.
        # Snapshot first to avoid mutating during iteration, then
        # delete by re-querying with `del`.
        grants = [here ->:Grant:->];
        for g in grants {
            del [here ->:Grant:-> g];
        }
        report_level = here.access_level();
        print(f"Published '{here.title}' -> access level: {report_level}");
    }
}

with entry {
    draft = Report(title="Q4 Forecast");
    root ++> draft;

    # Owner pre-shares the draft with a single reader.
    reader = Reader(name="Alice");
    draft +>:Grant(level="READ"):+> reader;

    root spawn Publish();

    # After publishing the hook returns READ for everyone; the
    # pre-publish grant is now redundant and has been removed.
    print(f"final access level: {draft.access_level()}");
}
```

```jac
"""Aggregate stats over a private todo graph into one report.

Counters accumulate during the walk and a single dict is reported at
Root exit; division by zero is guarded for accounts with no todos.
"""

node Todo {
    has title: str;
    has done: bool = False;
    has points: int = 1;
}

walker add_todo {
    has title: str;
    has done: bool = False;
    has points: int = 1;

    can run with Root entry {
        here ++> Todo(title=self.title, done=self.done, points=self.points);
    }
}

walker get_stats {
    has total: int = 0;
    has completed: int = 0;
    has effort_done: int = 0;
    has effort_total: int = 0;

    can count with Root entry {
        visit [-->];
    }

    can tally with Todo entry {
        self.total += 1;
        self.effort_total += here.points;
        if here.done {
            self.completed += 1;
            self.effort_done += here.points;
        }
    }

    can summarize with Root exit {
        report [{
            "total": self.total,
            "completed": self.completed,
            "pending": self.total - self.completed,
            "completion_rate": (self.completed / self.total * 100) if self.total > 0 else 0.0,
            "points_burned": self.effort_done,
            "points_total": self.effort_total,
        }];
    }
}
```

```jac
"""Task dashboard: walk the task tree, accumulate counters, report one dict at Root exit.

Endpoints covered:
  - total tasks
  - completed tasks
  - pending tasks
  - completion rate (with division-by-zero guard)
  - story points burned vs planned
"""

node Task {
    has title: str = "";
    has done: bool = False;
    has points: int = 0;
    has planned_points: int = 0;
}

walker Dashboard {
    has total: int = 0;
    has completed: int = 0;
    has pending: int = 0;
    has burned: int = 0;
    has planned: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can count with Task entry {
        self.total += 1;
        if here.done {
            self.completed += 1;
            self.burned += here.points;
        } else {
            self.pending += 1;
        }
        self.planned += here.planned_points;
        visit [-->];
    }

    can summarize with Root exit {
        rate: float = 0.0;
        if self.total > 0 {
            rate = self.completed / self.total;
        }
        output = f'{{"total": {self.total}, "completed": {self.completed}, "pending": {self.pending}, "completion_rate": {repr(rate)}, "points_burned": {self.burned}, "points_planned": {self.planned}}}';
        print(output);
        disengage;
    }
}

with entry {
    root ++> Task(title="Wire up auth", done=True, points=5, planned_points=5)
        ++> Task(title="Build dashboard", done=True, points=8, planned_points=8)
        ++> Task(title="Write docs", done=False, points=0, planned_points=3)
        ++> Task(title="Polish UI", done=False, points=0, planned_points=2);

    root spawn Dashboard();
}
```

```jac
"""Task dashboard: walk the task graph, accumulate counters, and report a single
summary dict at Root exit. Guards division by zero for accounts with no todos."""

node Account {
    has name: str = "";
}

node Task {
    has title: str = "";
    has completed: bool = False;
    has story_points: int = 0;
}

walker Auditor {
    has account_name: str = "";
    has total: int = 0;
    has done: int = 0;
    has pending: int = 0;
    has burned: int = 0;
    has planned: int = 0;
    has `report: dict = {};
    has target_account: str = "";
    has locked: bool = False;

    can start with Root entry {
        self.target_account = "";
        self.locked = False;
        visit [-->];
    }

    can account with Account entry {
        if not self.locked {
            self.target_account = here.name;
            self.account_name = here.name;
            self.locked = True;
            visit [-->];
        }
    }

    can count with Task entry {
        self.total += 1;
        if here.completed {
            self.done += 1;
            self.burned += here.story_points;
        } else {
            self.pending += 1;
            self.planned += here.story_points;
        }
        visit [-->];
    }

    can summarize with Root exit {
        rate: float = 0.0;
        if self.total > 0 {
            rate = self.done * 100 / self.total;
        }
        self.`report = {
            "account": self.account_name,
            "total": self.total,
            "completed": self.done,
            "pending": self.pending,
            "completion_rate": rate,
            "story_points_burned": self.burned,
            "story_points_planned": self.planned,
        };
        print(self.`report);
        disengage;
    }
}

with entry { }
